/** 파싱 결과가 '캡처할 가치'가 있는지 — 제목만 남으면(날짜·과목·챕터 무) 일반 검색으로 둔다. */
function meaningful(c: CaptureResult | null): c is CaptureResult {
  return !!c && !!(c.dateISO || c.subject || c.chapter);
}

/** 파싱 결과를 한 줄 칩 요약으로(팔레트 힌트·확인 토스트 공용).
 *  ⚠ **시각 칩과 세션유형 칩이 여기서 사라졌다**(P-18). 근거는 `lib/quickCapture.ts` 머리주석 —
 *  요지는 그 둘이 *블록을 만들겠다는 약속*으로 읽히는데 이 경로는 블록을 만들지 않는다는 것이다.
 *  남은 셋은 전부 착지가 있다: 날짜·과목은 저널 프리필로, 챕터는 `topic`/원문으로. */
function summarize(c: CaptureResult): string {
  const parts: string[] = [];
  if (c.dateLabel) parts.push(c.dateLabel + (c.dateISO ? ` (${c.dateISO.slice(5)})` : ''));
  if (c.subject) parts.push(c.subject);
  if (c.chapter) parts.push(c.chapter);
  return parts.join(' · ');
}

/* cmdk 항목의 `value` 는 매칭 문자열이자 선택 식별자다. 두 용도가 한 문자열이라 **만드는
   곳과 되찾는 곳이 반드시 같은 규칙**을 써야 한다 — 손으로 두 번 적으면 검색어가 바뀔 때
   조용히 어긋나고, 증상은 "→ 를 눌러도 아무 일도 안 일어남"이다(N-1). */
const contentValue = (h: ContentHit, search: string) => 'content ' + h.id + ' ' + search;
const verbValue = (v: HitVerb) => 'verb ' + v.id;

/** 결과 0건 안내.
 *
 *  ⚠ `filtered.count` 는 **forceMount 항목을 세지 않는다**(cmdk 는 forceMount 면 아예 등록을
 *  건너뛴다 — 실측). 이 팔레트의 캡처·통합검색·의미검색 결과가 전부 forceMount 라, 이 값은
 *  정확히 "명령·탭·분야 중 매칭 0"을 뜻한다. 그래서 다른 결과가 이미 있으면 가려낸다.
 *
 *  ⚠ **D-2 이전엔 여기가 캡처의 유일한 입구였다** — 결과가 0건일 때만 "보충에 담기" 행을
 *  띄웠다. 그래서 친 문장이 내가 공부 중인 무언가를 언급하는 순간(=검색이 히트하는 순간)
 *  캡처가 사라졌다. 지금은 캡처가 {@link MOD_ENTER_LABEL} 로 **항상** 도달 가능하므로 여기는
 *  안내만 한다(그 안내가 곧 발견 경로다). */
function NoMatchFallback({ search, suppressed }: { search: string; suppressed: boolean }) {
  const none = useCommandState((s) => s.filtered.count === 0);
  const q = search.trim();
  if (!none || suppressed) return null;
  if (!q) return <div className={EMPTY}>일치하는 명령이 없어요</div>;
  return <div className={EMPTY}>일치하는 명령이 없어요 — {MOD_ENTER_LABEL} 로 지금 친 문장을 그대로 캡처</div>;
}

/* CommandPalette — cmdk 기반 ⌘K 팔레트(손코딩 ui-command.js 대체, 설계도 §3).
   명령 목록은 네이티브 shell/palette(탭+액션)에서. 이동은 React Router, 액션은 shell/actions를 호출.
   open/onOpenChange는 부모(App)가 소유 — 전역 단축키도 거기서. */
/* ── Q-21 **객체 우선 팔레트** (2026-08-02) ────────────────────────────────────
   기본 항목이 **수십 개**(이동 = `ORDERED_TABS` 중 은퇴 제외 + 액션 = `palette.ts` 의 표)이고
   그것들이 콘텐츠 히트와 **평평하게** 섞였다. ⚠ 종전엔 "48개(이동 22 + 액션 26)"이라 적혀 있었고
   실측과 달랐다 — 수는 두 상수가 소유한다(2026-08-20 리뷰 n-5). 즉
   ⌘K 를 열면 제일 먼저 보이는 것이 *앱의 IA 를 다시 나열한 목록*이었다 — 레일이 이미 하는 일을
   한 번 더 하고, 정작 사용자가 찾는 객체(과목·챕터·보충·책)는 그 아래로 밀렸다.

   ## 시길 둘이 목록을 가른다 — 필터가 아니라 **의도 선언**이다

   · `>` — **명령만**. "무엇을 실행할지 이미 안다."
   · `@` — **이동만**. "어디로 갈지 이미 안다."
   · 없음 — **객체 우선**. 명령·탭은 검색어가 있을 때만 따라 나온다.

   ⚠⚠ **핵심은 마지막 줄이다.** 시길을 추가하는 것만으로는 아무것도 안 고쳐진다(아무도 안 치면
   기본 화면은 그대로 48개다). 기본 모드에서 **빈 검색어일 때 명령 목록을 접는 것**이 이 항목의
   실제 내용이고, 시길은 그렇게 접힌 것에 **여전히 한 글자로 닿는 길**이다. 접기만 하고 길을
   안 내면 그건 기능 삭제다.

   ⚠ 최근 명령(LRU)은 빈 검색어에서도 남는다 — `recordRecent` 가 쌓아 온 것이 정확히 "이 사람이
   실제로 쓰는 명령"이고, 그걸 숨기면 팔레트가 매번 처음부터가 된다.
   ⚠ 시길은 **첫 글자일 때만** 뜻을 갖는다. 검색어 중간의 `>` 는 그냥 글자다(챕터 제목에 화살표를
   쓰는 사람이 있다). 그리고 시길만 친 상태(`>` 한 글자)는 **빈 검색어와 같다** — 목록 전체를
   보여 줘야 고를 수 있다. */
export type PaletteMode = 'object' | 'command' | 'nav';
export interface PaletteQuery {
  mode: PaletteMode;
  /** 시길을 걷어낸 실제 검색어. 아래 모든 검색이 이것을 쓴다. */
  q: string;
}
export function parsePaletteQuery(raw: string): PaletteQuery {
  if (raw.startsWith('>')) return { mode: 'command', q: raw.slice(1).trim() };
  if (raw.startsWith('@')) return { mode: 'nav', q: raw.slice(1).trim() };
  return { mode: 'object', q: raw.trim() };
}

/** 빈 검색어의 객체 모드에서 남기는 최근 명령 수 — 48개 나열과 0개 사이의 타협점. */
export const RECENT_KEEP = 5;

export default function CommandPalette({ open, onOpenChange }: { open: boolean; onOpenChange: (v: boolean) => void }) {
  const navigate = useNavigate();
  const [search, setSearch] = useState('');
  /* Q-21 — 입력에서 **의도(모드)** 와 **검색어**를 가른다. 아래 모든 검색은 `q` 를 쓴다(시길이
     검색어에 섞이면 `>테마` 가 아무것도 못 찾는다). 매칭은 cmdk 의 `defaultFilter` 에 그대로
     위임하되 시길만 벗겨 넘긴다 — 직접 `includes` 로 갈면 퍼지 매칭 품질을 잃는다. */
  const { mode, q } = useMemo(() => parsePaletteQuery(search), [search]);
  // 열릴 때만 계산(최근 명령 LRU가 외부에서 바뀌므로 재오픈 시 최신 순서 반영). 닫히면 빈 목록.
  const cmds = useMemo(() => (open ? paletteCommands() : []), [open]);
  /* Q-21 — **모드가 목록을 가른다.** 기본(객체) 모드에서 검색어가 비면 최근 명령 몇 개만 남긴다:
     48개 나열이 곧 "팔레트가 IA 를 재나열한다"의 실체였다. 시길 둘이 그렇게 접힌 것에 한 글자로
     닿는 길이고, `RECENT_KEEP` 근거는 `parsePaletteQuery` 머리주석에 있다.
     ⚠ `nav` 모드가 `id.startsWith('tab:')` 까지 보는 이유: **은퇴한 탭**은 `kind:'act'` 인데
     (착지 라우트로 보내야 해서) 여전히 *이동*이다. `kind` 만 보면 은퇴 탭이 이동 모드에서
     사라지고, 그건 불변식 ②가 잠근 "graph 가 ⌘K 에서 조용히 사라졌던" 그 형태다. */
  const shownCmds = useMemo(() => {
    if (mode === 'command') return cmds.filter((c) => c.kind === 'act' && !c.id.startsWith('tab:'));
    if (mode === 'nav') return cmds.filter((c) => c.kind === 'tab' || c.id.startsWith('tab:'));
    return q ? cmds : cmds.slice(0, RECENT_KEEP);
  }, [cmds, mode, q]);

  // 과목 스냅샷(파서 입력) — 열릴 때만. store 접근은 shell(captureSubjects)에 위임(components→store 금지).
  const subjects = useMemo(() => (open ? captureSubjects() : []), [open]);
  // 닫힐 때 입력 초기화(이벤트 핸들러에서 — effect 내 setState 회피). 캡처 실행/Esc 모두 이 경로로.
  const close = () => {
    setSearch('');
    onOpenChange(false);
  };

  /* N-11 — 팔레트발 내비게이션은 **이름을 알고 찾아간 것**이라 레일 클릭과 뜻이 다르다.
     레일에서 지운 목적지가 여기서 계속 열린다면 그건 "안 쓰이는 탭"이 아니라 "숨겨 둔 탭"이다.
     `close()` 에 붙이지 않는 이유: 캡처·Esc 도 그 경로를 지나 내비게이션 없이 닫는다. */
  const go = (to: string) => {
    markVia('palette');
    navigate(to, { viewTransition: true });
  };

  // 자연어 빠른 캡처 — 입력을 파싱해 날짜·시간·과목·유형을 뽑는다(예: "내일 오후 3시 알고리즘 2챕터 복습").
  // 순수 lib(quickCapture)라 여기선 결과만 미리보고, 선택 시 shell 액션으로 기록 프리필에 넘긴다.
  const cap = useMemo(
    () =>
      open && mode === 'object' && q
        ? parseCapture(
            q,
            new Date(),
            subjects.map((s) => s.name),
          )
        : null,
    [open, mode, q, subjects],
  );
  const mutate = useApp((st) => st.mutate);
  const showCapture = meaningful(cap);

  /* T-12 — 문장을 계획 변경으로 읽는다. 객체 모드에서만(시길은 의도 선언이지 문장이 아니다 · Q-21).
     ⚠ 판정은 `lib/planCommand` 가 소유한다 — 여기선 결과를 그리고 커밋만 한다. */
  const planCmd = useMemo(
    () => (open && mode === 'object' && q ? parsePlanCommand(q, subjects) : null),
    [open, mode, q, subjects],
  );

  // E-6/C-3: 오프라인 통합 검색 — 학습 항목·보충·반복약점을 부분문자열로(Ollama 불필요, 항상 동작).
  const content = useMemo(() => (open && mode === 'object' && q ? contentSearch(q) : []), [open, mode, q]);

  // 의미 검색(로컬 임베딩) — 350ms 디바운스, 늦은 응답은 버림. Ollama 불가면 조용히 빈 목록.
  // 짧은 질의는 렌더에서 걸러낸다(이펙트 내 동기 setState 회피 — 상태는 마지막 결과만 유지).
  const [semHits, setSemHits] = useState<SemHit[]>([]);
  useEffect(() => {
    if (!open || mode !== 'object') return;
    if (q.length < 2) return;
    let stale = false;
    const t = setTimeout(() => {
      semanticPalette(q)
        .then((hits) => {
          if (!stale) setSemHits(hits);
        })
        .catch(() => {});
    }, 350);
    return () => {
      stale = true;
      clearTimeout(t);
    };
  }, [open, mode, q]);
  const shownSem = mode === 'object' && q.length >= 2 ? semHits : [];

  /** 캡처 실행 — **언제나 커밋**한다(E2). 파싱 결과가 있으면 함께 실린다. */
  const runCapture = () => {
    commitCapture(q, meaningful(cap) ? summarize(cap) : '');
  };

  /* ── D-2 캡처는 조건부이면 캡처가 아니다 ──────────────────────────────────
     예전엔 캡처 행이 "결과 0건일 때"(생 텍스트) 또는 "파서가 토큰을 뽑았을 때"(구조화)만
     떴다. 그래서 **친 문장이 내가 공부 중인 무언가를 언급하는 순간 캡처가 사라졌다** —
     "변위전류 유도 못 따라감"은 챕터를 히트시키므로 검색 결과가 뜨고, 그러면 담을 곳이
     없어진다. 캡처는 떠오른 것을 잃지 않으려고 있는 기능이라 조건부면 존재 이유가 없다.

     ⚠ **첫 줄 고정을 안 한다.** 캡처 행을 목록 맨 위에 박으면 `⌘K → t → Enter`(탭 이동)
     근육기억이 통째로 깨진다 — Enter 는 계속 '선택한 항목 실행'이고, 캡처는 전용 키를 갖는다.
     정확한 목표는 "1급 시민"이 아니라 **"항상 도달 가능"**이다.

     ⚠ cmdk 는 자기 키 처리 **전에** 이 핸들러를 부르고 `defaultPrevented` 를 존중한다
     (dist 실측) → preventDefault 로 Enter 의 기본 동작(선택 항목 실행)을 정확히 가로챈다. */
  /* ⚠ **E2 이후 갈래가 없다.** 종전엔 여기서 두 경로로 갈렸고(구조화=프리필+화면 이동 /
     생 문장=즉시 저장), 그래서 **입력이 정교할수록 덜 저장되는** 역전이 있었다. 지금은 어느
     쪽이든 커밋하고, 파싱 결과는 버려지는 대신 레코드에 실린다(`commitCapture` 머리주석). */
  const captureNow = () => {
    // Q-21 — 시길은 의도 선언이지 문장의 일부가 아니다. 객체 모드에서만 캡처가 성립한다.
    if (mode !== 'object' || !q) return;
    runCapture();
    close();
  };

  /* ── N-1 명사 → 동사 ──────────────────────────────────────────────────────
     히트 위에서 `→`/`Tab` 을 누르면 **그 객체의 동사 목록**으로 내려간다. 종전엔 팔레트가
     찾아주고 데려다만 줘서, "이 약점을 보충에 담기"는 화면을 옮겨 그 항목을 다시 찾아
     버튼을 누르는 4클릭이었다.

     ⚠ **선택 값을 제어한다**(`value`/`onValueChange`). cmdk 는 비제어일 때 선택 항목을
     알려 주지 않는데, "지금 무엇 위에 있나"를 모르면 `→` 가 어떤 객체의 동사를 열지 알 수
     없다. 제어로 바꾼 대가로 **자동 첫 항목 선택이 사라지므로** 단계 전환마다 직접 세운다.

     ⚠ `→` 는 캐럿이 **입력 끝에 있을 때만** 가로챈다. 안 그러면 검색어 중간을 고치려고
     오른쪽으로 움직이는 것이 화면을 갈아 치운다(텍스트 편집을 뺏는 단축키는 결함이다).
     `Tab` 은 그 모호함이 없어 무조건 받는다. */
  const [sel, setSel] = useState('');
  const [verbHit, setVerbHit] = useState<ContentHit | null>(null);
  const verbs = useMemo(() => (verbHit ? verbsFor(verbHit) : []), [verbHit]);
  // 검색어가 값에 섞여 있어(cmdk 매칭용) 역참조가 필요하다 — id 문자열 파싱보다 정직하다.
  const hitByValue = useMemo(() => new Map(content.map((h) => [contentValue(h, search), h])), [content, search]);
  const selectedHit = verbHit ? null : (hitByValue.get(sel) ?? null);
  const canDrill = !!selectedHit && verbsFor(selectedHit).length > 0;

  const openVerbs = (h: ContentHit) => {
    const vs = verbsFor(h);
    if (!vs.length) return;
    setVerbHit(h);
    setSel(verbValue(vs[0]!)); // 제어 값이라 첫 항목을 직접 세운다(위 ⚠)
  };
  const backToHits = () => {
    const h = verbHit;
    setVerbHit(null);
    if (h) setSel(contentValue(h, search)); // 왔던 자리로 — 되돌아왔는데 커서가 딴 데면 길을 잃는다
  };

  /** 팔레트가 닫힐 때 동사 단계도 함께 접는다 — 다음 ⌘K 가 남의 객체 위에서 열리면 안 된다. */
  const closeAll = () => {
    setVerbHit(null);
    setSel('');
    close();
  };

  /* ── A-8 **⇧Enter — 실행하고 머무른다**(W9 · 2026-08-07) ────────────────────────
     모든 `onSelect` 가 닫았다. 그래서 연속 네 동작(과목 넷을 차례로 열기 · 명령 몇 개를 잇달아
     실행)이 **⌘K 네 번 + 검색어 네 벌**이었고, 그 사이 팔레트가 열리고 닫히는 애니메이션이
     네 번 돈다. 팔레트는 *찾아서 실행하는 곳*인데 한 번에 하나만 하도록 강제돼 있었다.

     ⚠ **기본은 그대로 닫는다.** Enter 의 뜻을 바꾸면 근육기억이 통째로 깨진다(D-2 가 캡처를
     첫 줄에 안 박은 그 논증). 머무름은 **다른 키**여야 하고, ⇧+실행은 목록 UI 의 표준 관용구다.
     ⚠ cmdk 는 Enter 를 자기가 처리하므로 `preventDefault` 를 **하지 않는다** — 여기서는
     "이번 실행은 닫지 말라"는 플래그만 세우고, 실행 자체는 그대로 `onSelect` 가 한다.
     ⚠ 머무를 때 **검색어를 비운다**: 방금 친 말은 방금 실행한 것을 찾던 말이라, 남겨 두면
     다음 타이핑이 그 뒤에 이어 붙어 아무것도 안 맞는다(그리고 지우려면 백스페이스를 눌러야 한다). */
  const keepOpenRef = useRef(false);
  /** 실행 뒤 정리 — ⇧Enter 였으면 팔레트를 **유지**하고 다음 입력을 받을 준비만 한다. */
  const finish = () => {
    if (!keepOpenRef.current) {
      closeAll();
      return;
    }
    keepOpenRef.current = false;
    setVerbHit(null);
    setSel('');
    setSearch('');
  };

  return (
    <Command.Dialog
      open={open}
      /* ⚠ Esc 를 여기서 받는다(N-1). Radix 는 Escape 를 **document 캡처 단계**에서 처리하므로
         우리 `onKeyDown`(버블)은 언제나 한 발 늦고, `preventDefault` 도 이미 소용이 없다.
         그리고 cmdk 의 `Command.Dialog` 는 Radix **루트** props 만 받아 `onEscapeKeyDown` 이
         닿지 않는다(dist 타입 확인). 남는 정직한 접점이 "닫아 달라는 요청"인 이 콜백이다.

         동사 단계에서 닫기 요청은 **한 단계만** 접는다 — 잘못 들어왔을 때 친 검색어까지
         잃으면 다시 치게 되고, 그건 이 항목이 없애려던 마찰이다.
         ⚠ 알려진 비대칭: 이 접점은 Esc 와 바깥 클릭을 구분하지 못해 **바깥 클릭도 한 단계만**
         접는다(한 번 더 눌러야 닫힌다). 중첩 메뉴의 통상 동작과 같은 방향이고, 구분하려면
         Radix 레이어 내부에 손을 넣어야 해서 값보다 결합이 크다. */
      onOpenChange={(v) => {
        if (v) return onOpenChange(true);
        if (verbHit) return backToHits();
        closeAll();
      }}
      label="명령 팔레트"
      /* Q-21 — 시길만 벗겨 cmdk 의 기본 매칭에 **그대로 위임한다.** 직접 `includes` 로 갈면
         퍼지 매칭(오타·머리글자)을 잃고, 그건 시길이 주는 것보다 크게 잃는 것이다. */
      filter={(value, raw, keywords) => defaultFilter(value, parsePaletteQuery(raw).q, keywords)}
      className={DIALOG}
      overlayClassName={OVERLAY}
      contentClassName={CONTENT}
      value={sel}
      onValueChange={setSel}
      onKeyDown={(e) => {
        if (e.nativeEvent.isComposing) return;
        // ⌘Enter 캡처는 **동사 단계에서도** 산다(D-2 의 "무조건 성립"은 단계에 걸리지 않는다).
        if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
          e.preventDefault();
          captureNow();
          return;
        }
        // A-8 — 이번 Enter 는 닫지 않는다(실행은 cmdk 가 그대로 한다 · 위 ⚠).
        if (e.key === 'Enter' && e.shiftKey) keepOpenRef.current = true;
        if (e.metaKey || e.ctrlKey || e.altKey) return;
        const el = e.target as HTMLInputElement;
        const atEnd = el.selectionStart == null || el.selectionStart >= (el.value?.length ?? 0);
        const atStart = el.selectionStart == null || el.selectionStart === 0;
        if (!verbHit && selectedHit && (e.key === 'Tab' || (e.key === 'ArrowRight' && atEnd))) {
          e.preventDefault();
          openVerbs(selectedHit);
          return;
        }
        // ⚠ Esc 는 여기서 안 받는다 — Radix 가 **캡처 단계**에서 먼저 가져가 이 핸들러는
        //   언제나 한 발 늦는다. 뒤로 가기는 `onOpenChange` 가 소유한다(그쪽 주석이 근거).
        if (verbHit && (e.key === 'Tab' || (e.key === 'ArrowLeft' && atStart))) {
          e.preventDefault();
          backToHits();
        }
      }}
    >
      <Command.Input
        value={search}
        onValueChange={setSearch}
        className={INPUT}
        placeholder="명령·탭 검색, 또는 빠른 캡처 (예: 내일 오후 3시 알고리즘 복습)"
        /* 팔레트가 열리는 유일한 경로는 사용자의 명시적 ⌘K 다. 열릴 때 입력에 포커스가 가는 건
           combobox/팔레트의 표준 동작이고, 없으면 오히려 키보드 사용자가 아무 데도 못 간다.
           no-autofocus 의 원래 대상은 '페이지 로드 시 강제 포커스'라 여기엔 해당 없음. */
        // eslint-disable-next-line jsx-a11y/no-autofocus
        autoFocus
      />
      <Command.List className={LIST}>
        {/* ── N-1 동사 단계 ─────────────────────────────────────────────────
            동사 목록일 땐 **다른 것을 아무것도 안 그린다.** 명령·탭이 함께 보이면 지금
            무엇에 대해 말하고 있는지가 흐려지고, 그 순간 동사가 엉뚱한 객체에 작용한 것처럼
            읽힌다(실제로는 안 그래도 그렇게 보이는 것으로 충분히 나쁘다).
            `forceMount` — 검색어는 객체를 찾을 때 쓴 말이라 동사 라벨과 안 맞는다. */}
        {verbHit ? (
          <Command.Group heading={<span className={GROUP_HEAD}>{verbHit.label}</span>} forceMount>
            {verbs.map((v) => (
              <Command.Item
                key={v.id}
                forceMount
                value={verbValue(v)}
                className={ITEM}
                onSelect={() => {
                  try {
                    v.run();
                  } catch (e) {
                    console.error(e);
                  }
                  finish();
                  if (v.to) go(v.to);
                }}
              >
                <span className={LABEL}>{v.label}</span>
                <span className={HINT}>{v.hint}</span>
              </Command.Item>
            ))}
          </Command.Group>
        ) : (
          <>
            <NoMatchFallback search={search} suppressed={showCapture || content.length > 0 || shownSem.length > 0} />
            {/* ── T-12 명령줄이 계획을 쓴다 ─────────────────────────────────────────
                문장이 계획 변경으로 읽히면 **맨 위**에 둔다. 캡처보다 위인 이유: 계획 변경은
                *지금 바로 반영되는 행동*이고 캡처는 나중에 볼 기록이라 되돌리는 비용이 다르다.
                ⚠ 못 알아들었을 때 조용히 사라지지 않는다 — 판정·문구는 `lib/planCommand` 가
                  소유하고(화면마다 새로 지으면 갈린다) 여기선 그 결과를 그린다. */}
            {planCmd?.kind === 'ok' && (
              <Command.Item
                key="plan-cmd"
                forceMount
                value={'plan-cmd ' + search}
                className={`${ITEM} ${CAPTURE}`}
                onSelect={() => {
                  const c = planCmd.cmd;
                  // M-9 — 찾기·하한·daily 가드는 `lib/weekAlloc.applyWeeklyHours` 가 소유한다.
                  mutate((st) => void applyWeeklyHours(st, c.sid, { delta: c.deltaH }));
                  finish();
                }}
              >
                <span className={LABEL}>
                  <Icon name="balance" /> 계획 바꾸기 — {planCmd.echo}
                </span>
                <span className={HINT_CAP}>Enter 로 적용 · ⌘Z 로 되돌리기</span>
              </Command.Item>
            )}
            {planCmd?.kind === 'unknown-subject' && (
              <Command.Item key="plan-cmd-miss" forceMount value={'plan-cmd ' + search} className={ITEM} disabled>
                <span className={LABEL}>
                  <Icon name="balance" /> “{planCmd.typed}” 과목을 못 찾았어요
                </span>
                <span className={HINT_CAP}>예: {planCmd.candidates.join(' · ')}</span>
              </Command.Item>
            )}
            {showCapture && cap && (
              <Command.Item
                key="quick-capture"
                forceMount
                value={'quick-capture ' + search}
                className={`${ITEM} ${CAPTURE}`}
                onSelect={() => {
                  try {
                    runCapture();
                  } catch (e) {
                    console.error(e);
                  }
                  finish();
                }}
              >
                <span className={LABEL}>
                  <Icon name="pin" /> 빠른 캡처 — 보충에 담기
                </span>
                <span className={HINT_CAP}>{summarize(cap)}</span>
              </Command.Item>
            )}
            {/* E-6 오프라인 통합 검색 — 학습 항목·독서 부분문자열(forceMount: 자체 매칭이 기준). */}
            {content.length > 0 && (
              <Command.Group heading={<span className={GROUP_HEAD}>빠른 검색 — 학습 항목·독서</span>} forceMount>
                {content.map((h) => (
                  <Command.Item
                    key={h.id}
                    forceMount
                    value={contentValue(h, search)}
                    className={ITEM}
                    onSelect={() => {
                      finish();
                      go(h.to);
                    }}
                  >
                    <span className={LABEL}>
                      <Icon name={CONTENT_ICON[h.kind]} /> {h.label}
                    </span>
                    <span className={HINT}>{CONTENT_HINT[h.kind]}</span>
                  </Command.Item>
                ))}
              </Command.Group>
            )}
            {/* 의미 검색 결과 — cmdk 부분문자열 필터를 우회(forceMount): 임베딩 유사도가 매칭 기준. */}
            {shownSem.length > 0 && (
              <Command.Group heading={<span className={GROUP_HEAD}>의미 검색 — 내 학습 자산</span>} forceMount>
                {shownSem.map((h) => (
                  <Command.Item
                    key={'sem:' + h.id}
                    forceMount
                    value={'semantic ' + h.id + ' ' + search}
                    className={ITEM}
                    onSelect={() => {
                      finish();
                      go(h.to);
                    }}
                  >
                    <span className={LABEL}>
                      <Icon name={SEM_ICON[h.kind]} /> {h.label}
                    </span>
                    <span className={HINT}>{Math.round(h.sim * 100)}% 유사</span>
                  </Command.Item>
                ))}
              </Command.Group>
            )}
            {shownCmds.map((c) => (
              <Command.Item
                key={c.id}
                value={c.label + ' ' + c.hint}
                className={ITEM}
                onSelect={() => {
                  finish();
                  recordRecent(c.id); // 최근 명령 LRU — 다음 ⌘K에서 위로.
                  try {
                    if (c.kind === 'tab') go('/' + c.key);
                    else {
                      c.run?.(); // ⚠ 이동만 하는 항목은 `run` 이 없다(P3 — `act:graph`).
                      // 액션이 특정 탭에서 이어지는 경우(집중 시작·기록 프리필) 실행 후 이동.
                      if (c.to) go(c.to);
                      /* ⚠ `enter` 는 **실패하면 안 가는** 진입이다(N-20) — 창 모드처럼 부수효과가
                         실패했을 때 이동하면 반쪽 상태가 된다(`lib/miniMode` H9). 그래서 `to` 와
                         달리 결과를 기다린다. */
                      if (c.enter) void c.enter().then((dest) => dest && go(dest));
                    }
                  } catch (e) {
                    console.error(e);
                  }
                }}
              >
                <span className={LABEL}>{c.label}</span>
                <span className={HINT}>{c.hint}</span>
              </Command.Item>
            ))}
          </>
        )}
      </Command.List>
      {/* D-2 — 캡처의 발견 경로. 전용 키는 안 보이면 없는 것과 같아, 힌트 바가 곧 어포던스다.
          입력이 있을 때만 액센트로 올라온다(늘 밝으면 다섯 힌트가 서로를 죽인다 · D-6 과 같은 규율). */}
      {/* D-2 — 캡처의 발견 경로. N-1 의 `→` 도 같은 자리에서 배운다: 전용 키는 안 보이면
          없는 것과 같다. 액센트는 **지금 쓸 수 있을 때만** 켜진다(늘 밝으면 힌트가 서로를 죽인다). */}
      <div className={FOOT}>
        <span>
          {verbHit ? (
            <>
              <b>↑↓</b> 이동 · <b>Enter</b> 실행 · <b>⇧Enter</b> 계속 · <b>←</b> 뒤로
            </>
          ) : (
            <>
              <b>↑↓</b> 이동 · <b>Enter</b> 실행 · <b>⇧Enter</b> 계속 ·{' '}
              {/* Q-21 — 시길은 안 보이면 없는 것과 같다(D-2 가 캡처에서 세운 그 규율). 지금 쓰고
                  있는 모드를 액센트로 표시해, 무엇이 걸러지고 있는지를 목록이 아니라 힌트가 말한다. */}
              <b className={mode === 'command' ? 'text-acc' : undefined}>&gt;</b> 명령 ·{' '}
              <b className={mode === 'nav' ? 'text-acc' : undefined}>@</b> 이동
            </>
          )}
        </span>
        {canDrill ? (
          <span className="text-acc">
            <b>→</b> 이 항목으로 할 일
          </span>
        ) : (
          <span className={mode === 'object' && q ? 'text-acc' : undefined}>
            <b>{MOD_ENTER_LABEL}</b> 캡처 — 보충에 담기
          </span>
        )}
        <span className={BRAND}>{MOD_K_LABEL}</span>
      </div>
    </Command.Dialog>
  );
}

/* ============================================================
   FocusChip — 전역 집중 세션 표시(TopBar 상주). useFocus 세션의 단일 감시자:
   ① 남은 시간 칩(어느 탭에서든 보임, 클릭 → 오늘 탭) ② 문서 제목 미러(탭 전환해도 보임)
   ③ 종료 감지 — 시스템 알림 + '블록 완료로 표시' 액션 토스트(한 번만).
============================================================ */
import { useEffect, useRef, useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useFocus } from '@/store/useFocus';
import { useApp } from '@/store/useApp';
import { touchReview } from '@/lib/persistence';
import { mmss } from '@/lib/utils';
import { isTauri, shellNotify } from '@/lib/tauri';
import { MINI_PATH, enterMini, exitMini, miniMode } from '@/lib/miniMode';
import { toast, toastChoice } from '@/shell/toast';
import { Icon } from '@/components/Icon';
import { confirmIrreversible } from '@/shell/destructive';
import { routeTitle } from './docTitle';
import { onVisible } from '@/lib/visibility';

/* ── C-7 셸 티어 5/5 이식(Tailwind) ─────────────────────────────────────────────
   TopBar 상주 칩 — 네온 헤어라인 + 라이브 펄스 + 모노 숫자. 색은 전부 --acc/--glow 파생
   토큰(절대규칙 #3). ⚠ 두 버튼은 raw `<button>` 이라 언레이어드 전역 `button{}` 을 상대한다
   (배경·보더·radius·padding·font 계열에 `!`). 자손(`b`·`span`)은 버튼의 UA `line-height:normal`
   을 상속하던 자리라 내장 크기명(text-lg/text-sm)에 `leading-auto` 을 함께 박는다(규약 6-b).
   펄스 키프레임은 tw.css 로 옮겼다(CSS Module 스코프 밖이어야 유틸에서 부를 수 있다).
   `FocusChip.module.css` 삭제. */
const CHIP =
  'inline-flex items-stretch self-center overflow-hidden rounded-chip border border-line-acc-pill bg-tint-acc-9 shadow-focus-chip';
const BODY =
  'inline-flex min-h-8.5 items-center gap-2 border-0! bg-transparent! px-3! py-0! text-ink! hover:bg-tint-acc-14! focus-visible:outline-2 focus-visible:outline-acc focus-visible:-outline-offset-2';
const PULSE =
  'size-1.75 rounded-full bg-acc shadow-focus-dot animate-[live-breathe_var(--tempo)_var(--ease-live)_infinite] motion-reduce:animate-none';
const TIME = 'text-lg leading-auto font-extrabold tracking-topbar-sub text-acc tabular-nums text-shadow-focus-time';
const NAME =
  'max-w-30 overflow-hidden text-ellipsis whitespace-nowrap text-sm leading-auto font-bold text-mut max-mobile:hidden';
const STOP =
  // ⚠ radius·padding 은 **건드리지 않는다** — 원본 `.stopBtn`/`.body` 가 그 속성을 선언하지 않아
  //    언레이어드 전역 `button{}`(radius 7px · padding 8/13px)을 그대로 받고 있었다. 유틸로 0 을
  //    박으면 '이식'이 아니라 변경이다(칩은 overflow-hidden 이라 radius 차이가 눈엔 거의 안 보인다).
  'inline-flex w-7.5 items-center justify-center border-0! border-l! border-l-line-acc! bg-transparent! text-2xs! leading-auto text-mut! hover:bg-tint-acc-8! hover:text-bad! focus-visible:outline-2 focus-visible:outline-acc focus-visible:-outline-offset-2';

const fmt = mmss; // 표기 규약은 lib/utils 가 단일 원천(CT-S3)

export default function FocusChip() {
  const session = useFocus((st) => st.session);
  const stop = useFocus((st) => st.stop);
  const clear = useFocus((st) => st.clear);
  const navigate = useNavigate();
  const location = useLocation();
  const [now, setNow] = useState(() => Date.now());
  /** 접기 — 창 조작이 성공했을 때만 라우팅한다(반쪽 상태 금지 · `miniMode` 머리주석). */
  const foldToMini = async (): Promise<void> => {
    if (await enterMini(location.pathname)) navigate(MINI_PATH);
  };
  const doneKey = useRef<number | null>(null);

  // 1초 틱(세션 중에만). 백그라운드 스로틀은 브라우저에 맡기고, 복귀·시작 시 즉시 캐치업.
  useEffect(() => {
    if (!session) return;
    // eslint-disable-next-line react-hooks/set-state-in-effect -- 세션 시작/복귀 시 스테일 now 즉시 보정.
    setNow(Date.now());
    const id = setInterval(() => setNow(Date.now()), 1000);
    const off = onVisible(() => setNow(Date.now())); // 복귀 시 스테일 now 캐치업
    return () => {
      clearInterval(id);
      off();
    };
  }, [session]);

  const leftSec = session ? Math.max(0, Math.round((session.endsAt - now) / 1000)) : 0;

  // 종료 감지 — 세션당 정확히 한 번. 집중: 알림 + 완료 토글 토스트 + 자동 휴식(5분).
  // 휴식: 가벼운 알림 + '다음 블록 시작' 액션(완료 토글·재휴식 없음).
  useEffect(() => {
    if (!session || leftSec > 0) return;
    if (doneKey.current === session.startedAt) return;
    doneKey.current = session.startedAt;
    const { ds, sid, type, name, blockMin, kind, chapter } = session;
    const isBreak = kind === 'break';
    // 즉석 집중(ID-3)은 대상 블록이 없어 완료 토글을 못(안) 한다 — 축하·자동 휴식은 집중과 같되
    // '블록 완료로 표시' 액션만 뺀다(유령 완료 방지). isBreak 은 여전히 false라 회복 휴식은 붙는다.
    const isFree = kind === 'free';
    /* ⚠⚠ **이 앱이 자동으로 알림을 쏘는 자리는 여기 하나다 — 그리고 하나로 유지한다.**
       조건: **사용자가 스스로 시작한 세션이 끝났을 때.** 마감 임박·복습 밀림·하루 셧다운은
       알리지 않는다. 그 셋은 전부 "앱이 사용자를 부르는" 방향이고, 이 저장소는 넛지 계열
       제안을 반복해서 거절해 왔다(로드맵 드롭 목록의 Web Push·넛지 항목들이 같은 판단이다).
       사용자가 시작을 눌렀다는 것이 곧 "끝나면 알려 달라"는 요청이라, 여기만 예외다.
       → "마감 알림도 넣자"는 재제안은 이 주석 한 줄로 끝난다.
       **P-8 은 이 트리거를 한 글자도 안 건드렸다** — 트리거는 그대로 하나이고, 그 하나의
       *내용*이 두꺼워졌을 뿐이다.

       ⚠⚠ **여기 `new Notification(...)` 이 있었고, 단 한 번도 뜬 적이 없다(실측 2026-08-01).**
       가드가 `Notification.permission === 'granted'` 였는데 `tauri://` WebView2 에서 그 값은
       **항상 `denied`** 이고 `requestPermission()` 도 프롬프트 없이 즉시 거부한다(CDP 프로브).
       즉 옛 주석이 _"실측은 아직 안 했다"_ 고 적어 둔 바로 그 자리에서, 이 앱의 개입 채널은
       1개가 아니라 **0개**였다. 지금은 Tauri 알림 플러그인이 진짜로 쏜다(`shellNotify`).
       ⚠ 실패는 여전히 조용하다 — 알림은 부가 신호이고 같은 사실을 아래 토스트가 화면 안에서
       말한다. 다만 이제 그 침묵이 "권한 없음"이지 "코드가 죽어 있음"이 아니다. */
    /* ── Q-25 재개 단서 ────────────────────────────────────────────────────────────────
       종전 본문은 `"${name} — 수고했어요."` 뿐이라 **다음 행동 정보가 0**이었다. 그런데 이
       세션은 *자리를 뜨라고* 만든 것이고, 알림은 대개 **자리를 비운 사이에** 읽힌다 — 즉
       돌아왔을 때 "어디까지 했더라"를 기억으로 재구성해야 했다.
       중단 복귀에는 **재개 지연**이 있고 **단서가 그것을 유의하게 줄인다**(Nature 2025) —
       우리에겐 이미 그 단서가 있다(`session.chapter`). 안 실어 보낼 이유가 없었다.
       ⚠ 단서는 **방금 한 것**이지 지시가 아니다. "다음엔 X 하세요"는 알림이 계획을 대신
       세우는 것이고, 그건 이 자리(사용자가 시작한 세션의 종료)의 권한 밖이다. */
    const cue = chapter ? ` 마지막: ${chapter}.` : '';
    void shellNotify(
      isBreak ? '휴식 끝' : '집중 세션 완료',
      isBreak
        ? '재충전 완료 — 다음 블록을 시작해볼까요?'
        : isFree
          ? `${name} — 수고했어요.${cue}`
          : `${name} — 수고했어요.${cue} 앱에서 블록을 완료로 표시할 수 있어요.`,
    );
    if (isBreak) {
      toast('휴식 끝 — 다음 블록을 시작해볼까요?', 'info', 10_000, {
        label: '집중 시작',
        onAction: () => useFocus.getState().startOnCurrent(),
      });
    } else if (isFree) {
      // 완료 액션 없음 — 즉석 세션은 기록에 남기지 않는다(수고 인정만).
      toast(`즉석 집중 완료 — ${name}. 수고했어요.`, 'info', 8_000);
    } else {
      /* ── P-8 세 갈래 · 시한 없음(2026-08-01) ────────────────────────────────
         ⚠⚠ 종전엔 이 토스트가 **10초**였고 액션이 **'블록 완료로 표시' 하나**였다. 그런데 이
         세션은 **자리를 뜨라고 만든 것**이라, 돌아왔을 땐 대개 이미 사라져 있었다 — 그러면
         완료 체크는 계획 탭에서 손으로 찾는 길뿐이다(화면 1개·클릭 3+). 즉 **가장 값나가는
         기록(G-1 실측 분)이 10초짜리 창에 걸려 있었다.** 이제 누를 때까지 안 사라진다.
         ⚠ 원래 이 갈래들은 **OS 알림 액션 버튼**에 두려던 것인데 Windows 에서 불가라
         (Actions API 는 모바일 전용 · 실측) 앱 안이 진다. */
      toastChoice(`집중 세션 완료 — ${name}`, 'info', [
        {
          label: '블록 완료로 표시',
          onAction: () => {
            const app = useApp.getState();
            /* G-1 — **실제로 집중한 분**을 함께 남긴다. 지금까지 회고 넷은 계획 분을 "집중한
               시간"으로 읽었고, 그중 `adherenceFactor` 는 그 값으로 미래 용량을 깎았다. 이 경로가
               실측을 아는 유일한 자리다(세션 총 길이 = `total` 초). 세션을 중간에 멈췄다면 그 세션은
               완료 토스트 자체가 안 뜨므로 여기 오는 값은 언제나 '끝까지 한 세션'이다. */
            app.toggleDone(ds, sid, type, blockMin, true, Math.round(session.total / 60));
            // ReviewRun發 세션은 챕터를 아니까 챕터 터치도 기록 — 위험모델 lastDs 갱신(감사 #22).
            if (chapter) app.mutate((st) => touchReview(st, sid, chapter, ds));
          },
        },
        /* ⚠⚠ **자동 휴식 5분이 여기서 은퇴했다(P-8).** 종전엔 세션이 끝나는 즉시
           `startBreak(5)` 가 돌아 **사용자가 요청하지 않은 세션을 앱이 시작하는 유일한 자리**
           였다 — 게다가 완료 토스트를 읽는 동안 이미 다음 타이머가 흐르고 있었다. 같은 5분을
           **선택지로** 옮긴다: 없어진 것은 자동성이지 기능이 아니다.
           ⚠ `startBreak` 의 유일한 호출부가 이 줄이다 — 지우면 휴식이 도달 불가가 된다. */
        { label: '5분 휴식', onAction: () => useFocus.getState().startBreak(5) },
        // '계속' 은 아무것도 안 한다 — 시한 없는 토스트를 닫는 정직한 출구다(닫기는 공통 처리).
        { label: '계속', onAction: () => {} },
      ]);
    }
    clear();
  }, [session, leftSec, clear]);

  /* 미니 모드 자동 복귀(N-8) — 세션이 끝나면 알약을 접고 원래 창·원래 탭으로 돌아온다.
     ⚠ 세션 종료를 이 컴포넌트가 단독 감시하므로(위 이펙트) 복귀도 여기 둔다. 미니 화면이
     자기 종료를 감시하게 만들면 감시자가 둘이 되고, 그러면 알림·완료 토스트가 두 번 뜬다.
     ⚠ `session` 이 null 이 되는 순간에 걸린다 — 자동 휴식이 곧바로 새 세션을 만들지만 그건
     다음 렌더의 새 session 이라 이 이펙트는 이미 복귀를 걸었다(휴식은 알약에 안 가둔다). */
  /* ⚠ **상주 알약(N-20)은 자동으로 안 나간다.** 이 이펙트가 감시하는 것은 *세션을 접은* 알약이
     세션 종료와 함께 펼쳐지는 것이고, 세션 없이 들어온 알약에는 그 계약이 없다 — 여기서 걸러
     내지 않으면 상주 모드가 **켜지자마자 스스로 나간다**(session 이 처음부터 null 이므로). */
  const inMini = location.pathname === MINI_PATH;
  useEffect(() => {
    if (!inMini || session || miniMode() === 'resident') return;
    /* ⚠ 창 복원이 실패하면 **라우팅하지 않는다**(H9) — 알약 크기 그대로 다른 화면으로 넘어가면
       나갈 문(알약의 확장 버튼)까지 사라져 재시작 외 탈출이 없다. 알약에 머물면 다시 누를 수 있다. */
    void exitMini().then((back) => {
      if (back) navigate(back, { replace: true });
      else toast('창을 되돌리지 못했어요 — 다시 시도해 주세요.', 'bad');
    });
  }, [inMini, session, navigate]);

  // 문서 제목에 남은 시간 미러 — 다른 앱/탭에 가 있어도 세션이 보인다.
  useEffect(() => {
    if (!session) return;
    document.title = `${fmt(leftSec)} · ${session.name} — 러닝허브`;
    return () => {
      // 모듈로드 스냅샷이 아니라 종료 시점의 *현재* 라우트로 재계산 — App의 제목 이펙트는
      // 라우트 변경에만 발화하므로 여기서 복원하지 않으면 stale 제목이 남는다(X-9).
      document.title = routeTitle();
    };
  }, [session, leftSec]);

  if (!session) return null;
  const isBreak = session.kind === 'break';
  const mmss = fmt(leftSec);
  // 조기중단 confirm — 실수 클릭으로 세션이 날아가는 것 방지(휴식은 부담 없이 즉시 중단).
  const stopAsk = async () => {
    if (isBreak) return stop();
    if (
      await confirmIrreversible('집중 세션을 중단할까요? 진행 시간은 기록되지 않아요.', {
        title: '집중 중단',
        okLabel: '중단',
      })
    )
      stop();
  };
  return (
    <div className={CHIP}>
      <button
        type="button"
        className={BODY}
        onClick={() => navigate('/today', { viewTransition: true })}
        title={isBreak ? '휴식 중 — 오늘 탭으로' : '집중 세션 진행 중 — 오늘 탭으로'}
        aria-label={`${isBreak ? '휴식' : `집중 세션 ${session.name}`} 남은 시간 ${mmss} — 오늘 탭으로 이동`}
      >
        <i className={PULSE} aria-hidden="true" />
        <b className={TIME}>{mmss}</b>
        <span className={NAME}>
          {isBreak ? (
            <>
              <Icon name="coffee" /> 휴식
            </>
          ) : (
            session.name
          )}
        </span>
      </button>
      {/* 접기(N-8) — 셸에서만 뜬다. 브라우저(dev·트랙 A)엔 창 개념이 없어 눌러도 할 일이 없고,
          휴식은 5분짜리라 창을 접었다 펴는 비용이 값보다 크다. */}
      {!isBreak && isTauri() && (
        <button
          type="button"
          className={STOP}
          onClick={() => void foldToMini()}
          title="미니 타이머로 접기 — 항상 위에 뜨는 알약"
          aria-label="미니 타이머로 접기"
        >
          ▭
        </button>
      )}
      <button
        type="button"
        className={STOP}
        onClick={() => void stopAsk()}
        title={isBreak ? '휴식 중단' : '집중 중단'}
        aria-label={isBreak ? '휴식 타이머 정지' : '집중 타이머 정지'}
      >
        ■
      </button>
    </div>
  );
}

/* ============================================================
   MiniHud — 집중 미니 HUD(N-8). 320×92 알약 창의 유일한 내용.

   ⚠ **셸을 언마운트하지 않는다.** 이 화면은 셸 위에 덮는 오버레이고, 아래에서 `TopBar` 의
   `FocusChip` 이 계속 살아 있다. 그게 설계다: 세션 종료 감지(알림·완료 토스트·자동 휴식)의
   **단일 감시자**가 FocusChip 이라, 미니 모드가 셸을 걷어내면 그 감시가 통째로 멈춘다
   ("집중이 끝났는데 아무 일도 안 일어나는" 무음 회귀 — 창이 작아 눈에도 안 띈다).
   그래서 여기엔 타이머 로직이 없다. 남은 시간은 같은 스토어를 읽어 그리기만 한다.

   ⚠ 창을 되돌리는 책임도 나눠 갖지 않는다: 사용자가 펼치면 여기서, 세션이 끝나면 FocusChip
   에서 `exitMini()` 를 부른다(둘 다 같은 함수 · 복귀 크기 원천은 `miniMode` 하나).
============================================================ */
import { useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useApp } from '@/store/useApp';
import { useFocus } from '@/store/useFocus';
import { useOverlay } from '@/store/useOverlay';
import { selectSchedule } from '@/store/selectors';
import { commitCapture } from '@/shell';
import { mmss, reviewBlockMin, todayISO } from '@/lib/utils';
import { openBacklog } from '@/lib/methodology';
import { pickReminderLead } from '@/lib/reminder';
import { riskChapters } from '@/lib/spacedReview';
import { setMiniCaptureWindow } from '@/lib/tauri';
import { exitMini, miniMode } from '@/lib/miniMode';
import { toast } from '@/shell/toast';
import { useFocusTrap } from '@/hooks/useFocusTrap';
import { Icon } from '@/components/Icon';

const WRAP = 'fixed inset-0 z-[var(--z-modal)] flex items-center gap-3 border border-line-acc-pill bg-bg px-3.5 py-2.5';
const PULSE =
  'size-2 shrink-0 rounded-full bg-acc shadow-focus-dot animate-[live-breathe_var(--tempo)_var(--ease-live)_infinite] motion-reduce:animate-none';
/* N-20 상주 알약의 점 — **맥동하지 않는다.** `live` 어휘는 *지금 흐르는 것*을 뜻하는데(모션
   어휘 SSOT: `lib/motion.ts`) 상주 알약에는 흐르는 타이머가 없다. 같은 자리에 같은 모양으로
   두되 움직임만 뺀다: 움직이면 "세션 중"으로 읽힌다. */
const DOT = 'size-2 shrink-0 rounded-full bg-mut';
const TIME = 'text-4xl leading-none font-extrabold tracking-topbar-sub text-acc tabular-nums text-shadow-focus-time';
const NAME = 'min-w-0 flex-1 overflow-hidden text-ellipsis whitespace-nowrap text-sm font-bold text-mut';
const BTN =
  'inline-flex size-8 shrink-0 items-center justify-center rounded-sm! border! border-line! bg-transparent! p-0! text-sm! leading-auto text-mut! hover:border-line-acc! hover:text-ink! focus-visible:outline-2 focus-visible:outline-acc focus-visible:-outline-offset-2';

export default function MiniHud() {
  const session = useFocus((s) => s.session);
  const stop = useFocus((s) => s.stop);
  const navigate = useNavigate();
  const [now, setNow] = useState(() => Date.now());
  const capture = useOverlay((s) => s.miniCapture);
  const setCapture = useOverlay((s) => s.setMiniCapture);
  const wrapRef = useRef<HTMLDivElement | null>(null);

  /* ⚠⚠ **포커스를 이 알약 안에 묶는다(H11 · 2026-07-30 `/감사 근본`).**

     이 화면은 `fixed inset-0` 로 셸을 덮지만 셸을 **언마운트하지 않는다**(위 머리주석 — 세션 종료
     감시자를 살려 두려는 것이고 그 판단은 옳다). 그런데 배경에 `inert`·트랩이 없어서, 창이
     320×92 로 줄어든 상태에서 Tab 을 누르면 포커스가 **뷰포트 밖 셸 컨트롤**(스킵링크·레일 7개·
     TopBar 액션·본문 전부)로 이동했다. 아무것도 보이지 않는 채 Enter 를 누르면 임의의 탭 이동·
     테마 전환·`전체 초기화…` 확인창이 뜬다. 그리고 `/mini` 는 axe 로스터 밖이라 아무도 안 잡았다.
     (전 저장소에 `inert` 사용이 **0건**이었다 — 오버레이 계약에 그 도구가 아예 없었다.)

     `useFocusTrap` 은 Esc·복원까지 이미 소유한 훅이라 계약을 새로 만들지 않는다.
     ⚠ 남는 것: 스크린리더 **가상 커서**는 트랩이 막지 못한다(배경을 읽을 수 있다). 그건 `inert`
       가 필요한데, 그러려면 셸 컨테이너에 그 속성을 심어야 하고 이 파일 밖의 변경이다 —
       실害가 "보이지 않는 것을 조작한다"에서 "보이지 않는 것을 읽는다"로 줄었으므로 여기서 멈춘다. */
  useFocusTrap(true, wrapRef);

  // 1초 틱 — FocusChip 과 같은 관용구. 두 곳이 같은 스토어를 읽을 뿐이라 타이머가 갈리지 않는다.
  /* ⚠ 세션이 없으면 돌리지 않는다(H24). `FocusChip` 은 같은 가드를 갖고 있었는데 여기만 빠져서,
     미니 창을 띄운 채 세션이 끝나면('세션 종료' 표시) 1초마다 무의미한 리렌더가 무기한 이어졌다. */
  useEffect(() => {
    if (!session) return;
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, [session]);

  /* W9 — 창 높이는 캡처 열림의 함수다. 닫힐 때 반드시 줄인다(안 줄이면 알약이 영구히 커진다).
     ⚠ 언마운트에서도 줄인다: 세션이 끝나 미니가 통째로 사라질 때 캡처가 열려 있었으면
     복귀 크기 계산(`exitMini`)이 132px 을 물고 간다. */
  useEffect(() => {
    void setMiniCaptureWindow(capture);
    return () => {
      if (capture) void setMiniCaptureWindow(false);
    };
  }, [capture]);

  const leftSec = session ? Math.max(0, Math.round((session.endsAt - now) / 1000)) : 0;
  /* ⚠ 복원 실패면 그대로 알약에 머문다(H9 · `lib/miniMode.exitMini` 주석이 근거) — 나가는 문을
     들고 있는 것이 이 화면이라, 여기서 라우팅해 버리면 그 문이 사라진다. */
  const expand = async (): Promise<void> => {
    const back = await exitMini();
    if (back) navigate(back, { replace: true });
    else toast('창을 되돌리지 못했어요 — 다시 시도해 주세요.', 'bad');
  };

  /* Q-26 — 캡처를 닫는다. 잠깐 들어온 것이면 창까지 되돌린다.
     ⚠ **복원 실패면 알약에 머문다** — `expand` 와 같은 규율이다(라우팅해 버리면 나갈 문이
     사라진다). 대신 그 사실을 말한다: 조용히 남으면 "왜 안 커지지"가 된다. */
  const doneCapture = async (): Promise<void> => {
    setCapture(false);
    if (miniMode() !== 'capture') return;
    const back = await exitMini();
    if (back) navigate(back, { replace: true });
    else toast('창을 되돌리지 못했어요 — 펼치기로 다시 시도해 주세요.', 'bad');
  };

  return (
    <div className={WRAP} data-mini="1" ref={wrapRef} tabIndex={-1}>
      <div className="flex w-full flex-col gap-2">
        <div className="flex items-center gap-3">
          {session ? pill(leftSec, session, expand, stop) : <ResidentPill expand={expand} />}
        </div>
        {/* W9 — 전역 캡처 핫키의 착지. 같은 창 · 높이 92→132 · 제출 즉시 알약으로 복귀.
            ⚠ Q-26 — **잠깐 들어온 미니는 캡처가 끝나면 나간다.** 손으로 들어온 미니 모드는
            그대로 머문다(그게 그 사람이 요청한 창 모드다) — `wasTransient()` 가 그 둘을 가른다.
            판정을 여기서 하는 이유: 나가는 문을 들고 있는 것이 이 화면이다(위 `expand` 와 같은 논거). */}
        {capture && <MiniCapture onDone={() => void doneCapture()} />}
      </div>
    </div>
  );
}

/* ── N-20 **상주 알약**(W3 · 발산 6회차) ─────────────────────────────────────────
   ⚠⚠ 종전에 세션이 없는 알약이 말하던 것은 문자열 `'세션 종료'` 하나였다 — 즉 이 창은
   **집중 세션의 부속물**이라 세션 밖에서는 죽은 표면이었다. 그런데 320×92 always-on-top 알약은
   이 앱이 가진 유일한 *상시* 표면이고(작업표시줄 배지는 창을 숨기면 사라지고 트레이 툴팁은
   마우스를 올려야 보인다), 그 자리에 아무것도 안 쓰는 것은 표면을 버리는 것이다.

   말할 것은 **이미 있다**: 알림(A-1)·트레이 툴팁(A-6)이 쓰는 그 리드다. 세 채널이 같은 함수를
   쓰는 것이 요지 — 하나는 "회로이론 3장"이라 하고 다른 하나는 "대기 3건"이라 하면 사용자는
   둘을 다른 것으로 읽는다(옛 `lib/reminder.trayTooltip` 주석이 세운 규율 · 그 함수는 I049 로 은퇴).
   ⚠ 여기서도 **수를 안 쓴다.** 알약은 시야 안에 상주하므로 알림과 같은 부류다(말을 건다) —
     밀린 수를 상시 노출하면 그게 곧 A-1 이 없앤 회피 유발자의 영구판이 된다. */
function ResidentPill({ expand }: { expand: () => Promise<void> }): React.JSX.Element {
  const st = useApp((s) => s.state);
  const navigate = useNavigate();
  const { lead } = useMemo(
    () =>
      pickReminderLead({
        chapters: riskChapters(st, selectSchedule(st).days, todayISO(st), 1),
        backlog: openBacklog(st),
        reviewMin: reviewBlockMin(st.moduleLen || 120),
      }),
    [st],
  );
  /* 펼치면서 그 조각으로 간다 — 알약이 이름을 말했는데 펼침이 왔던 곳으로 돌아가면
     "말한 것"과 "간 곳"이 어긋난다(알림 착지가 고친 것과 같은 어긋남). */
  const go = async (): Promise<void> => {
    if (!(await exitMini())) return toast('창을 되돌리지 못했어요 — 다시 시도해 주세요.', 'bad');
    navigate(lead?.route ?? '/today', { replace: true });
  };
  return (
    <>
      <i className={DOT} aria-hidden="true" />
      <span className="min-w-0 flex-1 overflow-hidden text-sm font-bold text-ellipsis whitespace-nowrap text-ink">
        {lead ? lead.label : '오늘 몫은 끝났어요'}
      </span>
      <button
        type="button"
        className={BTN}
        onClick={() => void go()}
        title={lead ? `${lead.label} 하러 가기` : '앱 창으로 펼치기'}
        aria-label={lead ? `${lead.label} 화면으로 펼치기` : '앱 창으로 펼치기'}
      >
        <Icon name="play" />
      </button>
      <button type="button" className={BTN} onClick={() => void expand()} title="펼치기" aria-label="앱 창으로 펼치기">
        ⤢
      </button>
    </>
  );
}

/** 알약 본체(시간·이름·버튼) — 캡처 줄과 세로로 쌓기 위해 한 함수로 뽑았다. */
function pill(
  leftSec: number,
  session: { name: string },
  expand: () => Promise<void>,
  stop: () => void,
): React.JSX.Element {
  return (
    <>
      <i className={PULSE} aria-hidden="true" />
      {/* ⚠ `<b>` 는 **제네릭 롤**이라 `aria-label` 이 조용히 무시된다(H11 부수 · 2026-07-30).
          그래서 스크린리더는 맥락 없이 "12:34" 만 읽었다 — 그 숫자가 남은 시간인지 알 수 없다.
          `role="img"` 을 주면 라벨이 유효해진다(같은 저장소가 `NextActions`·`Discovery` 에서
          이미 쓰는 관용구). 시각 표현은 한 글자도 안 바뀐다. */}
      <b className={TIME} role="img" aria-label={`남은 시간 ${mmss(leftSec)}`}>
        {mmss(leftSec)}
      </b>
      <span className={NAME}>{session.name}</span>
      <button type="button" className={BTN} onClick={() => void expand()} title="펼치기" aria-label="앱 창으로 펼치기">
        ⤢
      </button>
      <button
        type="button"
        className={BTN}
        onClick={() => {
          stop();
          void expand();
        }}
        title="집중 중단"
        aria-label="집중 타이머 정지하고 펼치기"
      >
        ■
      </button>
    </>
  );
}

/* ── W9 미니 캡처 — 알약이 **그 자리에서** 캡처 한 줄이 된다 ─────────────────────────
   전역 핫키(`hotkey.rs`)의 유일한 값 구간이 "집중 세션 중"이고 그 구간의 창은 320×92 알약인데,
   착지는 무조건 풀사이즈 ⌘K 팔레트였다 — 알약 뷰포트 안에서 뜬다. 새 라우트를 만들지 않는 것이
   이 안의 제약이다(드롭된 `/capture` 를 되살리지 않는다): 같은 창 · 높이 92→132 · 제출 즉시 복귀.
   ⚠ 저장은 **데스크톱 ⌘Enter 와 같은 함수**(`commitCapture`)다 — 캡처 입구가 셋인데 결말이
     갈리면 그게 곧 조용한 데이터 손실이다(D-2·W8 이 같은 부류에 물렸다).
   ⚠⚠ ~~"폰 캡처 바와 같은 함수"는 사실이 아니었다(G7 · 2026-07-31 `/감사 근본`)~~ → **2026-08-01
     에 참이 됐다.** G7 이 잡은 것은 이랬다: `phone/CaptureBar` 는 레이어 규약상 `@/shell` 을
     import 할 수 없어 커밋 사슬을 **따로 갖고** 있었고, 공유되는 것은 레코드 조립까지였다 —
     세 입구 중 둘만 같은 함수였다. 지금은 **파싱부터 저장까지 `lib/quickCapture.fileCapture`**
     하나이고 세 입구가 전부 그걸 부른다. 갈리는 것은 표시뿐이다(여기·⌘K 는 되돌리기 토스트,
     폰은 6초 인라인 확인 줄 — 폰엔 토스트 자리가 없다).
   ⚠ 로드맵(H22)은 이 수렴을 `hooks → shellToast` 정책 변경에 묶어 뒀는데 **필요 없었다** —
     갈려 있던 것은 데이터 경로이고 그건 순수 lib 이다. */
function MiniCapture({ onDone }: { onDone: () => void }): React.JSX.Element {
  const [text, setText] = useState('');
  const ref = useRef<HTMLInputElement>(null);
  /* 마운트 포커스 — 이 컴포넌트는 **열릴 때만** 마운트된다(그래서 입력 초기화도 공짜다:
     닫으면 언마운트라 다음에 열 때 빈 줄이다. 이펙트에서 setState 로 지우면 그건 캐스케이드다). */
  useEffect(() => ref.current?.focus(), []);

  const submit = (): void => {
    const raw = text.trim();
    if (raw) commitCapture(raw, '');
    onDone();
  };
  return (
    <input
      ref={ref}
      type="text"
      className="w-full text-sm"
      value={text}
      onChange={(e) => setText(e.target.value)}
      onKeyDown={(e) => {
        // ⚠ 트랩(H11)이 Esc 를 안 먹는다 — 여기서 먼저 잡아 캡처만 닫는다(창은 알약으로 복귀).
        if (e.key === 'Escape') {
          e.stopPropagation();
          onDone();
        } else if (e.key === 'Enter') submit();
      }}
      placeholder="떠오른 것 한 줄 — Enter 로 보충에 담기"
      aria-label="빠른 캡처"
    />
  );
}

