  // Q-12 — 내비 스택. 라우터가 소유한 히스토리를 그대로 쓴다(자체 스택을 만들면 딥링크·⌘K·
  // 리다이렉트가 만든 이동을 놓친다).
  const navigate = useNavigate();
  // 팔레트·치트시트 열기는 스토어가 소유 — 예전엔 전자가 App 에서 내려오는 prop, 후자가
  // `window.dispatchEvent('lh:open-shortcuts')` 라는 DOM 이벤트 우회였다(같은 일, 두 배선).
  const openPalette = useOverlay((s) => s.setPalette);
  const openHelp = useOverlay((s) => s.setHelp);
  // ⚠ 정본(`state.theme`)이 아니라 **해소된** 테마다(H9) — 시스템 따라가기가 켜져 있으면
  //    정본과 화면이 다를 수 있고, 그때 정본을 읽으면 이 버튼이 반대 방향을 말한다.
  const theme = useTheme();
  const readouts = usePageChrome((s) => s.readouts);
  const primary = usePageChrome((s) => s.primary);
  const action = usePageChrome((s) => s.action);
  const [moreOpen, setMoreOpen] = useState(false);
  const wrapRef = useRef<HTMLDivElement>(null);
  const impRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!moreOpen) return;
    const onDown = (e: MouseEvent) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) setMoreOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setMoreOpen(false);
    };
    document.addEventListener('mousedown', onDown, true);
    document.addEventListener('keydown', onKey, true);
    return () => {
      document.removeEventListener('mousedown', onDown, true);
      document.removeEventListener('keydown', onKey, true);
    };
  }, [moreOpen]);

  const close = () => setMoreOpen(false);

  /* 되돌리기 백업의 존재·시각 — **메뉴를 여는 클릭이** 읽는다.
     ⚠ 렌더에서 읽으면 `Date.now()` 라 순수성 린트가 막고(옳다 — 시계는 렌더의 입력이 아니다),
       이펙트에서 읽으면 setState-in-effect 라 또 막힌다. 남는 정당한 자리가 이벤트 핸들러이고,
       마침 그게 의미도 맞다: **여는 순간이 "지금 알고 싶다"는 신호**다.
     ⚠ 마운트 시 한 번 읽는 방식은 안 된다 — 세션 내내 낡아 "방금"이라 적힌 3시간 전이 된다. */
  const [undoWhen, setUndoWhen] = useState<string | null>(null);
  const openMore = () => {
    const next = !moreOpen;
    if (next) {
      // ⚠ 갱신은 여는 쪽에서만 — 상태 업데이터 안에서 하면 StrictMode 이중 호출에 부작용이 두 번 돈다.
      const b = backupAt();
      setUndoWhen(b ? (b.at == null ? '시각 모름' : agoLabel(b.at, Date.now())) : null);
    }
    setMoreOpen(next);
  };
  const undoInfo = undoWhen !== null;

  return (
    <header className={BAR}>
      <h1 className={WORDMARK}>
        <span className={MARK_PART}>러닝</span>
        {/* W22 — 워드마크의 발광을 껐다(액센트 예산은 **행동과 상태**에만). 색으로 브랜드는 그대로
            읽히고, 값(44px `primary`)이 크롬과 경쟁하지 않는다. */}
        <span className={`${MARK_PART} font-[var(--emph-value-weight)] text-acc`}>허브</span>
      </h1>
      <span className={SUB}>오늘 할 일에 집중해요 — 계획·복습·일정은 자동으로</span>
      <span className="flex-1" />
      {/* 전역 집중 세션 칩 — 어느 탭에서든 진행 중 세션이 보인다(클릭 → 오늘). */}
      <FocusChip />
      {primary && (
        <div className={`${PRIMARY} ${readouts.length > 0 ? 'mr-7.5' : 'mr-2'}`}>
          <span className={RL}>{primary.label}</span>
          {/* Q-17 — 이 자리가 `<Num>` 이 추출된 원본이다. 크기·색·중량은 계속 `PV` 가 갖고,
              "단위는 값보다 작고 흐리다"는 비율만 프리미티브로 갔다(`components/Num` 머리주석). */}
          <Num className={PV} value={primary.value} unit={primary.unit} />
        </div>
      )}
      {readouts.length > 0 && (
        <div className={READOUTS}>
          {readouts.map((r, i) => (
            <div key={i} className={READOUT}>
              <span className={RL}>{r.label}</span>
              <span className={`${RV} ${r.value === '—' ? RV_NULL : r.accent ? RV_ACC : ''}`}>{r.value}</span>
            </div>
          ))}
        </div>
      )}
      <div className={ACTIONS}>
        {/* ── Q-12 내비 스택 ────────────────────────────────────────────────────────────
            🌍 격차표 _"왔던 길(BackStack) — 뒤로는 이전 위치로"_ 대비 우리 현재는 **없음**
            이었다(`navigate(-1)`·`history.back` 앱 전량 0건). 그래서 "방금 그 화면"으로
            돌아가려면 **이름으로 다시 찾아가야** 했다 — `lastLens` 가 있었지만 레일 한 경로·
            세션 한정이라(자기 주석이 자인) 일반 후퇴가 아니었다.
            ⚠ 활성/비활성을 그리지 않는다: 브라우저 히스토리 길이는 표준으로 읽을 수 없고
            (`history.length` 는 다른 오리진 항목까지 센다), 없는 정보를 아는 척하면 비활성
            버튼이 거짓말이 된다. 눌러서 아무 일도 안 나는 편이 정직하다. */}
        <button className={BTN_ICON} onClick={() => navigate(-1)} title="뒤로 (Alt+←)" aria-label="이전 화면으로">
          ‹
        </button>
        <button className={BTN_ICON} onClick={() => navigate(1)} title="앞으로 (Alt+→)" aria-label="다음 화면으로">
          ›
        </button>
        {action && (
          <button className={`${BTN_BASE} ${BTN_FILL}`} onClick={action.onClick}>
            {action.label}
          </button>
        )}
        <button
          className={BTN}
          onClick={() => openPalette(true)}
          title={`명령 팔레트 (${MOD_LABEL}+K)`}
          aria-label="명령 팔레트 열기"
        >
          {MOD_K_LABEL}
        </button>
        {/* C-12: 단축키 치트시트는 '?' 키·팔레트로만 열려 발견성이 낮았다 — 눈에 보이는 진입점. */}
        <button
          className={BTN_ICON}
          onClick={() => openHelp(true)}
          title="키보드 단축키 (?)"
          aria-label="키보드 단축키 보기"
        >
          ?
        </button>
        <button
          className={BTN_ICON}
          onClick={() => toggleTheme()}
          title={`테마: ${THEME_NAME[theme]} — 클릭하면 ${THEME_NEXT[theme]}로`}
          aria-label={`테마 전환 (현재 ${THEME_NAME[theme]})`}
        >
          <Icon name={THEME_ICON[theme]} className="size-4!" />
        </button>
        {/* ⋯ 메뉴 — 디스클로저(aria-expanded)로만 선언. role=menu는 화살표 내비·포커스 이동(APG)
            계약을 요구하는데 이 목록은 Tab 이동이라 role이 SR 기대만 깨뜨렸다(제거가 정확). */}
        <div className="relative" ref={wrapRef}>
          <button
            className={BTN_ICON}
            aria-expanded={moreOpen}
            onClick={openMore}
            title="데이터·백업 메뉴"
            aria-label="데이터·백업 메뉴"
          >
            ⋯
          </button>
          {moreOpen && (
            <div className="menu">
              <button
                type="button"
                onClick={() => {
                  close();
                  exportICS();
                }}
                title="일회성 스냅샷"
              >
                <Icon name="calendar" /> 캘린더(.ics) 내보내기
              </button>
              <button
                type="button"
                onClick={() => {
                  close();
                  exportJSON();
                }}
              >
                <Icon name="download" /> 데이터 내보내기(백업)
              </button>
              <button
                type="button"
                onClick={() => {
                  close();
                  impRef.current?.click();
                }}
              >
                <Icon name="upload" /> 데이터 가져오기
              </button>
              {/* ⚠ **언제 것인지 말한다.** 종전엔 라벨이 그냥 '되돌리기' 이고 백업이 없어도
                  눌렸다 — 누르면 "직전"이 아니라 *마지막 파괴적 동작 시점*(며칠 전일 수 있다)
                  으로 갔고, 그 사실이 화면 어디에도 없었다. 되돌리기가 조용히 며칠을 지우면
                  그건 안전망이 아니라 두 번째 사고다.
                  ⚠ 백업이 없으면 **비활성**이다(누르고 나서 토스트로 실패를 아는 것보다 낫다).
                  ⚠⚠ **라벨이 '스냅샷 복원'으로 바뀌었다**(근본① · 2026-08-01). 평범한 편집은 이제
                  전역 ⌘Z 가 덮으므로, 이 항목이 덮는 것은 **가져오기·초기화 직전**뿐이다 —
                  `backupNow()` 를 부르는 곳이 그 둘로 좁아졌기 때문이다(feature 삭제 경로에서 뺐다).
                  즉 위 "며칠 전" 문제의 원인이 사라졌고, 라벨이 그 사실을 정확히 말한다.
                  ⚠ 이 항목을 지우지 않은 이유: 스냅샷을 **유지**하기로 한 이상 6.5초 토스트가
                  유일한 접근로면 그건 유지가 아니다(창을 놓치면 도달 불가). ⌘Z 는 이 층을
                  **대체하지 않는다** — 통째 교체는 `undo` 스택에 안 쌓는다(`db/write.ts`). */}
              <button
                type="button"
                disabled={!undoInfo}
                onClick={() => {
                  close();
                  undoLast();
                }}
                title={
                  undoInfo
                    ? `가져오기·초기화 직전 스냅샷으로 되돌리기 (백업 ${undoWhen})`
                    : '복원할 스냅샷이 없습니다 — 가져오기·초기화 직전에 자동으로 만들어집니다. 평범한 편집은 ⌘Z 로 되돌려요'
                }
              >
                <Icon name="undo" /> 스냅샷 복원
                {undoInfo ? <span className="ml-auto text-2xs text-mut">{undoWhen}</span> : null}
              </button>
              <div className="menu-sep" />
              <button
                type="button"
                className="menu-danger"
                onClick={() => {
                  close();
                  resetAll();
                }}
              >
                <Icon name="trash" /> 전체 초기화…
              </button>
            </div>
          )}
        </div>
      </div>
      {/* importJSON(input)이 id="imp"의 .files를 읽는다 — 팔레트의 '가져오기'도 이 입력을 클릭. */}
      <input
        type="file"
        id="imp"
        ref={impRef}
        accept="application/json"
        className="hidden"
        onChange={(e) => importJSON(e.currentTarget)}
      />
    </header>
  );
}

/* ============================================================
   DetailDrawer — 단일화면 대시보드 위에 띄우는 우측 슬라이드 패널(온디맨드 세부).
   today의 '오늘 상세' 오버레이를 컴포넌트화 — 데이터보드형 탭이 깊은 차트·표를 여기로 뺀다.
   순수 표현(components → lib만): open/onClose/title/children. Esc·바깥 클릭으로 닫힘.
============================================================ */
import { useEffect, useRef, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { useFocusTrap } from '@/hooks/useFocusTrap';
import { useScrollLock } from '@/hooks/useScrollLock';

/* ── C-7 컴포넌트 티어 이식(Tailwind) ──────────────────────────────────────────
   ⚠ 원본은 `.overlayCenter .panel` 이라는 **조상 변형 자손 셀렉터**로 두 벌 기하를 갈랐다.
   규약 4 대로 자손에 직접 클래스를 준다 — placement 가 이미 prop 이므로 정적 맵 두 벌이면 된다
   (부칙: 동적 조립 금지 · 문자열이 통째로 소스에 있어야 Tailwind 가 클래스를 만든다).
   ⚠ 그리고 §15-8 ② — **한 속성은 한 문자열이 소유한다**: base 에 `justify-end` 를 두고 변형에서
   `justify-center` 로 덮으면 클래스 순서가 아니라 방출 순서로 갈린다. 정렬·폭·반경·보더처럼
   두 벌이 다른 속성은 전부 변형 쪽이 통째로 갖는다.
   닫기 버튼(`<button>`)은 언레이어드 전역 `button{}` 을 이겨야 하므로 해당 속성에 `!`. */
const OVERLAY_BASE =
  'fixed inset-0 z-[var(--z-modal)] flex bg-overlay backdrop-blur-overlay motion-reduce:animate-none';
/* 진입 애니는 별도로 뺐다(morphName 일 때 끄기 위해). View Transitions morph 로 여는 경우
   드로어 자체의 enter-pop/enter-fade 가 켜져 있으면 **새 스냅샷이 pop 시작(작고 투명) 상태로 잡혀**
   morph 가 "투명한 것으로 변형"이 된다 — 그래서 morph 열림에선 이 둘을 끄고 VT 가 전담한다. */
const OVERLAY_ENTER = 'animate-[enter-fade_var(--dur-fast)_var(--ease)]';
const OVERLAY = {
  right: 'justify-end',
  center: 'items-center justify-center px-drawer-pad-x py-drawer-pad-y max-mobile:p-0',
} as const;
const PANEL_BASE = 'flex w-full flex-col bg-bg shadow-float motion-reduce:animate-none';
const PANEL = {
  right: 'h-full max-w-drawer border-l border-line max-mobile:max-w-none max-mobile:border-l-0',
  center:
    'h-auto max-h-full max-w-drawer-sheet rounded-lg border border-line max-mobile:h-full max-mobile:max-h-none max-mobile:rounded-none max-mobile:border-0',
} as const;
const PANEL_ENTER = {
  right: 'animate-[enter-slide_var(--dur)_var(--ease)]',
  center: '[--pop-y:0] animate-[enter-pop_var(--dur)_var(--ease)]',
} as const;
const HEAD = 'flex flex-none items-center justify-between gap-3 border-b border-line px-5 py-4 text-md tracking-label';
/* 제목은 줄어들고 넘치면 말줄임 — min-w-0 이 없으면 flex 항목이 콘텐츠 폭 아래로 못 줄어
   좁은 시트에서 닫기 버튼을 패널 밖으로 밀어낸다. */
const TITLE = 'min-w-0 overflow-hidden text-ellipsis whitespace-nowrap';
/* ⚠ padding 을 건드리지 않는다 — 원본 `.panelX` 도 안 건드렸고, 실제 렌더는 전역 `button{}` 의
   8px 13px 이다(32×32 고정 박스 안이라 보이지는 않는다). 유틸로 0 을 주면 그건 이식이 아니라
   변경이다(절대규칙 #4). */
const CLOSE = 'size-8 flex-none rounded-chip! border! border-line! bg-transparent! text-ink! hover:bg-panel2!';
const BODY = 'min-h-0 flex-1 overflow-y-auto px-5 pt-4.5 pb-7 [scrollbar-width:thin]';

export default function DetailDrawer({
  open,
  onClose,
  title,
  children,
  placement = 'right',
  morphName,
}: {
  open: boolean;
  onClose: () => void;
  title: string;
  children: ReactNode;
  /** 'right'=우측 슬라이드 패널(기본·today 패턴) · 'center'=탭 프레임보다 작은 중앙 시트.
      중앙 시트는 "목록은 그대로 두고 한 항목만 파고든다"는 용도 — 뒤 목록의 조망을 깨지 않는다(과목 상세). */
  placement?: 'right' | 'center';
  /** View Transitions 공유요소 morph 이름(호출부가 여는 원본과 짝지어 준다). 주면 패널이 이 이름을
      갖고 진입 애니(enter-pop/enter-fade)를 끈다 — VT 가 원본→패널 morph 를 전담한다. 없으면 기존 동작. */
  morphName?: string;
}) {
  const panelRef = useRef<HTMLDivElement>(null);
  useFocusTrap(open, panelRef); // 포커스 트랩 + 복원(접근성 — aria-modal 선언만 있고 관리가 없던 결함 보완).
  useScrollLock(open); // 배경 스크롤 잠금 — 트랩의 짝(포커스가 안 새듯 스크롤도 안 새야 한다).
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [open, onClose]);

  if (!open) return null;
  // body로 포털 — 셸(#main 조상)이 스태킹 컨텍스트를 만들어, 여기 그대로 두면 position:fixed가 뷰포트가 아니라
  // 그 조상 박스를 기준으로 잡히고 z-index도 그 안에 갇힌다(헤더·사이드바가 오버레이를 덮고 패널 헤드가 잘림).
  // 모달은 뷰포트에 고정돼야 하는 물건이라 문서 최상위에서 그린다.
  return createPortal(
    /* 오버레이 클릭-닫기는 마우스 편의 레이어다. 키보드 경로는 셋 다 갖춰져 있다 —
       ESC(아래 useEffect) · useFocusTrap(진입 포커스 + Tab 순환 + 닫을 때 복원) · 헤더의
       진짜 닫기 버튼(aria-label="닫기"). 린트는 그 셋을 볼 수 없다. */
    // eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-noninteractive-element-interactions
    <div
      className={`${OVERLAY_BASE} ${OVERLAY[placement]}${morphName ? '' : ` ${OVERLAY_ENTER}`}`}
      role="dialog"
      aria-modal="true"
      aria-label={title}
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div
        className={`${PANEL_BASE} ${PANEL[placement]}${morphName ? '' : ` ${PANEL_ENTER[placement]}`}`}
        ref={panelRef}
        tabIndex={-1}
        style={morphName ? { viewTransitionName: morphName } : undefined}
      >
        <div className={HEAD}>
          <b className={TITLE} title={title}>
            {title}
          </b>
          <button type="button" className={CLOSE} onClick={onClose} aria-label="닫기">
            ✕
          </button>
        </div>
        <div className={BODY}>{children}</div>
      </div>
    </div>,
    document.body,
  );
}

/* ============================================================
   Alloc — 계획 › '배분' 세그먼트. 옛 배치 탭의 alloc 뷰를 독립 탭으로 승격(계획 재개편 v4).
   질문 "이번 주, 어느 과목을 어느 요일에 얼마씩?" — 캘린더(언제 할까)와 리듬이 다르다:
   배분은 주(週) 단위로 한 번 정하는 '전략', 캘린더는 매일 보는 '전술'. 뷰 스위치 안에 섞여 있으면
   계획의 축이 흐려져 세그먼트로 분리했다([캘린더 · 배분 · 과목] 순).

   보드 자체(과목행×요일열 매트릭스)는 AllocBoard가 소유 — 여긴 주 네비·리드아웃·드릴다운 배선만.
   ⚠ features → features import 금지(boundaries)라 AllocBoard가 schedule/에서 여기로 물리 이주했다.
============================================================ */
import { useNavigate, useSearchParams } from 'react-router-dom';
import { useApp } from '@/store/useApp';
import { useUI } from '@/store/useUI';
import { useSchedule, useStudyMinByWeekday } from '@/store/selectors';
import { usePageChromeEffect } from '@/store/usePageChrome';
import { exportICS } from '@/shell';
import { weekLabel, ddayInfo, hNum, hLabel, iso, addDays, parseISO } from '@/lib/utils';
import { useTodayISO } from '@/hooks/useTodayISO';
import { weekAllocTotalMin, weekBudgetMin as weekBudgetMinOf, weekDoneNewMin } from '@/lib/weekAlloc';
import { deadlineDdays } from '@/lib/scheduleView';
import { Button } from '@/components/ui';
import { useWeekOffset } from '@/hooks/useWeekOffset';
import { AllocBoard } from './AllocBoard';
import { Icon } from '@/components/Icon';

/* Alloc 세그먼트 셸 — 옛 CSS Module 을 Tailwind 유틸로 이식(C-7). 주 네비 크롬만 소유(보드는 AllocBoard).
   ⚠ 내장 크기 이름(text-lg/sm)은 preflight 없는 이 앱에서 companion line-height 를 흘리므로 정상흐름
   요소엔 leading-text(본문 상속)을 명시로 못박는다. 자간 -0.01em 은 사다리 밖이라 tracking-wk 로 이름. */
const C = {
  wrap: 'flex h-full min-w-0 flex-col',
  nav: 'flex flex-none flex-wrap items-center gap-2.5 border-b border-line px-5.5 py-3.5',
  // 주 이동 클러스터 — 한 덩어리(1 1 260px). 버튼 세로 붕괴 방지로 자식 Button 에 whitespace-nowrap.
  wknav: 'flex min-w-0 shrink grow basis-65 items-center gap-2.5',
  wk: 'min-w-22.5 flex-1 text-center',
  wkLab: 'text-lg leading-text font-extrabold tracking-wk whitespace-nowrap',
  wkOff: 'ml-1.5 text-sm leading-text font-semibold whitespace-nowrap text-mut',
  // 지난주 대조 한 줄 — 주 네비 오른쪽 끝(보드 바로 위).
  prev: 'ml-auto text-sm leading-text whitespace-nowrap text-mut tabular-nums',
  body: 'min-h-0 flex-1',
};

export default function Alloc() {
  const state = useApp((s) => s.state);
  const res = useSchedule();
  const capWd = useStudyMinByWeekday();
  const navigate = useNavigate();
  const setSchedView = useUI((s) => s.setSchedView);
  const todayIso = useTodayISO(state); // 앱의 '오늘' 단일 출처(_today 시드 존중 · 자정 자동 롤오버 H20)

  // 주 네비(오프셋 상태 · , / . 단축키 · 배지 라벨)는 useWeekOffset 단일 기계가 소유 —
  // 예전엔 todayOff 산식·useState·useWeekNavKeys가 캘린더와 글자까지 같은 모양으로 복제돼 있었다.
  // ⚠ 훅이 내부에서 useWeekNavKeys를 등록하므로 여기서 또 등록하면 이중 이동이 된다.
  /* N-12(W4) — **주가 주소를 갖는다.** `/week/:ws` 가 여기로 착지하고 `?week=` 로 어느 주인지를
     말한다. 초기값일 뿐이라 그 뒤엔 `,`/`.` 가 이긴다(주소가 상태를 계속 강제하면 화면 안에서
     주를 못 넘긴다 · 근거는 `useWeekOffset` 의 `startMon` 주석). */
  const [params] = useSearchParams();
  const { rel, prev, next, weekToday, isThisWeek, offsetLabel, curMon, weekMon } = useWeekOffset(state, {
    startMon: params.get('week') ?? undefined,
  });

  // 분자·분모 모두 weekAlloc의 단일 집계를 쓴다 — 각자 필터를 굴리던 시절엔 주당 0h 과목이
  // 분자에만 들어가 "4.0 / 2.0h · 예산 달성 200%" 같은 오염이 났다(집합 불일치).
  const weekAllocMin = weekAllocTotalMin(state, res, weekMon);
  // 주당 예산 합(스케줄 가능한 주간 과목 weeklyHours) — 배분이 채워가는 목표. '가용 총량'(수십 h)보다 배분과 직접 관계돼 리드아웃에 적합.
  const weekBudgetMin = weekBudgetMinOf(state);
  const allocPct = weekBudgetMin > 0 ? Math.round((weekAllocMin / weekBudgetMin) * 100) : 0;
  /* 지난주 대조 — **다음 주 숫자를 정하는 자리에 유일하게 없던 근거**(Later).
     보드는 "이번 주 얼마를 배분했나"만 말했고, "지난주엔 그 배분이 얼마나 지켜졌나"는 어디에도
     없었다. 새 데이터는 0이다(배분·완료 둘 다 이미 있다).
     ⚠ `new` 타입으로 좁힌 이유는 `weekDoneNewMin` 머리주석 — 안 좁히면 비교 불가능한 대조가 된다.
     ⚠ **이번 주에는 안 그린다**(진행 중이라 실제가 늘 모자라 보인다 = 매일 지는 게임). */
  const prevMon = iso(addDays(parseISO(weekMon), -7));
  const prevAllocMin = weekAllocTotalMin(state, res, prevMon);
  const prevDoneMin = weekDoneNewMin(state, prevMon);
  const showPrev = isThisWeek && prevAllocMin > 0;
  const ddays = deadlineDdays(res.itemStat, todayIso);
  const nearestDday = ddays.length ? ddays[0]!.dday : null;

  usePageChromeEffect(
    () => ({
      /* N-15 `primary` — 이 탭에서 먼저 읽어야 할 하나(예산을 얼마나 채웠나). 종전엔 리드아웃
         셋이 같은 30px 로 나란히 서서 "무엇을 먼저 보라"를 아무도 말하지 않았다.
         ⚠ 시그니처 비주얼(배분 보드 매트릭스)은 본문 한복판이라 상단 44px 과 읽는 순서가
           겹치지 않는다 — `stats` 회전 스파인과 같은 판단. */
      primary: weekBudgetMin ? { value: String(allocPct), unit: '%', label: '예산 달성' } : null,
      readouts: [
        {
          label: '이번 주 배분',
          value: (
            <>
              {hNum(weekAllocMin)}
              <small className="text-base14 font-bold text-mut"> / {hLabel(weekBudgetMin)}</small>
            </>
          ),
          accent: true,
        },
        /* ⚠ 옛 '예산 달성' 리드아웃은 **44px `primary` 로 승격**돼 여기서 사라졌다. 남겨 두면
           같은 수치가 한 화면에 두 번(그중 하나는 제일 크게) 뜨고, 그건 위계를 만드는 것이
           아니라 없애는 것이다 — 승격의 요점은 *하나를 크게*이지 *하나를 더*가 아니다.
           ⚠ 예산이 0이라 primary 를 못 세우는 경우에만 종전 자리로 되돌린다(그때는 위계를
           말할 대상 자체가 없다). */
        ...(weekBudgetMin ? [] : [{ label: '예산 달성', value: '—' }]),
        // D-day 라벨은 정본 헬퍼가 소유 — 직접 `D-${dday}`를 조립하면 오늘 마감이 "D-0"으로 샌다.
        { label: '마감', value: nearestDday == null ? '—' : ddayInfo(nearestDday).lab },
      ],
      action: !isThisWeek
        ? { label: '이번 주로 →', onClick: weekToday }
        : { label: '캘린더(.ics) 내보내기', onClick: () => exportICS() },
    }),
    [weekAllocMin, weekBudgetMin, allocPct, nearestDday, rel],
  );

  return (
    <section className={C.wrap} aria-label="주간 배분">
      <div className={C.nav}>
        <div className={C.wknav}>
          <Button sm className="whitespace-nowrap" onClick={prev}>
            <Icon name="chevronLeft" /> 이전 주
          </Button>
          <div className={C.wk}>
            <b className={C.wkLab}>{weekLabel(curMon)}</b>
            <span className={C.wkOff}>{offsetLabel}</span>
          </div>
          <Button sm className="whitespace-nowrap" onClick={next}>
            다음 주 <Icon name="chevronRight" />
          </Button>
          <Button sm variant="ghost" className="whitespace-nowrap" onClick={weekToday}>
            오늘
          </Button>
        </div>
        {/* 지난주 대조 — **상단 크롬이 아니라 여기**다. 크롬은 primary(44px)+리드아웃 3+액션으로
            이미 폭을 다 써서 4번째를 얹으면 형제 라벨이 두 줄로 접힌다(실렌더로 확인). 그리고
            이 값의 집은 원래 여기가 맞다: 다음 주 숫자를 정하는 보드 **바로 위**에 있어야
            근거로 읽힌다(크롬에 있으면 그냥 또 하나의 지표다). */}
        {showPrev ? (
          <span className={C.prev} title="지난주 새 학습: 실제로 해낸 시간 / 배분했던 시간">
            지난주 <b className="font-extrabold text-txt">{hNum(prevDoneMin)}</b>
            <span className="text-mut"> / {hLabel(prevAllocMin)} 지킴</span>
          </span>
        ) : null}
      </div>

      <div className={C.body}>
        <AllocBoard
          weekMon={weekMon}
          res={res}
          capWd={capWd}
          todayIso={todayIso}
          // 셀/요일 클릭 → 캘린더 탭의 그날 일 뷰로 드릴다운(전략=보드 → 전술=타임박스).
          // 세그먼트가 갈렸으므로 날짜는 딥링크(?ds=)로, 뷰 전환은 **보내는 쪽에서 먼저** 한다
          // — 받는 쪽 effect에서 setState로 되받으면 캐스케이드 렌더가 된다(린트가 막는 패턴).
          onOpenDay={(dsPick) => {
            setSchedView('day');
            navigate(`/schedule?ds=${dsPick}`);
          }}
        />
      </div>
    </section>
  );
}

/* ============================================================
   AllocBoard — 배치 세그먼트 '배분' 뷰(재개편 v2 §12-2). 계획의 중심.
   질문 "이번 주, 어느 과목을 어느 요일에 얼마씩?" — 과목(행) × 요일(열) 매트릭스.
   각 셀=그 과목·그 요일 배분(시간). 행 끝=배분/주당예산(✓/부족/초과). 열 아래=요일 배분/가용(초과 빨강).
   첫 편집 시 자동 파생 스냅샷을 managed로 승격(dayPlans 동형) → 배분 있는 주는 스케줄러가 그 벡터로 new 구동(§12-4).
   자동엔진은 복습/Anki/모의를 그 위에 자동으로 얹으므로 여기선 '새 학습(new)' 요일 분배만 사용자가 정한다.
   (React Compiler ON — 수동 메모 없이 파생 인라인.)
============================================================ */
import { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useApp } from '@/store/useApp';
import { toast } from '@/shell';
import { addDays, iso, parseISO, fmtShort, DOW_MON, hNum } from '@/lib/utils';
import {
  allocView,
  changedAllocCells,
  colSumMin,
  copyPrevWeekAlloc,
  isUnschedulable,
  isWeekManaged,
  neglectDaysBySid,
  NEGLECT_DAYS,
  outsideVec,
  setOutsideCell,
  resetWeekAlloc,
  rowSumMin,
  setAllocCell,
  weeklyItems,
  zeroVec,
} from '@/lib/weekAlloc';
import { dayStudyMin } from '@/lib/scheduler';
import { commit } from '@/lib/motion';
import { Button, NumberField } from '@/components/ui';
import { useKeymapDoc } from '@/hooks/useKeymap';
import State from '@/components/State';
import type { ScheduleResult } from '@/lib/types';
import { Icon } from '@/components/Icon';

/* ── AllocBoard — CSS Module → Tailwind 유틸 이식(C-7) ────────────────────────────
   1px 그리드선은 grid gap + 배경(cell=panel/panel2, gap=line)으로 그린다. 셀은 role 정직한 표.
   ⚠ 이 앱은 preflight 를 빼서, **내장 크기 이름**(text-sm/lg/xs)은 companion line-height 를 흘려
     상속 LH 를 덮는다 → 정상흐름 요소엔 leading-text(또는 소스 명시값 1.55)을 못박는다.
     **폼 컨트롤(<button>·<input>)의 자손 텍스트**는 UA line-height:normal 을 상속하므로 leading-auto.
     커스텀 브리지 크기(text-2xs/md/base14)는 LH 를 안 흘리므로 leading 불필요.
   ⚠ 전역 요소규칙(button/input)은 언레이어라 레이어드 유틸을 이긴다 → 다른 값만 `!`(같으면 클래스 없음).
     colHead <button> 의 로컬 :hover 는 전역 button:hover(더 높은 명시도)에 이미 가려져 있었다 →
     되살리지 않는다(전역이 이기게 둔다 · §15). 규약 SSOT 는 §15 + tokenBridge.css 머리주석. */
const CELL = 'flex min-h-12 items-center px-2.25 py-1.75';
const S = {
  wrap: 'flex h-full min-h-0 flex-col gap-3 px-5.5 pt-3.5 pb-3 max-wide:px-3.5 max-wide:py-3',
  toolbar: 'flex flex-none flex-wrap items-center gap-3',
  // 모드 배지 — 공통 골격 + 상태별 톤 맵(자동/내 배분 · §15 정적 맵). 자간 0.08em 은 tracking-mode.
  mode: 'rounded-full border px-2.5 py-0.75 text-xs leading-text font-extrabold tracking-mode',
  modeAuto: 'border-line bg-alloc-mode-bg text-mut',
  modeManual: 'border-line-acc-hover bg-acc-glow text-acc',
  toolHint: 'min-w-0 truncate text-sm leading-text text-mut',
