  // 입력 셀 — 비례 채움(.fill) + 색띠(before) + 빈칸 호버 '+'(after) + 드롭 오버(after '+1h').
  inputCell: 'relative flex min-h-12 items-center overflow-hidden p-0 text-md',
  // UX-A3: 드롭/타이핑으로 값이 바뀔 때 농도가 "툭" 갈리지 않게. 전역 reduced-motion 백스톱이 닿는다.
  fill: 'absolute inset-0 bg-[var(--sub,var(--acc))] transition-opacity duration-base', // opacity 는 런타임 인라인
  before:
    "before:pointer-events-none before:absolute before:top-0 before:bottom-0 before:left-0 before:z-[1] before:w-0.75 before:bg-[var(--sub,var(--acc))] before:content-['']",
  hoverPlus:
    "hover:after:pointer-events-none hover:after:absolute hover:after:inset-0 hover:after:flex hover:after:items-center hover:after:justify-center hover:after:text-md hover:after:font-bold hover:after:text-alloc-plus hover:after:content-['+']",
  dropOver:
    "outline-2 -outline-offset-2 outline-dashed outline-acc after:pointer-events-none after:absolute after:inset-0 after:z-[2] after:flex after:items-center after:justify-center after:bg-acc-glow after:text-xs after:leading-text after:font-extrabold after:text-acc after:content-['+1h']",
  // UX-A2 드롭 가능 프리뷰 — 잡은 과목 행의 놓을 수 있는 칸을 드래그 **시작 시점에** 옅게 예고한다.
  // dropOver(2px 실선급 점선 + '+1h')의 한 단 아래 버전 — 같은 시각 언어라 "여기 놓을 수 있다"가
  // 한 어휘로 읽힌다. ⚠ 정적이다(애니 아님) → reduced-motion·React Compiler 어느 쪽과도 무관.
  dragHint: 'outline-1 -outline-offset-1 outline-dashed outline-line-acc-hover',
  // UX-A4 스윕 — 툴바 액션이 **실제로 바꾼** 칸만 1회 훑는다. 지연은 인라인 animation-delay.
  sweep: 'animate-[commit-ring_var(--dur-slow)_var(--ease)_both]',
  // UX-A1 가장자리 비례 막대 — 셀의 .fill 관용구를 '결론' 칸(주당 예산 · 요일 가용)에 재사용.
  edgeBar: 'pointer-events-none absolute inset-y-0 left-0',
  /* ── W23 주(週) 실루엣 — **시그니처는 "같은 숫자의 다른 축척"이다**(2026-07-31) ──────────
     매일 여는 최대 화면 둘(`alloc`·`schedule`)은 `<svg>`·`<canvas>` **0**, 히어로 토큰 **0** 이라
     시그니처가 아예 없었다. 그런데 시그니처를 새 그래픽으로 얹으면 **세로 공간을 먹고**, 이
     화면에서 반복 요구된 것은 밀도다(그게 이 안의 미실행 사유였다).
     → 새 자리를 만들지 않는다. **이미 있는 푸터 행**의 비례 막대를 가로 게이지에서 **바닥 기준
     세로 막대**로 바꾼다: 같은 수(배분/가용)를 다른 축척으로 읽으면 그 행이 곧 주간 부하의
     실루엣이 된다. 추가 높이 **0px**. */
  footBar: 'pointer-events-none absolute inset-x-0 bottom-0',
  // NumberField <input type=number> — 전역 input 규칙(언레이어)을 이기려 다른 값만 `!`.
  // color/font-size(13)/width 는 전역과 동일 → 클래스 없음. ink≡txt.
  cellInput:
    'relative z-[1] h-full min-h-12 cursor-text border-0! bg-transparent! px-1! py-0! text-center font-bold tabular-nums placeholder:font-body placeholder:text-alloc-ph! focus:-outline-offset-2! focus:bg-acc-glow! focus:outline-2 focus:outline-acc',
  // ⚠ overflow-hidden + 자식 relative z-[1] 은 UX-A1 막대 때문이다 — 막대는 절대배치라
  //   비배치 형제(숫자·배지)보다 **위에** 칠해진다. 숫자를 배치요소로 올려야 막대가 배경이 된다.
  budgetCell: `${CELL} sticky right-0 z-[3] flex-col items-end justify-center gap-px overflow-hidden text-right text-md`,
  budgetB: 'relative z-[1] text-base14 font-extrabold text-txt tabular-nums',
  budgetOf: 'relative z-[1] text-xs leading-text font-semibold text-mut',
  badge: 'relative z-[1] text-2xs',
  // ID-7 방치 배지 — 행 이름 뒤 우측 정렬 warn 핀. 예산 배지(우측 셀)와 위계·위치가 달라 오독 없다.
  neglect:
    'ml-auto flex-none rounded-full bg-tint-warn px-1.5 py-0.5 text-2xs font-bold whitespace-nowrap text-warn tabular-nums',
  footHead: `${CELL} sticky left-0 z-[3] rounded-bl-base bg-panel2 text-2xs font-extrabold tracking-widest text-mut uppercase`,
  footCell: `${CELL} relative justify-center gap-0.75 overflow-hidden text-sm leading-text text-mut`,
  footNum: 'relative z-[1] font-extrabold tabular-nums',
  footCap: 'relative z-[1] font-semibold text-mut',
  footEnd: `${CELL} sticky right-0 z-[3] rounded-br-base bg-panel2`,
  hint: 'flex-none text-sm leading-text text-mut',
  hintB: 'font-bold text-txt',
} as const;

/* 예산 셀 톤 — 상태별 정적 맵(§15 · 동적 조립 금지). 셀 배경/불투명 + 배지 색/굵기를 각각 분리.

   ⚠⚠ **`done` 이 `opacity-60` 이었고, 그게 셀의 *글자까지* 흐리게 했다**(H5 · 2026-07-30).
   실측 `#949aa5` on `#eef0f5` = **2.48:1**(기준 4.5) — "챕터 완료" 배지와 배분 숫자가 사실상
   안 읽혔다. 라이트 대비 검사가 `/today` 한 화면만 보고 있어서 몇 달간 아무도 몰랐다.
   ⚠ **불투명도로는 이 의도를 표현할 수 없다** — 통과하는 최솟값이 실측 `0.95` 이고(0.90 은
   4.37), 0.95 는 1.0 과 눈으로 구분되지 않는다. 즉 "흐리게"와 "읽힘"이 이 축에서 양립하지 않는다.
   → **배경만** 흐리게 한다(`bg-panel2/60`). 합성 결과가 종전과 **픽셀 동일**(0.6·panel2 +
   0.4·뒷면 = `#eef0f5`)이라 디자인 의도는 그대로이고, 내용은 전부 온전한 대비로 돌아온다. */
const BUDGET_BG: Record<'done' | 'ok' | 'under' | 'over' | 'none', string> = {
  done: 'bg-panel2/60',
  ok: 'bg-panel2',
  under: 'bg-panel2',
  over: 'bg-alloc-over',
  none: 'bg-panel2',
};
const BADGE_TONE: Record<'done' | 'ok' | 'under' | 'over' | 'none', string> = {
  done: 'font-bold text-mut', // 완료: 중립(초록 ✓ 오독 방지) · 700
  ok: 'font-extrabold text-good',
  under: 'font-extrabold text-warn',
  over: 'font-extrabold text-bad',
  none: 'font-extrabold',
};

/** 셀 채움 농도(0.16~0.5) — 배분 분량에 비례. 2.5h(150분)에서 포화.
 *  작은 배분도 즉시 보이게 하한 0.16에서 출발, 무거운 날은 진하게 → 주(週) 부하를 색농도로 읽는다. */
function fillAlpha(min: number): number {
  if (min <= 0) return 0;
  return Math.min(0.5, 0.16 + (min / 150) * 0.34);
}

/** 가장자리 막대 농도(UX-A1) — 셀 채움(0.16~0.5)보다 **낮게** 고정한다.
 *  가장자리는 데이터가 아니라 *결론*(합계 대비 예산·가용)이다. 셀보다 진하면 시선이 표 테두리로
 *  끌려가 "어느 칸이 무거운가"라는 본래 질문이 뒤로 밀린다 — 위계 유지가 이 상수의 존재 이유다. */
const EDGE_ALPHA = 0.2;
/** 스윕 stagger(UX-A4) — 칸당 지연·지연 상한·다 훑은 뒤 머무는 시간(ms).
 *  상한이 필요한 이유: 복사는 과목×요일이라 칸이 수십 개가 될 수 있고, 캡이 없으면 꼬리가
 *  몇 초씩 늘어져 "아직 뭔가 돌고 있다"로 읽힌다. */
const SWEEP_STEP_MS = 45;
const SWEEP_MAX_DELAY_MS = 540;
const SWEEP_HOLD_MS = 900;

/**
 * Q-9 — 격자 이동의 목적지 셀 id(`sid:wd`). 범위를 벗어나면 빈 문자열(= 못 찾음 → 무동작).
 *
 * ⚠ **감싸지 않는다**(마지막 열에서 →가 다음 행 첫 칸으로 가지 않는다). 표는 2차원이고 감싸기는
 * 1차원 은유라, 요일 축을 넘어가면 사용자가 "월요일로 돌아왔다"를 예상하지 못한다. 끝에서 멈추는
 * 편이 W3C APG 격자 패턴의 기본이기도 하다.
 */
function gridId(
  sid: string,
  wd: number,
  dx: number,
  dy: number,
  rows: readonly { id: string }[],
  cols: readonly { wd: number }[],
): string {
  const r = rows.findIndex((x) => x.id === sid);
  const c = cols.findIndex((x) => x.wd === wd);
  if (r < 0 || c < 0) return '';
  const nr = r + dy;
  const nc = c + dx;
  if (nr < 0 || nr >= rows.length || nc < 0 || nc >= cols.length) return '';
  return `${rows[nr]!.id}:${cols[nc]!.wd}`;
}

export function AllocBoard({
  weekMon,
  res,
  capWd,
  todayIso,
  onOpenDay,
}: {
  weekMon: string; // 이 보드가 편집하는 주의 월요일(ISO)
  res: ScheduleResult;
  capWd: number[]; // 요일별 가용 학습분(index=wd 0=일..6=토)
  todayIso: string;
  onOpenDay: (ds: string) => void; // 셀/요일 클릭 → 그날 일 편집기 드릴다운
}) {
  const state = useApp((st) => st.state);
  const mutate = useApp((st) => st.mutate);
  const navigate = useNavigate();

  /* ⚠⚠ **격자 키보드 경로가 UI 어디에도 안 적혀 있었다**(M-13 · 2026-08-06 감사). Q-9 이
     화살표 이동·`+`/`-` 0.5h 를 붙이면서 _"드래그의 키보드 대안"_ 을 만들었는데, 그 존재를
     알 방법이 **소스 주석뿐**이었다 — 즉 접근성 경로를 만들고 **발견 가능성을 안 만들었다**
     (그걸 필요로 하는 사용자가 정확히 그것을 못 찾는다). `Items`·`Graph`·`Ledger` 는 이미
     같은 훅으로 자기 키를 치트시트(`?`)에 등재한다 — 이 화면만 그 목록 밖이었다.
     ⚠⚠ **`Alt + ↑/↓ 과목 행 순서 바꾸기` 가 여기 적혀 있었다 — 이 화면엔 없는 키다**
     (U033 · 2026-08-21 ux 축 · `[재현]`). 아래 격자 핸들러는 Alt 조합을 **비켜 주기만** 하고
     (`if (e.altKey …) return`), 그 키를 실제로 받는 곳은 **다른 화면**이다(`ChapterEditor` 의
     챕터 행 재정렬). 즉 치트시트가 «비켜 준다»를 «지원한다»로 옮겨 적었다.
     ⚠ 없는 키를 광고하는 것은 **없다고 말하지 않는 것보다 나쁘다** — 키보드로만 쓰는 사용자가
     그 키를 누르고 아무 일도 안 일어나면 그 사람은 자기 조작을 의심한다. 이 파일이 M-13 에서
     고친 결함(«경로는 있는데 발견 가능성이 없다»)의 **거울상**이 같은 자리에 생겼다. */
  useKeymapDoc('이 화면 · 배분 보드', [
    { display: '← → ↑ ↓', label: '칸 이동(값 끝에서)' },
    { display: '+ / −', label: '0.5시간씩 늘리기 / 줄이기' },
  ]);

  // 드래그 배분(§12-2 예산 칩) — 과목 행을 잡아 요일 칸에 놓으면 그날 +1h. 숫자 입력은 키보드 접근 경로로 병존(WCAG 2.1.1).
  const [dragSid, setDragSid] = useState<string | null>(null);
  const [overCell, setOverCell] = useState<string | null>(null); // `${sid}:${wd}`
  const DROP_STEP = 60; // 드롭 1회 = +1h

  // UX-A4 스윕 — `${sid}:${wd}` → animation-delay(ms). null 이면 아무 칸도 안 훑는 중.
  const [sweep, setSweep] = useState<Record<string, number> | null>(null);
  const sweepFx = useRef<{ t: number | null; raf: number | null }>({ t: null, raf: null });
  useEffect(() => {
    const fx = sweepFx.current;
    return () => {
      if (fx.t != null) clearTimeout(fx.t);
      if (fx.raf != null) cancelAnimationFrame(fx.raf);
    };
  }, []);

  const rows = weeklyItems(state); // 배분 대상=주간(new) 과목. 술어는 weekAlloc이 단일 소유(복붙 필터 제거).
  const validSids = new Set(rows.map((it) => it.id)); // 삭제된 과목의 고아 배분이 열 합을 부풀리지 않게
  const managed = isWeekManaged(state, weekMon);
  const alloc = allocView(state, res, weekMon); // managed면 명시값, 아니면 자동 파생 스냅샷
  // ID-7 방치 신호 — 과목별 마지막 손 댄 뒤 경과일(예산 상태와 직교한 최근성).
  const neglect = neglectDaysBySid(state, todayIso);

  const monday = parseISO(weekMon);
  // 열=월~일(Mon-first). 각 열의 실제 날짜·wd(getDay)·오늘 여부.
  const cols = Array.from({ length: 7 }, (_, i) => {
    const date = addDays(monday, i);
    const ds = iso(date);
    const wd = date.getDay();
    // ⚠ 열 가용은 capWd(요일 기본값)가 아니라 **그 날짜의 실제 가용**이어야 한다.
    // capWd는 routine만 반영하지만 스케줄러는 dayStudyMin으로 dayOverrides와 그날 events까지 뺀다.
    // 예전엔 보드가 capWd를 그대로 써서, 수요일에 4시간 일정을 넣어도 "가용 6.0h"를 표시하고
    // 5h 배분에 초과 배지를 안 띄웠다 — 실제로는 layoutDay가 남는 분을 start:null(over)로 떨궈
    // 캘린더에서 조용히 사라진다. "한눈에 조망"이 정확히 틀리던 지점.
    return { i, date, ds, wd, label: DOW_MON[i]!, isToday: ds === todayIso, cap: dayStudyMin(state, ds, wd, capWd) };
  });

  const setCell = (sid: string, wd: number, hours: number) => {
    const mins = Math.max(0, Math.round(hours * 60));
    mutate((st) => setAllocCell(st, res, weekMon, sid, wd, mins));
  };
  /* I053 — 전공 밖 레인. ⚠ `setCell` 과 **다른 뮤테이터**를 부르는 것이 이 항목의 전부다:
     `setAllocCell` 은 `ensureWeekAlloc` 을 지나 그 주를 managed 로 승격시킨다(근거는
     `lib/weekAlloc.ts` 의 I053 절). 여기는 그 경로를 안 지난다. */
  const outVec = outsideVec(state, weekMon);
  const setOutside = (wd: number, hours: number) => {
    mutate((st) => setOutsideCell(st, weekMon, wd, Math.max(0, Math.round(hours * 60))));
  };
  // 복사 결과를 정직하게 — copyPrevWeekAlloc은 소스가 비면(계획 첫 주 등) **아무것도 쓰지 않고** 0을 준다.
  // 예전엔 그때도 성공 토스트를 띄워 "복사했어요"만 보이고 화면은 그대로인 무음 실패였다.
  /** 툴바 액션이 **실제로 바꾼** 칸을 훑는다(UX-A4). `before` = 액션 직전의 배분 스냅샷.
   *  ⚠ 왜 로드맵이 적은 "copyPrevWeekAlloc 반환 확장"이 아니라 전후 diff 인가:
   *    ① 그 시그니처만 넓히면 '자동으로'(resetWeekAlloc)는 여전히 결과가 안 보인다 — 로드맵이
   *       지적한 "결과가 곳곳에 흩어지는데 토스트만"은 **두 버튼 공통** 증상이다.
   *    ② diff 는 weekAlloc.ts 계약을 안 건드린다(로드맵이 R2 로 표시한 유일한 리스크가 사라진다).
   *    ③ 복사는 '과목 단위'로 쓰는데 시각 단위는 '칸'이라, 어차피 lib 안에서 칸 단위로 되짚어야 했다.
   *  immer 는 구조 공유라 mutate 뒤에도 `before` 참조는 옛 값을 그대로 들고 있다(스냅샷이 성립). */
  const sweepChanged = (before: Record<string, number[]>) => {
    const after = allocView(useApp.getState().state, res, weekMon);
    const keys = changedAllocCells(
      before,
      after,
      rows.map((it) => it.id),
    );
    const delays: Record<string, number> = {};
    keys.forEach((k, i) => (delays[k] = Math.min(i * SWEEP_STEP_MS, SWEEP_MAX_DELAY_MS)));
    const fx = sweepFx.current;
    if (fx.t != null) clearTimeout(fx.t);
    if (fx.raf != null) cancelAnimationFrame(fx.raf);
    if (keys.length === 0) {
      setSweep(null);
      return;
    }
    // 한 번 껐다 켠다 — 같은 칸을 연달아 훑을 때 className 이 동일하면 CSS 애니가 재시작하지 않는다.
    setSweep(null);
    fx.raf = requestAnimationFrame(() => {
      fx.raf = null;
      setSweep(delays);
      fx.t = window.setTimeout(() => {
        fx.t = null;
        setSweep(null);
      }, SWEEP_MAX_DELAY_MS + SWEEP_HOLD_MS);
    });
  };

  const onCopyPrev = () => {
    const before = alloc;
    let n = 0;
    mutate((st) => {
      n = copyPrevWeekAlloc(st, res, weekMon);
    });
    if (n > 0) {
      toast(`지난 주 배분 ${n}개 과목을 이번 주로 복사했어요.`, 'ok');
      sweepChanged(before);
    } else toast('복사할 지난 주 배분이 없어요(계획 첫 주예요).', 'warn');
  };
  const onReset = () => {
    const before = alloc;
    mutate((st) => resetWeekAlloc(st, weekMon));
    toast('이번 주를 자동 배분으로 되돌렸어요.', 'info');
    sweepChanged(before);
  };

  const hasSubjects = rows.length > 0;
  const hasCap = capWd.some((m) => m > 0);

  // 열(요일) 합 vs 가용 — 초과 경고용. validSids로 걸러 삭제된 과목의 고아 배분이
  // "보이는 행 합 1h인데 푸터는 4h" 유령을 만들지 않게 한다(표시 단계 방어선).
  /* ⚠⚠ **전공 밖 레인을 더한다**(I053) — 이 한 줄이 항목의 값 전부다. 종전엔 이 푸터가
     «배분 3h / 가용 6h» 라 말하면서 그 날 실제로 두 시간을 먹은 전공 밖 학습을 **분모에서
     통째로 빼고** 있었다. 스케줄러는 여전히 이 값을 모른다(계약 0) — 바뀐 것은 **사람이 보는
     분모**뿐이고, 그게 부모 규약을 지키면서 이 축을 말하는 유일한 형태다(리포트 §7). */
  const colMins = cols.map((c) => colSumMin(alloc, c.wd, validSids) + (outVec[c.wd] || 0));

  // efficacy 안내 — 계획상 챕터를 다 배우게 된 과목(finished)에 배분해도 '새 학습' 블록은 더 안 생긴다
  // (엔진이 챕터 소진으로 판단 · 복습·Anki만 자동). 배분했는데 왜 안 굴러가는지 조용히 두지 않고 짚어준다.
  const inertFinished = rows.filter(
    (it) => res.itemStat.find((st) => st.id === it.id)?.finished && rowSumMin(alloc[it.id]) > 0,
  );

  // 같은 결의 두 번째 조용한 무효 — 주당 목표시간이 0/미입력인 과목은 엔진의 weeklyRaw 필터에서 빠져
  // 배분해도 new 블록이 0이다. 과목 카드의 '시간 없음 · 스케줄 안 됨'과 **같은 어휘**로 여기서도 짚는다.
  const noTime = rows.filter((it) => isUnschedulable(it));

  if (!hasSubjects) {
    return (
      <div className={S.wrap}>
        <State
          glyph="sliders"
          title="배분할 과목이 없어요"
          desc={
            <>
              <b>주당 목표 시간</b>이 있는 과목을 추가하면, 여기서 그 시간을 요일에 배분할 수 있어요(월2·목1처럼).
            </>
          }
          next={
            <Button sm variant="primary" onClick={() => navigate('/items')}>
              과목 추가하러 가기 →
            </Button>
          }
        />
      </div>
    );
  }

  return (
    <div className={S.wrap}>
      {/* 툴바 — 모드 배지(+상태 안내) + 이전주복사/자동으로. 배분 합계는 상단 크롬 리드아웃이 소유(중복 제거). */}
      <div className={S.toolbar}>
        <span className={`${S.mode} ${managed ? S.modeManual : S.modeAuto}`}>{managed ? '내 배분' : '자동 제안'}</span>
        <span className={S.toolHint}>
          {managed
            ? '내가 정한 배분으로 이번 주가 굴러가요.'
            : '엔진이 제안한 배분이에요 — 칸을 고치면 내 배분으로 바뀌어요.'}
        </span>
        <div className={S.toolBtns}>
          <Button sm variant="ghost" onClick={onCopyPrev} title="지난 주 배분을 이번 주로 복사">
            ⧉ 지난 주 복사
          </Button>
          {managed && (
            <Button sm variant="ghost" onClick={onReset} title="이번 주를 자동 배분으로 되돌리기">
              ↺ 자동으로
            </Button>
          )}
        </div>
      </div>

      {!hasCap && (
        <div className="ds-note">
          이번 주 <b>가용시간</b>이 0이에요 — 뼈대(일과)에서 수업·수면을 확인하면 배분 여력이 생겨요.
        </div>
      )}

      {noTime.length > 0 && (
        <div className="ds-note">
          <b>{noTime.map((it) => it.name).join(', ')}</b>은(는) <b>주당 목표 시간</b>이 없어 배분해도{' '}
          <b>시간 없음 · 스케줄 안 됨</b>이에요 — 과목에서 주당 시간을 넣어야 <b>새 학습</b>이 놓여요.
        </div>
      )}

      {inertFinished.length > 0 && (
        <div className="ds-noteInfo">
          완료 과목 <b>{inertFinished.map((it) => it.name).join(', ')}</b>에는 배분해도 계획상 챕터를 다 배우게 돼 있어{' '}
          <b>새 학습</b>은 안 생겨요 — 복습·Anki만 자동으로 얹혀요.
        </div>
      )}

      {/* 매트릭스 — 과목(행) × 요일(열) + 주당 예산 열 + 가용 푸터 행.
          role은 grid가 아니라 **table**이다. grid는 화살표 이동·단일 tab stop 같은 키보드 계약을 약속하는데
          이 보드는 셀마다 숫자 입력이 tab stop인 평범한 표라 그 계약을 이행하지 않는다 — SR 사용자는
          "표"라 안내받고 grid 탐색을 시도했다가 아무 반응도 얻지 못했다(Schedule의 tablist→group 판단과 동형).
          시맨틱 <table>로 내리지 않은 이유: 이 보드는 gap 1px 그리드선 + 스티키 프레임을 CSS grid로 얻는다.
          <table>에 display:grid를 걸면 브라우저가 표 시맨틱을 도로 벗겨(used display 기준 role 매핑)
          같은 거짓말이 된다. → role="table" + 정직한 row/columnheader/rowheader/cell.
          행 높이는 CSS의 `.cell{min-height:48px}`가 고정한다 — 과목 수와 무관하게 일정(신축 없음). */}
      <div className={S.scroll}>
        <div
          className={S.grid}
          role="table"
          aria-label="주간 배분 보드"
          /* 과목 + 헤더 + **전공 밖 레인**(I053) + 가용 푸터. 레인을 안 세면 SR 이 마지막 행을
             «표 밖»으로 읽는다 — 손으로 적은 수가 실물과 갈리는 그 형태다. */
          aria-rowcount={rows.length + 3}
          aria-colcount={9}
        >
          {/* 헤더 행 */}
          <div className="contents" role="row">
            <div className={S.corner} role="columnheader">
              과목 · 요일
            </div>
            {cols.map((c) => (
              // 요일 헤더는 '열머리글이자 일 편집기를 여는 버튼'이다. 예전엔 <button role="columnheader">로
              // 버튼 의미를 덮어써 SR엔 정적 머리글로만 읽혔다 → 머리글 래퍼(display:contents) 안에 버튼을 둔다.
              // 오늘 열은 색상 단독으로만 전달되던 걸 aria-current="date"로 보강.
              <div key={c.i} className="contents" role="columnheader" aria-current={c.isToday ? 'date' : undefined}>
                <button
                  type="button"
                  className={`${S.colHead}${c.isToday ? ' ' + S.colToday : ''}`}
                  onClick={() => onOpenDay(c.ds)}
                  title={`${fmtShort(c.date)} 일 편집기 열기`}
                >
                  <span className={S.dow}>{c.label}</span>
                  <span className={c.isToday ? S.dateToday : S.date}>{fmtShort(c.date)}</span>
                </button>
              </div>
            ))}
            <div className={S.budgetHead} role="columnheader">
              주당
            </div>
          </div>

          {/* 과목 행들 */}
          {rows.map((it) => {
            const vec = alloc[it.id] || zeroVec();
            const rowMin = rowSumMin(vec);
            const budgetMin = Math.round((it.weeklyHours || 0) * 60);
            const diff = rowMin - budgetMin; // +초과 / -부족
            const eps = 5; // 5분 이내는 정확 일치로
            // 챕터를 다 끝낸 과목은 예산이 남아도 "남음" 경고 대신 "완료"(더 배분하라 조르지 않게).
            const finished = res.itemStat.find((st) => st.id === it.id)?.finished;
            const state_: 'done' | 'ok' | 'under' | 'over' | 'none' = finished
              ? 'done'
              : budgetMin <= 0
                ? 'none'
                : Math.abs(diff) <= eps
                  ? 'ok'
                  : diff < 0
                    ? 'under'
                    : 'over';
            const subColor = it.color || 'var(--acc)';
            // ID-7 방치 배지 — 이번 주 배분했는데(rowMin>0) 7일+ 손 안 댄 과목만(소음 절제).
            const nds = neglect[it.id];
            const neglected = nds != null && nds >= NEGLECT_DAYS && rowMin > 0 && !finished;
            return (
              <div key={it.id} className="contents" role="row" style={{ ['--sub' as string]: subColor }}>
                {/* 린트가 draggable 을 상호작용 신호로 읽어 'rowheader 는 포커스 가능해야'라고
                    하지만, 이 행 머리글은 조작 대상이 아니다 — 드래그는 순수 마우스 편의 레이어이고
                    접근성 정본은 셀의 NumberField(step 0.5 · aria-label "과목 · 요일 배분(시간)")라
                    ↑↓·타이핑으로 동일하게 달성된다(결정로그: "드래그 배분은 순수 편의 레이어").
                    tabIndex 를 주면 조작할 수 없는 탭 스톱만 과목 수만큼 늘어난다. */}
                {/* eslint-disable-next-line jsx-a11y/interactive-supports-focus */}
                <div
                  className={`${S.rowHead} ${dragSid === it.id ? 'bg-acc-glow' : 'bg-panel2'}`}
                  role="rowheader"
                  title={`${it.name} — 요일 칸으로 끌면 그날 +1h`}
                  draggable
                  onDragStart={(e) => {
                    e.dataTransfer.setData('text/plain', it.id);
                    e.dataTransfer.effectAllowed = 'copy';
                    setDragSid(it.id);
                  }}
                  onDragEnd={() => {
                    setDragSid(null);
                    setOverCell(null);
                  }}
                >
                  <span className={S.grab} aria-hidden="true" />
                  <span className={S.swatch} style={{ background: subColor }} />
                  <span className={S.rowName}>{it.name}</span>
                  {neglected && (
                    <span
                      className={S.neglect}
                      title={`이번 주 배분했지만 ${nds}일째 실제 학습이 없어요 — 계획과 실행이 벌어지는 중`}
                      aria-label={`${nds}일째 손 안 댐`}
                    >
                      <Icon name="sleep" />
                      {nds}
                    </span>
                  )}
                </div>
                {cols.map((c) => {
                  const cellMin = vec[c.wd] || 0;
                  const cellKey = `${it.id}:${c.wd}`;
                  const dropOn = dragSid === it.id; // 잡은 과목 행에만 드롭 허용(과목→요일 의미 유지)
                  const isDrop = overCell === cellKey;
                  const sweepMs = sweep?.[cellKey];
                  // 강조는 하나만 — 지금 올라와 있는 칸(dropOver) > 놓을 수 있는 칸(dragHint) >
                  // 빈 칸 호버 '+'. 드래그 중엔 '+' 를 죽인다(같은 행에 두 어포던스가 겹치면 소음).
                  const affordance = isDrop ? S.dropOver : dropOn ? S.dragHint : cellMin > 0 ? '' : S.hoverPlus;
                  return (
                    <div
                      key={c.i}
                      className={`${S.inputCell} ${c.isToday ? 'bg-alloc-today' : 'bg-panel'}${cellMin > 0 ? ' ' + S.before : ''}${affordance ? ' ' + affordance : ''}${sweepMs != null ? ' ' + S.sweep : ''}`}
                      style={sweepMs != null ? { animationDelay: `${sweepMs}ms` } : undefined}
                      role="cell"
                      onDragOver={(e) => {
                        if (!dropOn) return;
                        e.preventDefault();
                        e.dataTransfer.dropEffect = 'copy';
                        setOverCell(cellKey);
                      }}
                      onDragLeave={() => setOverCell((o) => (o === cellKey ? null : o))}
                      onDrop={(e) => {
                        if (!dropOn) return;
                        e.preventDefault();
                        // currentTarget 은 디스패치 동안만 유효하다 → 동기로 붙잡아 둔다.
                        const cell = e.currentTarget;
                        setCell(it.id, c.wd, (cellMin + DROP_STEP) / 60);
                        setOverCell(null);
                        setDragSid(null);
                        // UX-A3 착지 펄스 — 이펙트가 아니라 핸들러라 prev 비교·set-state 위험이 없다.
                        // reduced-motion 가드는 lib/motion 이 소유한다(WAAPI 는 전역 CSS 백스톱 밖).
                        commit(cell, subColor);
                      }}
                    >
                      {/* 비례 시각 채움 — 배분 분량에 따라 과목색 농도가 진해져 주(週) 부하가 한눈에 읽힌다. */}
                      {cellMin > 0 && (
                        <span className={S.fill} style={{ opacity: fillAlpha(cellMin) }} aria-hidden="true" />
                      )}
                      {/* NumberField — 미완 입력(빈값·"1.")을 커밋하지 않는다. 예전엔 1.5를 치는 도중
                          '.' 시점의 빈값이 0으로 확정됐고, 그 0이 setAllocCell→ensureWeekAlloc을 타고
                          이 주를 managed로 승격시켜 자동 제안을 영구 대체했다(그리고 최종값도 5h가 됐다). */}
                      <NumberField
                        className={S.cellInput}
                        min={0}
                        step={0.5}
                        value={cellMin ? +hNum(cellMin) : 0}
                        emptyValue={0} // 칸을 비우는 건 "이 요일엔 배분 안 함"이라는 뜻
                        // 0 셀은 '·'로 채우지 않는다 — 전 칸에 깔린 점이 소음이 돼 "읽을 것 없는 표"로 보였다.
                        // 빈 칸은 비어 보이고(바탕 틴트 없음 · 캘린더 v5 사상), 값 있는 칸만 채움+색띠로 주인공이 된다.
                        placeholder=""
                        onCommit={(v) => setCell(it.id, c.wd, v)}
                        /* ── Q-9 격자 커서 ────────────────────────────────────────────────
                           🌍 격차표 _"격자는 화살표로 돌고 Enter 로 편집(Tab 은 격자 밖으로)"_
                           (W3C APG) 대비 우리 현재는 **없음**이었다: 셀마다 Tab 스톱 1개라
                           7요일 × 6과목 = **42 스톱**이고, `+1h` 의 **유일한** 빠른 길이
                           드래그였다(키보드 대안 0 — WCAG 2.1.1 관점에서 접근성 결함이다).
                           ⚠ 그래서 이 조각은 "1세션당 편집 셀 중앙값" 관측을 **기다리지 않는다**.
                             빈도는 편의 기능을 정당화하는 근거이지, 키보드 도달성의 근거가 아니다.
                           ⚠ Tab 은 **그대로 둔다**(APG 의 roving tabindex 를 안 쓴다): 이 격자는
                             셀이 전부 편집 가능한 입력이라 Tab 순회가 여전히 정당한 경로이고,
                             뺏으면 기존 사용자의 근육 기억을 깨뜨린다. 화살표는 **덧붙임**이다.
                           ⚠ `+`/`-` 는 0.5h 씩 — 드래그의 `DROP_STEP` 과 같은 눈금이라
                             두 입력 경로가 다른 단위를 말하지 않는다. */
                        onKeyDown={(e) => {
                          if (e.altKey || e.metaKey || e.ctrlKey) return; // Alt+↑↓ 는 행 재정렬이 쓴다
                          const step = e.key === '+' || e.key === '=' ? 0.5 : e.key === '-' ? -0.5 : 0;
                          if (step) {
                            e.preventDefault();
                            setCell(it.id, c.wd, Math.max(0, +hNum(cellMin) + step));
                            return;
                          }
                          const dx = e.key === 'ArrowRight' ? 1 : e.key === 'ArrowLeft' ? -1 : 0;
                          const dy = e.key === 'ArrowDown' ? 1 : e.key === 'ArrowUp' ? -1 : 0;
                          if (!dx && !dy) return;
                          // ⚠ ←/→ 는 숫자 입력의 캐럿 이동이기도 하다 — **캐럿이 끝에 있을 때만**
                          //   격자 이동으로 해석한다(안 그러면 값 안에서 커서를 못 옮긴다).
                          const el = e.currentTarget;
                          if (dx) {
                            const at = el.selectionStart ?? 0;
                            const len = el.value.length;
                            if (dx < 0 && at > 0) return;
                            if (dx > 0 && at < len) return;
                          }
                          const next = document.querySelector<HTMLInputElement>(
                            `[data-cell="${gridId(it.id, c.wd, dx, dy, rows, cols)}"]`,
                          );
                          if (!next) return;
                          e.preventDefault();
                          next.focus();
                          next.select();
                        }}
                        data-cell={`${it.id}:${c.wd}`}
                        aria-label={`${it.name} · ${c.label}요일 배분(시간)`}
                        title={`${it.name} · ${c.label} — 시간 입력(0.5 단위 · ←↑↓→ 이동 · +/- 조정)`}
                      />
                    </div>
                  );
                })}
                <div className={`${S.budgetCell} ${BUDGET_BG[state_]}`} role="cell">
                  {/* UX-A1 — "2.5 / 10h · 7.5h 남음"은 결론이 맞지만 **읽어서 빼야** 알 수 있다.
                      같은 결론을 폭으로도 주면 "어느 과목이 미달인가"가 산수 없이 눈에 든다.
                      색은 과목색(--sub) 재사용이라 행 정체성이 유지되고, 초과일 때만 bad 로 갈린다. */}
                  {budgetMin > 0 && (
                    <span
                      className={`${S.edgeBar} ${state_ === 'over' ? 'bg-bad' : 'bg-[var(--sub,var(--acc))]'}`}
                      style={{ width: `${Math.min(100, (rowMin / budgetMin) * 100)}%`, opacity: EDGE_ALPHA }}
                      aria-hidden="true"
                    />
                  )}
                  <b className={S.budgetB}>{hNum(rowMin)}</b>
                  {budgetMin > 0 && <span className={S.budgetOf}> / {hNum(budgetMin)}h</span>}
                  <span className={`${S.badge} ${BADGE_TONE[state_]}`}>
                    {/* 챕터를 다 끝낸 과목은 중립 라벨(배분 충족 초록 ✓와 구분 — 오독 방지). */}
                    {state_ === 'done' && '챕터 완료'}
                    {state_ === 'ok' && '충족 ✓'}
                    {state_ === 'under' && `${hNum(-diff)}h 남음`}
                    {state_ === 'over' && `+${hNum(diff)}h`}
                    {/* 주당 시간이 없는 과목 — 배분해도 엔진이 0블록. 과목 카드와 같은 문구. */}
                    {state_ === 'none' && '시간 없음'}
                  </span>
                </div>
              </div>
            );
          })}

          {/* ── I053 「전공 밖」 레인 — **분모를 정직하게**(2026-08-22 발상 축) ───────────────
              이 앱은 전공(`sources`→`pipeline`)만 센다. 그런데 실측(2026-08-22): 같은 2주에
              교양축(`survey/`) 커밋이 **131건**이었다 — 즉 앱이 세는 것 옆에서 그만한 학습이
              일어나는데 배분판은 그 시간을 **분모에서 통째로 빼고** «가용 6h 중 3h 배분» 이라
              말하고 있었다.
              ⚠⚠ **데이터를 나르지 않는다.** 부모 규약이 두 축의 계약을 0으로 못박았으므로
              (`survey` 는 hub 과도 pipeline 과도 계약이 0), 이 칸은 **사람이 손으로 적는다.**
              자동으로 채우는 순간 그 규약을 어기는 다리가 된다.
              ⚠ 스케줄러는 이 값을 안 읽는다 — 배치는 100% 종전 그대로다(`schema.ts` 의
                `outsideAlloc` 절). 바뀌는 것은 **위 푸터의 분모** 하나뿐이다.
              ⚠ 드래그·예산·방치 배지가 **없다**: 저것들은 전부 «과목» 의 어휘이고 이 줄은
                과목이 아니다. 같은 장식을 달면 이 줄이 여섯째 과목처럼 읽힌다. */}
          <div className="contents" role="row">
            <div
              className={`${S.rowHead} bg-panel2`}
              role="rowheader"
              title="전공 밖 학습(교양·언어 등) — 손으로 적어요. 배치는 안 바뀌고 아래 가용 분모에만 반영됩니다."
            >
              <span className={S.swatch} style={{ background: 'var(--mut)' }} />
              <span className={S.rowName}>전공 밖</span>
            </div>
            {cols.map((c) => {
              const cellMin = outVec[c.wd] || 0;
              return (
                <div
                  key={c.i}
                  className={`${S.inputCell} ${c.isToday ? 'bg-alloc-today' : 'bg-panel'}${cellMin > 0 ? ' ' + S.before : ''}`}
                  role="cell"
                >
                  {cellMin > 0 && (
                    <span className={S.fill} style={{ opacity: fillAlpha(cellMin) }} aria-hidden="true" />
                  )}
                  <NumberField
                    className={S.cellInput}
                    min={0}
                    step={0.5}
                    value={cellMin ? +hNum(cellMin) : 0}
                    emptyValue={0}
                    placeholder=""
                    onCommit={(v) => setOutside(c.wd, v)}
                    aria-label={`전공 밖 · ${c.label}요일 시간`}
                    title={`전공 밖 · ${c.label} — 시간 입력(0.5 단위)`}
                  />
                </div>
              );
            })}
            <div className={`${S.budgetCell} ${BUDGET_BG.none}`} role="cell">
              <b className={S.budgetB}>{hNum(rowSumMin(outVec))}</b>
              <span className={`${S.badge} ${BADGE_TONE.none}`}>배치 밖</span>
            </div>
          </div>

          {/* 가용 푸터 행 — 헤더 행과 마찬가지로 role="row" 래퍼 안에 둔다(예전엔 셀이 표 직속이라 행 구조가 깨졌다). */}
          <div className="contents" role="row">
            <div className={S.footHead} role="rowheader">
              가용
            </div>
            {cols.map((c, i) => {
              const cap = c.cap; // 그 날짜의 실제 가용(일정·override 반영) — capWd 요일 기본값이 아님
              const over = cap > 0 && colMins[i]! > cap + 5;
              // 배경 우선순위: 초과(bad 12%) > 오늘(acc 8%) > 기본(panel2) — 소스 순서(footOver 가 뒤).
              const footBg = over ? 'bg-alloc-foot-over' : c.isToday ? 'bg-alloc-today' : 'bg-panel2';
              return (
                <div
                  key={c.i}
                  className={`${S.footCell} ${footBg}`}
                  role="cell"
                  title={`${c.label} 배분 ${hNum(colMins[i]!)}h / 가용 ${hNum(cap)}h`}
                >
                  {/* UX-A1 — 열은 과목이 없으니 액센트로. "어느 요일이 빡빡한가"가 7개 분수를
                      비교하지 않고도 읽힌다(가용 0인 날은 분모가 없어 막대도 없다).
                      ⚠ W23 — **가로 게이지에서 세로 막대로 바꿨다.** 행 전체가 한눈에 주간 부하
                      실루엣으로 읽힌다(같은 숫자의 다른 축척 · 추가 높이 0px). 행 안쪽 셀의
                      막대는 가로 그대로다 — 축척이 다르면 두 층이 서로를 안 흉내낸다. */}
                  {cap > 0 && (
                    <span
                      className={`${S.footBar} ${over ? 'bg-bad' : 'bg-acc'}`}
                      style={{ height: `${Math.min(100, (colMins[i]! / cap) * 100)}%`, opacity: EDGE_ALPHA }}
                      aria-hidden="true"
                    />
                  )}
                  <b className={`${S.footNum} ${over ? 'text-bad' : 'text-txt'}`}>{hNum(colMins[i]!)}</b>
                  <span className={S.footCap}>/{hNum(cap)}</span>
                </div>
              );
            })}
            {/* 마지막 칸은 빈 자리(예산 열 아래) — 열 수를 맞춰야 행 구조가 정합하므로 aria-hidden 대신 빈 셀. */}
            <div className={S.footEnd} role="cell" />
          </div>
        </div>
      </div>

      <div className={S.hint}>
        과목 이름을 <b className={S.hintB}>요일 칸으로 끌면</b> 그날 +1h(숫자를 직접 넣어도 돼요). 배분한 요일엔{' '}
        <b className={S.hintB}>새 학습(new)</b>이 놓이고, 복습·Anki·모의는 엔진이 자동으로 얹어요. 요일 헤더를 누르면
        그날을 <b className={S.hintB}>시간표까지</b> 짤 수 있어요.
      </div>
    </div>
  );
}

/* ============================================================
   Journal — 탭: 📒 학습 기록 (Phase 4 · 앱상태/Zustand)
   레거시 ui-journal.js를 React로 — 공부 뒤 남기는 산출물: 3문장 요약·CBMS 오답·보충 백로그.
   '오늘 학습' 블록의 프리필 버튼이 prefill 스토어로 과목을 미리 채운다.
   스타일: 공유 디자인 시스템은 styles/ds.css(`ds-*` 전역), 요소·토큰은 전역 base.
============================================================ */
import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { DAY_PATH } from '@/shell/tabs';
import { useApp } from '@/store/useApp';
import { usePageChromeEffect } from '@/store/usePageChrome';
import { usePrefill } from '@/store/prefill';
import { exportAnkiCards, toast } from '@/shell';
import { summariesFor, cbmsBetween, openBacklog, activityFeed, setRitual } from '@/lib/methodology';
import { weeklyRecap } from '@/lib/insights';
import { shutdownChain } from '@/lib/records';
import { parseCaptureBatch } from '@/lib/quickCapture';
import { addDays, fmt, hLabel, iso, mondayOf, parseISO } from '@/lib/utils';
import { useTodayISO } from '@/hooks/useTodayISO';
import { Button } from '@/components/ui';
import JournalStream from './JournalStream';
import SummaryCard from './SummaryCard';
import CbmsCard from './CbmsCard';
import BacklogCard from './BacklogCard';
import { Icon } from '@/components/Icon';

/** 최근 활동(7일) — 완료·요약·오답·보충·백지를 시간역순 단일 피드로(온디맨드 <details>). */
function ActivityFeed({ ds2 }: { ds2: string }) {
  const state = useApp((s) => s.state);
  const feed = activityFeed(state, iso(addDays(parseISO(ds2), -6)), ds2);
  // 접힌 <details> 안 목록을 항상 렌더하지 않고 열렸을 때만(onToggle로 open 추적) 렌더 — lazy.
  const [open, setOpen] = useState(false);
  return (
    <details
      className="mt-2.5 flex-none border-t border-line2 pt-2"
      onToggle={(e) => setOpen((e.currentTarget as HTMLDetailsElement).open)}
    >
      <summary className="cursor-pointer text-xs leading-text font-extrabold tracking-widest text-mut select-none hover:text-acc">
        최근 활동 · 7일{feed.length ? ` (${feed.length})` : ''}
      </summary>
      {!open ? null : feed.length ? (
        <ol className="mt-2 max-h-45 [scrollbar-width:thin] list-none overflow-y-auto p-0">
          {feed.map((e, i) => (
            <li
              key={i}
              className="flex items-baseline gap-2 border-b border-dashed border-tint-line2 py-1 text-sm leading-text"
            >
              <span className="w-9.5 flex-none text-xs leading-text font-bold text-mut tabular-nums">
                {e.ds.slice(5).replace('-', '/')}
              </span>
              <span
                className="flex-none text-2xs font-extrabold text-acc data-[kind=blank]:text-warn data-[kind=cbms]:text-warn"
                data-kind={e.kind}
              >
                {e.label}
              </span>
              <span className="min-w-0 flex-1 truncate text-txt">{e.detail}</span>
            </li>
          ))}
        </ol>
      ) : (
        <div className="mt-2 text-xs leading-text text-mut">최근 7일 기록이 없어요 — 오늘 첫 발자취를 남겨보세요.</div>
      )}
    </details>
  );
}

/** I-11 배치 캡처 — 여러 줄을 한 번에 파싱해 요약 폼 다건 프리필(우 컬럼 상단, 접이식). */
function BatchCapture() {
  const state = useApp((s) => s.state);
  const [open, setOpen] = useState(false);
  const [text, setText] = useState('');
  // 파싱 미리보기 — 줄 수만큼 CaptureResult(빈 줄·실패 제외). subjects=이름 있는 항목명.
  const subjects = state.items.map((i) => i.name).filter(Boolean) as string[];
  const parsed = text.trim() ? parseCaptureBatch(text, new Date(), subjects) : [];
  const apply = () => {
    if (!parsed.length) return; // 빈 파싱이면 no-op
    const reqs = parsed.map((r) => {
      // 정확 name 일치만 id로 매핑(스케줄러 오염 방지) — 없으면 ''.
      const item = r.subject ? state.items.find((i) => i.name === r.subject) : undefined;
      return { form: 'sum' as const, sid: item?.id || '', ds: r.dateISO || '' };
    });
    usePrefill.getState().requestBatch(reqs);
    setText('');
    setOpen(false);
    toast(`${reqs.length}건 프리필 — 요약 폼이 순차로 채워져요`, 'ok');
  };

  return (
    <details
      className="mb-3.5 rounded-base border border-dashed border-line bg-panel2"
      open={open}
      onToggle={(e) => setOpen((e.currentTarget as HTMLDetailsElement).open)}
    >
      <summary className="cursor-pointer px-3 py-2 text-xs leading-text font-extrabold tracking-wider text-mut select-none hover:text-acc">
        여러 줄 한 번에 — 배치 캡처
      </summary>
      <div className="px-3 pb-3">
        <textarea
          className="resize-y leading-normal"
          rows={4}
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder={'한 줄에 하나씩 — 예)\n미적분 7장 부분적분 요약\n어제 선형대수 고윳값 정리'}
        />
        <div className="mt-2 flex items-center justify-between gap-2.5">
          <span className="ds-tiny text-mut">
            {parsed.length ? `${parsed.length}건 인식 — 요약 폼으로 순차 프리필` : '한 줄씩 적으면 요약 폼을 채워요'}
          </span>
          <Button sm variant="primary" onClick={apply} disabled={!parsed.length}>
            {parsed.length ? `${parsed.length}건 프리필` : '프리필'}
          </Button>
        </div>
      </div>
    </details>
  );
}

/** I-12 주간 리캡 — '이번 주 해낸 것'(격려 톤). review(처방)와 분리. 좌 컬럼. */
function WeeklyRecapCard() {
  const state = useApp((s) => s.state);
  const today = useTodayISO(state);
  const weekMon = iso(mondayOf(parseISO(today)));
  const recap = weeklyRecap(state, weekMon);
  return (
    <div className="mt-3 flex-none rounded-base border border-line-acc bg-tint-acc-faint px-3.5 py-3">
      <div className="mb-2 flex items-baseline justify-between gap-2">
        <span className="text-sm leading-text font-extrabold tracking-wider text-txt">이번 주 해낸 것</span>
        {recap.focusMin > 0 && (
          <span className="text-xs leading-text font-bold text-acc tabular-nums">{hLabel(recap.focusMin)} 집중</span>
        )}
      </div>
      {recap.wins.length ? (
        <ul className="m-0 flex list-none flex-wrap gap-1.5 p-0">
          {recap.wins.map((w, i) => (
            <li
              key={i}
              className="rounded-full border border-line-acc-soft bg-acc-soft px-2.25 py-1 text-xs leading-text font-semibold text-txt"
            >
              {w}
            </li>
          ))}
        </ul>
      ) : (
        <div className="text-xs leading-normal text-mut">이번 주 기록이 쌓이면 여기 성취가 모여요.</div>
      )}
    </div>
  );
}

/** I-13 셧다운 체인 — 최근 14일 연속성 도트 + 'N일 연속' 배지 + 오늘 토글. "Don't break the chain". */
function ShutdownChain() {
  const state = useApp((s) => s.state);
  const mutate = useApp((s) => s.mutate);
  const chain = shutdownChain(state, 14);
  const today = useTodayISO(state);
  const todayDone = chain.days[chain.days.length - 1]?.done ?? false;
  const doneN = chain.days.filter((d) => d.done).length;
  const toggle = () => mutate((st) => setRitual(st, today, 'shutdown', !todayDone));
  return (
    <div className="mt-3 flex-none border-t border-line2 pt-2.5">
      <div className="mb-2 flex items-center gap-2">
        <span className="text-xs leading-text font-extrabold tracking-widest text-mut">셧다운 체인</span>
        {chain.streak > 0 && (
          <span className="text-xs leading-text font-extrabold text-acc tabular-nums">
            <Icon name="flame" /> {chain.streak}일 연속
          </span>
        )}
      </div>
      <div className="mb-2.5 flex flex-wrap gap-1.25" role="img" aria-label={`최근 14일 중 ${doneN}일 셧다운 완료`}>
        {chain.days.map((d) => (
          <span
            key={d.ds}
            className={`size-3 rounded-xs border ${d.done ? 'border-acc bg-acc' : 'border-line2 bg-tint-mut'}`}
            title={`${d.ds}${d.done ? ' · 셧다운 완료' : ''}`}
          />
        ))}
      </div>
      <button
        type="button"
        className="appearance-none rounded-base! border border-line px-2.5! py-1.5! text-xs! leading-text! font-bold! hover:border-acc! hover:text-acc! aria-pressed:border-line-acc-hover! aria-pressed:bg-tint-acc-faint! aria-pressed:text-acc-on-soft!"
        onClick={toggle}
        aria-pressed={todayDone}
      >
        {todayDone ? '오늘 셧다운 완료 ✓ — 취소' : '오늘 하루를 닫기 — 셧다운 완료'}
      </button>
    </div>
  );
}

/* ── N-12 **하루가 주소를 갖는다**(W4 · 2026-08-07) ──────────────────────────────────
   보고 있는 날이 `useState` 였다. 그래서 "7/12 를 다시 열기"가 **경로 재현**이었다 — 탭을 열고
   스테퍼를 N번 누른다. 링크로 못 가리키는 것은 ⌘K 로도 못 찾고, 알림도 못 데려가고, 이 앱이
   자기 자신을 참조하지도 못한다(`journal` 이 로드맵에서 "매일 열 이유가 없는 아카이브"로 읽힌
   것과 무관하지 않다: 아카이브인데 **주소가 없어** 갈 이유가 발생하지 않았다).

   ⚠ **경로가 정본이고 `useState` 는 없다.** 스테퍼는 이제 `navigate` 다 — 뒤로가기가 날짜를
   되돌리고, 오늘로 오면 URL 이 `/day` 로 접힌다(오늘은 파라미터를 안 쓴다: 어제 남긴 `/day`
   링크가 오늘 열면 오늘을 보여 주는 것이 이 주소의 뜻이다).
   ⚠ 미래는 못 간다 — 주소로 들어와도 마찬가지다. `ds` 를 URL 에서 받으므로 **입력을 신뢰하지
   않는다**: 형식이 아니거나 미래면 오늘로 접는다(잘못된 주소가 빈 화면을 그리는 것보다 낫다). */
export default function Day() {
  const state = useApp((s) => s.state);
  const navigate = useNavigate();
  const { ds } = useParams<{ ds: string }>();
  const today = useTodayISO(state); // '오늘' 단일 출처 존중 (+ 자정 자동 롤오버 H20)
  const ds2 = ds && /^\d{4}-\d{2}-\d{2}$/.test(ds) && ds <= today ? ds : today;
  const isToday = ds2 === today;
  const setDs2 = (next: string): void => {
    // 오늘이면 파라미터 없는 주소로 접는다 — 그 주소의 뜻이 "오늘"이다.
    navigate(next === today ? DAY_PATH : `${DAY_PATH}/${next}`, { replace: true });
  };
  // C-10: 빠른 캡처가 파싱한 날짜로 기록 탭을 이동(백필). nonce 변화 시점에만 반응(usePrefillForm과 같은 규율).
  // 로컬 setState는 컴파일러 set-state-in-effect에 걸려(usePrefillForm의 prop setter는 불투명해 통과) setTimeout 비동기 커밋으로 회피.
  const prefillNonce = usePrefill((s) => s.nonce);
  const prefillDs = usePrefill((s) => s.ds);
  useEffect(() => {
    if (!(prefillDs && prefillDs <= today)) return;
    const t = setTimeout(() => setDs2(prefillDs), 0);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [prefillNonce]);
  const stepDay = (d: number) => {
    const next = iso(addDays(parseISO(ds2), d));
    if (next > today) return; // 미래 금지
    setDs2(next);
  };
  /* ⚠ **리드아웃은 화면이 보고 있는 날을 따라간다**(`ds2`), '오늘'이 아니라.
     종전엔 여기만 `today` 였고 스트림·입력 폼은 `ds2` 였다 → '과거 보충' 으로 7/12 요약을
     저장해도 최상단 `요약` 숫자가 그대로였다. 리드아웃은 "0.5초에 상태를 읽는 자리"라는 계약을
     정면으로 깨는 자리다(저장이 됐는지 목록을 다시 훑게 만든다).
     ⚠ `열린 보충` 만 날짜 무관이다 — 그건 "오늘까지 안 닫힌 것" 전량이라 선택 날짜와 무관하다. */
  const sumN = summariesFor(state, ds2).length;
  const cbmsN = cbmsBetween(state, ds2, ds2).length;
  const openN = openBacklog(state).length;
  /* 내보내기는 **오늘 것**을 내보낸다(`'today'`) → 게이트도 오늘 수로 본다. 리드아웃과 다른
     날을 보는 것이 맞다: 라벨이 따라가는 것은 *보고 있는 날*이고, 액션이 따르는 것은 *하는 일*이다. */
  const todaySumN = isToday ? sumN : summariesFor(state, today).length;
  const todayCbmsN = isToday ? cbmsN : cbmsBetween(state, today, today).length;

  usePageChromeEffect(
    () => ({
      /* W22 앵커 예산 — 44px 로 자기 값을 말한다(원칙 ②의 물리적 표현).
         ⚠ 종전 이 줄은 _"**destination 은** 자기 값을 44px 로 말한다"_ 였다(M-15 · 2026-08-06 정정).
         `journal` 은 W9 에서 **lens 로 강등**됐으므로 그 문장은 이제 자기 자신을 설명하지 않는다.
         앵커를 **유지하는 것은 판단이다**: 이 화면의 일은 여전히 "오늘 몇 건을 남겼나"이고,
         역할(나브에 서는가)과 값의 크기(무엇이 제일 중요한가)는 다른 축이다. 실제로 앵커를 세운
         lens 는 여섯이다(`alloc`·`items`·`forecast`·`mistakes`·`questions`·여기) — `find` 의
         _"렌즈다 — 44px 앵커를 세우지 않는다"_ 는 그 화면의 **지역 판단**이지 규약이 아니다.
         0이어도 그린다 — 기록 탭에서 0은 "아직 안 썼다"라는 **행동을 바꾸는 사실**이지 값 부재가 아니다.
         ⚠⚠ 첫 판은 `sumN + cbmsN` **합계**였고 그 아래 리드아웃이 같은 둘을 **분해**로 또 그렸다 —
         W7 이 레일 배지에서 금지한 바로 그 형태를 이 배치가 스스로 새로 만든 것이다(실렌더가
         잡았다). 게다가 `selectors.ts` 는 _"둘은 성격이 다른 일이라 합치면 어느 쪽도 행동으로
         안 이어진다"_ 라 이미 적어 뒀다. → 헤드라인은 **요약**(이 탭의 주된 산출) 하나이고,
         리드아웃에서는 그 칸을 뺀다(한 양 = 한 자리). */
      primary: { value: String(sumN), unit: '건', label: isToday ? '오늘 요약' : `${ds2.slice(5)} 요약` },
      readouts: [
        // 오늘이 아니면 라벨에 날짜를 붙인다 — 안 붙이면 과거 수치가 오늘 수치로 읽힌다.
        { label: isToday ? '오답' : `오답 · ${ds2.slice(5)}`, value: cbmsN },
        { label: '열린 보충', value: openN },
      ],
      // 무데이터면 빈 파일 데드엔드 → 상단바 액션 자체를 미노출(카드 내부 버튼은 canExport로 별도 가드).
      action:
        todaySumN || todayCbmsN ? { label: 'Anki 카드(.txt)', onClick: () => exportAnkiCards('today') } : undefined,
    }),
    [sumN, cbmsN, openN, isToday, ds2, todaySumN, todayCbmsN],
  );

  return (
    <section className="h-full min-w-0" aria-label="학습 기록">
      <div className="grid h-full min-h-0 grid-cols-journal max-wide:grid-cols-1 max-wide:overflow-y-auto">
        {/* 좌 — 로그(시그니처, fill) + 최근 활동(온디맨드). 선택 날짜를 따라간다. */}
        <div className="flex min-h-0 min-w-0 flex-col px-5.5 pt-5.5 pb-4.5 max-wide:min-h-90">
          {/* I004 — **그날 실제로 있었던 일**(2026-08-22 발상 축). 이 화면의 다른 것은 전부
              *산출물*(요약·오답·보충)이라 「계획대로 했나」의 흔적인데, 이 한 줄만 계획을 안 본다.
              ⚠ **되읽히는 자리가 여기다** — 소비처 없는 기록은 기록이 아니다(이 저장소의 규율).
              오늘 화면(`일일 의식`)이 받고, 지난 날을 열면 그 날의 것이 여기 보인다.
              ⚠ 없으면 안 그린다: 빈 칸을 매일 그리면 그게 새 죄책감 더미다(T-10 과 같은 판단). */}
          {(state.rituals?.[ds2]?.did || '').trim() && (
            <div className="ds-note mb-2 flex-none">
              <b className="text-txt">그날 있었던 일</b> — {state.rituals?.[ds2]?.did}
            </div>
          )}
          <JournalStream ds={ds2} isToday={isToday} fill />
          <WeeklyRecapCard />
          <ActivityFeed ds2={ds2} />
          <ShutdownChain />
          <div className="mt-2.5 flex-none text-xs leading-normal text-mut">
            공부 뒤 남기는 산출물({fmt(new Date(ds2 + 'T00:00:00'))}) — 블록을 끝낼 때마다 하나씩. 누적 추세·약점 분포는{' '}
            <button
              type="button"
              className="appearance-none border-none! bg-transparent! p-0! text-xs! leading-normal! font-extrabold! text-acc! underline decoration-acc-glow underline-offset-2 hover:decoration-acc"
              onClick={() => navigate('/stats', { viewTransition: true })}
            >
              통계
            </button>
            ·
            <button
              type="button"
              className="appearance-none border-none! bg-transparent! p-0! text-xs! leading-normal! font-extrabold! text-acc! underline decoration-acc-glow underline-offset-2 hover:decoration-acc"
              onClick={() => navigate('/review', { viewTransition: true })}
            >
              주간 리뷰
            </button>
            에서.
          </div>
        </div>
        {/* 우 — 기록 입력(온화면 패널, 스크롤) */}
        <div className="min-w-0 [scrollbar-width:thin] overflow-y-auto border-l border-line2 px-5 pt-5 pb-7 max-wide:border-t max-wide:border-l-0">
          <div className="ds-caps mb-3">기록 입력 — 요약 · 오답 · 보충</div>
          {/* 날짜 스테퍼 — 과거 보충 진입점. 오늘이면 담백하게, 과거면 강조 배너. */}
          <div
            className={`mb-3.5 flex items-center gap-2 rounded-base border px-2.5 py-1.75 ${isToday ? 'border-line bg-panel2' : 'border-line-warn-strong bg-tint-warn-faint'}`}
          >
            <Button sm variant="ghost" onClick={() => stepDay(-1)} aria-label="이전 날">
              <Icon name="chevronLeft" />
            </Button>
            <span className="text-md font-bold text-txt">
              {fmt(new Date(ds2 + 'T00:00:00'))}
              {isToday ? <span className="ds-tiny text-mut"> · 오늘</span> : <b> · 과거 보충</b>}
            </span>
            <Button sm variant="ghost" onClick={() => stepDay(1)} disabled={isToday} aria-label="다음 날">
              <Icon name="chevronRight" />
            </Button>
            {/* ⚠ **±1 스테퍼만 있으면 7일 전은 7클릭이다**(U037 · 2026-08-21 ux 축). 이 패널의
                존재 이유가 «과거 보충» 인데, 실제로 보충하는 날은 «며칠 전»이지 «어제»가 아니다.
                날짜 입력을 그 옆에 둔다 — 새 어휘가 아니라 **네이티브 컨트롤**이고(`type="date"`
                는 이 저장소가 이미 시험일·마감에서 쓴다), 키보드·스크린리더 경로가 그대로 온다.
                ⚠ `max` 로 미래를 막는다 — `stepDay` 가 코드로 막던 규칙을 컨트롤도 알게 한다. */}
            <input
              type="date"
              className="ds-tiny"
              aria-label="날짜 고르기"
              value={ds2}
              max={today}
              onChange={(e) => {
                const v = e.target.value;
                if (/^\d{4}-\d{2}-\d{2}$/.test(v) && v <= today) setDs2(v);
              }}
            />
            {!isToday && (
              <Button sm variant="ghost" onClick={() => setDs2(today)} style={{ marginLeft: 'auto' }}>
                오늘로
              </Button>
            )}
          </div>
          <BatchCapture />
          <SummaryCard ds={ds2} />
          <CbmsCard ds={ds2} />
          <BacklogCard />
        </div>
      </div>
    </section>
  );
}

/* ============================================================
   JournalStream — 오늘의 로그(기록 시그니처). 그날 남긴 산출물을 검정 위 에디토리얼
   타임라인으로: 요약=얇은 행, CBMS=진단 칩 행(C/B/M/S/T 색), 보충=네온 플래그.
   순수 파생(읽기 전용 개요) — 입력은 아래 카드들이 소유. 데이터는 기존 selector 그대로.

   월드클래스 라운드(AmbientCanvas 언어) — 패널이 살아있는 발광 보드로: 포인터 추적
   스포트라이트 + 색 오로라('ds-spotHost'/spotlight/aura/glow) + 카운트 카운트업.

   ── C-7 이식(journal) — Tailwind ──────────────────────────────────────────────
   보드 껍데기는 전역 `ds-board` 를 유지하고, fill(시그니처 발광 보드) 델타만 `!` 로 얹는다.
   시그니처 배경/상단 헤어라인은 review 가 토큰화한 --bg-sig-chart/--bg-sig-top 을 그대로 공유하고,
   마운트 애니는 enter-rise(tw.css)을 재사용한다(값·키프레임 동일). 노드/칩의 색·발광은 정적
   클래스로 자식에 직접 준다(규약 4 · 동적 조립 금지 — 백지 통과/막힘은 passed 로 가른다).
============================================================ */
import { useApp } from '@/store/useApp';
import { useListCursor, type ListCursor } from '@/hooks/useListCursor';
import { useHeroPointer, useCountUp } from '@/hooks/interactions';
import { summariesFor, cbmsBetween, CBMS_INFO } from '@/lib/methodology';
import { itemById, hhmm, openVaultSearch } from '@/lib/utils';
import type { CbmsCode } from '@/lib/types';

// fill 시그니처 보드 델타 — 'ds-board' 를 발광 보드로(회색 카드 탈피). 배경/헤어라인/애니는 공유 토큰.
/* Q-14 — 노치 HUD 통일. `ds-board` 위에 얹던 `rounded-lg!` 를 `ds-frame` 으로 바꾼다(둥근
   글래스 → 계기판). 나머지 `!` 델타는 그대로다: `ds-board` 의 전역 규칙을 이겨야 하기 때문. */
const BOARD_FILL =
  'ds-frame flex h-full min-h-0 flex-col rounded-none! mb-0! bg-[image:var(--bg-sig-chart)]! px-5! pt-4.5! pb-4! animate-[enter-rise_var(--dur-slow)_var(--ease)_both] motion-reduce:animate-none ds-hairline';
// 스트림 행 · 노드 · 종류 칩의 공유 base(상태별 색은 아래에서 조건부로 얹는다).
const ROW =
  'relative flex min-h-7.5 items-center gap-2 border-b border-dashed border-line2 py-1.75 pl-5.5 last:border-b-0';
const NODE = 'absolute top-1/2 left-1.25 size-2.25 -translate-y-1/2';
const KIND = 'flex-none rounded-xs px-1.5 py-0.5 text-2xs font-extrabold tracking-widest uppercase';
/* ── W13 커서 — **이 스트림엔 탭 스톱이 0이었다**(2026-07-31) ────────────────────────────
   순수 파생(읽기 전용)이라 동사가 없다는 이유로 커서를 안 붙였는데, 그 결과 키보드로는 오늘의
   로그에 **닿을 수조차 없었다**(마우스 전용 화면). 어휘가 7개로 닫혀 있으므로 없는 동사를
   지어낼 필요는 없다 — 이 화면이 실제로 갖는 동사는 하나, **`v` 볼트에서 찾기**다
   (`Review` 의 🔎 딥링크와 같은 어휘 · `openVaultSearch`).
   ⚠ 행은 `<li>` 로 남고 포커스는 안쪽 `<button>` 이 받는다(FlowRail 이 검증한 형태) — `li` 에
     `tabIndex` 를 주려면 role 을 덮어야 하고 그러면 목록 구조가 깨진다. */
const ROW_BTN = 'flex min-h-7.5 w-full items-center gap-2 text-left';

/** 헤더 카운트 — 마운트 시 0→값 카운트업(reduced-motion이면 즉시). */
function Count({ n }: { n: number }) {
  const v = useCountUp(n);
  return <b className="mr-0.75 text-md font-extrabold text-acc tabular-nums">{Math.round(v)}</b>;
}

/** 작성 시각 HH:MM — 구버전 기록엔 at이 없어 빈 문자열(타임스탬프 생략). */
function fmtTime(at?: number): string {
  if (!at) return '';
  const d = new Date(at);
  if (isNaN(d.getTime())) return '';
  return hhmm(d);
}

/** 스트림 한 줄 — 포커스·커서를 받는 껍데기. 내용은 호출부가 그대로 넘긴다(형상 변경 0). */
function StreamRow({
  cursor,
  k,
  extra,
  children,
}: {
  cursor: ListCursor;
  k: string;
  extra?: string;
  children: React.ReactNode;
}) {
  return (
    <li className={`${ROW}${extra || ''}`}>
      <button
        type="button"
        ref={cursor.register(k)}
        tabIndex={cursor.tabStop === k ? 0 : -1}
        onFocus={() => cursor.onItemFocus(k)}
        aria-current={cursor.cursor === k ? true : undefined}
        className={ROW_BTN}
      >
        {children}
      </button>
    </li>
  );
}

export default function JournalStream({
  ds: dsKey,
  isToday = true,
  fill,
}: {
  ds: string;
  isToday?: boolean;
  fill?: boolean;
}) {
  const state = useApp((st) => st.state);
  // 포인터 추적 스포트라이트 — 시그니처 보드가 커서를 따라 발광(틸트 없는 큰 보드).
  const { ref, onMouseMove, onMouseLeave } = useHeroPointer(0);
  const sums = summariesFor(state, dsKey);
  const cbms = cbmsBetween(state, dsKey, dsKey);
  const backlogToday = (state.backlog || []).filter((b) => b.ds === dsKey);
  // 백지 복습 결과(통과/막힘) — 7일 활동피드엔 이미 들지만 일일 로그엔 빠져 불일치였다.
  const blanks = (state.blankResults || []).filter((b) => b.ds === dsKey);
  /* W13 — 커서가 도는 목록(네 종류를 시각 순서 그대로 이어 붙인다). 동사는 `v` 하나뿐이라
     "여기 없는 동사"의 침묵이 최소다(탈출구는 ⌘K). */
  const cursor = useListCursor<string>({
    items: [
      ...sums.map((x) => ({ key: `s-${x.id}`, item: x.name || '' })),
      ...cbms.map((e) => ({ key: `c-${e.id}`, item: `${e.name || ''} ${e.chapter || ''}`.trim() })),
      ...blanks.map((b) => ({ key: `bl-${b.id}`, item: b.name || '' })),
      ...backlogToday.map((b) => ({ key: `b-${b.id}`, item: b.topic || b.name || '' })),
    ],
    docTitle: '이 화면 · 오늘의 로그',
    verbs: { v: (q) => q && openVaultSearch(q) },
  });
  const total = sums.length + cbms.length + blanks.length + backlogToday.length;
  // 날짜 스테퍼로 과거일 백필 시 '오늘의 로그'는 모호 → 오늘이 아니면 날짜 표기.
  const [, mm, dd] = dsKey.split('-');
  const titleLabel = isToday ? '오늘의 로그' : `${Number(mm)}/${Number(dd)} 로그`;

  return (
    <div
      ref={ref}
      onMouseMove={onMouseMove}
      onMouseLeave={onMouseLeave}
      className={`ds-board ds-spotHost relative ds-glow${fill ? ' ' + BOARD_FILL : ''}`}
    >
      <div className="ds-spotlight" aria-hidden="true" />
      <div className="ds-aura" aria-hidden="true" />
      <div className="mb-3 flex items-baseline justify-between">
        <span className="ds-caps">{titleLabel} — LOG</span>
        <span className="flex gap-3.5 text-xs leading-text text-mut">
          <span>
            <Count n={sums.length} /> 요약
          </span>
          <span>
            <Count n={cbms.length} /> 오답
          </span>
          {blanks.length > 0 && (
            <span>
              <Count n={blanks.length} /> 백지
            </span>
          )}
          <span>
            <Count n={backlogToday.length} /> 보충
          </span>
        </span>
      </div>

      {total === 0 ? (
        <div className="flex flex-1 flex-col items-center justify-center gap-2 px-1 pt-2.5 pb-1.5 text-center text-sm leading-text text-mut">
          {/* 빈 보드가 의도된 상태로 읽히도록 — 흐릿한 에디토리얼 글리프 + 중앙 정렬(문구는 그대로). */}
          <span className="text-display leading-none text-acc opacity-14 select-none" aria-hidden="true">
            ✎
          </span>
          {/* ⚠ 「오늘」을 조건 없이 말하면 **과거 하루를 보는 화면이 거짓말을 한다**(U026 ·
              2026-08-21 ux 축). 이 컴포넌트는 `isToday` 를 이미 받고 있었고(제목이 그걸 쓴다)
              이 문장만 안 쓰고 있었다 — 처방도 갈린다: 오늘은 «앞으로 적어라», 과거는 «그날
              아무것도 안 적혔다»(이제 와서 할 수 있는 일이 다르다). */}
          <div>
            {isToday ? (
              <>
                오늘 아직 기록이 없어요. <b>블록을 끝낼 때마다 하나씩</b> — 요약 한 줄, 막힌 곳 한 개.
              </>
            ) : (
              <>
                이 날엔 남긴 기록이 없어요. <b>하루 백필</b>로 지금 채울 수 있어요.
              </>
            )}
          </div>
        </div>
      ) : (
        <ol
          className={`relative m-0 list-none p-0 pl-1.5 before:absolute before:top-1.5 before:bottom-1.5 before:left-2.25 before:w-px before:bg-line before:content-['']${fill ? ' min-h-0 flex-1 [scrollbar-width:thin] overflow-y-auto' : ''}`}
        >
          {sums.map((x) => {
            const lead = x.s1?.trim() || x.s2?.trim() || x.s3?.trim() || '(내용 없음)';
            return (
              <StreamRow key={`s-${x.id}`} cursor={cursor} k={`s-${x.id}`}>
                <span className={`${NODE} rounded-full bg-bg shadow-node-ring`} />
                {fmtTime(x.at) && (
                  <span className="w-8.5 flex-none text-2xs font-bold tracking-wide text-mut tabular-nums">
                    {fmtTime(x.at)}
                  </span>
                )}
                <span className={`${KIND} bg-acc-soft text-acc-on-soft`}>요약</span>
                <span
                  className="size-2.25 flex-none rounded-xs"
                  style={{ background: itemById(state, x.sid)?.color || 'var(--acc)' }}
                />
                <span className="max-w-45 flex-none truncate text-md font-bold">{x.name || '(과목 없음)'}</span>
                <span className="min-w-0 flex-1 truncate text-sm leading-text text-mut">{lead}</span>
              </StreamRow>
            );
          })}
          {cbms.map((e) => {
            const inf = CBMS_INFO[e.code as CbmsCode] || { label: '?', color: 'var(--mut)' };
            return (
              <StreamRow key={`c-${e.id}`} cursor={cursor} k={`c-${e.id}`}>
                <span className={`${NODE} rounded-full bg-bg shadow-node-ring`} />
                {fmtTime(e.at) && (
                  <span className="w-8.5 flex-none text-2xs font-bold tracking-wide text-mut tabular-nums">
                    {fmtTime(e.at)}
                  </span>
                )}
                <span className="ds-cbmsChip" style={{ '--c': inf.color } as React.CSSProperties}>
                  {e.code} {inf.label}
                </span>
                <span className="max-w-45 flex-none truncate text-md font-bold">{e.name || '오답'}</span>
                {e.chapter && <span className="flex-none text-xs leading-text text-mut">· {e.chapter}</span>}
                {e.note && <span className="min-w-0 flex-1 truncate text-sm leading-text text-mut">{e.note}</span>}
              </StreamRow>
            );
          })}
          {blanks.map((b) => (
            <StreamRow key={`bl-${b.id}`} cursor={cursor} k={`bl-${b.id}`}>
              <span className={`${NODE} rounded-full bg-bg shadow-node-ring`} />
              <span className={`${KIND} ${b.passed ? 'bg-tint-good text-good' : 'bg-tint-warn-soft text-warn'}`}>
                {b.passed ? '백지 통과' : '백지 막힘'}
              </span>
              <span
                className="size-2.25 flex-none rounded-xs"
                style={{ background: itemById(state, b.sid)?.color || 'var(--acc)' }}
              />
              <span className="max-w-45 flex-none truncate text-md font-bold">{b.name || '(과목 없음)'}</span>
              {b.note && <span className="min-w-0 flex-1 truncate text-sm leading-text text-mut">{b.note}</span>}
            </StreamRow>
          ))}
          {backlogToday.map((b) => (
            /* Q-10 — 끝난 항목은 `ds-shed`(채도 저하 + 취소선)가 어휘다. `opacity-50` 은 뜻도
               흐리고(끝났나? 비활성인가?) 글자까지 못 읽게 했다. */
            <StreamRow key={`b-${b.id}`} cursor={cursor} k={`b-${b.id}`} extra={b.done ? ' ds-shed' : ''}>
              <span className={`${NODE} rotate-45 rounded-xs bg-acc shadow-dot motion-reduce:shadow-none`} />
              {fmtTime(b.at) && (
                <span className="w-8.5 flex-none text-2xs font-bold tracking-wide text-mut tabular-nums">
                  {fmtTime(b.at)}
                </span>
              )}
              <span className={`${KIND} bg-tint-ink text-txt`}>{b.done ? '회수' : '보충'}</span>
              <span className="max-w-45 flex-none truncate text-md font-bold">{b.topic || '(주제 없음)'}</span>
              {b.name && <span className="flex-none text-xs leading-text text-mut">· {b.name}</span>}
              {b.note && <span className="min-w-0 flex-1 truncate text-sm leading-text text-mut">{b.note}</span>}
            </StreamRow>
          ))}
        </ol>
      )}
    </div>
  );
}

/* ============================================================
   journal/shared.tsx — 기록 탭 카드 3종(요약·CBMS·백로그)이 함께 쓰는 조각.

   왜 features 안에 남는가: SubjectSelect·usePrefillForm 둘 다 store를 읽으므로
   components/·hooks/로 올릴 수 없다(레이어 규약: 그 둘은 lib만 import 가능).
   같은 feature 안의 공유물이라 여기가 제자리다.
============================================================ */
import { useEffect } from 'react';
import { useApp } from '@/store/useApp';
import { usePrefill, type PrefillForm } from '@/store/prefill';
import { itemById } from '@/lib/utils';
import { reveal } from '@/lib/motion';
import type { AppState } from '@/lib/types';

/** 과목 선택 <option> — 이름 있는 항목만. */
export function SubjectSelect({
  id,
  value,
  onChange,
  refEl,
}: {
  id: string;
  value: string;
  onChange: (v: string) => void;
  refEl?: React.Ref<HTMLSelectElement>;
}) {
  const items = useApp((s) => s.state.items);
  return (
    <select id={id} ref={refEl} value={value} onChange={(e) => onChange(e.target.value)}>
      <option value="">(과목 선택)</option>
      {items
        .filter((i) => i.name)
        .map((i) => (
          <option key={i.id} value={i.id}>
            {i.name}
          </option>
        ))}
    </select>
  );
}

/** prefill 요청을 구독해 해당 폼의 과목을 채우고 스크롤/포커스.
 *  @param setText C-10 잔여 — 캡처가 뽑은 **챕터**를 받을 텍스트 칸이 있는 폼만 넘긴다(보충의
 *    '막힌 주제'). 챕터가 비어 있으면 부르지 않는다 — 빈 값으로 사용자가 이미 친 글자를 지우면
 *    프리필이 도움이 아니라 파괴가 된다. */
export function usePrefillForm(
  form: PrefillForm,
  setSid: (sid: string) => void,
  focusEl: React.RefObject<HTMLElement | null>,
  setText?: (v: string) => void,
) {
  const nonce = usePrefill((s) => s.nonce);
  const reqForm = usePrefill((s) => s.form);
  const reqSid = usePrefill((s) => s.sid);
  const reqChapter = usePrefill((s) => s.chapter);
  const consume = usePrefill((s) => s.consume);
  useEffect(() => {
    if (reqForm !== form) return;
    setSid(reqSid);
    if (setText && reqChapter) setText(reqChapter);
    consume(form);
    const el = focusEl.current;
    if (el) {
      // ⚠ 모션 자제 가드가 여기만 빠져 있었다(H16) — 판정을 `lib/motion.reveal` 하나로 모은다.
      reveal(el);
      setTimeout(() => el.focus(), 300);
    }
    // nonce가 바뀔 때만 반응(같은 과목 재요청도 감지). setSid/consume/focusEl은 안정 참조, reqSid는
    // nonce 변화 시점 값만 쓰므로 의도적으로 제외(전체 포함 시 무관 변경에 재발화).
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [nonce, reqForm]);
}

export const nameOf = (state: AppState, sid: string) => itemById(state, sid)?.name || '';

/* ============================================================
   Goals(내 길) — 탭: 🧭 내 길 지도(P9 Phase 6 · 축 A · D2/D10).
   손저작 goals.json(전파통신 연구원 자립 트리)을 렌더 — 루트 성취목표 히어로 + 하위목표 카드
   (상대 중요도 weight 바 · 학위요건 흡수 degree_req 롤업 · kind 배지). 노트→목표 연관은
   하이브리드(핵심만 goals: 명시링크·나머지 개념그래프 거리 Phase 4)라 콜드면 정직하게 안내.
   레이어: store(queries·usePageChrome)·lib(goals)만 소비. app/다른 feature import 금지(boundaries).
============================================================ */
import { useMemo } from 'react';
import { usePageChromeEffect } from '@/store/usePageChrome';
import { useGoals, useKnowledge, usePing } from '@/store/queries';
import { useApp } from '@/store/useApp';
import { toast } from '@/shell';
import { addBacklog, openBacklog } from '@/lib/methodology';
