import {
  buildGoalTree,
  byWeightDesc,
  degreeReqRows,
  activeGoals,
  projectNodes,
  projectViews,
  type GoalTreeNode,
  needKnowledgeRows,
  type NeedKnowledgeRow,
  type ProjectView,
} from '@/lib/goals';
import State from '@/components/State';
import { artifactErrorCopy, classifyArtifact } from '@/lib/artifactState';
import { useNavigate } from 'react-router-dom';
import { Button } from '@/components/ui';
import { Icon } from '@/components/Icon';

/* ── C-7 네 번째 이식(goals) ─────────────────────────────────────────────
   `Goals.module.css`(307줄) 를 없앴다. 규약은 설계서 §15 + `styles/tokenBridge.css`
   머리주석이 SSOT(색은 tokens.css 파생 · 임의값 금지 · 사다리로 반올림).

   이 파일에서 처음 만난 것 둘:
   ① **em 단위 min-width**(`.wVal` 2.5em · `.projK` 4.5em) — 라벨 컬럼을 폰트에 상대적으로
      맞추던 자리다. `min-w-[2.5em]` 은 임의값이라 린트가 막는다 → `--container-*` 로 이름을
      주고 `min-w-wval`·`min-w-projk` 로 쓴다(규약 2·3 의 결).
   ② **auto-fill 카드 그리드**(`repeat(auto-fill, minmax(240px, 1fr))`) — 임의값 대신
      `--grid-template-columns-goals` 테마 항목으로(guide 의 `grid-cols-guide` 와 동형).

   ⚠ 반올림: 간격은 최근접 4px(동점은 내림 · discovery/review-run 선례 14→12·22→20).
   단 **치수적 그래픽 요소**(6px 중요도 바 높이 · 8px 점 · 6px 점 정렬 오프셋)는 사다리
   반올림의 예외로 표준 분수 유틸(`h-1.5`·`mt-1.5`)로 정확히 남긴다 — 2px 가 사라지면
   보이지 않는 간격이 아니라 시각 신호(바 두께·점 정렬)가 흔들리기 때문. 임의값(`[6px]`)이
   아니라 표준 유틸이라 규약 위반이 아니다.

   ⚠ acc2 색 4종은 정적으로 나뉜다 — 14%(`tint-acc2`)·18%(`tint-acc2-strong`)·
   25%(`line-acc2`)·40%(`line-acc2-strong`)·6%-over-panel(`panel-acc2-faint`). 한 이름에
   여러 세기를 몰면 guide 이식에서 물린 규약 5(재정의) 를 다시 밟는다. */
const ROOT = 'px-5 pt-4 pb-12';
const HERO = 'mb-5 rounded-lg border border-line-acc bg-linear-to-b from-acc-soft to-transparent p-5';
const GRID = 'grid grid-cols-goals gap-3';
const CARD = 'flex flex-col gap-2 rounded-md border border-line bg-panel px-4 py-3';
const CARD_HEAD = 'flex items-baseline justify-between gap-2';
const CARD_TITLE = 'm-0! text-md! tracking-tight!'; // h1~h3 — 언레이어드 전역 h2/h3{} 를 ! 로 이긴다
const KIND_BASE = 'flex-none rounded-full px-2 py-1 text-xs font-semibold whitespace-nowrap';
const KIND = { goal: 'bg-acc-soft text-acc-on-soft', project: 'bg-tint-acc2-strong text-acc2' } as const;
const PROJ_ROW = 'flex items-baseline gap-2 text-sm';
const PROJ_K = 'min-w-projk flex-none text-xs text-mut';

export default function Goals() {
  const navigate = useNavigate();
  const goals = useGoals();
  const ping = usePing();
  const data = goals.data;

  /* ⚠ **capability-unlock 가능신호가 P10 W4 에서 빠졌다**(2026-08-07). 그 신호의 출처는 발견
     큐(`discovery` 아티팩트)였고 그 화면·아티팩트가 `survey/` 필러로 갔다. D10 의 양방향 앵커
     중 **상향(축적→"이제 가능")** 이 여기서 끊긴 셈인데, 그게 P10 D2 의 뜻이다 — 교양축이 hub 에
     닿는 길은 **승격 → pipeline → 아티팩트** 하나이고 hub 이 그 큐를 직접 들여다보지 않는다.
     하향(프로젝트→필요지식 분해)은 `goals` 계약 안에 있으므로 그대로 남는다. */
  /* ID-8 하향 루프 — 필요지식이 **약점인가**를 알려면 지식엔진 산출물이 필요하다. 숙달도·리뷰 탭이
     이미 쓰는 같은 쿼리라 캐시를 공유한다(신규 IO 0에 가깝다). 콜드면 undefined → 칩은 지금까지처럼
     정적으로 남는다(조인 실패를 '약점 아님'으로 조용히 바꾸지 않는다는 뜻이기도 하다). */
  const knowledge = useKnowledge().data;

  const roots = useMemo(() => buildGoalTree(data), [data]);
  const active = useMemo(() => activeGoals(data), [data]);
  const projects = useMemo(() => projectNodes(data), [data]);
  const projViews = useMemo(() => projectViews(data), [data]);

  // 상단 리드아웃 — 목표 수·활성·프로젝트·명시 링크(하이브리드 콜드 정직).
  usePageChromeEffect(
    () => ({
      /* W22/H3 — `primary` 는 **필수 키**다(`store/usePageChrome.ts` 머리주석). 이 화면은 렌즈라
         44px 앵커를 세우지 않는다 — 잊은 것이 아니라 없다고 정한 것이다. */
      primary: null,
      readouts: [
        { label: '목표 노드', value: data?.nodes.length ?? 0 },
        { label: '활성', value: active.length },
        { label: '프로젝트', value: projects.length },
      ],
    }),
    [data?.nodes.length, active.length, projects.length],
  );

  if (goals.isLoading) {
    return (
      /* W15 — 골격이 아니라 `indeterminate`(Discovery 와 같은 판단·같은 근거). 목표 카드 수는
         데이터가 정하므로 행 수를 약속하면 그 약속이 곧 오답이다. */
      <section className={ROOT}>
        <State kind="loading" shape="indeterminate" title="내 길을 불러오는 중" />
      </section>
    );
  }

  /* ⚠⚠ **진짜 읽기 실패를 '비어 있음'으로 접고 있었다**(H-21 · 2026-08-06 감사 · `Discovery` 와
     같은 결함·같은 처방). `goals.isError` 를 무조건 콜드로 흡수하면 *계약 파일이 아직 없다*
     (정상)와 *읽다 죽었다*(파싱 실패·백엔드 오류)가 같은 화면이 된다 — 후자는 원인이 어디에도
     안 남는다. 형제 화면 넷은 이미 `classifyArtifact` SSOT 를 쓴다.
     ⚠ 판정만 SSOT 로 옮기고 아래 콜드 화면의 문구·처방(손저작 계약 안내)은 그대로 둔다. */
  const 진짜실패 = classifyArtifact({ hasData: !!data, query: goals, ping }) === 'error';
  if (진짜실패) {
    return (
      <section className={ROOT}>
        <State
          kind="error"
          title="내 길을 읽지 못했어요"
          desc={artifactErrorCopy(goals.error)}
          next={
            <Button sm variant="primary" onClick={() => void goals.refetch()}>
              다시 시도
            </Button>
          }
        />
      </section>
    );
  }
  // 워크스페이스 미설정/계약 부재 → 빈 상태(goals.json 은 손저작이라 실전에선 항상 실재 · 서버 없을 때만).
  if (goals.isError || !data || roots.length === 0) {
    return (
      <section className={ROOT}>
        <State
          glyph="compass"
          title="내 길이 아직 안 보여요"
          desc={
            <>
              손저작 계약 <code>knowledge/_meta/contract/goals.json</code> 을 읽어 옵니다. 설정 탭에서 워크스페이스를
              지정하면 목표 트리가 여기 그려집니다.
            </>
          }
          /* 콜드 게이트 — 막힌 지점(워크스페이스 미설정)으로 **데려다준다**. 종전엔 어디로
             가야 하는지 문장으로만 말하고 사용자가 탭을 찾아야 했다. */
          next={
            <Button sm onClick={() => navigate('/settings')}>
              설정에서 워크스페이스 지정 →
            </Button>
          }
        />
      </section>
    );
  }

  return (
    <section className={ROOT}>
      {roots.map((root) => (
        <GoalBranch key={root.id} node={root} maxWeight={maxChildWeight(root)} isRoot />
      ))}

      {/* 프로젝트·활용 표면(D10) — 선언 프로젝트(진행 중) + capability-unlock 가능신호(양방향). */}
      <ProjectsSection projects={projViews} k={knowledge} />

      {/* 노트→목표 연관 — 하이브리드 모델 안내(핵심만 명시링크·나머지 개념그래프 거리 Phase 4). */}
      <div className="mt-5 flex gap-2 rounded-md border border-dashed border-line bg-panel px-4 py-3 text-sm leading-normal text-mut">
        <span className="mt-1.5 h-2 w-2 flex-none rounded-full bg-acc" />
        <div>
          <b className="text-txt">노트→목표 연관 = 하이브리드.</b> 핵심 노트만 <code>goals:</code> 로 직접 잇고,
          나머지는 개념그래프 거리로 계산합니다(연관성 엔진). 명시 링크·라이브 숙련 신호가 쌓이면 시퀀싱이 목표 근접도로
          재정렬됩니다(숙달도 지도 · Phase 4).
        </div>
      </div>
    </section>
  );
}

/** 프로젝트·활용 표면(D10) — 학습을 응용에 붙이는 앵커.
   선언된 프로젝트(kind:project · 진행 중) = 앵커목표↑·필요지식↓·산출물(done)·capability임계.
   콜드(프로젝트 미명시)면 억지 시드 없이 D10 모델을 정직하게 안내(과설계 금지).
   ⚠ 둘째 축이던 *가능신호*(발견 큐 surface)는 P10 W4 에서 빠졌다 — 위 훅 자리의 주석 참조. */
function ProjectsSection({ projects, k }: { projects: ProjectView[]; k: Knowledge | undefined }) {
  const cold = projects.length === 0;
  return (
    <section className="mt-6" aria-label="프로젝트·활용 표면">
      <div className="mb-3 flex flex-wrap items-baseline gap-2">
        <h2 className="m-0! text-lg! tracking-tight!">프로젝트 · 활용 표면</h2>
        <span className="text-xs text-mut">학습을 응용에 잇는 앵커 — 관계성이 학습을 견인(D10)</span>
      </div>

      {cold ? (
        <div className="rounded-md border border-dashed border-line-acc2-strong bg-panel-acc2-faint px-4 py-3 text-sm leading-relaxed text-mut">
          <b className="text-txt">아직 선언된 프로젝트가 없어요.</b> 목표 계약에 <code>kind:project</code>{' '}
          노드(분야·산출물·필요지식·capability임계)를 더하면 진행 중 프로젝트가 그려집니다. 프로젝트를 필요지식으로
          분해하는 <b className="text-txt">하향</b> 앵커예요.
        </div>
      ) : (
        <>
          {projects.length > 0 && (
            <div className={GRID}>
              {projects.map((p) => (
                <ProjectCard key={p.node.id} p={p} k={k} />
              ))}
            </div>
          )}
        </>
      )}
    </section>
  );
}

/** 필요지식 칩 — 약점이면 **행동 가능한 버튼**, 아니면 지금까지처럼 정적 칩(ID-8).
 *
 *  이 칩이 이 탭의 핵심 비대칭이었다: capability **상향**(축적 → "이제 가능")은 배선돼 있는데
 *  **하향**("이 프로젝트를 열려면 이 지식이 약하다")은 정적 텍스트라 죽어 있었다. 약점인 것만
 *  보충으로 담을 수 있게 해서 그 방향을 잇는다 — 제품 telos(관계성이 학습을 견인)에 정확히 붙는다.
 *
 *  ⚠ 약점이 아니거나 **조인이 안 된 이름은 버튼으로 만들지 않는다.** 지식엔진이 모르는 이름을
 *    누르게 하면 "담았다"는 피드백만 주고 무엇에 대한 보충인지가 비어 버린다(칩은 그대로 보인다).
 *  ⚠ 이미 담긴 주제는 잠근다 — 같은 보충이 여러 번 쌓이면 목록이 곧 소음이 된다(SR-4 '✓보냄' 선례). */
function NeedChip({ row, seeded, onSeed }: { row: NeedKnowledgeRow; seeded: boolean; onSeed: () => void }) {
  const base = 'rounded-full px-2 py-1 text-xs';
  if (!row.weak) {
    return (
      <span
        className={`${base} bg-line2 text-txt`}
        title={row.concept ? '지식엔진이 아는 개념 — 지금은 약점이 아니에요' : '지식엔진에 같은 이름의 개념이 없어요'}
      >
        ↓ {row.name}
      </span>
    );
  }
  if (seeded) {
    return (
      <span className={`${base} bg-tint-warn text-warn`} title="이미 보충에 담겨 있어요">
        ✓ {row.name}
      </span>
    );
  }
  return (
    <button
      type="button"
      className={`${base} bg-tint-warn font-semibold text-warn`}
      onClick={onSeed}
      title={`'${row.name}'은(는) 지금 약점이에요 — 보충('나중에 볼 것')에 담기`}
      aria-label={`${row.name} — 약점, 보충에 담기`}
    >
      <Icon name="alert" /> {row.name}
    </button>
  );
}

/** 프로젝트 카드 — 앵커목표(상향)·산출물(done)·필요지식 칩(하향)·capability임계.
   capability '가능/잠김' 판정은 라이브 숙련 신호 축적 후(콜드 정직 · 시퀀싱과 대칭)라 임계값만 표시. */
function ProjectCard({ p, k }: { p: ProjectView; k: Knowledge | undefined }) {
  const mutate = useApp((s) => s.mutate);
  // 이미 열려 있는 보충의 주제 집합 — 중복 시드 잠금의 근거를 로컬 state 가 아니라 **실제 상태**에서 판다
  // (탭을 다시 열어도, 다른 화면에서 담았어도 같은 답이 나온다).
  /* ⚠⚠ **셀렉터가 새 객체를 만들면 구독이 항상 깨진다(H17 · 2026-07-30 `/감사 근본`).**
     종전엔 `useApp((s) => new Set(openBacklog(s.state).map(...)))` 였다. zustand 의 기본 비교는
     `Object.is` 이므로 **앱 스토어의 모든 알림마다** 참조가 달라져(다른 탭의 완료 토글·집중
     시작·`setRuntimeCache` 까지) 마운트된 카드 전부가 리렌더했다. React Compiler 는 훅 **반환값**
     이 매번 새 참조인 것을 고칠 수 없다 — 메모의 입력 자체가 달라지기 때문이다.
     → 원시 슬라이스만 구독하고 파생은 렌더 본문에서 한다(그건 컴파일러가 메모한다). */
  const backlog = useApp((s) => s.state.backlog);
  const openTopics = new Set(openBacklog({ backlog }).map((b) => b.topic));
  const rows = needKnowledgeRows(p.필요지식, k);
  const weakN = rows.filter((r) => r.weak).length;

  const seed = (name: string): void => {
    mutate((s) => addBacklog(s, '', '', name, `프로젝트 '${p.node.title}'의 필요지식`));
    toast(`보충에 담았어요 — ${name}`, 'ok', 4000);
  };

  /* Q-10 — 비활성은 `ds-past`(채도만 낮춤 · 명도 보존). `opacity-55` 는 카드 안 글자를
     통째로 대비 미달로 떨궜다(H5·H6 와 같은 형태). */
  return (
    <article className={`${CARD} ${p.node.active ? '' : 'ds-past'}`}>
      <div className={CARD_HEAD}>
        <h3 className={CARD_TITLE}>{p.node.title}</h3>
        <span className={`${KIND_BASE} ${KIND.project}`}>프로젝트</span>
      </div>

      {p.분야 && (
        <div className={PROJ_ROW}>
          <span className={PROJ_K}>분야</span>
          <span className="text-txt">{p.분야}</span>
        </div>
      )}
      {p.산출물 && (
        <div className={PROJ_ROW}>
          <span className={PROJ_K}>산출물</span>
          <span className="text-txt">{p.산출물}</span>
        </div>
      )}
      {p.anchor && (
        <div className={PROJ_ROW}>
          <span className={PROJ_K}>앵커 목표</span>
          <span className="text-txt">↑ {p.anchor.title}</span>
        </div>
      )}

      {rows.length > 0 && (
        <div className="flex items-start gap-2">
          <span className={PROJ_K}>필요지식</span>
          <div className="flex flex-wrap items-center gap-1">
            {rows.map((r) => (
              <NeedChip key={r.name} row={r} seeded={openTopics.has(r.name)} onSeed={() => seed(r.name)} />
            ))}
            {/* 조인이 아무것도 못 찾았을 수도, 전부 튼튼할 수도 있다 — 약점이 **있을 때만** 말한다.
                (지식 산출물이 콜드면 rows 는 전부 weak=false 라 이 줄이 자연히 침묵한다.) */}
            {weakN > 0 && <span className="ml-1 text-xs text-mut">— {weakN}개가 약점이에요(눌러서 보충에 담기)</span>}
          </div>
        </div>
      )}

      {typeof p.capability임계 === 'number' && (
        <div
          className="border-t border-line2 pt-1 text-xs text-mut"
          title="축적 숙달이 이 임계에 도달하면 '가능' — 판정은 라이브 신호 후"
        >
          capability 임계 <b className="text-acc2 tabular-nums">{Math.round(p.capability임계 * 100)}%</b>
          <span className="ml-1 text-mut">· 판정 대기(신호 콜드)</span>
        </div>
      )}

      {!p.node.active && <div className="self-start text-xs text-mut">비활성</div>}
    </article>
  );
}

/** 최대 자식 weight(바 스케일 기준). 자식 없으면 1(0 나눗셈 방어). */
function maxChildWeight(node: GoalTreeNode): number {
  return node.children.reduce((m, c) => Math.max(m, c.weight), 0) || 1;
}

/** 목표 가지 — 루트는 히어로, 자식은 카드 그리드로. 재귀(프로젝트 중첩 대비 · 현재 2단). */
function GoalBranch({ node, maxWeight, isRoot }: { node: GoalTreeNode; maxWeight: number; isRoot?: boolean }) {
  const children = byWeightDesc(node.children);
  if (isRoot) {
    return (
      <>
        <header className={HERO}>
          <div className="font-mono text-xs font-semibold tracking-wide text-acc uppercase">내 길 · 성취목표</div>
          {/* ⚠ **`h1` 이 아니라 `h2` 다**(M-12 · 2026-08-06 감사). W9 이 이 화면을 `/degree` 의
              뷰로 접으면서 페이지의 `h1` 은 앱 셸이 갖게 됐는데(`러닝허브`), 이 히어로가 계속
              `h1` 이라 **한 페이지에 h1 이 둘**이고 호스트의 `h2 졸업` **뒤에** h1 이 오는
              역전이 생겼다(실측). 흡수는 도달 경로만 바꾼 게 아니라 **문서 구조상의 깊이**도
              바꾼다 — 그 축이 안 따라온 것이다.
              ⚠ `font-extrabold` 는 픽셀 보존용이다: 전역 `h1`=800 · `h2`=700 이고 크기·자간·여백은
              이미 `!` 로 못박혀 있어 **굵기만** 달라진다(유틸리티 레이어가 base 를 이긴다). */}
          <h2 className="mt-1! mb-2! text-xl! font-extrabold tracking-tight!">{node.title}</h2>
          <p className="m-0 max-w-prose text-sm text-mut">
            이 단일 목표를 하위목표로 분해해 학습 노력의 연관성 그래디언트를 만듭니다.
          </p>
        </header>
        {children.length > 0 && (
          <div className={GRID}>
            {children.map((c) => (
              <GoalCard key={c.id} node={c} maxWeight={maxWeight} />
            ))}
          </div>
        )}
      </>
    );
  }
  return <GoalCard node={node} maxWeight={maxWeight} />;
}

/** 하위목표 카드 — 제목 + kind 배지 + 상대 중요도 바 + (학위요건이면) degree_req 롤업 + 중첩 자식. */
function GoalCard({ node, maxWeight }: { node: GoalTreeNode; maxWeight: number }) {
  const pct = Math.round((node.weight / maxWeight) * 100);
  const degRows = degreeReqRows(node);
  const kids = byWeightDesc(node.children);
  return (
    <article className={`${CARD} ${node.active ? '' : 'ds-past'}`}>
      <div className={CARD_HEAD}>
        <h2 className={CARD_TITLE}>{node.title}</h2>
        <span className={`${KIND_BASE} ${node.kind === 'project' ? KIND.project : KIND.goal}`}>
          {node.kind === 'project' ? '프로젝트' : '목표'}
        </span>
      </div>

      <div className="flex items-center gap-2" aria-label={`상대 중요도 ${node.weight}`}>
        <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-line2">
          <span className="block h-full rounded-full bg-acc" style={{ width: `${pct}%` }} />
        </div>
        <span className="min-w-wval text-right text-xs text-mut tabular-nums">{node.weight.toFixed(2)}</span>
      </div>

      {degRows && (
        <dl className="m-0 grid grid-cols-2 gap-1">
          {degRows.map((r) => (
            <div
              key={r.label}
              className="flex items-baseline justify-between rounded-sm border border-line2 bg-bg px-2 py-1"
            >
              <dt className="text-xs text-mut">{r.label}</dt>
              <dd className="m-0 text-sm font-semibold tabular-nums">
                {r.credits}
                <span className="ml-1 text-xs font-body text-mut">학점</span>
              </dd>
            </div>
          ))}
        </dl>
      )}

      {!node.active && <div className="self-start text-xs text-mut">비활성</div>}

      {kids.length > 0 && (
        <div className="mt-1 grid gap-2 border-l-2 border-line2 pl-2">
          {kids.map((k) => (
            <GoalCard key={k.id} node={k} maxWeight={maxWeight} />
          ))}
        </div>
      )}
    </article>
  );
}

/* ============================================================
   PhaseBoard — **학기의 경계**를 그리는 한 판(T-4 국면 전환 · T-15 개강 리허설 · T-16 부하 시뮬).

   ## 왜 여기(졸업 계획 탭)인가

   셋 다 **학기 날짜**를 입력으로 쓰고, 그 날짜를 넣는 화면이 여기다. 오늘 탭에 두면 학기 밖
   364일 중 350일 동안 "지금은 그 국면이 아니에요"만 그리게 된다 — 오늘 탭은 *오늘*의 화면이지
   *올해*의 화면이 아니다(각도 3 이 짚은 "시그니처 7종이 전부 지금 상태"의 반대편 함정).

   ## 국면마다 다른 것을 그린다 — 빈 카드를 그리지 않는다

   - `pre`(개강 전): 램프(하루 N분이면 밀림 0) + D-14 안쪽이면 리허설 + 부하 시뮬
   - `in`(학기 중): 이 판은 **자기를 접는다.** 학기 중 처방은 계획이 소유하고(두 벌 금지),
     여기 남는 것은 종강 D-day 한 줄뿐이다.
   - `off`(학기 미정): 지금이 그 상태다 — 수를 지어내지 않고 **무엇을 넣어야 수가 나오는지**를
     말한다. 이 화면이 그 입력을 가진 자리라 처방과 조치가 한 화면에 있다.

   ⚠ **판정은 전부 lib 이 한다**(`lib/phaseRamp` · `lib/semesterEntry`). 여기는 그리기만 —
   문구조차 `advice` 로 받는다(화면마다 문구를 새로 지으면 같은 상태를 다르게 말하게 된다).
============================================================ */
import { useNavigate } from 'react-router-dom';
import { useApp } from '@/store/useApp';
import { phaseRamp, staleSemesterLinks } from '@/lib/phaseRamp';
import { rehearsalSteps, simulateSemester } from '@/lib/semesterEntry';
import { upcomingMarks } from '@/lib/semester';
import { MARK_LABEL } from '@/lib/syllabusIntake';
import { hNum, todayISO } from '@/lib/utils';
import { useSchedule } from '@/store/selectors';
import StrataStrip from '@/components/StrataStrip';
import { Button, Pill } from '@/components/ui';

/** 부하 비율의 어휘. **1.0 이 벽이 아니라 0.85 가 벽이다** — 계획은 늘 100% 로 차지 않는다. */
function loadTone(ratio: number): { tone: 'good' | 'warn' | 'bad'; label: string } {
  if (!Number.isFinite(ratio)) return { tone: 'bad', label: '가용 시간 0' };
  if (ratio > 1) return { tone: 'bad', label: '주당 시간이 모자라요' };
  if (ratio > 0.85) return { tone: 'warn', label: '빠듯해요' };
  return { tone: 'good', label: '감당 돼요' };
}

export default function PhaseBoard() {
  const state = useApp((s) => s.state);
  const navigate = useNavigate();
  const res = useSchedule();
  const ds = todayISO(state);
  const ramp = phaseRamp(state, ds);
  const stale = staleSemesterLinks(state, ds);
  const steps = rehearsalSteps(state, ds);
  const marks = upcomingMarks(state, ds);
  const sim = ramp.semester && ramp.kind !== 'off' ? simulateSemester(state, ramp.semester, ds) : null;
  const open = steps.filter((s) => !s.done);

  return (
    <div className="ds-board mb-4! pb-3.5!">
      <div className="mb-3.5 flex items-baseline justify-between gap-3">
        <span className="ds-caps">국면 — PHASE</span>
        <Pill tiny tone={ramp.kind === 'in' ? 'good' : ramp.kind === 'pre' ? 'warn' : undefined}>
          {ramp.kind === 'in' ? '학기 중' : ramp.kind === 'pre' ? `개강 D-${ramp.daysToStart}` : '학기 미정'}
        </Pill>
      </div>

      {/* T-4 — 처방 한 줄. `off` 에서도 **빈 화면이 아니다**(무엇을 넣으면 수가 나오는지 말한다). */}
      <p className="m-0 text-md leading-body">{ramp.advice}</p>
      {ramp.perDayMin !== null && ramp.perDayMin > 0 && (
        <div className="mt-2 flex items-baseline gap-2">
          <b className="text-3xl font-extrabold text-acc tabular-nums">{ramp.perDayMin}</b>
          <span className="text-sm text-mut">분 / 일 · 남은 {hNum(ramp.remainingMin)} h</span>
        </div>
      )}
      {ramp.kind === 'off' && (
        <Button sm variant="primary" className="mt-2.5" onClick={() => navigate('/degree')}>
          아래에서 학기 날짜 넣기
        </Button>
      )}

      {/* T-21 지층 — **학기가 어떻게 흘러왔나**를 12px 한 줄로. 이 앱의 시그니처 7종이 전부
          *지금 상태*였고 시간축이 수개월인 것이 0 이었다(각도 3). 6주 미만이면 스스로 사라진다
          (`lib/series.strata` — 3주짜리 띠는 지층이 아니라 막대 세 개다). */}
      <div className="mt-3">
        <StrataStrip
          matrix={res.weekHours}
          keys={state.items.map((i) => i.id)}
          nameOf={(id) => state.items.find((i) => i.id === id)?.name ?? id}
        />
      </div>

      {/* T-16 — 감당 되나. 근거(`basis`)를 함께 말한다: 근거 없는 수는 믿을지 판단할 수 없다. */}
      {sim && sim.rows.length > 0 && (
        <div className="mt-3.5 border-t border-line pt-3">
          <div className="mb-2 flex items-baseline justify-between gap-3">
            <span className="ds-caps">{sim.semester.name || '학기'} 부하</span>
            <Pill tiny tone={loadTone(sim.ratio).tone}>
              {loadTone(sim.ratio).label}
            </Pill>
          </div>
          {/* ⚠⚠ **N-1(W8) — 예산이 2단이다.** 진도와 과제를 한 수로 합치면 "감당 된다"가 어느 쪽
              덕인지 말할 수 없고, 감당이 안 될 때 **뺄 수 있는 것**(과제는 못 뺀다 · 진도는
              조절된다)이 구분되지 않는다. 과제 칸이 비어 있으면 그 단은 안 그린다(0을 외치지 않는다). */}
          <div className="flex flex-wrap items-baseline gap-2 text-md">
            <b className="tabular-nums">주 {sim.weeklyH}h</b>
            {sim.choreWeeklyH > 0 && <span className="text-mut">+ 과제 {sim.choreWeeklyH}h</span>}
            <span className="text-mut">/ 가용 {sim.capacityH}h</span>
            <span className="ds-tiny text-mut">
              · 총 {sim.totalH}h / {sim.weeks}주
            </span>
          </div>
          <ul className="m-0 mt-2 flex list-none flex-col gap-1 p-0">
            {sim.rows.map((r) => (
              <li key={r.course.id} className="flex items-center gap-2 text-md">
                <span className="min-w-0 flex-1 truncate">{r.course.name || '(이름 없음)'}</span>
                <span className="tabular-nums">{r.estH}h</span>
                {/* 챕터에서 나온 수와 학점 환산은 신뢰도가 다르다 — 같은 픽셀로 그리지 않는다. */}
                <span className="ds-tiny w-11 flex-none text-right text-mut">
                  {r.basis === 'chapters' ? '챕터' : '학점'}
                </span>
              </li>
            ))}
          </ul>
          {sim.rate.basis === 'default' && (
            <p className="ds-tiny mt-1.5 text-mut">
              학점 환산은 기본값({sim.rate.hoursPerCredit}h/학점)이에요 — 한 학기를 끝내면 실투입에서 배웁니다.
            </p>
          )}
        </div>
      )}

      {/* N-19(W8) — **학사일정 눈금.** 정정·철회·휴강·보강은 전부 *되돌릴 수 없는 마감*인데
          지금까지 머릿속과 포털에만 있었다. 지난 것은 안 그린다(지나면 정보가 아니라 자책이다 ·
          `upcomingMarks` 가 그 판정을 소유한다). 없으면 이 절이 통째로 사라진다. */}
      {marks.length > 0 && (
        <div className="mt-3.5 border-t border-line pt-3">
          <div className="ds-caps mb-2">학사일정</div>
          <ul className="m-0 flex list-none flex-col gap-1 p-0">
            {marks.map(({ mark, daysLeft }) => (
              <li key={mark.id} className="flex items-center gap-2 text-md">
                <Pill tiny tone={daysLeft <= 3 ? 'warn' : undefined}>
                  {MARK_LABEL[mark.kind]}
                </Pill>
                <span className="min-w-0 flex-1 truncate text-mut">{mark.label}</span>
                <span className="ds-tiny tabular-nums">{daysLeft === 0 ? '오늘' : `D-${daysLeft}`}</span>
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* T-15 — 개강 리허설. **줄어드는 것이 정상**이고, 다 하면 이 절이 사라진다. */}
      {open.length > 0 && (
        <div className="mt-3.5 border-t border-line pt-3">
          <div className="ds-caps mb-2">개강 리허설 — 지금 할 수 있는 것</div>
          <ul className="m-0 flex list-none flex-col gap-2 p-0">
            {open.map((s) => (
              <li key={s.id} className="flex items-start gap-2">
                <div className="min-w-0 flex-1">
                  <div className="text-md font-bold">{s.label}</div>
                  <div className="ds-tiny text-mut">{s.why}</div>
                </div>
                {s.to && (
                  <Button sm variant="ghost" onClick={() => navigate(s.to!)}>
                    →
                  </Button>
                )}
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* T-4 학기 처분 — 끝난 학기가 아직 분모에 들어 있으면 밀림이 실제보다 커 보인다.
          ⚠ 여기서 아무것도 안 지운다. 결정은 사용자 것이고, **결정할 것이 있다는 사실**만 말한다. */}
      {stale.length > 0 && (
        <div className="mt-3.5 border-t border-line pt-3">
          <div className="ds-caps mb-2">지난 학기 처분 대기</div>
          <ul className="m-0 flex list-none flex-col gap-1 p-0">
            {stale.map((s) => (
              <li key={`${s.semester.id}-${s.item.id}`} className="flex items-center gap-2 text-md">
                <span className="min-w-0 flex-1 truncate">{s.item.name}</span>
                <span className="ds-tiny text-mut">{s.semester.name}</span>
                <Pill tiny tone={s.openChapters ? 'warn' : 'good'}>
                  {s.openChapters ? `${s.openChapters}챕터 남음` : '끝냄'}
                </Pill>
                <Button sm variant="ghost" onClick={() => navigate(`/subject/${s.item.id}`)}>
                  →
                </Button>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

/* ============================================================
   Find — **T-25 검색 화면**(`/find`). `guide` 은퇴의 짝.

   ## 왜 매뉴얼이 아니라 검색인가

   `guide` 는 347줄 **정적 매뉴얼**이었고 레일 한 칸을 상시 썼다. 그런데 이 앱에서 사람이 실제로
   찾는 것은 **탭 이름이 아니라 내용**이다 — "회로 3장이 어디 있더라", "그 보충 뭐였지". 매뉴얼은
   그 질문에 답하지 못하고, 답할 수 있는 것(⌘K)은 **떠 있는 동안만** 존재해 훑어보기가 안 된다.

   ## ⌘K 와 무엇이 다른가 — **머무를 수 있다**

   팔레트는 고르면 닫힌다. 그래서 "여러 개를 훑고 비교한다"가 안 되고, 뒤로 왔다 갔다 하면
   검색어를 매번 다시 친다. 이 화면은 URL 을 갖고(`?q=`) 결과가 **남아 있는다** — 같은 `lib`
   (`contentSearch`)를 쓰므로 **판정은 한 벌**이고, 달라지는 것은 수명뿐이다.

   ## ⚠ 여기서 검색 규칙을 새로 만들지 않는다

   `contentSearch` 가 이미 객체 6종(과목·챕터·책·보충·약점·오답)을 인덱싱한다. 여기서 자체
   필터를 짜면 팔레트와 이 화면이 **같은 질의에 다르게 답하고**, 그때 어느 쪽이 규칙인지 말할 수
   없다. 늘어난 것은 결과 개수 상한 하나뿐이다(화면이 넓으니 더 보여 준다).
============================================================ */
import { Suspense, lazy, useMemo } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { FIND_GUIDE_VIEW } from '@/shell/tabs';
import { useApp } from '@/store/useApp';
import { usePageChromeEffect } from '@/store/usePageChrome';
import { contentSearch, type ContentHit } from '@/lib/contentSearch';
import { type AdhocNav } from '@/lib/resume';
import { railTabs } from '@/shell';
import State from '@/components/State';
import { Icon } from '@/components/Icon';
import { Button, Pill } from '@/components/ui';

/** 화면이 넓으니 팔레트(8)보다 많이 보여 준다 — **유일하게 다른 값**이다(머리주석). */
const LIMIT = 40;

/* ⚠⚠ **결과 행이 가운데 정렬돼 있었다 — `justify-start!` 가 무효였다**(2026-08-08).
   전역 `button{}` 은 `display` 를 안 정하므로 UA 기본 `inline-block` 이고, 그러면
   `justify-content` 는 **적용될 자리가 없다**(플렉스 컨테이너가 아니다). 대신 UA 의
   `text-align: center` 가 남아 행 전체가 가운데로 몰렸고, 과목 이름의 `ml-auto` 도 같은
   이유로 죽어 **이름과 과목이 붙어 렌더**됐다(`미적분미적분`).
   ⚠ 아무 게이트도 못 잡았다 — 질의가 있는 상태의 스냅샷이 **한 장도 없었다**(그래서 이번에
   `find-results` 케이스를 함께 만들었다). `flex` 를 주면 두 유틸이 그제야 뜻대로 동작한다. */
const ROW = 'flex w-full items-center justify-start! text-left';

/** 검색어 지우기 — 전역 `button{}`(패널 배경·테두리·13px 패딩)을 이겨야 하므로 그 속성만 `!`. */
const CLEAR =
  'absolute top-1/2 right-1.5 grid size-8 -translate-y-1/2 place-items-center rounded-chip! border-0! bg-transparent! p-0! text-mut! hover:bg-panel2! hover:text-txt!';

const KIND_LABEL: Record<ContentHit['kind'], string> = {
  subject: '과목',
  chapter: '챕터',
  backlog: '보충',
  weak: '약점',
  mistake: '오답',
};

/* ⚠⚠ **`guide`(안내)가 이 화면의 두 번째 뷰가 됐다 — 은퇴가 여기서 닫힌다**(W9 · 2026-08-06).

   W7(2026-08-02)이 `guide` 를 은퇴시키려다 되돌린 이유는 정확했다: 불변식 ②가 _"은퇴한 탭은
   **착지 경로**를 갖는다"_ 를 요구하는데 `to: '/guide'` 는 자기 자신이라 그 계약을 못 만족한다.
   흡수가 **셋 중 둘**이었기 때문이다 — 찾기는 이 화면(T-25)이, 화면별 키는 `KeycapBar`(T-22)가
   가져갔고, 남은 하나 _"이 시스템이 할 수 있는 것"_ 본문의 갈 곳이 없었다.

   그 갈 곳이 여기다. 두 화면이 답하는 질문은 **한 축의 두 끝**이다: 이 화면이 *"그게 어디
   있나"*, 매뉴얼이 *"무엇을 할 수 있나"*. 둘 다 참조물이고, 둘 다 머무는 화면이며, 검색이
   빈손일 때 갈 곳이 있다는 것 자체가 이 화면의 결말을 낫게 한다.
   ⚠ **lazy** — 351줄 정적 매뉴얼이라 찾으러 온 방문에 내려받을 이유가 없다. */
const Guide = lazy(() => import('./GuideView'));

export default function Find() {
  const state = useApp((s) => s.state);
  const [params, setParams] = useSearchParams();
  const navigate = useNavigate();
  const q = params.get('q') ?? '';

  const hits = useMemo(() => (q.trim() ? contentSearch(q, state, LIMIT) : []), [q, state]);
  /* I043 — 세트가 될 수 있는 것은 **챕터 히트뿐**이다(과목·보충·오답은 카드가 아니다).
     ⚠ `id` 를 되파싱하지 않는다 — `ContentHit` 이 `sid`·`chapter` 를 필드로 들고 다니는 이유가
     그것이고(N-1), 그 규율을 여기서 깨면 접두어가 바뀌는 날 조용히 엉뚱한 챕터를 부른다. */
  const chapterKeys = useMemo(
    () => hits.filter((h) => h.kind === 'chapter' && h.sid && h.chapter).map((h) => `${h.sid}|${h.chapter}`),
    [hits],
  );
  /* 화면 이름도 함께 찾는다 — 내용이 주(主)지만 "그 탭 이름이 뭐였지"도 실재하는 질문이다.
     ⚠ 은퇴한 화면은 여기 안 나온다(`railTabs()` 가 이미 걸러 준다 · Q-22).
     ⚠ N-14(W5) 이후 **렌즈도 나온다** — 레일에 서는 것이 곧 찾을 수 있는 화면이다. */
  const screens = useMemo(
    () => (q.trim() ? railTabs().filter((t) => t.label.toLowerCase().includes(q.trim().toLowerCase())) : []),
    [q],
  );

  usePageChromeEffect(
    () => ({
      primary: null, // 렌즈다 — 44px 앵커를 세우지 않는다(잊은 것이 아니라 없다고 정한 것)
      readouts: q.trim() ? [{ label: '결과', value: hits.length + screens.length }] : [],
    }),
    [q, hits.length, screens.length],
  );

  if (params.get('view') === FIND_GUIDE_VIEW)
    return (
      <div className="flex min-h-0 flex-col">
        {/* ⚠ 돌아가는 문이 **화면 안에** 있어야 한다. 세그먼트 바는 이미 `찾기` 가 눌린 상태라
            (매뉴얼도 이 탭이다) 거기서는 여기를 벗어나는 방법이 보이지 않는다 — 은퇴 흡수가
            만드는 전형적인 막다른 골목이고, 한 줄로 닫힌다. */}
        <div className="flex-none px-6 pt-4">
          <Button sm variant="ghost" onClick={() => setParams({}, { replace: true })}>
            ← 찾기
          </Button>
        </div>
        <Suspense fallback={<State kind="loading" title="안내 여는 중…" shape="frame" />}>
          <Guide />
        </Suspense>
      </div>
    );

  return (
    /* ⚠ `<section aria-label>` — 탭 본문의 랜드마크 계약(`visual.spec.ts` 가 집행). */
    <section className="flex h-full flex-col gap-3.5 p-6" aria-label="찾기">
      <div className="ds-fld flex-none">
        <label htmlFor="find-q">무엇을 찾나요</label>
        {/* ⚠ 이 칸은 화면의 **유일한 컨트롤**이다 — 크기·아이콘은 장식이 아니라 그 사실의 표현이다.
            종전엔 폭 185px 짜리 네이티브 흰 상자였는데, 원인은 이 화면이 아니라 전역 폼 스킨의
            타입 목록에 `search` 가 없던 것이다(`styles/global/components.css` · 불변식 ⑬이 잠갔다).
            ⚠ `max-w-160` — 한 줄이 화면 폭 전체로 늘어나면 검색창이 아니라 *구분선*처럼 읽힌다. */}
        <div className="relative max-w-160">
          <Icon
            name="search"
            className="pointer-events-none absolute top-1/2 left-3.5 size-4 -translate-y-1/2 text-mut"
          />
          <input
            id="find-q"
            type="search"
            className="h-11 pr-11 pl-10.5 text-base"
            value={q}
            /* ⚠ `autoFocus` 는 린트가 (옳게) 막는다 — 스크린리더 사용자를 화면 중간으로 순간이동
               시킨다. 이 화면은 ⌘K 와 달리 **머무는** 곳이라 자동 포커스의 이득도 작다. */
            placeholder="과목·챕터·보충·약점·오답·읽을거리"
            onChange={(e) => setParams(e.target.value ? { q: e.target.value } : {}, { replace: true })}
          />
          {/* 네이티브 지우기 X 는 전역에서 껐다(테마 토큰을 안 탄다) → 앱이 자기 것으로 준다.
              ⚠ `replace: true` 로 지운다 — 검색은 되돌아갈 이력이 아니다(입력 때와 같은 규칙). */}
          {q !== '' && (
            <button
              type="button"
              className={CLEAR}
              aria-label="검색어 지우기"
              onClick={() => setParams({}, { replace: true })}
            >
              ✕
            </button>
          )}
        </div>
      </div>

      {!q.trim() ? (
        <State
          kind="empty"
          glyph="search"
          title="내용으로 찾습니다"
          desc="탭 이름이 아니라 과목·챕터·보충·약점·오답·읽을거리를 직접 찾아요. ⌘K 와 같은 규칙이지만, 여기선 결과가 남아 있어 여러 개를 훑을 수 있습니다."
          /* ⚠ 종전엔 `terminal`(행동 없음)이었다. 매뉴얼이 이 화면으로 들어오면서 **행동이
             생겼다** — 그리고 그 문은 여기밖에 없다(은퇴한 탭은 나브에 안 선다). */
          next={
            <Button variant="primary" onClick={() => setParams({ view: FIND_GUIDE_VIEW }, { replace: true })}>
              이 시스템이 할 수 있는 것
            </Button>
          }
        />
      ) : hits.length + screens.length === 0 ? (
        <State
          kind="empty"
          glyph="search"
          title={`“${q}” 에 걸리는 것이 없어요`}
          desc="더 짧은 단어로 줄여 보세요 — 부분 일치로 찾습니다."
          /* ⚠⚠ 여기가 `terminal`(행동 없음)이었다(U024 · 2026-08-21 ux 축). 바로 위 첫 진입
             상태는 *"그 문은 여기밖에 없다"* 며 매뉴얼 버튼을 세워 뒀는데, **질의를 한 글자라도
             치면 그 문이 사라졌다** — 아무것도 못 찾은 순간이 «이 시스템이 뭘 할 수 있나»를
             가장 묻고 싶은 순간인데 정확히 그때 답이 없었다. 화면이 스스로 적어 둔 근거가
             자기 형제 상태에는 적용되지 않은 형태다. */
          next={
            <Button variant="primary" onClick={() => setParams({ view: FIND_GUIDE_VIEW }, { replace: true })}>
              이 시스템이 할 수 있는 것
            </Button>
          }
        />
      ) : (
        <ul className="m-0 flex min-h-0 max-w-160 flex-1 [scrollbar-width:thin] list-none flex-col gap-1.5 overflow-y-auto p-0">
          {screens.map((t) => (
            <li key={`s-${t.key}`}>
              <Button variant="ghost" className={ROW} onClick={() => navigate('/' + t.key)}>
                <Pill tiny>화면</Pill>
                <span className="ml-2">{t.label}</span>
              </Button>
            </li>
          ))}
          {/* ⚠⚠ **임시 학습 세트**(I043 · 2026-08-22). "내일 시험이니 이 범위만" 은 실재하는
              요구인데 이 앱엔 그걸 말할 문법이 없었다(큐는 위험도가 짠다). 밖의 대응(필터 덱)이
              자기 매뉴얼에 *"반복 사용에 부적절"* 을 적어 두는 이유가 이 기능의 설계 조건이다 —
              그래서 **기본이 preview** 이고(앵커 무변경), 그 사실을 버튼 옆 문장이 말한다.
              근거 전문은 `lib/reviewQueue.buildAdhocQueue` 머리주석. */}
          {chapterKeys.length > 0 && (
            <li>
              <div className={`${ROW} flex-wrap items-center gap-2`}>
                <Button
                  sm
                  onClick={() =>
                    navigate('/review-run', { state: { adhoc: chapterKeys, preview: true } satisfies AdhocNav })
                  }
                >
                  이 결과 {chapterKeys.length}개로 지금 세션
                </Button>
                <span className="ds-tiny text-mut">사다리는 안 건드려요(임시) · 정규 복습은 그대로 돌아옵니다</span>
              </div>
            </li>
          )}
          {hits.map((h) => (
            <li key={h.id}>
              <Button variant="ghost" className={ROW} onClick={() => navigate(h.to)}>
                <Pill tiny>{KIND_LABEL[h.kind]}</Pill>
                <span className="ml-2 min-w-0 truncate">{h.label}</span>
                {h.subject && <span className="ds-tiny ml-auto pl-2 text-mut">{h.subject}</span>}
              </Button>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

/* ============================================================
   AnkiPanel — Anki 현황(볼트 _anki 파일 + AnkiConnect). Phase 5 · 서버/외부.
   카드 스캔/실시간 due는 Query 캐시(['ankiFile']/['ankiLive']) — persist X. 단, 실시간 due는
   ① 오늘 탭 KPI가 읽도록 state._ankiLive로 write-through ② 주별 due 스냅샷(retentionLog)은
   앱 데이터라 recordRetentionSnapshot으로 persist(설계도 §1-B).
============================================================ */
import LiveRegion from '@/components/LiveRegion';
import { useCallback, useEffect, useState } from 'react';
import { useQuery, useQueryClient, skipToken } from '@tanstack/react-query';
import { useApp } from '@/store/useApp';
import { useRuntime } from '@/store/useRuntime';
import { useUI } from '@/store/useUI';
import { exportAnkiCards, toast } from '@/shell';
import { pickAndScanAnki, fetchAnkiLive, totalDue, totalCards, type AnkiFile, type AnkiLive } from '@/lib/anki';
import { recordRetentionSnapshot } from '@/lib/methodology';
import { idbPut } from '@/lib/idb';
import { onVisible } from '@/lib/visibility';
import { makeItem, clamp, jsq, hhmm } from '@/lib/utils';
import { Button } from '@/components/ui';
import { Icon } from '@/components/Icon';

export function AnkiPanel() {
  const qc = useQueryClient();
  const mutate = useApp((s) => s.mutate);
  const setAnkiLive = useRuntime((s) => s.set); // plan-무관 캐시 — state 참조를 갈지 않음(B1/B3)
  const items = useApp((s) => s.state.items);
  // 구독형으로 읽어 연결/해제 시 패널이 즉시 반응(skipToken = fetch 없이 캐시만 구독).
  const file = useQuery<AnkiFile>({ queryKey: ['ankiFile'], queryFn: skipToken }).data;
  const live = useQuery<AnkiLive>({ queryKey: ['ankiLive'], queryFn: skipToken }).data;
  const [busy, setBusy] = useState<'' | 'file' | 'live'>('');
  const [err, setErr] = useState('');
  // 실시간 due 자동 새로고침 — 연결돼 있을 때 5분마다 + 탭 복귀 시 재조회(로컬 설정).
  // 2단계-A4: 예전엔 여기서 localStorage를 **직접** 만졌다(유일한 kv SSOT 우회 · 백업 누락).
  // 이제 useUI가 소유하므로 lh_ui_v1에 담기고 _local 사이드카를 타고 이관·백업된다.
  const autoRefresh = useUI((s) => s.ui.ankiAutoRefresh);
  const setAutoRefresh = useUI((s) => s.setAnkiAutoRefresh);
  const [lastAuto, setLastAuto] = useState<string>('');
  /* ⚠⚠ **자동 갱신 실패를 상태로 남긴다(H8 · 2026-08-01).** 아래 이펙트의 `catch` 가 비어 있고
     `lastAuto` 는 **성공했을 때만** 갱신되므로, Anki 를 끄면 화면은 마지막 성공 시각(`↻ 09:14
     갱신`)을 **하루 뒤까지** 계속 보여 준다 — 그건 "9시 14분에 갱신됐고 그 뒤로도 정상"이라는
     뜻으로 읽힌다. 실제로는 그 시점 이후 한 번도 못 받았다.
     조용한 것 자체는 옳다(5분마다 토스트는 소음이다). 틀린 것은 **아무 데도 안 남는다**는
     것이었다 — `useCollectTool.lastError` 가 같은 계열에서 이미 쓴 처방을 그대로 옮긴다. */
  const [autoErr, setAutoErr] = useState<string | null>(null);

  // 개별 해제 — 각 연동을 독립적으로 끊는다(다른 채널엔 영향 없음).
  const clearFile = () => {
    qc.removeQueries({ queryKey: ['ankiFile'], exact: true });
    toast('Anki 카드 스캔을 비웠어요.', 'info');
  };
  const clearLive = () => {
    qc.removeQueries({ queryKey: ['ankiLive'], exact: true });
    setAnkiLive('_ankiLive', null); // 오늘 탭 due KPI도 초기화
    toast('실시간 due 연결을 해제했어요.', 'info');
  };

  const scanFiles = async () => {
    setErr('');
    setBusy('file');
    try {
      const handle = qc.getQueryData<FileSystemDirectoryHandle>(['vaultHandle']);
      const r = await pickAndScanAnki(handle);
      if (r) {
        qc.setQueryData(['ankiFile'], r.scan);
        // 셸엔 핸들 개념이 없다(폴더를 안 물으므로) — 브라우저에서만 공유·영속한다.
        if (r.handle) {
          qc.setQueryData(['vaultHandle'], r.handle);
          idbPut('vaultHandle', r.handle); // 볼트 패널과 공유 — 다음 부팅 재연결
        }
      }
    } catch (e) {
      setErr((e as Error).message || String(e));
    } finally {
      setBusy('');
    }
  };

  // 실시간 due 반영 — 쿼리 캐시 + 오늘 탭 KPI(_ankiLive) + 주별 유지율 스냅샷. 수동/자동 공용.
  const applyLive = useCallback(
    (l: AnkiLive) => {
      qc.setQueryData(['ankiLive'], l);
      setAnkiLive('_ankiLive', l); // 오늘 탭 Anki due KPI가 소비
      mutate((st) => recordRetentionSnapshot(st, l.decks)); // 주별 due 스냅샷(유지율 추세) — persist
    },
    [qc, setAnkiLive, mutate],
  );

  const goLive = async () => {
    setErr('');
    setBusy('live');
    try {
      applyLive(await fetchAnkiLive());
    } catch (e) {
      setErr(
        'AnkiConnect 연결 실패. Anki가 실행 중이고 AnkiConnect 애드온이 설치됐는지, 설정 webCorsOriginList에 "*" 또는 "null"이 있는지 확인하세요. ' +
          ((e as Error).message || ''),
      );
    } finally {
      setBusy('');
    }
  };

  const toggleAuto = () => setAutoRefresh(!autoRefresh);

  /* 자동 새로고침 — **한 번이라도 연결한 적이 있고** 켜졌을 때. 5분 주기 + 탭 복귀 시 즉시.
     실패는 조용히(다음 주기/포커스에 복구).

     ⚠⚠ **게이트가 `!!live` 였던 동안 이 이펙트는 재시작 뒤 한 번도 안 돌았다.** `live` 는
     `skipToken` 구독이라(위 `useQuery`) 부팅 직후엔 언제나 undefined 이고, 그 값을 채우는
     유일한 경로가 수동 '실시간 연결' 버튼이다 — 즉 "자동"이 매 세션 수동 1회를 요구했다.
     그런데 `_ankiLive` 는 `runtime` 테이블에 살아남아 오늘 탭이 그 옛 숫자를 계속 그렸다
     (갱신은 멈췄는데 표시는 멈추지 않는 조합 — 조용하고 그럴듯한 오류).
     → 판정 기준을 "지금 캐시에 값이 있나"에서 **"이 기기가 Anki 를 연결한 적 있나"** 로.
       영속된 `_ankiLive` 가 정확히 그 증거다. */
  const cachedLive = useRuntime((s) => s.cache._ankiLive);
  const everConnected = !!live || !!cachedLive;
  useEffect(() => {
    if (!autoRefresh || !everConnected) return;
    let alive = true;
    const refresh = async () => {
      try {
        const l = await fetchAnkiLive();
        if (!alive) return;
        applyLive(l);
        const now = new Date();
        setLastAuto(hhmm(now));
        setAutoErr(null); // 성공이 사유를 지운다 — 낡은 경고가 남으면 그게 다음 오진이다
      } catch (e) {
        /* AnkiConnect 순간 단절 — 다음 주기/포커스에 복구된다. 토스트는 안 띄우되(소음)
         **표시가 거짓말을 하지 않도록** 사유를 남긴다(H8). */
        if (alive) setAutoErr(String((e as Error)?.message || e).slice(0, 120) || '연결 실패');
      }
    };
    const id = setInterval(refresh, 5 * 60 * 1000);
    const off = onVisible(refresh);
    return () => {
      alive = false;
      clearInterval(id);
      off();
    };
  }, [autoRefresh, everConnected, applyLive]);

  const addAnki = (name: string, mins: number) => {
    const nm = 'Anki: ' + name;
    if (items.some((s) => s.name === nm)) {
      toast('이미 추가됨', 'warn');
      return;
    }
    mutate((st) => {
      st.items.push(makeItem({ source: 'Anki', name: nm, mode: 'daily', dailyMin: mins }));
    });
    toast(`"${nm}" 매일 ${mins}분 복습으로 추가됨`, 'ok');
  };

  const dueBudget = () => {
    if (!live || !live.decks.length) {
      toast('먼저 "AnkiConnect 실시간 due"로 현황을 불러오세요.', 'warn');
      return;
    }
    const due = totalDue(live.decks);
    if (due <= 0) {
      toast('오늘 풀 due가 0이에요 — 잡을 예산이 없어요.', 'info');
      return;
    }
    const mins = clamp(Math.round(due * 0.5), 10, 180);
    const nm = 'Anki: 오늘 due 복습';
    const ex = items.find((s) => s.name === nm);
    mutate((st) => {
      const cur = st.items.find((s) => s.name === nm);
      if (cur) {
        cur.mode = 'daily';
        cur.dailyMin = mins;
        cur.source = 'Anki';
      } else {
        st.items.push(makeItem({ source: 'Anki', name: nm, mode: 'daily', dailyMin: mins }));
      }
    });
    toast(
      ex
        ? `"${nm}" 복습예산을 ${mins}분으로 갱신(due ${due}장).`
        : `"${nm}" 매일 ${mins}분 복습예산으로 추가(due ${due}장 → 시간 역연동).`,
      'ok',
    );
  };

  // 파일 스캔 결과: 과목별 묶기
  const bySubj: Record<string, AnkiFile['decks']> = {};
  (file?.decks || []).forEach((d) => {
    (bySubj[d.subj] = bySubj[d.subj] || []).push(d);
  });
  const grandDecks = (file?.decks || []).length;
  const grandCards = totalCards(file?.decks ?? []);
  const dueTot = live ? totalDue(live.decks) : 0;

  return (
    <>
      <div className="ds-rule">
        <h2>Anki 현황</h2>
        <div className="ds-row">
          <Button sm disabled={busy === 'file'} onClick={scanFiles}>
            {busy === 'file' ? (
              <>
                <span className="ds-spin" /> 스캔 중
              </>
            ) : (
              <>
                <Icon name="folder" /> 볼트 카드 스캔
              </>
            )}
          </Button>
          <Button sm disabled={busy === 'live'} onClick={goLive}>
            {busy === 'live' ? (
              <>
                <span className="ds-spin" /> 연결 중
              </>
            ) : (
              <>
                <Icon name="plug" /> AnkiConnect 실시간 due
              </>
            )}
          </Button>
          <Button
            sm
            variant="ghost"
            onClick={() => exportAnkiCards('all')}
            title="전체 3문장 요약·오답을 Anki import용 .txt 카드 초안으로"
          >
            <Icon name="cards" /> 요약·오답 → 카드(.txt)
          </Button>
          <div style={{ flex: 2 }} />
        </div>
        <div className="ds-foot">
          카드 스캔: 정본 _meta/cache/_index.json의 덱 목록(검사.sh --index 생성)을 읽음. 없으면 anki/*.txt 폴더 폴백.
          실시간: Anki 실행 + AnkiConnect 애드온 필요(localhost:8765). <b>카드 생성</b>: 그동안 적은 3문장 요약·반복
          오답을 import용 초안(.txt)으로 — Anki에서 추리고 손질(큐레이션).
        </div>
        {/* ⚠ 리전은 **상시 마운트**한다(H19) — 조건부로 넣으면 리전과 텍스트가 동시에 삽입돼 AT 에 따라 공지가 씹힌다. */}
        <LiveRegion message={err ?? ''} assertive />
        {err && (
          <div className="ds-warnbox" style={{ marginTop: 8 }}>
            {err}
          </div>
        )}
        {file && (
          <div className="ds-tiny text-mut" style={{ marginTop: 6, display: 'flex', alignItems: 'center', gap: 8 }}>
            <span>
              <Icon name="folder" /> 카드 스캔: {file.at}
              {file.src ? ' · ' + file.src : ''}
            </span>
            <Button sm variant="ghost" danger onClick={clearFile} title="카드 스캔 결과 비우기">
              ✕ 해제
            </Button>
          </div>
        )}
        {live && (
          <div
            className="ds-tiny text-mut"
            style={{ marginTop: 6, display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}
          >
            <span>
              <Icon name="plug" /> 실시간 연결됨: {live.at}
            </span>
            <label style={{ display: 'inline-flex', alignItems: 'center', gap: 5, cursor: 'pointer' }}>
              <input type="checkbox" checked={autoRefresh} onChange={toggleAuto} /> 자동 새로고침(5분)
            </label>
            {/* ⚠ 실패했으면 **마지막 성공 시각을 그대로 두지 않는다**(H8) — 그 표시는 "그 뒤로도
                정상"으로 읽힌다. 시각은 남기되 *멈췄다는 사실*을 같은 자리에 붙인다. */}
            {autoRefresh &&
              lastAuto &&
              (autoErr ? (
                <span className="text-warn" title={autoErr}>
                  ↻ {lastAuto} 이후 갱신 실패 — Anki 가 꺼져 있을 수 있어요
                </span>
              ) : (
                <span>↻ {lastAuto} 갱신</span>
              ))}
            {/* 한 번도 성공하지 못한 채 실패한 경우 — 시각조차 없으므로 사실만 말한다. */}
            {autoRefresh && !lastAuto && autoErr && (
              <span className="text-warn" title={autoErr}>
                ↻ 자동 갱신 실패
              </span>
            )}
            <Button sm variant="ghost" danger onClick={clearLive} title="실시간 due 연결 해제">
              ✕ 해제
            </Button>
          </div>
        )}
      </div>

      {file && (
        <div className="ds-rule">
          <h3>볼트 카드(파일 기준)</h3>
          <table>
            <thead>
              <tr>
                <th scope="col">과목</th>
                <th scope="col">덱</th>
                <th scope="col">카드</th>
                <th scope="col" />
              </tr>
            </thead>
            <tbody>
              {Object.entries(bySubj).map(([s, dks]) =>
                dks.map((d, i) => (
                  <tr key={d.file}>
                    {i === 0 && (
                      <th rowSpan={dks.length} scope="rowgroup">
                        <b>{s}</b>
                        <br />
                        <span className="ds-tiny text-mut">{totalCards(dks)}장</span>
                      </th>
                    )}
                    <th className="ds-tiny" scope="row">
                      {d.file}
                    </th>
                    <td>{d.cards}</td>
                    <td>
                      <Button
                        sm
                        variant="ghost"
                        onClick={() => addAnki(jsq(d.file), Math.max(15, Math.round(d.cards * 0.5)))}
                      >
                        +스케줄
                      </Button>
                    </td>
                  </tr>
                )),
              )}
            </tbody>
            <tfoot>
              <tr>
                <td colSpan={2}>
                  <b>합계</b> · {grandDecks}덱
                </td>
                <td>
                  <b>{grandCards}</b>
                </td>
                <td />
              </tr>
            </tfoot>
          </table>
          <div className="ds-foot">
            '+스케줄'은 해당 덱을 '매일 복습' 항목으로 추가합니다(예상 분 = 카드수×0.5, 수정 가능).
          </div>
        </div>
      )}

      {live && (
        <div className="ds-rule">
          <h3>실시간 due (AnkiConnect)</h3>
          <div className="ds-row" style={{ marginBottom: 6, alignItems: 'center' }}>
            <Button
              sm
              onClick={dueBudget}
              title={`오늘 풀 due 합계(${dueTot}장)를 '매일 복습' 분 예산으로 — FSRS due를 시간으로 역연동`}
            >
              <Icon name="inbox" /> 오늘 due 합계 → 복습 시간예산
            </Button>
            <span className="ds-tiny text-mut">
              오늘 풀 due 합 <b>{dueTot}</b>장
            </span>
          </div>
          <table>
            <thead>
              <tr>
                <th scope="col">덱</th>
                <th scope="col">신규</th>
                <th scope="col">학습</th>
                <th scope="col">복습</th>
                <th scope="col">오늘 합</th>
                <th scope="col" />
              </tr>
            </thead>
            <tbody>
              {live.decks.map((d) => {
                const due = d.new + d.learn + d.review;
                return (
                  <tr key={d.name}>
                    <th scope="row">{d.name}</th>
                    <td>{d.new}</td>
                    <td>{d.learn}</td>
                    <td>{d.review}</td>
                    <td>
                      <b>{due}</b>
                    </td>
                    <td>
                      <Button
                        sm
                        variant="ghost"
                        onClick={() => addAnki(`${jsq(d.name)} (due)`, Math.max(10, Math.round(due * 0.5)))}
                      >
                        +스케줄
                      </Button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          <div className="ds-foot">
            '+스케줄'은 덱별로 항목을 추가하고, '복습 시간예산'은 <b>전체 due 합</b>을 하나의 매일 복습 항목으로
            잡아요(스케줄 용량에 반영). 시점(due)은 FSRS가 소유.
          </div>
        </div>
      )}
    </>
  );
}

/* ============================================================
   VaultPanel — 옵시디언 볼트 현황(FS Access). Phase 5 · 서버/외부.
   폴더 선택 → 정본 _index.json(또는 .md) 스캔. 결과는 Query 캐시(['vault'])에 — persist X.
   과목/챕터를 '+학습항목'으로 넣는 건 앱상태 변경이라 store.mutate.
============================================================ */
import LiveRegion from '@/components/LiveRegion';
import { useEffect, useRef, useState } from 'react';
import { useQuery, useQueryClient, skipToken } from '@tanstack/react-query';
import { useApp } from '@/store/useApp';
import { importVaultSubject, toast } from '@/shell';
import {
  pickAndScanVault,
  chaptersFromVault,
  queryVaultPermission,
  requestVaultPermission,
  VAULT_ERROR_KEY,
  type VaultScan,
  type VaultSubject,
  type VaultChapter,
} from '@/lib/vault';
import { isTauri } from '@/lib/tauri';
import { idbGet, idbPut, idbDel } from '@/lib/idb';
import { makeItem } from '@/lib/utils';
import { useLedger } from '@/store/queries';
import { Button } from '@/components/ui';
import { Icon } from '@/components/Icon';

export function VaultPanel() {
  const qc = useQueryClient();
  const mutate = useApp((s) => s.mutate);
  const items = useApp((s) => s.state.items);
  // 구독형으로 읽어 연동/해제 시 패널이 즉시 반응(skipToken = fetch 없이 캐시만 구독).
  const scan = useQuery<VaultScan>({ queryKey: ['vault'], queryFn: skipToken }).data;
  const handle = useQuery<FileSystemDirectoryHandle>({ queryKey: ['vaultHandle'], queryFn: skipToken }).data;
  /* ⚠⚠ **셸의 스캔 실패가 여기로 온다**(U006 · 2026-08-21 ux 축). 셸에는 폴더 연동 버튼이 없어
     아래 `err` 상태(FSA 경로 전용)에 실릴 길이 없었고, 그래서 볼트를 못 읽는 사실의 사용자
     표면이 **어디에도 없었다** — `lib/tauri.ts` 주석이 지목한 `capabilities.vaultWatchError` 는
     감시자만 세운다. 실패는 `app/VaultSync` 가 쿼리 캐시에 적고 이 패널이 그린다(볼트의 집). */
  const scanErr = useQuery<string | null>({ queryKey: VAULT_ERROR_KEY, queryFn: skipToken }).data ?? null;
  // 원장(W4) — 임포트 직후 "카드까지 갔다"를 물으려면 여기서 실제로 읽어야 한다.
  const led = useLedger();
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState('');
  const [open, setOpen] = useState<Set<number>>(() => new Set());
  // 저장된 핸들이 있으나 권한이 만료돼(재시작 후 'prompt') 제스처 재요청이 필요한 상태.
  const [pending, setPending] = useState<FileSystemDirectoryHandle | null>(null);
  const initRef = useRef(false);

  /* 셸(3단계) — 볼트는 `<워크스페이스>/knowledge` 라 **묻지 않고 그냥 읽는다.**
     폴더 선택도, 권한 조회/요청도, IDB 핸들 영속도 여기선 존재하지 않는다.
     ⚠ W3(2026-07-31) — 그 스캔+감시는 **`app/VaultSync` 로 올라갔다.** 이 화면에만 있는 동안엔
     앱이 "볼트에 뭐가 있나"를 이 탭을 열기 전까지 묻지도 않았고, 그게 콜드 스타트가 빈 앱처럼
     보이던 이유였다. 여기 남은 것은 브라우저(dev·트랙 A)의 FSA 재연결뿐이다. */

  // 부팅 재연결(브라우저 전용) — IDB에 저장한 폴더 핸들을 되살린다. 권한이 아직 살아있으면
  // 조용히 재스캔, 아니면 '지난 볼트 다시 연결' 버튼으로 한 번의 제스처만 받아 재선택 없이 붙는다.
  useEffect(() => {
    if (isTauri()) return; // 셸은 위 이펙트가 담당
    if (initRef.current) return;
    initRef.current = true;
    if (qc.getQueryData(['vault'])) return; // 이번 세션에 이미 연동됨(쿼리 캐시 유지)
    let alive = true;
    (async () => {
      const saved = await idbGet<FileSystemDirectoryHandle>('vaultHandle');
      if (!alive || !saved) return;
      const perm = await queryVaultPermission(saved);
      if (!alive) return;
      if (perm === 'granted') {
        try {
          const r = await pickAndScanVault(saved);
          if (alive && r) {
            qc.setQueryData(['vault'], r.scan);
            qc.setQueryData(['vaultHandle'], r.handle);
          }
        } catch {
          if (alive) setPending(saved); // 스캔 실패 → 수동 재연결 유도
        }
      } else {
        setPending(saved);
      }
    })();
    return () => {
      alive = false;
    };
  }, [qc]);

  const doScan = async () => {
    setErr('');
    setBusy(true);
    try {
      const r = await pickAndScanVault();
      if (r) {
        qc.setQueryData(['vault'], r.scan);
        qc.setQueryData(['vaultHandle'], r.handle); // Anki 패널이 같은 폴더 재사용
        idbPut('vaultHandle', r.handle); // 다음 부팅에 재선택 없이 재연결
        setPending(null);
      }
    } catch (e) {
      setErr((e as Error).message || String(e));
    } finally {
      setBusy(false);
    }
  };

  // 저장된 핸들로 재연결 — 제스처 안에서 권한 요청 후 스캔(폴더 재선택 없음).
  const reconnect = async () => {
    if (!pending) return;
    setErr('');
    setBusy(true);
    try {
      const perm = await requestVaultPermission(pending);
      if (perm !== 'granted') {
        setErr('폴더 접근 권한이 필요해요 — 허용하거나, 폴더 연동으로 다시 선택하세요.');
        return;
      }
      const r = await pickAndScanVault(pending);
      if (r) {
        qc.setQueryData(['vault'], r.scan);
        qc.setQueryData(['vaultHandle'], r.handle);
        idbPut('vaultHandle', r.handle);
        setPending(null);
      }
    } catch (e) {
      setErr((e as Error).message || String(e));
    } finally {
      setBusy(false);
    }
  };

  // 연동 해제 — 스캔 결과·공유 폴더 핸들을 캐시·IDB에서 제거(Anki 패널이 재사용하던 핸들도 함께 풀림).
  const disconnect = () => {
    qc.removeQueries({ queryKey: ['vault'], exact: true });
    qc.removeQueries({ queryKey: ['vaultHandle'], exact: true });
    idbDel('vaultHandle');
    setOpen(new Set());
    setPending(null);
    setErr('');
    toast('볼트 폴더 연동을 해제했어요.', 'info');
  };

  const toggle = (i: number) =>
    setOpen((prev) => {
      const next = new Set(prev);
      if (next.has(i)) next.delete(i);
      else next.add(i);
      return next;
    });

  /* 임포트 규칙(W4 포함)은 `shell/importVaultSubject` 가 소유한다 — 과목 탭의
     볼트 임포트와 **같은 함수**여야 한다(종전엔 28줄 사본 둘이었다 · H22). */
  const addSubject = (s: VaultSubject) =>
    importVaultSubject(s, led.data, '학습 항목 탭에서 주당 시간·마감 조정하세요.');
  const addChapter = (s: VaultSubject, c: VaultChapter) => {
    const name = `${s.name} · ${c.name}`;
    if (items.some((x) => x.name === name)) {
      toast('이미 추가됨', 'warn');
      return;
    }
    mutate((st) => {
      st.items.push(makeItem({ source: '볼트', name, weeklyHours: 2, chapters: chaptersFromVault([c]) }));
    });
    toast(`"${name}" 추가됨`, 'ok');
  };

  /* 경로가 둘이라 자리도 둘이었다 — 사용자에겐 "볼트를 못 읽었다" 하나다(FSA 는 `err`,
     셸은 쿼리 캐시). 그리는 자리를 하나로 접는다. */
  const 경고 = err || (scanErr ? `볼트를 읽지 못했어요 — ${scanErr}` : '');

  return (
    <>
      <div className="ds-rule">
        <h2>옵시디언 볼트 현황</h2>
        <div className="ds-row">
          {/* 셸에선 폴더 연동·해제 버튼이 없다 — 볼트 위치를 앱이 알고, 변경은 감시가 알려 준다. */}
          {!isTauri() && (
            <Button sm variant="primary" disabled={busy} onClick={doScan}>
              {busy ? (
                <>
                  <span className="ds-spin" /> 스캔 중...
                </>
              ) : scan ? (
                <>
                  <Icon name="refresh" /> 다시 스캔
                </>
              ) : (
                <>
                  <Icon name="folder" /> 볼트 폴더 연동
                </>
              )}
            </Button>
          )}
          {!isTauri() && !scan && pending && (
            <Button
              sm
              variant="primary"
              disabled={busy}
              onClick={reconnect}
              title="지난번 연동한 폴더에 재선택 없이 다시 연결"
            >
              <Icon name="link" /> 지난 볼트 다시 연결{pending.name ? ` (${pending.name})` : ''}
            </Button>
          )}
          {!isTauri() && scan && (
            <Button
              sm
              variant="ghost"
              danger
              disabled={busy}
              onClick={disconnect}
              title="연동 해제 — 스캔 결과와 폴더 연결을 제거"
            >
              ✕ 연동 해제
            </Button>
          )}
          <div style={{ flex: 3 }} />
        </div>
        <div className="ds-foot">
          {isTauri()
            ? '워크스페이스의 knowledge 폴더를 읽습니다 — 파일이 바뀌면 자동으로 갱신돼요. 항목 옆 ‘+스케줄’로 바로 학습 항목에 넣어요.'
            : "전공 폴더를 고르면 과목→챕터→노트 수와 검증/Anki 상태(YAML)를 읽습니다. 항목 옆 '+스케줄'로 바로 학습 항목에 넣어요. (Chrome/Edge)"}
        </div>
        {/* ⚠ 리전은 **상시 마운트**한다(H19) — 조건부로 넣으면 리전과 텍스트가 동시에 삽입돼 AT 에 따라 공지가 씹힌다. */}
        <LiveRegion message={경고 ?? ''} assertive />
        {경고 && (
          <div className="ds-warnbox" style={{ marginTop: 8 }}>
            {경고}
          </div>
        )}
        {scan && (
          <div className="ds-tiny text-mut" style={{ marginTop: 6 }}>
            <Icon name="folder" /> {isTauri() ? '감시 중' : '연동됨'}:{' '}
            <b style={{ color: 'var(--ink)' }}>{handle?.name || 'knowledge'}</b> · 스캔 {scan.at} · 과목{' '}
            {scan.subjects.length}개{scan.src ? ' · ' + scan.src : ''}
          </div>
        )}
      </div>

      {scan && (
        <div className="ds-rule">
          {scan.subjects.map((s, si) => {
            // 노트 0개면 0/0=NaN → 헤더·진행바가 'NaN%'가 된다. 0%로 가드.
            const vp = s.notes ? Math.round((s.verified / s.notes) * 100) : 0;
            const ep = s.notes ? Math.round((s.exported / s.notes) * 100) : 0;
            // Anki 미출력 = 노트는 있으나 아직 카드가 안 만들어진 것(볼트↔Anki 커버리지 갭). 파생 산술만.
            const uncovered = Math.max(0, s.notes - s.exported);
            const isOpen = open.has(si);
            return (
              <div key={si} className="mb-2.25 overflow-hidden rounded-md border border-line bg-panel">
                <div
                  className="flex cursor-pointer items-center gap-2 px-3.25 py-2.5 transition-[background] hover:bg-panel2"
                  role="button"
                  tabIndex={0}
                  aria-expanded={isOpen}
                  onClick={() => toggle(si)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault();
                      toggle(si);
                    }
                  }}
                >
                  <b style={{ flex: 1 }}>{s.name}</b>
                  <span className="ds-tiny text-mut">
                    노트 {s.notes} · 검증 {s.verified}({vp}%){s.wip ? ` · 진행중 ${s.wip}` : ''}
                    {s.legacy ? ` · 구버전 ${s.legacy}` : ''} · Anki {s.exported}({ep}%)
                    {uncovered > 0 ? ` · 미출력 ${uncovered}` : ''}
                  </span>
                  <Button
                    sm
                    onClick={(e) => {
                      e.stopPropagation();
                      void addSubject(s);
                    }}
                  >
                    +학습항목(챕터 포함)
                  </Button>
                </div>
                <div className="ds-bar" style={{ margin: '0 12px 6px' }}>
                  <i style={{ width: `${vp}%`, background: 'var(--acc)', boxShadow: '0 0 8px var(--glow)' }} />
                </div>
                {isOpen && (
                  <div className="pt-0.5 pr-3.25 pb-2.25 pl-7.5">
                    {s.chapters.length ? (
                      s.chapters.map((c, ci) => (
                        <div
                          key={ci}
                          className="flex items-center gap-2 border-b border-dashed border-line-soft py-1.25 text-md last:border-b-0"
                        >
                          <span className="flex-1">{c.name}</span>
                          <span className="ds-tiny text-mut">
                            {c.notes}노트 · 검증 {c.verified}
                            {c.wip ? ` · 진행중 ${c.wip}` : ''}
                            {c.legacy ? ` · 구버전 ${c.legacy}` : ''} · Anki {c.exported}
                          </span>
                          <Button sm variant="ghost" onClick={() => addChapter(s, c)}>
                            +단일
                          </Button>
                        </div>
                      ))
                    ) : (
                      <div className="ds-tiny text-mut">하위 챕터 없음</div>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </>
  );
}

/* ============================================================
   CourseContext — 과목 화면의 **맥락 카드 둘**: 주차 싱크(T-17) · 선수 관계(T-27).

   ## 왜 한 파일인가

   둘 다 _"이 과목이 다른 것과 어떻게 맞물리나"_ 를 묻는다 — 하나는 **시간축**(교수 진도가
   지금 어디), 하나는 **의존축**(무엇이 먼저여야 하나). 정의(`SubjectDefinition`)는 이 과목
   *자체*를 정하는 자리라 성격이 다르고, 거기 얹으면 이미 745줄인 파일이 더 커진다.

   ## 규율

   - **판정은 lib 이 소유한다**(`lib/syllabus` · `lib/prereq`). 여기는 그리기만 한다 — 이 저장소가
     반복해 세운 경계(판정=lib · 그리기=components/features)를 그대로 따른다.
   - **학기 밖에서는 주차 싱크를 안 그린다.** 주차는 학기 시작일에서 나오는 값이라(T-1) 날짜가
     없으면 "몇 주차"라는 질문 자체가 성립하지 않는다. 그때는 **왜 못 그리는지와 어디서 채우는지**
     를 말한다 — 빈 카드는 고장과 구분되지 않는다.
   - ⚠ **자동으로 시험 범위를 채우지 않는다.** 범위는 교수가 말하는 것이고 앱은 그 자리에 없었다.
     제안을 보여 주고 버튼을 누르게 한다(`suggestExamThru` 머리주석).
============================================================ */
import { useNavigate } from 'react-router-dom';
import { useApp } from '@/store/useApp';
import { isSoftSubject, semesterPhase } from '@/lib/semester';
import { clearSyllabusMark, setSyllabusMark, syllabusOf, syncGap } from '@/lib/syllabus';
import { addPrereq, prereqChain, prereqGaps, removePrereq } from '@/lib/prereq';
import { todayISO } from '@/lib/utils';
import { Button, Pill } from '@/components/ui';
import type { AppState, Item } from '@/lib/types';

type Mutate = (recipe: (st: AppState) => void) => void;

const CARD_T = 'mb-2! ds-caps';

/** 어긋남 한 줄 — **앞섬도 어긋남이다.** 부호로 어휘를 가르되 앞선 것을 경고로 부르지 않는다. */
function GapLine({ gap }: { gap: number }) {
  if (gap === 0)
    return (
      <Pill tiny tone="good">
        수업과 나란함
      </Pill>
    );
  if (gap > 0)
    return (
      <Pill tiny tone={gap >= 3 ? 'bad' : 'warn'}>
        수업이 {gap}챕터 앞서요
      </Pill>
    );
  return (
    <Pill tiny tone="good">
      내가 {-gap}챕터 앞서요
    </Pill>
  );
}

/** T-17 주차 싱크 — 교수 진도를 주차마다 한 점씩 찍고, 내 진도와의 어긋남을 본다. */
function SyllabusCard({ item, mutate }: { item: Item; mutate: Mutate }) {
  const state = useApp((s) => s.state);
  const navigate = useNavigate();
  const phase = semesterPhase(state, todayISO(state));
  const chapters = item.chapters || [];
  const marks = syllabusOf(item);

  if (phase.kind !== 'in' || phase.week === null)
    return (
      <div className="ds-rule">
        <h3 className={CARD_T}>수업 진도</h3>
        <p className="ds-tiny text-mut">
          {phase.kind === 'pre' ? '개강 후에 주차가 시작돼요.' : '학기 날짜가 없어 “몇 주차”를 알 수 없어요.'}
        </p>
        <Button sm variant="ghost" className="mt-2.5" onClick={() => navigate('/degree')}>
          학기 날짜 넣기 →
        </Button>
      </div>
    );

  const week = phase.week;
  const g = syncGap(item, week);
  const thisWeek = marks.find((m) => m.week === week);

  return (
    <div className="ds-rule">
      <h3 className={CARD_T}>수업 진도 — {week}주차</h3>
      <div className="mb-2 flex items-center gap-2">
        {g.known ? (
          <GapLine gap={g.gap} />
        ) : (
          <span className="ds-tiny text-mut">아직 기록이 없어요 — 이번 주부터 찍으면 어긋남이 보입니다.</span>
        )}
      </div>
      <div className="ds-fld">
        <label htmlFor={`syl-${item.id}`}>이번 주에 나간 데까지</label>
        <select
          id={`syl-${item.id}`}
          value={thisWeek?.thru || ''}
          onChange={(e) => {
            const v = e.target.value;
            mutate((st) => {
              const it = st.items.find((i) => i.id === item.id);
              if (!it) return;
              if (v) setSyllabusMark(it, week, v);
              else clearSyllabusMark(it, week);
            });
          }}
        >
          <option value="">(기록 없음)</option>
          {chapters.map((c) => (
            <option key={c.id} value={c.id}>
              {c.name}
            </option>
          ))}
        </select>
      </div>
      {marks.length > 0 && (
        <ul className="m-0 mt-2.5 flex list-none flex-col gap-1 p-0">
          {marks.slice(-4).map((m) => (
            <li key={m.week} className="flex items-center gap-2 text-md">
              <span className="w-12 flex-none text-mut tabular-nums">{m.week}주</span>
              <span className="min-w-0 flex-1 truncate">
                {chapters.find((c) => c.id === m.thru)?.name ?? '(지워진 챕터)'}
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/** T-27 선수 관계 — 무엇이 먼저여야 하고, 그중 무엇이 비어 있나. */
function PrereqCard({ item, mutate }: { item: Item; mutate: Mutate }) {
  const state = useApp((s) => s.state);
  const navigate = useNavigate();
  const chain = prereqChain(state, item.id);
  const gaps = prereqGaps(state, item);
  const linked = new Set(item.prereqIds || []);
  const candidates = state.items.filter((i) => i.id !== item.id && !linked.has(i.id));

  return (
    <div className="ds-rule">
      <h3 className={CARD_T}>선수 과목</h3>
      {chain.cycle && (
        /* ⚠ 조용히 멈추지 않는다 — 멈추기만 하면 선행 하나가 왜 빠졌는지 영원히 알 수 없다. */
        <p className="ds-tiny mb-2 text-bad">선수 관계가 서로를 가리켜요(순환) — 한쪽 링크를 지워 주세요.</p>
      )}
      {(item.prereqIds?.length ?? 0) === 0 ? (
        <p className="ds-tiny text-mut">지정된 선수 과목이 없어요.</p>
      ) : (
        <ul className="m-0 flex list-none flex-col gap-1.5 p-0">
          {(item.prereqIds || []).map((pid) => {
            const p = state.items.find((i) => i.id === pid);
            const gap = gaps.find((x) => x.item.id === pid);
            return (
              <li key={pid} className="flex items-center gap-2 text-md">
                <span className="min-w-0 flex-1 truncate">{p?.name ?? '(지워진 과목)'}</span>
                {gap && (
                  <Pill tiny tone="warn">
                    {gap.missing.length}/{gap.total} 비었음
                  </Pill>
                )}
                {p && (
                  <Button sm variant="ghost" onClick={() => navigate(`/subject/${p.id}`)}>
                    →
                  </Button>
                )}
                <Button
                  sm
                  variant="ghost"
                  aria-label={`${p?.name ?? '선수 과목'} 링크 지우기`}
                  onClick={() =>
                    mutate((st) => {
                      const it = st.items.find((i) => i.id === item.id);
                      if (it) removePrereq(it, pid);
                    })
                  }
                >
                  ✕
                </Button>
              </li>
            );
          })}
        </ul>
      )}
      {candidates.length > 0 && (
        <div className="ds-fld mt-2.5">
          <label htmlFor={`pre-${item.id}`}>선수 과목 추가</label>
          <select
            id={`pre-${item.id}`}
            value=""
            onChange={(e) => {
              const v = e.target.value;
              if (!v) return;
              mutate((st) => {
                const it = st.items.find((i) => i.id === item.id);
                if (it) addPrereq(it, v);
              });
            }}
          >
            <option value="">(고르기)</option>
            {candidates.map((c) => (
              <option key={c.id} value={c.id}>
                {c.name}
              </option>
            ))}
          </select>
        </div>
      )}
      {gaps.length > 0 && (
        <p className="ds-tiny mt-2.5 text-mut">
          결손은 <b>안 끝났고 미루지도 않은</b> 챕터만 셉니다 — 미룬 것은 모르는 것이 아니에요.
        </p>
      )}
    </div>
  );
}

export function CourseContext({ item, mutate }: { item: Item; mutate: Mutate }) {
  /* P10 D6 — 소양 과목엔 **주차 싱크를 안 그린다.** 그 카드가 묻는 것은 _"교수가 지금 어디까지
     나갔나"_ 인데 소양엔 교수도 강의 주차도 없다. 위 규율("빈 카드는 고장과 구분되지 않는다")을
     그대로 적용하면 답은 *안내를 다르게 쓰는 것*이 아니라 **안 그리는 것**이다 — 채울 방법이
     아예 없는 칸이라 어디로 보낼 곳도 없다.
     ⚠ 선수 관계는 남긴다: 소양 과목에도 "이게 먼저다"는 성립한다(학기 회계와 무관한 축이다). */
  return (
    <>
      {!isSoftSubject(item) && <SyllabusCard item={item} mutate={mutate} />}
      <PrereqCard item={item} mutate={mutate} />
    </>
  );
}

/* ============================================================
   ExamSheet — **T-18 시험 전날 한 장**(`/subject/:id?view=sheet`).

   ## 왜 새 탭이 아닌가

   이 화면은 **한 과목의 상세**다 — 객체 축(`/subject/:id`)이 이미 그 자리이고, W7 이 탭을 줄이는
   중이라 여기서 25번째 탭을 세우면 재편이 아니라 증식이 된다. `graph` 가 `/items?view=structure`
   로 내려온 것과 **같은 관용구**(P-19): 호스트는 그대로, 뷰만 하나 더. lazy 라 시트를 안 여는
   방문에는 파서도 이 화면도 안 내려온다.

   ## 화면 = 선택 목록 + 접힌 결과

   왼쪽에서 챕터를 고르고 오른쪽에 한 장이 선다. **기본 선택은 다가오는 시험의 범위**다
   (`examScopes` · T-1 이 만든 그릇) — 시험 전날에 여는 화면이므로 고를 것을 고르게 두되
   *첫 화면부터 답에 가깝게* 둔다.

   ## ⚠ 이 화면이 조용히 거짓말할 수 있는 자리 셋 — 전부 다르게 말한다

   ① **볼트를 못 읽는다**(브라우저·워크스페이스 미설정) → 콜드 게이트 문구.
   ② **폴더는 읽혔는데 노트가 0** → 그 챕터 이름의 폴더가 볼트에 없다는 뜻(직접 만든 과목).
   ③ **노트는 읽혔는데 항목이 0**(`parsed=false`) → 마크업이 우리 규약과 다르다.
   ②와 ③을 같은 픽셀로 그리면 사용자는 자기 노트가 비었다고 오해한다(`lib/examSheet` 규율 2).
============================================================ */
import { useMemo, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { useNavigate } from 'react-router-dom';
import type { Item } from '@/lib/types';
import { vaultNotesText } from '@/lib/tauri';
import { isTauri } from '@/lib/isTauri';
import { artifactErrorCopy } from '@/lib/artifactState';
