import { SubjectDefinition } from './SubjectDefinition';
import { CourseContext } from './CourseContext';
import { SHEET_VIEW } from '@/shell/tabs';

/* T-18 — **시험 전날 한 장**은 이 화면의 두 번째 뷰다(`?view=sheet`). `graph` 가 `/items` 의 뷰로
   내려온 것과 같은 관용구(P-19): 호스트는 그대로, 탭은 안 늘어난다.
   ⚠ **lazy** — 볼트 본문 파서는 시트를 여는 방문에만 필요하다. */
const ExamSheet = lazy(() => import('./ExamSheet'));

const COL = 'flex min-h-0 min-w-0 flex-col gap-3.5 overflow-y-auto [scrollbar-width:thin]';
const CARD_T = 'mb-2! ds-caps';

/** 앎 컬럼 — 원장 5단계(이 과목) + 지식엔진 숙달. **계산은 각 lib 이 이미 소유한다.** */
function Knowing({ name }: { name: string }) {
  const led = useLedger();
  const ping = usePing();
  const know = useKnowledge(ping.isSuccess).data;
  const navigate = useNavigate();

  const names = Object.keys(led.data?.subjects || {});
  const li = matchSubjectIndex(name, names);
  const roll = li >= 0 ? subjectRollup(names[li]!, led.data!.subjects[names[li]!]!) : null;

  const kSubs = know?.subjects || [];
  const kNames = kSubs.map((s) => s.subject);
  const ki = matchSubjectIndex(name, kNames);
  const mastery = ki >= 0 ? (kSubs[ki]?.mastery ?? null) : null;

  return (
    <div className={COL}>
      <div className="ds-rule">
        <h3 className={CARD_T}>원장 — 챕터가 얼마나 멀리 갔나</h3>
        {roll ? (
          <>
            <div className="flex flex-col gap-1.5">
              {LEDGER_STAGES.map((st) => {
                const n = roll.reached[st];
                return (
                  <div key={st} className="flex items-center gap-2 text-md">
                    <span className="w-14 flex-none text-mut">{STAGE_META[st].label}</span>
                    <span className="h-1.5 flex-1 overflow-hidden rounded-full bg-panel2">
                      <i
                        className="block h-full rounded-full"
                        style={{
                          width: `${roll.total ? (n / roll.total) * 100 : 0}%`,
                          background: STAGE_META[st].color,
                        }}
                      />
                    </span>
                    <b className="w-12 flex-none text-right tabular-nums">
                      {n}/{roll.total}
                    </b>
                  </div>
                );
              })}
            </div>
            <Button sm variant="ghost" className="mt-2.5" onClick={() => navigate('/ledger')}>
              원장 전체 보기 →
            </Button>
          </>
        ) : (
          <p className="ds-tiny text-mut">볼트 원장에 이 과목이 아직 없어요(워크스페이스·빌드 필요).</p>
        )}
      </div>
      <div className="ds-rule">
        <h3 className={CARD_T}>숙달도 — 지식엔진</h3>
        {mastery != null ? (
          <>
            <div className="text-2xl font-extrabold tabular-nums">{pctLabel(mastery)}</div>
            <Button sm variant="ghost" className="mt-2" onClick={() => navigate('/mastery')}>
              숙달도 지도 →
            </Button>
          </>
        ) : (
          /* ⚠ "0%" 로 그리지 않는다 — 값 부재와 값 0 이 같은 픽셀이 되면 그게 곧 조용한 거짓말이다
             (`visits.ts` 가 물린 "쌓이고 있다는 믿음만 쌓인다"와 같은 부류). */
          <p className="ds-tiny text-mut">아직 관측이 없어요 — 지식엔진이 이 과목을 아직 모릅니다.</p>
        )}
      </div>
    </div>
  );
}

/** 인출 컬럼 — 이 과목의 밀린 챕터 + 반복 약점. sid 가 고정이라 눈으로 행을 찾지 않는다. */
function Retrieval({ sid }: { sid: string }) {
  const state = useApp((s) => s.state);
  const res = useSchedule();
  const navigate = useNavigate();
  const today = todayISO(state);
  /* ⚠ 메모가 필수다 — 이 컴포넌트는 `useApp((s) => s.state)` 로 루트 참조를 구독하므로 앱의
     어떤 편집이든 리렌더되고, `riskChapters` 는 그때마다 챕터 전량의 사다리를 다시 판정한다
     (2026-08-20 리뷰 m-9). 아래 행별 `chapterStrength` 도 같은 이유로 한 번에 접는다. */
  const risky = useMemo(
    () => riskChapters(state, res.days || [], today, 100).filter((c) => c.sid === sid),
    [state, res.days, today, sid],
  );
  const strengths = useMemo(() => chapterStrengths(state, today), [state, today]);
  const weak = (state.cbms || []).filter((c) => c.sid === sid);

  return (
    <div className={COL}>
      <div className="ds-rule">
        <h3 className={CARD_T}>복습 위험 — 오래 안 본 챕터</h3>
        {risky.length ? (
          <ul className="m-0 flex list-none flex-col gap-1.5 p-0">
            {risky.slice(0, 10).map((c) => {
              // T-5 챕터 기억 강도 — "언제 봤나"(일수) 옆에 **"얼마나 붙었나"**를 놓는다.
              // ⚠ `unseen` 은 **안 그린다**: 표본 0을 칩으로 그리면 값 부재와 값 0 이 같은 픽셀이
              //   되고, 그게 곧 조용한 거짓말이다(이 파일이 숙달도에서 이미 피한 함정).
              const st = strengths.get(sid + '|' + c.chapter) ?? unseenAt(state, sid, c.chapter, today);
              return (
                <li key={c.chapter} className="flex items-center gap-2 text-md">
                  <span className="min-w-0 flex-1 truncate">{c.chapter}</span>
                  {c.fromVault && <span className="ds-pill ds-tiny">볼트</span>}
                  {st.band !== 'unseen' && (
                    <Pill tiny tone={st.band === 'shaky' ? 'warn' : 'good'}>
                      {BAND_LABEL[st.band]} {st.passes}/{st.attempts}
                    </Pill>
                  )}
                  <b className={`tabular-nums ${c.risk === 'overdue' ? 'text-bad' : 'text-warn'}`}>{c.daysSince}일</b>
                </li>
              );
            })}
          </ul>
        ) : (
          <p className="ds-tiny text-mut">밀린 챕터가 없어요.</p>
        )}
        <Button sm variant="ghost" className="mt-2.5" onClick={() => navigate('/review-run')}>
          지금 인출 →
        </Button>
      </div>
      <div className="ds-rule">
        <h3 className={CARD_T}>오답 · 약점 {weak.length ? `· ${weak.length}건` : ''}</h3>
        {weak.length ? (
          <ul className="m-0 flex list-none flex-col gap-1.5 p-0">
            {weak.slice(0, 8).map((c) => (
              <li key={c.id} className="truncate text-md">
                <span className="ds-tiny mr-1.5 text-mut">{c.code}</span>
                {c.chapter || '(챕터 미기재)'}
              </li>
            ))}
          </ul>
        ) : (
          <p className="ds-tiny text-mut">기록된 약점이 없어요.</p>
        )}
        {/* `?sid=` 를 원래 받던 유일한 화면 — 객체 축이 서면 그 관용구가 예외가 아니라 규칙이 된다. */}
        <Button sm variant="ghost" className="mt-2.5" onClick={() => navigate(`/mistakes?sid=${sid}`)}>
          오답 노트에서 보기 →
        </Button>
      </div>
    </div>
  );
}

export default function Subject() {
  const { id = '' } = useParams();
  const navigate = useNavigate();
  const [params, setParams] = useSearchParams();
  const sheet = params.get('view') === SHEET_VIEW;
  /* U011 — 머리주석이 약속한 `#ch-<id>` 착지를 **실제로** 일으킨다. 그 약속은 2026-07-31 부터
     적혀 있었지만 `.hash` 를 읽는 코드가 저장소에 0이라 한 번도 안 일어났다.
     ⚠ 챕터 표가 렌더된 뒤여야 하므로 과목 id·챕터 수를 의존성으로 함께 넘긴다. */
  const { hash } = useLocation();
  const items = useApp((s) => s.state.items);
  const state = useApp((s) => s.state);
  const mutate = useApp((s) => s.mutate);
  const res = useSchedule();
  const item = items.find((i) => i.id === id) ?? null;
  const today = todayISO(state);
  const wk = weekMonOf(today);
  const allocMin = item ? rowSumMin(allocView(state, res, wk)[item.id]) : 0;
  const chs = item?.chapters || [];
  const doneCh = chs.filter((c) => c.done).length;
  const weakN = item ? (weakCountBySid(state)[item.id] ?? 0) : 0;
  const nextExam = item ? nextExamOf(item, today) : null;
  useHashTarget(sheet ? '' : hash, `${id ?? ''}:${chs.length}`);
  /* Q-5 — 추정 배율. **표본이 얇으면 null 이고 그때는 안 그린다**(값 부재 ≠ 배율 1.0).
     게이트는 `lib/estimateCalibration` 이 소유한다 — 화면이 문턱을 다시 판단하면 화면마다 갈린다. */
  const calib = item ? subjectCalibration(state, item.id) : null;
  /* I013 — 이 과목의 **수업 시간**. 종전엔 수업이 「가용시간을 깎는 장애물」이기만 해서, 주 10시간을
     먹는 강의가 과목 화면 어디에도 없었다(실측 2026-08-22). 0이면 안 그린다 — 안 묶인 것이
     정상이고(교양·전공 밖), 「0 h」는 «수업이 없다»가 아니라 «아직 안 묶였다»라 오독을 만든다. */
  const lectureMin = item ? weeklyLectureMin(state, item.id) : 0;

  /* W22 의 짝 — destination 이 아니어도 **객체 화면은 자기 이름과 수를 크게 말한다**(원칙 ②).
     이 화면의 존재 이유가 "그 과목 지금 어떤가"라 리드아웃이 곧 답의 첫 줄이다. */
  usePageChromeEffect(
    () => ({
      primary: item ? { label: item.name || '(이름 없음)', value: `${doneCh}/${chs.length || 0} 챕터` } : null,
      readouts: !item
        ? []
        : [
            { label: '이번 주 배분', value: `${hNum(allocMin)} h` },
            ...(lectureMin ? [{ label: '주간 강의', value: `${hNum(lectureMin)} h` }] : []),
            { label: '약점', value: weakN || '—' },
            ...(calib ? [{ label: '추정 대조', value: calibrationLabel(calib) }] : []),
            // T-1. 다가오는 시험이 있으면 그것이 이 과목의 리드아웃이다("기말"이 아니라 "중간 D-7").
            {
              label: nextExam ? `${EXAM_LABEL[nextExam.kind]}고사` : '유형',
              value: nextExam ? ddayInfo(dayDiff(today, nextExam.date)).lab : item.mode === 'daily' ? '매일' : '주간',
            },
          ],
    }),
    [item, doneCh, chs.length, allocMin, weakN, today],
  );

  /* Q-13 ①단 — 확인창 없이 커밋하고 ⌘Z 로 가리킨다(사다리 SSOT `shell/destructive.ts`).
     ⚠ 세 줄이 **한 `mutate` 안**이어야 하는 이유는 그대로다(참조 무결성) — 그리고 그게 곧
     ⌘Z 한 번이 셋을 함께 되돌리는 조건이다. */
  const removeItem = useCallback(
    (sid: string) => {
      const it = items.find((s) => s.id === sid);
      commitUndoable(`"${(it && it.name) || '과목'}" 삭제됨 (챕터·진행 기록도 함께)`, () => {
        mutate((st) => {
          st.items = st.items.filter((s) => s.id !== sid);
          removeSidFromAlloc(st, sid); // 참조 무결성 — Items 의 삭제와 **같은 세 줄**이어야 한다
          removeSidFromDayPlans(st, sid);
        });
      });
      navigate('/items', { replace: true });
    },
    [items, mutate, navigate],
  );

  if (!item)
    return (
      <State
        kind="empty"
        glyph="search"
        title="그 과목이 없어요"
        desc="삭제됐거나 링크가 낡았어요."
        next={
          <Button variant="primary" onClick={() => navigate('/items')}>
            과목 목록으로
          </Button>
        }
      />
    );

  /* T-18 뷰 — 같은 과목의 두 번째 표현. `lazy` 라 상세만 보는 방문엔 안 내려온다. */
  if (sheet)
    return (
      <Suspense fallback={<State kind="loading" title="한 장 준비 중…" shape="frame" />}>
        <ExamSheet item={item} todayDs={today} />
      </Suspense>
    );

  return (
    <section className="grid min-h-0 flex-1 grid-cols-3 gap-4 px-5.5 pt-2 pb-5.5 max-wide:grid-cols-1 max-wide:overflow-y-auto">
      <div className={COL}>
        <div className="flex items-center gap-2">
          <Pill tiny>{item.source || '직접'}</Pill>
          <Button sm variant="ghost" onClick={() => navigate('/items')}>
            ← 과목 목록
          </Button>
          {/* T-18 — 시험 전날에 여는 문. 시험이 있으면 그 사실을 라벨이 말한다. */}
          <Button sm variant="ghost" onClick={() => setParams({ view: SHEET_VIEW })}>
            {nextExam ? `${EXAM_LABEL[nextExam.kind]} 한 장` : '한 장'} →
          </Button>
        </div>
        <SubjectDefinition item={item} mutate={mutate} onDelete={removeItem} />
        {/* T-17·T-27 — 이 과목이 **다른 것과 어떻게 맞물리나**(시간축·의존축). 정의 아래가 자리다. */}
        <CourseContext item={item} mutate={mutate} />
      </div>
      <Knowing name={item.name} />
      <Retrieval sid={item.id} />
    </section>
  );
}

/* ============================================================
   VaultImport — 과목 세그먼트 인라인 '볼트/Anki에서 불러오기'(계획개편 §5-2).
   연동 탭 VaultPanel·AnkiPanel과 같은 lib(pickAndScanVault·pickAndScanAnki·chaptersFromVault·makeItem)·
   같은 쿼리 캐시(['vault']·['ankiFile']·['vaultHandle'])를 호출한다(코드 이동 아님 · 두 곳에서 같은 훅).
   여기선 '연결→항목 추가'만 — 해제/실시간 due/트리 상세는 연동 탭 소유. 탭 이동 없이 과목을 넣는다.
============================================================ */
import LiveRegion from '@/components/LiveRegion';
import { useState } from 'react';
import { useQuery, useQueryClient, skipToken } from '@tanstack/react-query';
import { useApp } from '@/store/useApp';
import { importVaultSubject, toast } from '@/shell';
import { pickAndScanVault, type VaultScan, type VaultSubject } from '@/lib/vault';
import { isTauri } from '@/lib/tauri';
import { pickAndScanAnki, type AnkiFile } from '@/lib/anki';
import { idbPut } from '@/lib/idb';
import { makeItem, jsq } from '@/lib/utils';
import { useLedger } from '@/store/queries';
import { Button } from '@/components/ui';
import { Icon } from '@/components/Icon';

// Items.module.css → Tailwind 이식(C-7) 잔여 3종. 볼트/Anki 스캔 결과의 컴팩트 행.
const VAULT_LIST = 'mt-2.5 flex max-h-[var(--vault-list-vh)] flex-col gap-1.5 overflow-y-auto';
const VAULT_ROW = 'flex items-center gap-2.5 rounded-md bg-panel2 px-2.5 py-1.75 shadow-inset-line2';
const VAULT_NAME = 'min-w-0 flex-1 truncate text-md font-bold';

export function VaultImport({ onClose }: { onClose?: () => void }) {
  const qc = useQueryClient();
  const mutate = useApp((s) => s.mutate);
  const items = useApp((s) => s.state.items);
  const scan = useQuery<VaultScan>({ queryKey: ['vault'], queryFn: skipToken }).data;
  const anki = useQuery<AnkiFile>({ queryKey: ['ankiFile'], queryFn: skipToken }).data;
  // 원장(W4) — 임포트 직후 "카드까지 갔다"를 물으려면 여기서 실제로 읽어야 한다(구독만으론 비어 있다).
  const led = useLedger();
  const [busy, setBusy] = useState<'' | 'vault' | 'anki'>('');
  const [err, setErr] = useState('');

  /* ⚠ 셸의 볼트 스캔은 **`app/VaultSync` 가 부팅에 한다**(W3 · 2026-07-31). 종전엔 여기와
     연동 탭에 각자 있었고, 그래서 두 화면 중 하나를 열기 전까지 `['vault']` 가 비어 있었다. */

  /* 셸(3단계)에선 볼트가 `<워크스페이스>/knowledge` 라 폴더를 묻지 않는다. 부팅에 이미 읽혀
     있고 감시가 갱신하므로 이 버튼 자체가 필요 없다 — 아래 렌더에서 숨긴다.
     여기 남은 경로는 브라우저(dev·트랙 A)용이다. */
  const doScanVault = async () => {
    setErr('');
    setBusy('vault');
    try {
      const r = await pickAndScanVault();
      if (r) {
        qc.setQueryData(['vault'], r.scan);
        qc.setQueryData(['vaultHandle'], r.handle); // 연동 탭·Anki가 같은 폴더 재사용
        idbPut('vaultHandle', r.handle);
      }
    } catch (e) {
      setErr((e as Error).message || String(e));
    } finally {
      setBusy('');
    }
  };
  const doScanAnki = async () => {
    setErr('');
    setBusy('anki');
    try {
      const handle = qc.getQueryData<FileSystemDirectoryHandle>(['vaultHandle']);
      const r = await pickAndScanAnki(handle);
      if (r) {
        qc.setQueryData(['ankiFile'], r.scan);
        qc.setQueryData(['vaultHandle'], r.handle);
        idbPut('vaultHandle', r.handle);
      }
    } catch (e) {
      setErr((e as Error).message || String(e));
    } finally {
      setBusy('');
    }
  };

  /* 임포트 규칙(W4 포함)은 `shell/importVaultSubject` 가 소유한다 — 연동 탭의
     볼트 패널과 **같은 함수**여야 한다(종전엔 28줄 사본 둘이었다 · H22). */
  const addSubject = (s: VaultSubject) => importVaultSubject(s, led.data, '주당 시간·마감을 조정하세요.');
  const addAnki = (name: string, mins: number) => {
    const nm = 'Anki: ' + name;
    if (items.some((x) => x.name === nm)) {
      toast('이미 추가됨', 'warn');
      return;
    }
    mutate((st) => {
      st.items.push(makeItem({ source: 'Anki', name: nm, mode: 'daily', dailyMin: mins }));
    });
    toast(`"${nm}" 매일 ${mins}분 복습으로 추가됨`, 'ok');
  };

  return (
    <div className="ds-rule" style={{ marginBottom: 14 }}>
      <div className="ds-row" style={{ alignItems: 'center', flexWrap: 'wrap' }}>
        <b style={{ flex: 1 }}>
          <Icon name="folder" /> 볼트 / Anki에서 불러오기
        </b>
        {!isTauri() && (
          <Button sm variant="primary" disabled={!!busy} onClick={doScanVault}>
            {busy === 'vault' ? (
              <>
                <span className="ds-spin" /> 스캔 중…
              </>
            ) : scan ? (
              <>
                <Icon name="refresh" /> 볼트 다시 스캔
              </>
            ) : (
              '볼트 폴더 연동'
            )}
          </Button>
        )}
        <Button sm disabled={!!busy} onClick={doScanAnki}>
          {busy === 'anki' ? (
            <>
              <span className="ds-spin" /> 스캔 중…
            </>
          ) : (
            <>
              <Icon name="cards" /> Anki 카드 스캔
            </>
          )}
        </Button>
        {onClose && (
          <Button sm variant="ghost" onClick={onClose} aria-label="불러오기 닫기">
            닫기
          </Button>
        )}
      </div>
      <div className="ds-foot">
        볼트=전공 폴더의 과목→챕터. Anki=덱을 '매일 복습' 항목으로. 검증/실시간 due 상세·연동 해제는 연동 탭에서.
        (Chrome/Edge)
      </div>
      {/* ⚠ 리전은 **상시 마운트**한다(H19) — 조건부로 넣으면 리전과 텍스트가 동시에 삽입돼 AT 에 따라 공지가 씹힌다. */}
      <LiveRegion message={err ?? ''} assertive />
      {err && (
        <div className="ds-warnbox" style={{ marginTop: 8 }}>
          {err}
        </div>
      )}
      {scan && (
        <div className={VAULT_LIST}>
          {scan.subjects.length === 0 ? (
            <div className="ds-tiny text-mut">스캔된 과목이 없어요 — 폴더 구조를 확인하세요.</div>
          ) : (
            scan.subjects.map((s, si) => {
              const added = items.some((x) => x.name === s.name);
              return (
                <div key={si} className={VAULT_ROW}>
                  <span className={VAULT_NAME}>{s.name}</span>
                  <span className="ds-tiny text-mut">
                    노트 {s.notes} · 챕터 {s.chapters.length}
                  </span>
                  <Button sm variant={added ? 'ghost' : 'primary'} disabled={added} onClick={() => void addSubject(s)}>
                    {added ? '추가됨' : '+ 학습항목'}
                  </Button>
                </div>
              );
            })
          )}
        </div>
      )}
      {anki && anki.decks.length > 0 && (
        <div className={VAULT_LIST}>
          {anki.decks.map((d) => {
            const nm = 'Anki: ' + jsq(d.file);
            const added = items.some((x) => x.name === nm);
            return (
              <div key={d.file} className={VAULT_ROW}>
                <span className={VAULT_NAME}>
                  <Icon name="cards" /> {d.file}
                </span>
                <span className="ds-tiny text-mut">{d.cards}장</span>
                <Button
                  sm
                  variant={added ? 'ghost' : 'primary'}
                  disabled={added}
                  onClick={() => addAnki(jsq(d.file), Math.max(15, Math.round(d.cards * 0.5)))}
                >
                  {added ? '추가됨' : '+ 매일복습'}
                </Button>
              </div>
            );
          })}
        </div>
      )}
      {anki && anki.decks.length === 0 && (
        <div className="ds-tiny text-mut" style={{ marginTop: 6 }}>
          스캔된 Anki 덱이 없어요 — 정본 인덱스나 anki/*.txt 폴더를 확인하세요.
        </div>
      )}
    </div>
  );
}

/* ============================================================
   Ledger — 탭: 📒 정본 원장
   ⚠ 종전 이 줄은 _"자료 그룹 · 연동 현황과 세그먼트 페어"_ 였다(M-16 · 2026-08-06 정정).
   `integrations` 가 호스트에서 렌즈로 내려가며 이 탭은 **앎 호스트**로 옮겨졌고, 그 페어는
   더 이상 존재하지 않는다. 배치의 정본은 `shell/tabs.ts` 의 `SUBTAB_GROUPS` — 여기 사본을
   두면 다음 IA 개편에 또 낡는다.
   과목×챕터의 5단계 파이프라인(sourced→noted→verified→carded→reviewed) 진척을 한 화면에.
   원본: 산출물 `ledger` ← knowledge/_meta/cache/_챕터원장.json (챕터원장.py). 통합 4단계 소비.
   흩어져 있던 볼트 생산 진척(진척 14곳)을 단일 출처로 모은다 — "각 과목이 파이프라인 어디까지 왔나".

   today 재설계 사상: 상단 리드아웃(챕터·검증·카드) · fill 프레임 · 히어로 퍼널 · 온디맨드 챕터 세부.
   데이터 원본은 볼트 빌드 산출물(읽기전용) — 워크스페이스가 설정돼 있으면 자동, 오프라인이면 안내(mastery와 동형).

   ── C-7 아홉 번째 이식(ledger) — Tailwind ─────────────────────────────────────
   레이아웃이 mastery 와 동형이라 인프라를 크게 승계한다: 지식맵/폴백 그래디언트(--bg-map-panel),
   상단 헤어라인(--bg-sig-top), 마운트 페이드업(enter-rise 키프레임), shadow-hero/card, hero-gap/px.
   새로 이름 준 것: 히어로 그래디언트(violet 층 없는 변형 · --bg-hero-ledger)·퍼널 막대 트랙
   (--bar-track)·2컬럼 트랙(380px)·상세 오버레이 폭·퍼널 gap·eyebrow 자간(0.24em)·상세 그림자(lg).
   전역 요소 규칙을 이기는 `!`(control §15-7): h2 히어로 제목·셋업/에러 h3·셀/딥링크 버튼(border/padding/radius).
   런타임 색 주입(퍼널 채움·셀·범례 스와치·단계 점 = style={{ background }})은 절대규칙 #3 구현이라 인라인 유지.
============================================================ */
import { Suspense, lazy, useEffect, useRef, useState } from 'react';
