const NOTE_CAP = 2;

/* ── N-4 지식요소 태그(발산 6회차 · 2026-08-07) ────────────────────────────
   여기가 입구인 이유: 이 축의 검증이 *"기존 오답에 손으로 달아 본다"* 이고, 기존 오답이
