      <div className={ROW_TOP}>
        <span className={NAME}>{row.subject}</span>
        {/* 챕터가 비어 있는 기록도 버리지 않는다 — 과목 단위로라도 "여기서 반복해 막힌다"는 사실이 남는다. */}
        <span className={CH}>{row.chapter || '(챕터 미기재)'}</span>
        <span className={META}>
          {row.codes.map((c) => (
            <CodeChip key={c} code={c} />
          ))}
          <span title="이 칸의 오답 기록 수">{row.count}회</span>
          {/* 과신은 따로 짚는다 — '안다고 믿어 복습을 건너뛰는' 방향이라 단순 횟수와 무게가 다르다. */}
          {row.confident > 0 && <span className="font-bold text-warn">확신 오답 {row.confident}</span>}
          <span title="마지막으로 틀린 날">{row.lastDs}</span>
        </span>
      </div>
      {/* ── P-14 행동 한 줄 ─────────────────────────────────────────────────
          이 화면은 "무엇이 반복해서 나를 막는가"까지 답하고 **끝났다** — 읽고 나서 무엇을
          할지가 없으니 다시 안 읽혔다. 처방은 `CBMS_INFO.tip` 의 **파생**이라 새 저장 필드가
          0이다(항목별 행동을 사용자가 적게 하면 그건 새 입력이고 §1-b 대상이 된다).
          ⚠ 오늘 3건에만 붙인다 — 전량 목록에 붙이면 같은 다섯 문장이 스무 번 반복돼
            처방이 배경 무늬가 된다. */}
      {action && (
        <p className={ACTION}>
          <span aria-hidden="true">→ </span>
          {CBMS_INFO[row.topCode].tip}
        </p>
      )}
      {row.notes.slice(0, NOTE_CAP).map((n) => (
        <div key={n.ds + n.text} className={NOTE} title={n.text}>
          {n.ds} — {n.text}
        </div>
      ))}
      {kc && <KcTags tags={kc.tags} known={kc.known} onAdd={kc.add} onRemove={kc.remove} />}
      <div className={ACTS}>
        <button type="button" className={MINI} onClick={onDrill}>
          ↻ 다시 인출하기
        </button>
        <button type="button" className={MINI} onClick={onSeed}>
          <Icon name="inbox" /> 보충에 담기
        </button>
        <button
          type="button"
          className={MINI} /* H14 — 종전엔 `chapter || subject` 라 챕터가 있으면 **과목을 버렸다**(다른 화면 넷과
           정반대). 질의 조립은 `lib/utils.vaultQuery` 하나가 소유한다. */
          onClick={() => openVaultSearch(vaultQuery(row.subject, row.chapter))}
        >
          <Icon name="search" /> 볼트
        </button>
      </div>
    </article>
  );
}

export default function Mistakes() {
  const state = useApp((s) => s.state);
  const mutate = useApp((s) => s.mutate);
  const nav = useNavigate();
  /* ⚠ 필터 초기값을 **URL 에서 받는다**(A11). 종전엔 순수 로컬 state 라 `/mistakes?sid=…` 로
     보내도 전체 목록에 떨어졌다 — ⌘K 오답 히트·챕터 서랍의 '오답 N건' 이 데려다줄 곳이
     없었다는 뜻이다(찾아주는 것과 데려다주는 것은 다르다 · `contentSearch` 머리주석의 같은 규율).
     ⚠ 초기값만 읽고 그 뒤로는 사용자 조작이 소유한다 — URL 을 계속 따라가면 칩을 눌러 필터를
       바꾼 순간 주소와 화면이 어긋나거나, 되돌아가기가 필터 조작을 되감는다. */
  const [params] = useSearchParams();
  const [sid, setSid] = useState(() => params.get('sid') ?? '');
  const [code, setCode] = useState<CbmsCode | ''>(() => (params.get('code') as CbmsCode | null) ?? '');

  const rows = mistakeArchive(state, { sid: sid || undefined, code: code || undefined });
  const totals = mistakeTotals(rows);
  /* P-14 — 오늘 볼 창(날짜 회전 · 규칙은 `lib/mistakes` 가 소유). 필터가 걸려 있으면 그 결과
     안에서 돈다 — 데려온 필터를 무시하고 전체에서 뽑으면 딥링크가 엉뚱한 것을 보여 준다. */
  const picks = todayMistakes(rows, todayISO(state));
  // 필터 칩은 **전 기간에 실제로 기록이 있는 과목**만 — 안 틀린 과목까지 나열하면 필터가 소음이 된다.
  const subjects = [...new Map((state.cbms || []).map((e) => [e.sid, e.name || '?'])).entries()];

  usePageChromeEffect(
    () => ({
      /* N-15 `primary` — 이 탭의 질문은 "어디가 막혔나"이고, 그 답이 곧 막힌 칸 수다.
         ⚠ 0이면 안 그린다(위 예보와 같은 규율) — 막힌 데가 없다는 것은 화면이 비어 있는 것으로
         이미 말해진다. */
      primary: totals.spots > 0 ? { value: String(totals.spots), unit: '칸', label: '막힘' } : null,
      readouts: [
        { label: '오답 기록', value: totals.records },
        { label: '확신 오답', value: totals.confident, accent: totals.confident > 0 },
      ],
      action: { label: '복습 실행', onClick: () => nav('/review-run') },
    }),
    [totals.spots, totals.records, totals.confident],
  );

  // 아카이브가 통째로 비었는가(필터 때문에 빈 것과 구분한다 — 두 상태의 처방이 다르다).
  const empty = !(state.cbms || []).length;

  if (empty) {
    return (
      <section className={WRAP}>
        <State
          glyph="alert"
          title="아직 오답 기록이 없어요"
          desc={
            <>
              {/* ⚠ 탭 이름은 `shell/tabs.ts` 가 정본이다(U009 · 2026-08-21). `학습 기록` 은
                  N-12 에서 `하루`(/day)로 은퇴한 이름인데 이 문장만 옛 이름에 머물러 있었다 —
                  아래 버튼이 실제로 데려가는 곳과 글자가 달랐다. */}
              <b>하루</b> 탭의 <b>오답(CBMS)</b> 에 막힌 지점을 적으면, 여기에 과목·챕터별로 쌓여{' '}
              <b>무엇이 반복해서 나를 막는가</b>가 보여요.
            </>
          }
          next={
            <Button sm variant="primary" onClick={() => nav('/day')}>
              기록하러 가기 →
            </Button>
          }
        />
      </section>
    );
  }

  /* N-4 — 칸 단위 요소 태그. 한 곳에서 만들어 두 목록(오늘·아카이브)이 같은 것을 쓴다. */
  const known = knownKc(state, todayISO(state));
  const kcFor = (row: MistakeRow) => ({
    tags: chapterKc(state, row.sid, row.chapter),
    known,
    add: (v: string) => mutate((st) => void tagChapter(st, row.sid, row.chapter, v)),
    remove: (v: string) => mutate((st) => void untagChapter(st, row.sid, row.chapter, v)),
  });
  const seed = (row: MistakeRow) => {
    const topic = row.chapter || row.subject;
    mutate((st) => addBacklog(st, row.sid, row.subject, topic, `오답 ${row.count}회 · ${CBMS_INFO[row.topCode].tip}`));
    toast(`보충에 담았어요 — ${topic}`, 'ok', 4000);
  };

  return (
    <section className={WRAP} aria-label="오답 노트">
      <div className={FILTERS}>
        <button
          type="button"
          className={`${CHIP} ${sid ? '' : CHIP_ON}`}
          onClick={() => setSid('')}
          aria-pressed={!sid}
        >
          전체 과목
        </button>
        {subjects.map(([id, name]) => (
          <button
            key={id}
            type="button"
            className={`${CHIP} ${sid === id ? CHIP_ON : ''}`}
            onClick={() => setSid(sid === id ? '' : id)}
            aria-pressed={sid === id}
          >
            {name}
          </button>
        ))}
        <span className="mx-1 h-4 w-px bg-line2" aria-hidden="true" />
        <button
          type="button"
          className={`${CHIP} ${code ? '' : CHIP_ON}`}
          onClick={() => setCode('')}
          aria-pressed={!code}
        >
          전체 유형
        </button>
        {CBMS_CODES.map((c) => (
          <button
            key={c}
            type="button"
            className={`${CHIP} ${code === c ? CHIP_ON : ''}`}
            onClick={() => setCode(code === c ? '' : c)}
            aria-pressed={code === c}
            title={CBMS_INFO[c].tip}
          >
            {CBMS_INFO[c].label}
          </button>
        ))}
      </div>

      {rows.length === 0 ? (
        /* 필터가 만든 빈 상태 — 위 '기록 없음'과 다른 사건이라 다른 문장을 준다(막다른 골목 금지). */
        <p className="py-4 text-sm text-mut" role="status">
          이 조건에 맞는 오답이 없어요 — 필터를 풀어 보세요.
        </p>
      ) : (
        /* ── P-14 오늘 볼 것이 먼저, 전량은 접힘 뒤로(2026-08-01) ─────────────────
           종전엔 전 기간 전량이 **상시**였다. 도달은 쉬웠지만(클릭 2) 도착한 뒤 무엇부터
           볼지가 다시 사용자의 일이었고, 그래서 다시 안 읽혔다.
           ⚠ **필터는 상시로 남긴다**(위 칩) — 접는 것은 *목록*이지 *찾는 길*이 아니다.
             `/mistakes?sid=…` 로 데려온 사람은 그 필터 결과를 보러 온 것이므로, 필터가 걸려
             있으면 오늘 창도 그 안에서 돈다(같은 `rows` 에서 뽑는다). */
        <div className={LIST}>
          <h2 className={TODAY_HEAD}>
            오늘 볼 것<span className="font-semibold normal-case">— 하루 1~3분이면 충분해요</span>
          </h2>
          {picks.map((r) => (
            <MistakeCard
              key={r.key}
              row={r}
              action
              kc={kcFor(r)}
              onDrill={() => nav('/review-run')}
              onSeed={() => seed(r)}
            />
          ))}
          {rows.length > picks.length && (
            <details>
              <summary className={FOLD}>전체 {rows.length}칸 보기 — 아카이브</summary>
              <div className="mt-2 flex flex-col gap-2">
                {rows.map((r) => (
                  <MistakeCard
                    key={r.key}
                    row={r}
                    kc={kcFor(r)}
                    onDrill={() => nav('/review-run')}
                    onSeed={() => seed(r)}
                  />
                ))}
              </div>
            </details>
          )}
        </div>
      )}

      {/* T-19 — 같은 질문("무엇이 반복해서 틀리나")의 **더 큰 표본이 Anki 안에 이미 있다**.
          여기 나란히 두면 "앱에는 안 적었지만 Anki 는 알고 있는 것"이 보인다.
          ⚠ 누를 때만 부른다 — 왕복 셋 + Anki 가 꺼져 있으면 타임아웃이라, 화면 열 때마다
            내면 오답 노트가 느려진다. */}
      <LapseCard />
    </section>
  );
}

/* ============================================================
   Questions — 탭: **문항 원장**(T-7) + **시험 회수 창**(T-2)

   ## 위치가 설계다 — 인출 호스트의 세그먼트

   `review-run`(굴리기) → `forecast`(앞으로) → `mistakes`(틀린 사건) 옆이다. 이 넷은 전부
   *다시 꺼내는 일*이고, 여기는 그중 **꺼낼 대상 자체**를 쥔다. 오답 노트와 나란한 이유는
   서로를 먹지 않기 때문이다: `cbms` 는 틀린 **사건**(코드·메모), 여기는 다시 풀 수 있는
   **대상**. 시험 2주 전에 열리는 것은 후자다.

   ## 화면이 두 얼굴인 이유

   시험 직후에는 **회수 시트**가 위로 온다(T-2 · 직후 20분의 기억이 나중보다 정확하다는 전제).
   그 창이 닫히면 평범한 원장으로 돌아간다 — 창은 `lib/questions.recallWindows` 가 판정하고,
   여기서 기간을 다시 정하지 않는다.

   ## ⚠ 이 화면은 자기가 값을 내는지 스스로 말한다

   T-7 의 검증 조건이 _"2개 이상이 같은 챕터면 참"_ 이었다. `chapterHotspots` 가 그 판정을
   하고, **밀집이 없으면 화면이 그렇게 적는다** — 목록만 쌓이고 있는 상태를 "잘 되고 있다"로
   그리면 앱이 자기 기능을 과대평가한다(이 저장소가 `visits.ts` 에서 이미 물린 형태).

   레이어: store·lib·components 만. app/다른 feature import 금지(boundaries).
============================================================ */
import { useMemo, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { useApp } from '@/store/useApp';
import { usePageChromeEffect } from '@/store/usePageChrome';
import {
  addQuestion,
  chapterHotspots,
  dueQuestions,
  markMet,
  nextMeetDs,
  questionsOf,
  recallWindows,
  removeQuestion,
} from '@/lib/questions';
import { EXAM_LABEL, examsOf } from '@/lib/semester';
import { rid, todayISO } from '@/lib/utils';
import { commitUndoable, toast } from '@/shell';
import State from '@/components/State';
import { Button, Pill } from '@/components/ui';
import type { Question } from '@/lib/types';

const WRAP = 'flex h-full flex-col gap-3.5 p-6';
/* ⚠ `ds-well`(눌린 면)이다 — 옛 `rounded-md border bg-panel` 관용구는 원칙 ④가 폐기했고
   `check:tokens` 가 새 파일에서 그걸 막는다(오답 노트 등 기존 파일은 원장의 예외로만 남아 있다). */
const ROW = 'ds-well flex flex-col gap-1.5 px-4 py-3';
const LIST = 'flex min-h-0 flex-1 flex-col gap-2 overflow-y-auto [scrollbar-width:thin]';

/** 4칸 입력 — **한 문항 30초**가 이 항목의 전제라 칸이 넷을 넘지 않는다(정답·해설·태그 없음). */
function Capture({
  sid,
  chapters,
  fromRecall,
  onDone,
}: {
  sid: string;
  chapters: string[];
  fromRecall: boolean;
  onDone: () => void;
}) {
  const state = useApp((s) => s.state);
  const mutate = useApp((s) => s.mutate);
  const [prompt, setPrompt] = useState('');
  const [chapter, setChapter] = useState('');
  const [source, setSource] = useState('');
  const [why, setWhy] = useState('');

  const submit = (): void => {
    const q: Question = {
      id: rid(),
      ds: todayISO(state),
      sid,
      prompt: prompt.trim(),
      ...(chapter ? { chapter } : {}),
      ...(source.trim() ? { source: source.trim() } : {}),
      ...(why.trim() ? { why: why.trim() } : {}),
      ...(fromRecall ? { fromRecall: true } : {}),
    };
    let ok = false;
    mutate((st) => void (ok = addQuestion(st, q)));
    if (!ok) {
      toast('문제 칸이 비어 있어요 — 나머지 셋은 비어도 됩니다.', 'warn');
      return;
    }
    /* 연속 입력이 이 시트의 목적이라 **칸만 비우고 화면을 안 닫는다**(회수 창은 여러 문항을
       한 번에 적는 자리다). 챕터는 유지 — 같은 챕터가 이어지는 것이 보통이다. */
    setPrompt('');
    setSource('');
    setWhy('');
    onDone();
  };

  return (
    <div className="ds-fieldgrid">
      <div className="ds-fld ds-wide">
        <label htmlFor={`q-prompt-${sid}`}>문제</label>
        <input
          id={`q-prompt-${sid}`}
          type="text"
          value={prompt}
          placeholder="무엇을 묻는 문제였나"
          onChange={(e) => setPrompt(e.target.value)}
          onKeyDown={(e) => {
            // IME 조합 중 Enter 를 삼키지 않는다 — 한글 입력에서 첫 글자가 사라지는 그 함정.
            if (e.key === 'Enter' && !e.nativeEvent.isComposing) submit();
          }}
        />
      </div>
      <div className="ds-fld">
        <label htmlFor={`q-ch-${sid}`}>챕터</label>
        <select id={`q-ch-${sid}`} value={chapter} onChange={(e) => setChapter(e.target.value)}>
          <option value="">(미기재)</option>
          {chapters.map((c) => (
            <option key={c} value={c}>
              {c}
            </option>
          ))}
        </select>
      </div>
      <div className="ds-fld">
        <label htmlFor={`q-src-${sid}`}>출처</label>
        <input
          id={`q-src-${sid}`}
          type="text"
          value={source}
          placeholder="교재 3-2 · 중간 5번"
          onChange={(e) => setSource(e.target.value)}
        />
      </div>
      <div className="ds-fld ds-wide">
        <label htmlFor={`q-why-${sid}`}>관건</label>
        <input
          id={`q-why-${sid}`}
          type="text"
          value={why}
          placeholder="무엇이 관건이었나 / 왜 틀렸나"
          onChange={(e) => setWhy(e.target.value)}
        />
      </div>
      <div className="ds-wide">
        <Button variant="primary" onClick={submit}>
          문항 넣기
        </Button>
      </div>
    </div>
  );
}

export default function Questions() {
  const state = useApp((s) => s.state);
  const mutate = useApp((s) => s.mutate);
  const navigate = useNavigate();
  const [params, setParams] = useSearchParams();
  const today = todayISO(state);
  const items = state.items;
  const urlSid = params.get('sid') || '';
  const sid = items.some((i) => i.id === urlSid) ? urlSid : (items[0]?.id ?? '');
  const item = items.find((i) => i.id === sid) ?? null;

  const windows = useMemo(() => recallWindows(state, today, (it) => examsOf(it)), [state, today]);
  const all = questionsOf(state);
  const mine = useMemo(
    () =>
      all
        .filter((q) => q.sid === sid)
        .slice()
        .reverse(),
    [all, sid],
  );
  const hotspots = useMemo(() => chapterHotspots(state, sid), [state, sid]);
  /* A-14 — **다시 만날 때가 된 문항.** 과목을 안 가린다: 이 목록의 존재 이유가 *찾아가지 않아도
     떠오르는 것*이라, 과목 셀렉트 뒤에 숨기면 이 항목이 없애려는 마찰이 그대로 남는다. */
  const due = useMemo(() => dueQuestions(state, today), [state, today]);
  const win = windows.find((w) => w.item.id === sid) ?? windows[0] ?? null;

  usePageChromeEffect(
    () => ({
      primary: { label: '문항 원장', value: `${all.length}건` },
      readouts: [
        { label: '이 과목', value: mine.length },
        /* A-14 — 0 이면 `—` 다(빈 수를 외치지 않는다 · 레일 신호와 같은 규칙). */
        { label: '다시 만날 것', value: due.length || '—' },
        // 밀집이 이 원장의 값 판정이다 — 리드아웃이 그것을 1급으로 말한다.
        { label: '챕터 밀집', value: hotspots.length ? `${hotspots.length}곳` : '—' },
        ...(win ? [{ label: '회수 창', value: `${EXAM_LABEL[win.exam.kind]} 직후` }] : []),
      ],
    }),
    [all.length, mine.length, hotspots.length, win, due.length],
  );

  if (!items.length)
    return (
      <State
        kind="empty"
        glyph="notebook"
        title="과목이 아직 없어요"
        desc="문항은 과목에 붙습니다 — 과목을 먼저 만들면 여기서 문제를 모을 수 있어요."
        next={
          <Button variant="primary" onClick={() => navigate('/items')}>
            과목 만들기
          </Button>
        }
      />
    );

  const chapters = (item?.chapters || []).map((c) => c.name);

  return (
    /* ⚠ `<section aria-label>` 이다 — 탭 본문은 **h2 또는 라벨된 섹션**을 가져야 한다는 계약이
       있고(`visual.spec.ts` 가 그걸 집행한다), 그건 스냅샷 편의가 아니라 **랜드마크**다.
       처음엔 `<div>` 로 두었다가 그 검사에 잡혔다. */
    <section className={WRAP} aria-label="문항 원장">
      <div className="flex flex-none flex-wrap items-center gap-2">
        <label htmlFor="q-sid" className="ds-caps">
          과목
        </label>
        <select
          id="q-sid"
          value={sid}
          onChange={(e) => setParams({ sid: e.target.value }, { replace: true })}
          className="max-w-60"
        >
          {items.map((i) => (
            <option key={i.id} value={i.id}>
              {i.name}
            </option>
          ))}
        </select>
      </div>

      {/* T-2 — 회수 창. 시험 직후에만 뜨고, 그 사실을 문장으로 말한다(왜 지금인가). */}
      {win && win.item.id === sid && (
        <div className="ds-rule">
          <div className="mb-2 flex items-baseline gap-2">
            <h3 className="ds-caps mb-0!">
              {EXAM_LABEL[win.exam.kind]}고사 회수 — {win.daysSince === 0 ? '오늘' : '어제'} 봤어요
            </h3>
            <Pill tiny tone={win.written ? 'good' : 'warn'}>
              {win.written ? `${win.written}건 적음` : '아직 0건'}
            </Pill>
          </div>
          <p className="ds-tiny mb-2.5 text-mut">
            기억이 가장 정확한 구간이에요. 떠오르는 문제를 <b>생각나는 대로</b> — 정답은 안 적어도 됩니다.
          </p>
          <Capture sid={sid} chapters={chapters} fromRecall onDone={() => {}} />
        </div>
      )}

      {/* T-7 — 평상시 원장. 회수 창이 떠 있으면 입력이 둘이 되므로 그때는 접는다. */}
      {!(win && win.item.id === sid) && (
        <div className="ds-rule">
          <h3 className="ds-caps mb-2!">문항 넣기</h3>
          <Capture sid={sid} chapters={chapters} fromRecall={false} onDone={() => {}} />
        </div>
      )}

      {/* ── A-14(W8) — **문항이 스스로 부른다** ─────────────────────────────────────
          이 원장의 결함은 내용이 아니라 시제였다: 아카이브는 *사용자가 갈 때만* 존재하는데
          갈 이유가 발생하지 않았다. 간격은 앱의 복습 사다리 그대로이고(`nextMeetDs`), "다시
          봤어요"가 그 사다리를 한 칸 올린다.
          ⚠ **정답을 안 묻는다.** 이 원장에는 정답이 없고(30초 계약), 맞았는지를 물으면 그 순간
          문제은행이 된다 — 여기서 재는 것은 *다시 만났나*뿐이다. */}
      {due.length > 0 && (
        <div className="ds-rule flex-none">
          <div className="mb-2 flex items-baseline gap-2">
            <h3 className="ds-caps mb-0!">다시 만날 문항</h3>
            <Pill tiny tone="warn">
              {due.length}건
            </Pill>
          </div>
          <ul className="m-0 flex list-none flex-col gap-1.5 p-0">
            {due.slice(0, 5).map(({ q, over }) => (
              <li key={q.id} className="flex flex-wrap items-baseline gap-2 text-md">
                <span className="min-w-0 flex-1 truncate">{q.prompt}</span>
                <span className="ds-tiny text-mut">{items.find((i) => i.id === q.sid)?.name ?? ''}</span>
                <span className="ds-tiny text-mut tabular-nums">{over === 0 ? '오늘' : `${over}일 지남`}</span>
                <Button sm onClick={() => mutate((st) => markMet(st, q.id, today))}>
                  다시 봤어요
                </Button>
              </li>
            ))}
          </ul>
          {due.length > 5 && <p className="ds-tiny mt-1.5 mb-0 text-mut">외 {due.length - 5}건</p>}
        </div>
      )}

      {hotspots.length > 0 ? (
        <div className="flex flex-none flex-wrap items-center gap-2">
          <span className="ds-caps">챕터 밀집</span>
          {hotspots.slice(0, 6).map((h) => (
            <Pill key={h.chapter} tiny tone="warn">
              {h.chapter} · {h.n}
            </Pill>
          ))}
        </div>
      ) : (
        /* ⚠ 밀집이 없다는 사실을 **말한다**. 이 원장이 시험 전에 열릴 이유는 밀집이고,
           없는데 있는 척하면 앱이 자기 기능을 과대평가한다. */
        <p className="ds-tiny flex-none text-mut">
          아직 같은 챕터에 두 건 이상 몰린 곳이 없어요 — 밀집이 생기면 여기에 뜹니다.
        </p>
      )}

      {mine.length === 0 ? (
        <State
          kind="empty"
          glyph="notebook"
          title="이 과목의 문항이 아직 없어요"
          desc="시험 직후·문제를 푼 직후가 가장 싸게 적히는 순간이에요."
          next={{ terminal: '위 칸에 바로 적으면 됩니다.' }}
        />
      ) : (
        <ul className={`m-0 list-none p-0 ${LIST}`}>
          {mine.map((q) => (
            <li key={q.id} className={ROW}>
              <div className="flex flex-wrap items-baseline gap-2">
                <span className="text-md font-bold">{q.prompt}</span>
                {q.chapter && <span className="text-sm text-mut">{q.chapter}</span>}
                <span className="ml-auto flex items-center gap-2 text-xs text-mut tabular-nums">
                  {q.fromRecall && (
                    <Pill tiny tone="good">
                      회수
                    </Pill>
                  )}
                  {q.source && <span>{q.source}</span>}
                  <span>{q.ds}</span>
                  {/* A-14 — 다음에 만날 날. 저장값이 아니라 파생이다(`met` 에서 계산). */}
                  <span title={`${(q.met || []).length}번 다시 봄`}>↻ {nextMeetDs(q)}</span>
                  <Button
                    sm
                    variant="ghost"
                    aria-label={`문항 "${q.prompt}" 지우기`}
                    onClick={() =>
                      commitUndoable(`문항 "${q.prompt}" 삭제됨`, () => mutate((st) => removeQuestion(st, q.id)))
                    }
                  >
                    ✕
                  </Button>
                </span>
              </div>
              {q.why && <span className="truncate text-xs text-mut">{q.why}</span>}
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

/* ============================================================
   Forecast — 탭: 📈 복습 부하 예보 (ID-1 · N-9 가용선 · fill 대시보드)
   학습 루프에서 유일하게 비어 있던 시제를 메운다: 오늘탭이 '밀린 것'(overdue backlog)이라면
   여기선 '다가오는 복습 파도'를 앞 14일 날짜별로 조망한다. 볼트 챕터를 '마지막 만진 날' +
   간격반복 오프셋으로 미래에 투영해, 어느 날 복습이 몰릴지를 그린다.

   ⚠ N-9: 막대 단위는 **개수가 아니라 복습 블록**이고 날짜마다 **가용선**(점선)이 함께 선다.
   개수 막대는 "언젠가 몰린다"까지만 말할 수 있었다 — 비교 대상이 없으면 3개가 많은지 적은지
   화면 안에서 판정이 불가능하고, 그래서 예전 부제는 '정확 예측이 아니라 부하의 형태'라는
   면책으로 끝났다. 부하와 가용이 같은 단위가 된 지금은 그 문장이 필요 없다(비교가 답을 준다).
   환산 규칙과 그 안전장치(임의 계수 0 · rev 이중계상 금지)는 `lib/spacedReview` 가 소유한다.

   ⚠ Anki(FSRS) 는 미래 due 를 앱이 아닌 Anki 가 소유하므로 막대는 볼트 챕터만 그리고,
   Anki 는 '오늘 기준 due' 를 별도 컨텍스트로만 정직하게 얹는다(예보 정밀 비대칭 · ID-1).
   데이터는 store(useApp·useSchedule) / 로직은 lib.

   [a11y] 막대는 `role="img" + aria-label + data-tip + tabIndex={0}` 규약(StatsDetail 선례)을
   따른다. tabIndex 목적은 **툴팁 도달성**(components/Tooltip 이 전역 focusin 으로 `[data-tip]`
   에 툴팁을 띄운다) — 없으면 호버 정보가 키보드 사용자에게만 사라진다(SR 은 같은 문자열
   aria-label 로 이미 받음). no-noninteractive-tabindex 는 이 '툴팁 타깃' 예외를 표현 못 해
   파일 단위로 끈다 — 이 파일은 차트 전용이라 여기 생길 tabIndex 는 전부 같은 패턴이다.
============================================================ */
/* eslint-disable jsx-a11y/no-noninteractive-tabindex */
import { weakKey } from '@/lib/domainKeys';
import { useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useApp } from '@/store/useApp';
import { useRuntime } from '@/store/useRuntime';
import { useSchedule } from '@/store/selectors';
import { usePageChromeEffect } from '@/store/usePageChrome';
import { heldReviews, releaseReview } from '@/lib/reviewHold';
import { dueForecast, pullForwardCandidates, FORECAST_HORIZON, type ForecastDay } from '@/lib/spacedReview';
import { loadCurve, CURVE_HORIZON, TRADEOFF } from '@/lib/loadCurve';
import { addOrMergeBlock } from '@/lib/dayPlans';
import { toast } from '@/shell';
import { totalDue, dueBySubject, ankiFreshness } from '@/lib/anki';
import { todayISO, fmtShort, reviewBlockMin, DOW } from '@/lib/utils';
import State from '@/components/State';
import { Button } from '@/components/ui';
import { Icon } from '@/components/Icon';

const WRAP = 'flex h-full flex-col gap-4 p-6';
const CHART = 'flex min-h-0 flex-1 items-end gap-1.5';
/* 한 날 = 세로 컬럼(막대 + 라벨). 주말은 살짝 죽여 평일 파도와 시각적으로 가른다. */
const COL = 'flex min-w-0 flex-1 flex-col items-center gap-1.5';
/** 컬럼의 세로 무대 — 막대는 바닥에, 가용선은 그 위 절대 좌표에 선다(둘이 같은 축을 쓴다). */
const STAGE = 'relative w-full';
const BAR_TRACK = 'absolute inset-x-0 bottom-0 flex flex-col-reverse overflow-hidden rounded-t-sm';
/** 가용선 — 그날 복습에 쓸 수 있는 블록 수. 축 밖(여유 충분)이면 맨 위에 옅게 눕는다.
 *  ⚠ 색은 여기 안 굳힌다 — 초과일 때 `border-bad` 를 덧붙이면 같은 특이도라 소스 순서가 승자를
 *  정해(유틸리티 두 개가 같은 속성) 조용히 어느 한쪽이 이긴다. 호출부가 **하나만** 고른다. */
const CAP_LINE = 'absolute inset-x-0 border-t border-dashed';
const LEGEND = 'flex flex-wrap items-center gap-x-4 gap-y-1.5';
const OVER_STRIP =
  'flex flex-wrap items-baseline gap-x-2 gap-y-1 rounded-sm border border-line-bad bg-tint-bad-faint px-3 py-2';

/** 막대 영역 최대 높이(px) — fill 프레임 안에서 flex-1 이 실제 높이를 정하되, 세그먼트 비율의
 *  기준 높이다. 인라인 style 로 세그먼트별 height 를 주는 건 StatsDetail 스파크바와 같은 관용구. */
const BAR_MAX = 200;

const short = (ds: string): string => fmtShort(new Date(ds + 'T00:00:00'));
/** 앞당길 후보 칩 — 텍스트였던 것이 버튼이 됐다(A10). 조밀한 스트립 안이라 최소 높이만 잡는다. */
const PULL_CHIP =
  'cursor-pointer rounded-full border! border-line! bg-none! px-2! py-0.5! text-2xs! text-mut! enabled:hover:border-acc! enabled:hover:text-txt!';

function DayColumn({ d, axisMax }: { d: ForecastDay; axisMax: number }) {
  const weekend = d.wd === 0 || d.wd === 6;
  const cap = d.capBlocks;
  // 가용선이 축 위로 벗어나면(=파도보다 한참 여유) 맨 위에 눕히고 옅게 — 좌표를 잃되 존재는 남긴다.
  const capClamped = cap != null && cap > axisMax;
  const capH = cap == null ? null : Math.round((Math.min(cap, axisMax) / axisMax) * BAR_MAX);
  const capTxt = cap == null ? '' : ` — 가용 ${cap}블록`;
  const label =
    d.chapters === 0
      ? `${short(d.ds)} 복습 없음${capTxt}`
      : `${short(d.ds)} (${DOW[d.wd]}) 복습 ${d.blocks}블록 · 챕터 ${d.chapters}개${capTxt}` +
        (d.over ? ' · 가용 초과' : '') +
        ' — ' +
        d.subjects.map((s) => `${s.subject} ${s.count}`).join(', ');
  return (
    <div className={COL}>
      <div className={STAGE} style={{ height: BAR_MAX }} role="img" aria-label={label} data-tip={label} tabIndex={0}>
        <div
          className={`${BAR_TRACK} ${d.over ? 'ring-1 ring-bad' : ''}`}
          style={{ height: Math.round((d.blocks / axisMax) * BAR_MAX) }}
          aria-hidden="true"
        >
          {d.subjects.map((s) => (
            <div
              key={s.sid}
              style={{
                height: `${(s.count / Math.max(1, d.chapters)) * 100}%`,
                background: s.color || 'var(--acc)',
              }}
              aria-hidden="true"
            />
          ))}
        </div>
        {capH != null && (
          <div
            className={`${CAP_LINE} ${d.over ? 'border-bad' : 'border-line'} ${capClamped ? 'opacity-45' : ''}`}
            style={{ bottom: capH }}
            aria-hidden="true"
          />
        )}
      </div>
      <div
        className={`ds-tiny leading-none ${d.over ? 'text-bad' : weekend ? 'text-mut' : 'text-txt'}`}
        aria-hidden="true"
      >
        {d.offset}
      </div>
      <div className="ds-tiny leading-none text-mut" aria-hidden="true">
        {DOW[d.wd]}
      </div>
    </div>
  );
}

export default function Forecast() {
  const state = useApp((s) => s.state);
  const mutate = useApp((s) => s.mutate);
  const res = useSchedule();
  const nav = useNavigate();
  const today = todayISO(state);
  const ankiLive = useRuntime((s) => s.cache._ankiLive);
  const ankiDue = ankiLive?.decks ? totalDue(ankiLive.decks) : null;
  const ankiFresh = ankiFreshness(ankiLive, today);
  /* E18 — 덱 due 를 **과목에** 붙인다. 종전엔 `totalDue()` 한 숫자뿐이라 "Anki 340장"을 보고
     어느 과목이 밀렸는지 알려면 Anki 를 직접 열어야 했다(앱 밖 왕복).
     ⚠ 이 탭이 그 자리인 이유(E13): 여기가 **볼트 due 와 Anki due 를 한 화면에 쥔** 유일한
     화면이고, 인출 축의 호스트다. 연동 탭은 "붙었나"만 말한다. */
  const ankiBy = ankiLive?.decks ? dueBySubject(ankiLive.decks, state.items) : null;

  const held = heldReviews(state);

  const forecast = useMemo(() => dueForecast(state, res.days || [], today), [state, res.days, today]);
  /* I019 — **노브를 돌리기 전에 곡선을 본다**(2026-08-22 발상 축). 근거 전문은 `lib/loadCurve`
     머리주석. 여기가 자리인 이유: 이 화면이 이미 «앞으로 얼마나 오나»를 묻는 화면이고,
     그 질문의 다음 칸이 «사다리를 바꾸면 어떻게 되나»다. */
  const curve = useMemo(() => loadCurve(state, res.days || [], today), [state, res.days, today]);

  const total = forecast.reduce((t, d) => t + d.chapters, 0);
  const max = forecast.reduce((m, d) => Math.max(m, d.blocks), 0);
  /* 축 = 파도 최댓값에 앵커한다. 가용선까지 축에 넣으면(가용은 '안 자고 안 수업인 모든 시간'이라
     보통 파도의 몇 배다) 막대가 통째로 납작해져 정작 부하의 형태를 잃는다 — 그런 날의 가용선은
     맨 위에 옅게 눕혀(capClamped) '천장이 높다'만 말하게 한다. 넘는 날은 정의상 축 안이라 안 잘린다.
     여유가 있는 날에도 선이 보이도록 파도 위 1블록(축 자신의 눈금)만 머리 공간을 준다. */
  const axisMax = Math.max(1, max + (forecast.some((d) => d.capBlocks != null && d.capBlocks > max) ? 1 : 0));
  // 가장 몰리는 날(peak) — 여러 날이 같으면 가장 이른 날.
  const peak = max > 0 ? forecast.find((d) => d.blocks === max)! : null;
  const revMin = reviewBlockMin(state.moduleLen);
  // 개입 — 가용선을 넘는 첫 날(가장 이른 = 가장 먼저 손쓸 수 있는 날) 하나만 말한다.
  const overDays = forecast.filter((d) => d.over);
  const firstOver = overDays[0] ?? null;
  // firstOver 는 memo 된 forecast 의 원소 참조라 forecast 가 그대로면 참조도 그대로다(deps 안전).
  const pull = useMemo(
    () => (firstOver ? pullForwardCandidates(forecast, firstOver.offset) : []),
    [forecast, firstOver],
  );
  const toLabel = (off: number | null): string => {
    if (off == null) return '오늘';
    const at = forecast.find((f) => f.offset === off);
    return at ? short(at.ds) : '오늘';
  };

  /* ⚠ **후보를 실제로 꽂는다.** 종전엔 이 줄들이 순수 텍스트였다 — 가용 초과를 알려주고
     해법(어느 챕터를 언제로)까지 계산해 놓고, 옮기는 일은 사용자가 계획 탭에 가서 손으로 했다.
     배관만 없었다: `dayPlans.addOrMergeBlock` 은 같은 `sid|type` 병합(완료 키 충돌 방지)까지
     설계돼 있는데 **소비처가 0곳**이었다(테스트에만 존재).
     ⚠ 단위·분은 새로 짓지 않는다 — `reviewBlockMin(moduleLen)` 은 예보 막대가 쓰는 그 값이다
       (임의 계수 0 · `spacedReview` 가 스스로 못박은 규율).
     ⚠ **부작용을 말한다**: 목적지 날은 `ensureManual` 로 수동 편집 모드가 된다. 조용히
       바꾸면 다음에 그 날 자동 배치가 안 도는 것이 원인 불명의 결함으로 보인다. */
  const pullTo = (p: (typeof pull)[number]): void => {
    const at = p.toOffset == null ? null : forecast.find((f) => f.offset === p.toOffset);
    const ds = at ? at.ds : today;
    mutate((st) => {
      addOrMergeBlock(st, res, ds, {
        sid: p.chapter.sid,
        type: 'rev',
        name: p.chapter.subject,
        min: revMin,
        chapters: [p.chapter.chapter],
      });
    });
    toast(`${short(ds)}에 "${p.chapter.chapter}" 복습 블록을 넣었어요 — 그날은 수동 편집 모드가 됩니다.`, 'ok', 6000);
  };

  // 예보에 등장하는 과목(색 범례) — 첫 등장 순, 중복 제거.
  const legend = useMemo(() => {
    const seen = new Map<string, { subject: string; color?: string }>();
    for (const d of forecast) for (const s of d.subjects) if (!seen.has(s.sid)) seen.set(s.sid, s);
    return [...seen.values()];
  }, [forecast]);

  usePageChromeEffect(
    () => ({
      /* N-15 `primary` — 예보의 결론은 "앞으로 얼마나 오나" 하나다(막대는 그 분포를 그린다).
         ⚠ **0이면 안 그린다.** 44px 짜리 `0개` 는 빈 예보 화면에서 가장 큰 요소가 되는데,
         그때 그 화면이 이미 "다가오는 복습 파도가 아직 없어요" 라고 말하고 있다 — 같은 0을 두 번,
         그것도 제일 크게 외치는 꼴이다(N-13 이 레일 상태 슬롯에서 못박은 규율과 같다:
         매일 0을 외치면 신호가 죽는다). */
      primary: total > 0 ? { value: String(total), unit: '개', label: `앞 ${FORECAST_HORIZON}일 복습` } : null,
      readouts: [
        { label: '가장 몰리는 날', value: peak ? `+${peak.offset}일 · ${peak.blocks}블록` : '—' },
        // 가용 초과가 있으면 그것이 이 탭의 결론이다 — 없을 때만 Anki 컨텍스트가 그 자리를 쓴다.
        overDays.length
          ? { label: '가용 초과', value: `${overDays.length}일`, accent: true }
          : // ⚠ 낡은 캐시를 '오늘 due' 라 부르지 않는다 — Anki due 는 날이 바뀌면 통째로 갈린다.
            { label: ankiFresh?.stale ? 'Anki due · 옛 값' : 'Anki 오늘 due', value: ankiDue == null ? '—' : ankiDue },
      ],
      action: { label: '복습 실행', onClick: () => nav('/review-run') },
    }),
    [total, peak?.offset, peak?.blocks, overDays.length, ankiDue, ankiFresh?.stale],
  );

  if (total === 0) {
    return (
      <section className={WRAP} aria-label="복습 부하 예보">
        <State
          glyph="trend"
          title="다가오는 복습 파도가 아직 없어요"
          desc={
            <>
              완료한 학습 챕터가 간격반복 사다리(1·3·7·16일)를 타면 여기에 앞 {FORECAST_HORIZON}일치 복습 부하가
              그려집니다. 오늘 학습을 마치면 곧 첫 파도가 나타나요.
            </>
          }
          next={<Button onClick={() => nav('/today')}>오늘 학습으로</Button>}
          /* Q-31 — 예보는 **막대의 모양이 곧 정보**라(어느 날이 무거운가) 문장으로 대체되지 않는다.
             합성 7일치로 그 형상만 보여 준다 — 수는 캡션이 남의 것이라고 말한다. */
          preview={
            <div className="flex h-16 items-end justify-between gap-1.5">
              {[3, 7, 2, 9, 5, 1, 4].map((h, i) => (
                <div
                  key={i}
                  className={`flex-1 rounded-t-xs ${h >= 8 ? 'bg-bad' : 'bg-acc'}`}
                  style={{ height: `${h * 11}%` }}
                />
              ))}
            </div>
          }
        />
      </section>
    );
  }

  return (
    <div className={WRAP}>
      {/* E18 — Anki 가 어느 과목에 밀려 있나. **미연결 덱을 숨기지 않는다**: 합계가 안 맞아야
          조인이 틀렸다는 것을 알 수 있다(E3 계측이 하려던 일을 이 화면이 되돌리지 않게).
          ⚠ 넛지 문장은 두지 않는다 — "이미 밀려 있어요" 가 조언이 되려면 임계가 필요하고 그건
          임의 계수다(`spacedReview` 가 못박은 규율). 분해까지만 한다. */}
      {ankiBy && (ankiBy.rows.length > 0 || ankiBy.unmatchedDecks > 0) && (
        <p className="m-0 flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-mut">
          <span className="font-bold text-txt">Anki 오늘 due</span>
          {ankiBy.rows.slice(0, 3).map((r) => (
            <span key={r.sid}>
              {r.name} <b className="text-txt">{r.due}</b>
            </span>
          ))}
          {ankiBy.unmatchedDecks > 0 && (
            <span>
              미연결 {ankiBy.unmatchedDecks}덱 <b className="text-txt">{ankiBy.unmatchedDue}</b>
            </span>
          )}
        </p>
      )}
      {/* ── I019 부하 곡선 — **바꾸기 전에 결과를 본다** ────────────────────────────────
          ⚠⚠ 노브가 아니라 **곡선이 먼저**다(밖의 표본이 세운 순서). 그리고 대가를 함께 판다:
          «간격을 늘리면 하루 부하는 줄지만 더 많이 잊는다». 그 문장은 `lib/loadCurve.TRADEOFF`
          가 소유한다 — 화면마다 다르게 말하면 그 경고는 곧 장식이 된다.
          ⚠ **노브는 없다**(아직). 이 화면이 답하는 것은 «바꾸면 어떻게 되나»이고, 바꾸는 것은
          그 답을 보고 사람이 결정할 일이다 — 곡선 없이 노브를 먼저 두는 것이 이 항목이
          막으려는 형태다. ⚠ 두 곡선은 **같은 눈금**이다(`curve.peak`) — 각자 정규화하면
          «늘리면 낮아진다»가 그림에서 사라지고, 그건 이 기능의 전부다. */}
      {curve.peak > 1 && (
        <details className="ds-note m-0! mt-2">
          <summary className="ds-tiny cursor-pointer">복습 간격을 늘리면 — 앞 {CURVE_HORIZON}일 부하</summary>
          <div className="mt-1.5 flex items-end gap-px" aria-hidden="true">
            {curve.now.map((n, i) => (
              <span key={i} className="flex w-1.5 flex-col justify-end" style={{ height: 28 }}>
                <span className="w-full bg-acc" style={{ height: `${Math.round((n / curve.peak) * 28)}px` }} />
              </span>
            ))}
          </div>
          <div className="ds-tiny mt-0.5 text-mut">지금 사다리(1·3·7·16·34)</div>
          <div className="mt-1.5 flex items-end gap-px" aria-hidden="true">
            {curve.stretched.map((n, i) => (
              <span key={i} className="flex w-1.5 flex-col justify-end" style={{ height: 28 }}>
                <span className="w-full bg-mut" style={{ height: `${Math.round((n / curve.peak) * 28)}px` }} />
              </span>
            ))}
          </div>
          <div className="ds-tiny mt-0.5 text-mut">한 칸 늘렸을 때</div>
          <p className="ds-tiny mt-1.5 text-warn">{TRADEOFF.replace(/\*\*/g, '')}</p>
        </details>
      )}
      {/* ── P-11 보류 선반 — **되돌릴 수 있는 유일한 자리** ─────────────────────────────
          러너에서 뺀 챕터는 큐에서 사라지므로, 여기 목록이 없으면 사용자 입장에서 '보류'와
          '조용한 삭제'가 구분되지 않는다. 이 탭인 이유: 복습 부하를 묻는 화면이고, "왜 예보가
          가벼워졌지"의 답이 정확히 이 줄이다.
          ⚠ 자동 만료를 두지 않으므로(P-9 와 같은 규칙) 이 선반은 **비지 않는다** — 그래서
            상시 노출이 아니라 있을 때만 그린다. */}
      {held.length > 0 && (
        <details className="ds-note m-0!">
          <summary className="cursor-pointer text-xs font-bold text-txt">
            복습에서 뺀 챕터 {held.length}개 — 되돌리기
          </summary>
          <ul className="m-0! mt-1.5 flex list-none flex-col gap-1 p-0!">
            {held.map((h) => (
              <li key={`${h.sid}|${h.chapter}`} className="m-0! flex items-center gap-2">
                <span className="ds-shed flex-1 truncate text-xs">
                  {h.name ?? '(없어진 과목)'} · {h.chapter}
                </span>
                <span className="text-2xs text-mut">{h.ds}</span>
                <Button
                  sm
                  variant="ghost"
                  onClick={() =>
                    mutate((st) => {
                      releaseReview(st, h.sid, h.chapter);
                    })
                  }
                >
                  되돌리기
                </Button>
              </li>
            ))}
          </ul>
        </details>
      )}
      <div className="flex flex-wrap items-baseline justify-between gap-2">
        <h2 className="m-0">
          복습 부하 예보{' '}
          <span className="ds-tiny text-mut">
            — 앞 {FORECAST_HORIZON}일 볼트 챕터. 막대 = 복습 블록(1블록 {revMin}분) · 점선 = 그날 가용
          </span>
        </h2>
        {ankiDue != null && (
          <span className="ds-tiny text-mut">Anki 미래 due 는 Anki 가 소유 — 여기 막대는 볼트 챕터만</span>
        )}
      </div>

      <div className={CHART}>
        {forecast.map((d) => (
          <DayColumn key={d.ds} d={d} axisMax={axisMax} />
        ))}
      </div>

      {/* 이름 있는 status — 셸에 sr-only status 영역이 상시 둘(App.tsx) 있어 무명이면 구분이 안 된다. */}
      {firstOver && (
        <div className={OVER_STRIP} role="status" aria-label="가용 초과">
          <span className="ds-tiny font-bold text-bad">
            <Icon name="alert" /> {short(firstOver.ds)} ({DOW[firstOver.wd]}) 복습 {firstOver.blocks}블록 · 가용{' '}
            {firstOver.capBlocks}블록
            {overDays.length > 1 && ` · 외 ${overDays.length - 1}일 초과`}
          </span>
          {pull.length > 0 && (
            <span className="ds-tiny flex flex-wrap items-center gap-1.5 text-mut">
              앞당길 후보 —
              {pull.map((p) => (
                <button
                  key={weakKey(p.chapter.sid, p.chapter.chapter)}
                  type="button"
                  className={PULL_CHIP}
                  onClick={() => pullTo(p)}
                  title={`${toLabel(p.toOffset)}에 ${revMin}분 복습 블록으로 넣습니다(그날은 수동 편집 모드가 됩니다)`}
                >
                  {p.chapter.subject} {p.chapter.chapter} → {toLabel(p.toOffset)}
                </button>
              ))}
            </span>
          )}
        </div>
      )}

      {legend.length > 0 && (
        <div className={LEGEND}>
          {legend.map((s) => (
            <span key={s.subject} className="ds-tiny flex items-center gap-1.5 text-mut">
              <span
                className="inline-block size-2.5 rounded-full"
                style={{ background: s.color || 'var(--acc)' }}
                aria-hidden="true"
              />
              {s.subject}
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

/* ============================================================
   ReviewRun — 탭: ↻ 복습 실행 (I-9 · doing surface)
   식별(review/stats/mastery)은 풍부하나 '실제로 복습을 굴리는 화면'이 빔 — 그 빈칸을 메운다.
   오늘 인출할 것을 한 카드씩 흐름으로: ① 회상(내 요약 다시 설명) ② 착각 재확인(과신 오답 재인출)
   ③ 밀린 챕터(간격반복 due/overdue). 진행은 이 세션의 로컬 상태(가짜 위험 감소 주장 없음) —
   실제 학습은 '집중 시작'(전역 타이머)·볼트 딥링크로 다리 놓고, 완료 세션이 정직하게 루프를 먹인다.

   ## 조작은 키보드가 정본이다(D-3)
   `Space` 펼치기 · `1` 건너뛰기 · `2` 판정/집중 시작 · `3` 떠올렸어요(챕터 · 볼트를 연 뒤) ·
   `V` 볼트 · `U` 되돌리기 · `Esc` 중단.
   카드 안에는 버튼이 없다 — 전부 화면 발치의 키캡 한 줄(`KeyBar`)로 모였고, 그 키캡이 곧
   누를 수 있는 버튼이다. 목록(`keys`)이 리스너와 화면의 **단일 원천**이라 둘이 갈릴 수 없다.

   ## 인출이 앵커를 옮긴다(E1 · 2026-07-29)
   이 화면은 챕터 카드에 _"지금 인출해 망각곡선을 리셋하세요"_ · _"한 번 인출하면 그때부터 유지
   주기가 잡힙니다"_ 라고 **약속해 놓고 그 경로를 주지 않았다.** `touchReview` 의 쓰기 호출부가
   `app/FocusChip.tsx` 하나였기 때문 — 즉 앵커를 얻으려면 25분 집중 세션을 완주하고 토스트가
   살아 있는 동안 '블록 완료로 표시'까지 눌러야 했다. 그래서 유지 큐(끝낸 챕터)는 앵커를 못 얻어
   영구히 `due` 였고, `reviewQueue.ts` 의 `MAINTENANCE_CAP` 주석이 그 기능의 존립 근거로 든
   _"볼 때마다 진짜 앵커가 하나씩 생겨 큐가 스스로 수렴한다"_ 가 한 번도 참이 아니었다.

   ⚠ **`2`(집중 시작)에서 앵커를 옮기지 않는 것이 이 설계의 핵심이다.** 그건 인출 사건이 아니라
     세션 *시작*이라, 거기에 매달면 25분 공부 없이 `2` 를 14번 눌러 14개 챕터의 망각곡선을
     리셋하게 된다 — 사용자가 승인한 "인출 사건이 사다리의 단위"라는 근거로도 정당화되지 않는다
     (그 경우 인출 사건 자체가 없다). 그래서 **`3` 을 따로 판다.**
   ⚠ **`3` 에는 대조 게이트가 없다** — 챕터 카드엔 펼칠 본문이 없어서(`revealable` 이 이 종류를
     애초에 제외한다) 요구할 대조가 없고, 볼트 열람을 조건으로 걸면 그건 계약이 아니라 새 마찰이다.
     자기보고의 위험은 알려진 채로 수용된 것이고, 최악이 "덜 급한 챕터를 좀 늦게 본다"라 방향이
     안전한 쪽이다(`spacedReview.ts:47-50` 의 비대칭 논거와 부호가 같다).
   ⚠ **회상 카드는 앵커가 원리적으로 없다** — `Summary` 에 `chapter` 필드 자체가 없다(요약은 과목
     단위다). sid 만으로 아무 챕터나 리셋하는 것은 인출 기록이 아니라 오염이라 하지 않는다.
============================================================ */
