  const state = useApp((s) => s.state);
  const navigate = useNavigate();
  const open = openBacklog(state);
  const closedThisWeek = backlogClosedBetween(state, ds0, ds6);
  // 회수 체크는 목록에서 즉시 사라진다 — 실수 클릭 대비 되돌리기 토스트(Journal과 단일 출처).
  const close = useToggleBacklog();
  return (
    <div className="ds-rule">
      <h2>
        보충 필요 회수 <span className="ds-tiny text-mut">— 백로그를 닫는 고리</span>
      </h2>
      <div className="ds-row" style={{ marginBottom: 8 }}>
        <span className={`ds-pill ${open.length ? 'ds-warn' : 'ds-good'}`}>열림 {open.length}</span>
        <span className="ds-pill ds-good">이번 주 회수 {closedThisWeek}</span>
      </div>
      {open.length ? (
        open.map((b) => (
          <div key={b.id} className="ds-rec ds-blOpen">
            <div className="ds-recHead">
              <input type="checkbox" aria-label="회수 완료" checked={false} onChange={() => close(b.id)} />
              {/* H25 — 색은 **파생물**이다(절대규칙 #3). 저장값을 읽고 생 hex 로 폴백하던 자리 —
                  H8 이 `TodayBlocks` 에 적용한 처방 그대로 `colorForId` 로 유도한다. */}
              <span className="ds-swatch" style={{ background: colorForId(b.sid) }} />
              <b>{b.topic || '(주제 없음)'}</b>
              {b.name && <span className="ds-tiny text-mut"> · {b.name}</span>}
              <span className="ds-tiny text-mut" style={{ marginLeft: 6 }}>
                열린 지 {dayDiff(b.ds, todayISO(state))}일
              </span>
            </div>
            {b.note && <div className="ds-tiny">{b.note}</div>}
          </div>
        ))
      ) : (
        <div className="ds-empty ds-tiny">열린 백로그가 없어요.</div>
      )}
      <div className="ds-foot" style={{ marginTop: 8 }}>
        오래 열린 항목일수록 위로. 더 안 중요하면 과감히 버린다(재시작 루틴). 추가는{' '}
        <button type="button" className={INLINE_LINK} onClick={() => navigate('/today', { viewTransition: true })}>
          오늘 학습
        </button>{' '}
        탭에서.
      </div>
    </div>
  );
}

/** 주간 체크리스트 + 메모(10절). */
function ChecklistCard({ wk }: { wk: string }) {
  const w = useApp((s) => s.state.weekly?.[wk]) || { checks: {}, note: '' };
  const mutate = useApp((s) => s.mutate);
  const checks = w.checks || {};
  const ckDone = WEEKLY_CHECKS.filter(([k]) => !!checks[k]).length;
  // 메모는 로컬 draft로 미러링 — 키 입력마다 전역 mutate(→schedule 전체 재계산 캐스케이드)를 피하고
  // onBlur(및 언마운트 flush)에서만 커밋한다(Journal 텍스트 필드와 동일 패턴).
  // draft 초기값=이번 주 note. 주(wk)가 바뀌면 이 카드는 부모 key={wk}로 리마운트돼 자동 재동기화된다.
  const [draft, setDraft] = useState(w.note || '');
  const commit = () => mutate((st) => setWeeklyNote(st, wk, draft));
  useFlushOnUnmount(commit); // 마지막 편집 유실 방지 — 탭 이탈/주 이동으로 언마운트될 때 draft 커밋.
  return (
    <div className="ds-rule">
      <h2>
        주간 점검 체크리스트{' '}
        <span className={`ds-pill ${ckDone === WEEKLY_CHECKS.length ? 'ds-good' : ''} ds-tiny`}>
          {ckDone}/{WEEKLY_CHECKS.length}
        </span>
      </h2>
      {WEEKLY_CHECKS.map(([k, label]) => (
        <label key={k} className="ds-chkRow">
          <input
            type="checkbox"
            checked={!!checks[k]}
            onChange={(e) => mutate((st) => setWeeklyCheck(st, wk, k, e.target.checked))}
          />
          <span>{label}</span>
        </label>
      ))}
      <label htmlFor="wk-note" style={{ marginTop: 10 }}>
        이번 주 메모 <span className="ds-tiny text-mut">(무엇을 바꿀까)</span>
        {draft.trim() && <span className="ds-pill ds-good ds-tiny"> ✓ 자동 저장됨</span>}
      </label>
      <textarea
        id="wk-note"
        rows={3}
        value={draft}
        onChange={(e) => setDraft(e.target.value)}
        onBlur={commit}
        placeholder="예) M 오답이 많았다 → 다음 주 통신 도출 백지연습 +1블록. 보충필요 2개 남음, 토요일 오전에 닫기."
      />
      <div className="ds-foot">체크/메모는 그 주에 저장돼요(주를 넘기면 각각 따로 보관).</div>
    </div>
  );
}

/** 회고 코칭(B7) + 반복 약점(C9) — 결정적 인사이트를 항상 보이고, Ollama 가 있으면 AI로 구체화. */
/* E-4 레버 SSOT — 약점/위험 과목의 주간 배정시간(weeklyHours, 스케줄러 입력)을 +1h/정확한 -1h 언두로
   조정. CoachCard·WorkbenchCard가 바이트 동일 복붙하던 것(반올림 로직 드리프트=실버그 위험)을 한 곳으로.
   daily 모드는 이 레버가 없어(leverFor가 undefined) 버튼이 미표시된다. */
function useWeeklyAllot() {
  const items = useApp((s) => s.state.items);
  const mutate = useApp((s) => s.mutate);
  const leverFor = (subject: string) => items.find((it) => it.name === subject && it.mode !== 'daily');
  /* Q-19 → M-9 — 산술뿐 아니라 **찾아서 쓰는 것까지** `lib/weekAlloc.applyWeeklyHours` 가
     소유한다(종전엔 이 세 줄이 팔레트·⌘K 에도 글자단위로 복제돼 있었다). 여기 남은 것은
     `mutate` 한 겹뿐이다. */
  const bumpWeekly = (id: string, delta: number) => mutate((st) => void applyWeeklyHours(st, id, { delta }));
  const allotMore = (subject: string, id: string) => {
    bumpWeekly(id, 1);
    toastUndoable(`"${subject}" 주간 배정 +1h`);
  };
  return { leverFor, allotMore };
}

function CoachCard({ ds0 }: { ds0: string }) {
  const state = useApp((s) => s.state);
  const mutate = useApp((s) => s.mutate);
  const { data: ping } = usePing();
  const online = !!ping?.ok;
  const insights = weeklyInsights(state, ds0);
  const weak = weakSpots(state); // 전 기간 반복 약점(C9) — '반복적으로 막히는 지점' 자각.
  const { data: k } = useKnowledge();
  const roots = rootCauseRollup(k); // 여러 약점의 공통 뿌리(선수개념). k 없거나 오프라인이면 [].

  // I-1: 진단→행동 — 반복약점/근본원인을 원클릭으로 보충 백로그(소비 승격과 같은 그릇)로 시드.
  const seedBacklog = (seed: BacklogSeed) => {
    mutate((s) => addBacklog(s, '', seed.name, seed.topic, seed.note));
    toast(PROMOTE_TOAST);
  };

  // E-4: 리뷰→계획 되먹임 — 약점 과목의 주간 배정시간 +1h(정확한 -1h 언두). SSOT는 useWeeklyAllot.
  const { leverFor, allotMore } = useWeeklyAllot();

  const [aiBusy, setAiBusy] = useState(false);
  const [aiPreview, setAiPreview] = useState('');
  const [ai, setAi] = useState<ReviewCoachResult | null>(null);
  const [aiErr, setAiErr] = useState<string | null>(null);
  const askAI = async () => {
    if (aiBusy) return;
    setAiBusy(true);
    setAiErr(null);
    setAiPreview('');
    try {
      const facts = insights.map((i) => i.text);
      const weakLines = weak.map((w) => `${w.subject} — ${w.chapter} (${w.count}회, ${w.codes.join('/')})`);
      const r = await reviewCoach(facts, weakLines, {
        onDelta: (t) => setAiPreview(previewFromJsonStream(t)),
      });
      if (r.ok && r.coach) setAi(r.coach);
      else setAiErr(r.error || 'AI 코칭 실패');
    } catch (e) {
      setAiErr((e as Error).message || 'AI 연결 실패');
    }
    setAiBusy(false);
  };

  const hasData = insights.length > 0 || weak.length > 0 || roots.length > 0;

  return (
    <div className="ds-rule">
      <h2>
        회고 코칭 <span className="ds-tiny text-mut">— 이번 주 데이터가 말하는 다음 주 우선순위</span>
      </h2>
      {hasData ? (
        <>
          {insights.length > 0 && (
            <ul className={COACH_LIST}>
              {insights.map((ins, i) => (
                <li key={i} className={COACH_ITEM} data-tone={ins.tone}>
                  <span className={COACH_DOT} aria-hidden="true" />
                  <span>{ins.text}</span>
                </li>
              ))}
            </ul>
          )}
          {weak.length > 0 && (
            <div className={WEAK_BOX}>
              <div className="ds-tiny text-mut">반복 약점 — 같은 곳에서 여러 번 막힌 지점</div>
              <ul className={WEAK_LIST}>
                {weak.map((w) => {
                  const lever = leverFor(w.subject);
                  return (
                    <li key={w.key} className={WEAK_ITEM}>
                      <b className="font-bold text-txt">
                        {w.subject} — {w.chapter}
                      </b>
                      <span className={WEAK_META}>
                        {w.count}회 · {w.codes.map((c) => CBMS_INFO[c].label).join('·')}
                      </span>
                      <span className={WEAK_ACTIONS}>
                        <button
                          type="button"
                          className={WEAK_SEED}
                          onClick={() => seedBacklog(backlogFromWeakSpot(w))}
                          title={`"${w.subject} — ${w.chapter}"를 보충 백로그로 보내기`}
                          aria-label={`${w.subject} ${w.chapter} 보충 백로그로 보내기`}
                        >
                          ＋보충
                        </button>
                        {lever && (
                          <button
                            type="button"
                            className={WEAK_ALLOT}
                            onClick={() => allotMore(w.subject, lever.id)}
                            title={`"${w.subject}" 주간 배정시간 +1h (현재 ${lever.weeklyHours || 0}h)`}
                            aria-label={`${w.subject} 다음 주 배정시간 1시간 늘리기`}
                          >
                            +1h 배정
                          </button>
                        )}
                      </span>
                    </li>
                  );
                })}
              </ul>
            </div>
          )}
          {roots.length > 0 && (
            <div className={WEAK_BOX}>
              <div className="ds-tiny text-mut">
                약점의 뿌리 — 한 선수개념이 여러 약점의 공통 근본원인(먼저 메우면 상류가 함께 풀림)
              </div>
              <ul className={WEAK_LIST}>
                {roots.map((c) => (
                  <li key={c.cause} className={WEAK_ITEM}>
                    <b className="font-bold text-txt">
                      <Icon name="sprout" /> {c.cause}
                    </b>
                    <span className={WEAK_META}>{c.count}개 약점의 뿌리</span>
                    <span className={WEAK_ACTIONS}>
                      <button
                        type="button"
                        className={WEAK_SEED}
                        onClick={() => seedBacklog(backlogFromRootCause(c))}
                        title={`"${c.cause}"(선수개념)를 보충 백로그로 보내기`}
                        aria-label={`${c.cause} 보충 백로그로 보내기`}
                      >
                        ＋보충
                      </button>
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          )}
        </>
      ) : (
        <div className="ds-foot">이번 주 요약·오답·백지 기록이 쌓이면 코칭이 나와요.</div>
      )}
      {/* ⚠ **공지는 미리 서 있는 리전이 맡는다**(H22 · 2026-07-30). 종전엔 `role="alert"`/`status` 가
          `{aiErr && …}`·`{ai && …}` 안쪽 노드에 붙어 있어 **리전과 텍스트가 동시에 삽입**됐다 —
          `shell/toast` 가 "그러면 AT 에 따라 공지가 통째로 씹힌다"고 적어 둔 그 형태다. AI 회고는
          수 초 뒤에 비동기로 도착하므로, 씹히면 스크린리더 사용자에겐 **버튼을 눌렀는데 아무 일도
          안 일어난 것**이 된다. 오류만 assertive(하던 일을 끊어도 되는 소식)다. */}
      <LiveRegion message={aiErr ?? ''} assertive />
      <LiveRegion message={ai ? 'AI 회고가 도착했어요' + (ai.headline ? ` — ${ai.headline}` : '') : ''} />
      <div className={COACH_AI}>
        <Button
          sm
          onClick={askAI}
          disabled={aiBusy || !online || !hasData}
          title={online ? '' : '워크스페이스가 설정되지 않았어요'}
        >
          {aiBusy ? (
            <>
              <span className="ds-spin" /> 코칭 중…
            </>
          ) : (
            <>
              <Icon name="bot" /> AI 회고 받기
            </>
          )}
        </Button>
        {aiErr && (
          <>
            <span className="ds-tiny text-mut">{aiErr}</span>
            <Button sm variant="ghost" onClick={askAI} disabled={aiBusy || !online}>
              다시 시도
            </Button>
          </>
        )}
      </div>
      {/* 코칭 스트리밍 미리보기 — 완성 문장부터(SR에는 버튼의 '코칭 중…'이 상태). */}
      {aiBusy && aiPreview && (
        <p className={AI_STREAM} aria-hidden="true">
          {aiPreview}
        </p>
      )}
      {ai && (
        <div className={AI_BOX}>
          {ai.headline && <div className={AI_HEAD}>{ai.headline}</div>}
          {ai.focus && (
            <div className={AI_FOCUS}>
              <b className="mr-1 font-bold text-acc">먼저 손볼 것</b> {ai.focus}
            </div>
          )}
          {Array.isArray(ai.actions) && ai.actions.length > 0 && (
            <ul className={AI_ACTIONS}>
              {ai.actions.map((a, i) => (
                <li key={i}>{a}</li>
              ))}
            </ul>
          )}
          {ai.encourage && <div className="ds-foot">{ai.encourage}</div>}
        </div>
      )}
    </div>
  );
}

/** I-14 약점 워크벤치(RiskCard 승격) — 복습 위험(C8: 배웠지만 오래 안 본 개념)을 '식별'에서 끝내지 않고
   각 행을 식별→행동 전환대로: [＋보충 큐][+1h 배정][🔎 볼트][↻ 복습 실행]. weakSpots는 좌측 코칭 카드가,
   여기선 riskChapters·openBacklog 신호를 소비(전부 이 파일 스코프에 이미 있어 재페치 0). */
function WorkbenchCard() {
  const state = useApp((s) => s.state);
  const mutate = useApp((s) => s.mutate);
  const res = useSchedule();
  const navigate = useNavigate();
  const today = todayISO(state);
  const [expanded, setExpanded] = useState(false);
  /* 조용한 절단 금지 — 전체를 받아 접기/펼치기로 숨은 수를 밝힌다.
     ⚠ 메모가 필수다: 이 컴포넌트는 `useApp((s) => s.state)` 로 **루트 참조**를 구독하므로 앱의
     어떤 편집이든 리렌더되고, `riskChapters` 는 그 안에서 챕터 전량의 사다리를 다시 판정한다.
     `expanded` 토글·상위 리렌더에서 그것이 다시 도는 것은 순수 낭비다(2026-08-20 리뷰 m-9 ·
     같은 파일군의 `features/items/Items.tsx` 가 이미 이 형태를 쓴다). */
  const all = useMemo(() => riskChapters(state, res.days || [], today, 100), [state, res.days, today]);
  const shown = expanded ? all : all.slice(0, 6);
  const hidden = all.length - shown.length;
  const openN = openBacklog(state).length; // 워크벤치가 채우는 큐의 현재 깊이(맥락).

  // E-4 레버 재사용 — 약점/위험 과목의 주간 배정시간 +1h(정확한 -1h 언두). SSOT는 useWeeklyAllot.
  const { leverFor, allotMore } = useWeeklyAllot();
  // I-1과 동일 경로(addBacklog→toast) — 방치된 개념을 보충 큐로 넣어 백지 복습을 예약한다.
  const seedRisk = (c: { subject: string; chapter: string; daysSince: number }) => {
    const seed: BacklogSeed = {
      name: '복습 위험',
      topic: `${c.subject} — ${c.chapter}`,
      note: `${c.daysSince}일 방치된 개념 — 백지 복습으로 인출`,
    };
    mutate((s) => addBacklog(s, '', seed.name, seed.topic, seed.note));
    toast(PROMOTE_TOAST);
  };
  // 질의 조립은 `lib/utils.vaultQuery` 하나가 소유한다(H14) — 여기 있던 `+ ' ' +` 는 챕터가
  // 없으면 끝에 공백을 붙였다.
  const openVault = (c: { subject: string; chapter: string }) => openVaultSearch(vaultQuery(c.subject, c.chapter));

  return (
    <div className="ds-rule">
      <h2>
        약점 워크벤치 <span className="ds-tiny text-mut">— 오래 안 본 개념을 식별에서 행동으로</span>
      </h2>
      <div className="ds-row" style={{ marginBottom: 8 }}>
        <span className={`ds-pill ${all.length ? 'ds-warn' : 'ds-good'}`}>복습 위험 {all.length}</span>
        <span className={`ds-pill ${openN ? 'ds-warn' : 'ds-good'}`}>보충 열림 {openN}</span>
      </div>
      {all.length ? (
        <>
          <ul className={RISK_LIST}>
            {shown.map((c) => {
              const lever = leverFor(c.subject);
              return (
                /* ⚠ **행이 자기 앵커를 얻는다**(U027 · 2026-08-21 ux 축) — ⌘K·찾기의 약점 히트가
                   `/review#weak-<sid|챕터>` 로 오면 이 줄에 선다. 착지는 `useHashTarget` 이 한다
                   (`Subject` 의 챕터 앵커와 같은 관용구 · U011 이 세운 것). */
                <li
                  key={weakKey(c.sid, c.chapter)}
                  id={`weak-${weakKey(c.sid, c.chapter)}`}
                  className={RISK_ROW}
                  data-risk={c.risk}
                >
                  <span className={RISK_DOT} style={{ background: c.color || 'var(--acc)' }} aria-hidden="true" />
                  <span className={RISK_NM}>
                    {c.subject} <small className="ml-1 text-sm font-medium text-mut">{c.chapter}</small>
                  </span>
                  {/* ⚠ 볼트 유래 앵커는 배지로 **구분**한다(W2) — `reviewed:` 는 검증 통과일이지
                      인출일이 아니라, 앱 자신의 기록과 같은 얼굴로 두면 폴백을 승격시키는 셈이다. */}
                  {c.fromVault && (
                    <span className="ds-pill ds-tiny" title="앱 인출 기록이 없어 볼트 reviewed: 를 앵커로 쓴 항목">
                      볼트
                    </span>
                  )}
                  <span className={RISK_AGE}>{c.daysSince}일</span>
                  <span className={BENCH_ACTIONS}>
                    {lever && (
                      <button
                        type="button"
                        className={WEAK_ALLOT}
                        onClick={() => allotMore(c.subject, lever.id)}
                        title={`"${c.subject}" 주간 배정시간 +1h (현재 ${lever.weeklyHours || 0}h)`}
                        aria-label={`${c.subject} 다음 주 배정시간 1시간 늘리기`}
                      >
                        +1h
                      </button>
                    )}
                    <button
                      type="button"
                      className={BENCH_BTN}
                      onClick={() => seedRisk(c)}
                      title={`"${c.subject} — ${c.chapter}"를 보충 백로그로 보내기`}
                      aria-label={`${c.subject} ${c.chapter} 보충 백로그로 보내기`}
                    >
                      ＋
                    </button>
                    {/* 백지 복습 유도의 손잡이 — 볼트 딥링크(Graph E-5 미러). obsidian://search는 볼트명 없이도 동작. */}
                    <button
                      type="button"
                      className={BENCH_BTN}
                      onClick={() => openVault(c)}
                      title="Obsidian에서 이 개념 검색 (설치돼 있어야 함)"
                      aria-label={`${c.subject} ${c.chapter} 볼트에서 검색`}
                    >
                      <Icon name="search" />
                    </button>
                    <button
                      type="button"
                      className={BENCH_BTN}
                      onClick={() => navigate('/review-run', { viewTransition: true })}
                      title="지금 복습 실행(백지 인출)"
                      aria-label={`${c.subject} ${c.chapter} 복습 실행`}
                    >
                      ↻
                    </button>
                  </span>
                </li>
              );
            })}
          </ul>
          {(hidden > 0 || expanded) && (
            <button type="button" className={SHOW_MORE} onClick={() => setExpanded((v) => !v)}>
              {expanded ? '접기' : `+${hidden}개 더 보기`}
            </button>
          )}
        </>
      ) : (
        <div className="ds-foot">위험한 챕터가 없어요 — 최근 학습을 잘 따라가고 있어요.</div>
      )}
      <div className="ds-foot">
        오래될수록 붉게 — 배정으로 시간을 주거나 · 보충 큐로 넣거나 · 볼트에서 찾아 · 복습 실행으로 인출.
      </div>
    </div>
  );
}

export default function Review() {
  const res = useSchedule();
  const state = useApp((s) => s.state);
  /* U027 — 약점 히트(`/review#weak-<sid|챕터>`)가 그 행에 착지한다. 워크벤치가 이 화면 아래쪽에
     있어 앵커 없이 오면 사용자가 그 줄을 눈으로 다시 찾아야 했다. */
  const { hash } = useLocation();
  useHashTarget(hash, `${state.cbms?.length ?? 0}:${state.items.length}`);
  const [weekOffset, setWeekOffset] = useState(0);
  // , / . — 이전/다음 주(스케줄 탭과 동일 키).
  // 회고는 과거·현재만 — 미래 주는 데이터가 없어 전부 '달성 0%' 보드다. 앞으로는 이번 주(0)까지만.
  useWeekNavKeys(
    () => setWeekOffset((o) => o - 1),
    () => setWeekOffset((o) => Math.min(0, o + 1)),
  );

  const mon = addDays(mondayOf(parseISO(todayISO(state))), weekOffset * 7); // '오늘' 단일 출처 경유.
  const ds0 = iso(mon);
  const ds6 = iso(addDays(mon, 6));
  const wk = ds0;
  const isThis = weekOffset === 0;
  const pa = weekPlanActual(state, res, mon);

  // 디브리프 리드아웃 — 달성률·가장 잦은 오답·보충 열림을 상단 바로(데모 v6 헤더).
  // cnt는 여기서 한 번 집계해 CbmsDistCard에도 주입한다(이중 cbmsCounts 순회 제거).
  const cnt = cbmsCounts(state, ds0, ds6);
  const cbmsT = cbmsTop(cnt); // 최다 오답 코드 + 합 — 리드아웃·분포 카드가 공유.
  const openN = openBacklog(state).length;
  /* P-5 — 적응형 용량 한 줄(적용된 주에만). ⚠ 주(週)와 무관하게 **현재** 계수를 말한다:
     `adherenceFactor` 의 창은 오늘 기준 최근 14일이라 과거 주로 이동해도 그 값은 안 바뀐다.
     그래서 문장도 "이번 주"라고 말하지 않는다(모르는 것을 우기지 않는다). */
  const adhere = adherenceLine(res.adapt, res.adaptApplied === true);

  usePageChromeEffect(
    () => ({
      /* W22/H3 — `primary` 는 **필수 키**다(`store/usePageChrome.ts` 머리주석). 이 화면은 렌즈라
         44px 앵커를 세우지 않는다 — 잊은 것이 아니라 없다고 정한 것이다. */
      primary: null,
      readouts: [
        {
          label: '달성률',
          value: (
            <>
              {pa.rate}
              <small className="text-base14 font-bold text-mut">%</small>
            </>
          ),
          accent: true,
        },
        { label: '잦은 오답', value: cbmsT?.code ?? '—' },
        { label: '보충 열림', value: openN },
      ],
    }),
    [pa.rate, cbmsT?.code, openN],
  );

  return (
    <section className={WRAP} aria-label="주간 리뷰">
      <div className={NAV}>
        <Button sm onClick={() => setWeekOffset((o) => o - 1)}>
          <Icon name="chevronLeft" /> 이전 주
        </Button>
        <div className={WKBOX}>
          <b className={WKLAB}>{weekLabel(mon)}</b>
          <span className={WKOFF}>{isThis ? '이번 주' : weekOffset > 0 ? `+${weekOffset}주` : `${weekOffset}주`}</span>
        </div>
        <Button sm onClick={() => setWeekOffset((o) => Math.min(0, o + 1))} disabled={weekOffset >= 0}>
          다음 주 <Icon name="chevronRight" />
        </Button>
        <Button sm variant="ghost" onClick={() => setWeekOffset(0)} disabled={weekOffset === 0}>
          이번 주
        </Button>
      </div>

      <div className={GRID}>
        {/* 좌 — 시그니처 차트(계획 대비 실제 · CBMS 분포) */}
        <div className={MAINCOL}>
          <div className={HINT}>
            주 1회 15~20분, <b>공부 방식</b>을 점검하는 자리. 시간(투입)이 아니라 <i>CBMS 분포 축소·진행률</i> 같은
            나아진 증거가 가장 강한 동기.
          </div>
          {/* ── P-5 적응형 용량을 문장으로(2026-08-01) ─────────────────────────────
              `adherenceFactor` 가 최근 14일 이행률로 계획 용량을 0.5~1.0배로 **실제로 깎는다.**
              그 수는 오늘 탭 리드아웃에 `용량 −30%` 로 이미 있었지만(PL-5) 숫자뿐이라
              "이게 뭔가 · 왜 · 어떻게 되돌리나"를 못 말했다 — 사용자가 "계획이 왜 헐거워졌지"를
              물을 곳이 없던 것이 그 공백이다.
              ⚠ 문장 **순서가 규칙**이다(조정 사실 → 근거 → 회복 조건). 하락을 앞세우면 같은
                사실이 죄책감 계기판이 되고, 그건 이 화면이 하려는 일의 정반대다. 판정·문구는
                `lib/adherence` 가 소유한다(판정=lib · 그리기=feature).
              ⚠ 안 깎인 주에는 **줄 자체가 없다**(0·평온은 아무것도 안 그린다). */}
          {adhere && (
            <p className={HINT} role="status">
              <Icon name="balance" /> {adhere.line}
            </p>
          )}
          {/* key=주 — 주를 이동하면 AI 코칭(ai/aiErr/aiBusy)이 리셋된다(이전 주 코칭이 그대로 남던 오표시 방지). */}
          <CoachCard key={ds0} ds0={ds0} />
          <PlanActualCard pa={pa} />
          <CbmsDistCard cnt={cnt} />
        </div>
        {/* 우 — 점검·회수(액션) */}
        <div className={SIDECOL}>
          {/* key=주 — 주 이동 시 리마운트해 메모 draft를 그 주 note로 재동기화(+언마운트 flush). */}
          <ChecklistCard key={wk} wk={wk} />
          {/* T-9 지연 JOL — **조건부 한 줄**. 물을 것이 없으면 스스로 사라진다(그 카드 머리주석).
              여기(리뷰)인 이유는 러너에서 물으면 묻고 바로 푸는 즉시 JOL 이 되기 때문이다. */}
          <JolCard />
          <WorkbenchCard />
          <BacklogReviewCard ds0={ds0} ds6={ds6} />
        </div>
      </div>
    </section>
  );
}

/* ============================================================
   DayPlannerCards — 일 편집기의 순수 프레젠테이션 조각 3종.
   TrayRow(미지정 트레이 한 줄) · EventBand(일정 띠) · TimedCard(타임박스 카드).

   전부 props만 받아 그리는 무상태 컴포넌트라 1137줄짜리 DayPlanner에서 그대로 떼어냈다
   (상태·드래그 오케스트레이션은 DayPlanner가 계속 소유 — 여기로 새어나오면 안 된다).
   좌표 변환은 lib/dayPlanGeometry가 소유.
============================================================ */
import { hLabel, toHM } from '@/lib/utils';
import { useKeymapDoc } from '@/hooks/useKeymap';
import { pxToMin } from '@/lib/dayPlanGeometry';
import { SNAP, snap as snapMin } from '@/lib/dayPlans';
import { COL_CLASS, EDIT_BAR_ID, type DragKind } from './dayPlannerShared';
import { Icon } from '@/components/Icon';

/* ── C-7 이식(DayPlannerCards) — Tailwind 클래스 SSOT ────────────────────────────
   TrayRow(트레이 한 줄) · EventBand(일정 띠) · TimedCard(타임박스 카드) 셋 다 무상태 프레젠테이션.
   ⚠ 좌측 색 띠·채움은 런타임 --seg(과목색) 파생이라 인라인 style 이 얹는 사용 시점 해석(절대규칙 #3).
   ⚠ 카드/밴드는 <div> 라 전역 button 경합이 없지만, 안의 tool/durBtn 은 <button> 이라 전역 button
   (언레이어)을 이겨야 하므로 다른 값만 `!`(§ global element rules · TOOLBASE 참조). built-in 크기
   (text-xs/sm)만 companion line-height 를 흘려 폼컨트롤/자손엔 leading-auto, 정상 흐름엔 원본 LH
   (1.6/1.15)를 명시(line-height 트랩). hover/focus 로 드러나는 툴바는 group-hover/-focus-within(§15).
   ⚠ tool 의 로컬 :hover 는 전역 button:hover(더 높은 명시도)에 이미 가려져 있어 되살리지 않는다. */
// 공용 아이콘 툴 버튼(색은 사용처에서 text-mut!/text-acc! 로 — 같은 property 라 한쪽만).
const TOOLBASE =
  'inline-flex h-5.5 w-5.5 flex-none items-center justify-center rounded-seg! border-transparent! bg-transparent! text-sm! leading-auto focus-visible:outline-offset-1! motion-reduce:transition-none';
const C = {
  trayRow:
    'seg-scope flex cursor-grab items-center gap-2 rounded-md border-solid border-l-[length:var(--bw-seg)] border-l-[color:var(--seg,var(--acc))] bg-[var(--tray-fill)] px-2.25 py-1.75 shadow-inset-line2 active:cursor-grabbing',
  grabDot: 'h-4 w-1 flex-none rounded-xs bg-[image:var(--grab-bar)] opacity-70',
  rowName: 'min-w-0 flex-1 truncate text-md font-bold',
  rowMeta: 'flex-none whitespace-nowrap text-2xs font-bold text-mut',
  durStep: 'inline-flex flex-none cursor-default items-center gap-0.5',
  durBtn:
    'inline-flex h-4.5 w-4.5 items-center justify-center rounded-chip-md! border-line2! bg-panel! leading-none font-extrabold! focus-visible:outline-offset-1!',
  durVal: 'min-w-8.5 text-center text-xs leading-text font-extrabold tabular-nums text-txt',
  rowDur: 'flex-none whitespace-nowrap text-xs leading-text font-extrabold tabular-nums text-mut',
  tool: `${TOOLBASE} text-mut!`,
  ev: 'seg-scope group absolute left-1 box-border flex min-h-4 items-start justify-between gap-1.5 overflow-hidden rounded-blk border-solid border-l-[length:var(--bw-seg)] border-l-[color:var(--event)] bg-[var(--ev-fill)] px-2 text-txt shadow-[var(--shadow-ev)] transition-shadow duration-fast ease-[var(--ease)] hover:z-[6] hover:shadow-[var(--shadow-ev-hover)] focus-within:z-[8] focus-within:-outline-offset-2 focus-within:outline-2 focus-within:outline-acc motion-reduce:transition-none',
  evSel: 'z-[9] outline-2 -outline-offset-1 outline-acc',
  cardMain: 'flex min-w-0 flex-col gap-px',
  cardName: 'truncate text-sm leading-display font-extrabold tracking-wk',
  cardMeta: 'whitespace-nowrap text-2xs font-bold opacity-[0.82]',
  cardTools:
    'flex flex-none gap-px opacity-0 transition-opacity duration-fast group-hover:opacity-100 group-focus-within:opacity-100 motion-reduce:transition-none',
  card: 'seg-scope group absolute right-1 box-border flex min-h-4 cursor-grab items-start justify-between gap-1.5 overflow-hidden rounded-blk px-2 text-txt transition-[box-shadow,filter] duration-fast ease-[var(--ease)] hover:z-[6] hover:shadow-[var(--shadow-card-hover)] focus-within:z-[8] focus-within:-outline-offset-2 focus-within:outline-2 focus-within:outline-acc active:cursor-grabbing motion-reduce:transition-none',
  cardStudy:
    'border-solid border-l-[length:var(--bw-seg)] border-l-[color:var(--seg,var(--acc))] bg-[var(--seg-fill-20)] shadow-[var(--shadow-card-study)]',
  cardTask:
    '[border-left-style:dashed] border-l-[length:var(--bw-seg)] border-l-[color:var(--seg,var(--acc))] bg-[var(--seg-fill-12)] shadow-inset-line2',
  cardSel: 'z-[9] outline-2 -outline-offset-1 outline-acc',
  resizeHandle: 'absolute inset-x-0 bottom-0 h-1.75 cursor-ns-resize touch-none hover:bg-[var(--seg-handle)]',
} as const;

/* ── W23 시간 스파인 — **이 화면의 시그니처**(2026-07-31) ────────────────────────────────
   매일 여는 최대 화면 둘(`alloc`·`schedule`)은 `<svg>`·`<canvas>` **0**, 히어로 토큰 **0** 이라
   시그니처가 아예 없었다. 새 그래픽을 얹으면 밀도를 파는데(그게 미실행 사유였다), 이 화면엔
   **이미 시각 눈금 열(gutter)이 있다** → 거기에 하루를 한 줄로 세운다: 회색이 하루 전체,
   액센트 구간이 **가용 창**. 타임라인이 "무엇이 언제"라면 스파인은 "하루가 어떻게 생겼나"이고,
   둘은 **같은 숫자의 다른 축척**이다(alloc 의 주간 실루엣과 같은 처방). 추가 폭·높이 0px.
   ⚠ 액센트 사용은 W22 의 승인된 예외다 — 시그니처는 화면당 하나이고 이 화면의 하나가 이것이다. */
const SPINE = 'pointer-events-none absolute inset-y-0 right-0 w-0.5 rounded-full bg-line-soft';
const SPINE_FREE = 'pointer-events-none absolute right-0 w-0.5 rounded-full bg-acc opacity-45';

export function TimeSpine({ windows, pos }: { windows: { s: number; e: number }[]; pos: (m: number) => number }) {
  return (
    <>
      <span className={SPINE} aria-hidden="true" />
      {windows.map((w, i) => (
        <span
          key={i}
          className={SPINE_FREE}
          style={{ top: `${pos(w.s)}%`, height: `${Math.max(0, pos(w.e) - pos(w.s))}%` }}
          aria-hidden="true"
        />
      ))}
    </>
  );
}

/* ── 트레이 한 줄 ────────────────────────────────────────────────────── */
export function TrayRow({
  title,
  meta,
  color,
  mock,
  min,
  free,
  repeat,
  done,
  onToggle,
  onSetMin,
  onPlace,
  onDelete,
  onDragStart,
  rowRef,
  tabIndex,
  onFocus,
  selected,
}: {
  title: string;
  meta: string;
  color?: string;
  /** 모의시험 블록 — 연결된 과목이 없어 팔레트 색이 없다. 색 리터럴 대신 CSS 토큰(.mock)으로 구분. */
  mock?: boolean;
  min?: number;
  free?: boolean;
  repeat?: 'daily' | 'weekly';
  done: boolean;
  onToggle: (on: boolean) => void;
  onSetMin?: (min: number) => void;
  onPlace: () => void;
  onDelete?: () => void;
  onDragStart: (e: React.DragEvent) => void;
  /* ── W13 커서(2026-07-31) ─────────────────────────────────────────────────
     ⚠⚠ 이 행은 **탭 스톱이 최대 5개**였다(체크박스·−·＋·⤵·✕). 실측: 트레이 3번째 행의 ⤵ 까지
     **Tab 14회**, 4번째면 19회 — 마우스는 1클릭이다. 이제 행 자신이 유일한 탭 스톱이고
     (`role="group"` + roving tabindex) 안쪽 컨트롤은 전부 `tabIndex={-1}` 이라 Tab 이 안 든다.
     동사는 `useListCursor` 의 닫힌 어휘로 온다: `x` 완료 · `p` 배치 · `d` 삭제.
     ⚠ 마우스 경로는 한 픽셀도 안 바뀐다 — 안쪽 버튼은 클릭 가능한 진짜 버튼 그대로다. */
  rowRef?: (el: HTMLElement | null) => void;
  tabIndex?: number;
  onFocus?: () => void;
  selected?: boolean;
}) {
  return (
    <div
      ref={rowRef}
      role="group"
      aria-label={title}
      tabIndex={tabIndex ?? -1}
      onFocus={onFocus}
      aria-current={selected ? true : undefined}
      className={`${C.trayRow} ${done ? 'opacity-50' : ''} ${free ? '[--seg:var(--mut)]' : ''} ${mock ? '[--seg:var(--bad)]' : ''} ${selected ? 'rounded-md bg-[var(--tint-ink-5)]' : ''}`}
      draggable
      onDragStart={onDragStart}
      style={color ? ({ ['--seg']: color } as React.CSSProperties) : undefined}
    >
      <input
        type="checkbox"
        tabIndex={-1}
        checked={done}
        onChange={(e) => onToggle(e.target.checked)}
        aria-label={`${title} 완료`}
      />
      <span className={C.grabDot} aria-hidden="true" />
      <span className={`${C.rowName} ${done ? 'ds-shed' : ''}`}>{title}</span>
      <span className={C.rowMeta}>
        {repeat && (
          <span title={repeat === 'daily' ? '매일 반복' : '매주 반복'}>
            <Icon name="refresh" />{' '}
          </span>
        )}
        {meta}
      </span>
      {/* 길이 편집(§6-2 인라인) — 스테퍼로 30분 단위(입력창은 draggable 행과 충돌해 버튼으로). */}
      {onSetMin && min != null ? (
        /* 핸들러가 stopPropagation 뿐이다 — 상태를 바꾸지 않는 순수 드래그 차단 가드다.
           실제 조작은 안쪽 진짜 버튼 2개가 하고, 키보드로는 부모 드래그가 애초에 발동하지
           않으므로 이 가드가 없어도 무해하다. */
        // eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions
        <span
          className={C.durStep}
          onClick={(e) => e.stopPropagation()}
          onMouseDown={(e) => e.stopPropagation()}
          draggable={false}
        >
          <button
            type="button"
            className={C.durBtn}
            tabIndex={-1}
            onClick={() => onSetMin(Math.max(SNAP, min - 30))}
            title="길이 30분 줄이기"
            aria-label={`${title} 길이 30분 줄이기`}
          >
            −
          </button>
          <span className={C.durVal}>{hLabel(min)}</span>
          <button
            type="button"
            className={C.durBtn}
            tabIndex={-1}
            onClick={() => onSetMin(min + 30)}
            title="길이 30분 늘리기"
            aria-label={`${title} 길이 30분 늘리기`}
          >
            ＋
          </button>
        </span>
      ) : (
        min != null && <span className={C.rowDur}>{hLabel(min)}</span>
      )}
      <button
        type="button"
        className={C.tool}
        tabIndex={-1}
        onClick={onPlace}
        title="첫 빈 시간에 배치"
        aria-label={`${title} 시간박기`}
      >
        <Icon name="arrowDownRight" />
      </button>
      {onDelete && (
        <button
          type="button"
          className={C.tool}
          tabIndex={-1}
          onClick={onDelete}
          title="삭제"
          aria-label={`${title} 삭제`}
        >
          ✕
        </button>
      )}
    </div>
  );
}

/* ── 일정 밴드(캘린더) ──────────────────────────────────────────────────
   약속·시험·행사 = 과목과 무관한 단발 사건. 공부 블록/할 일과 **의도적으로 다르게** 생겼다:
   완료 토글도 핀도 트레이 되돌리기도 없고(그 시각에 '일어나는' 것이지 해치우는 게 아니다),
   색도 과목 팔레트가 아니라 의미론 토큰(--event)이다(절대규칙 3 — 색 리터럴·팔레트 오용 금지).
   드래그를 붙이지 않았으므로 WCAG 2.1.1 키보드 대안 부담이 없다 — 시각·길이는 편집 바(✎)에서 고친다. */
export function EventBand({
  title,
  start,
  min,
  half,
  selected,
  pos,
  onSelect,
  onDelete,
}: {
  title: string;
  start: number;
  min: number;
  half?: boolean;
  selected?: boolean;
  pos: (m: number) => number;
  onSelect: () => void;
  onDelete: () => void;
}) {
  const top = pos(start);
  const height = Math.max(3, pos(start + min) - top);
  const compact = min < 45;
  const range = `${toHM(start)}–${toHM(start + min)}`;
  return (
    <div
      className={`${C.ev} ${compact ? 'py-0.5' : 'py-1.25'} ${selected ? C.evSel : 'z-[5]'} ${half ? 'right-[var(--evhalf)]' : 'right-1'}`}
      style={{ top: `${top}%`, height: `${height}%` }}
      role="group"
      aria-label={`일정 ${title} ${range}`}
      data-tip={`${title}\n일정 · ${range}`}
    >
      <div className={C.cardMain}>
        <span className={C.cardName}>{title}</span>
        {!compact && <span className={C.cardMeta}>일정 · {range}</span>}
      </div>
      <div className={C.cardTools}>
        <button
          type="button"
          className={`${TOOLBASE} ${selected ? 'text-acc!' : 'text-mut!'}`}
          onClick={onSelect}
          title="시각·길이 편집"
          aria-label={`${title} 시각·길이 편집`}
          aria-expanded={!!selected}
          aria-controls={selected ? EDIT_BAR_ID : undefined}
        >
          ✎
        </button>
        <button type="button" className={C.tool} onClick={onDelete} title="일정 삭제" aria-label={`${title} 일정 삭제`}>
          ✕
        </button>
      </div>
    </div>
  );
}

/* ── 타임박스 카드(캘린더) ──────────────────────────────────────────────
   드래그로 이동, Alt+↑↓ 시간(±15), Alt+Shift+↑↓ 길이(±15), 하단 핸들 포인터 리사이즈,
   툴바로 완료·핀·트레이·삭제(§6-4 키보드 대안). */
export function TimedCard({
  kind,
  title,
  meta,
  color,
  mock,
  start,
  min,
  spanMin,
  pinned,
  done,
  selected,
  half,
  pos,
  onSelect,
  onDragStart,
  onMove,
  onSetMin,
  onUnplace,
  onPin,
  onToggle,
  onDelete,
}: {
  kind: DragKind;
  title: string;
  meta: string;
  color?: string;
  /** 모의시험 블록 — 과목색이 없으므로 CSS 토큰(.mock)으로 구분(색 리터럴 금지 · 절대규칙 3). */
  mock?: boolean;
  start: number;
  min: number;
  spanMin: number;
  pinned?: boolean;
  done: boolean;
  selected?: boolean;
  /** 같은 시간대에 일정이 있어 오른쪽 반폭으로 물러난 상태(일정이 왼쪽 레인). */
  half?: boolean;
  pos: (m: number) => number;
  onSelect?: () => void;
  onDragStart: (e: React.DragEvent) => void;
  onMove: (delta: number) => void;
  onSetMin: (min: number) => void;
  onUnplace: () => void;
  onPin?: () => void;
  onToggle: (on: boolean) => void;
  onDelete?: () => void;
}) {
  const top = pos(start);
  const height = Math.max(3, pos(start + min) - top);
  const compact = min < 45;

  /* E16 — 이 Alt 조합들은 **`aria-label` 문장 하나에만** 적혀 있었다. 즉 스크린리더 사용자에게만
     문서화되고 `?` 치트시트엔 없었다(있는데 아무도 모르는 키의 전형). 등록은 요소 스코프
     `onKeyDown` 이라 전역 리스너로 옮길 수 없으므로 설명만 올린다. */
  useKeymapDoc('이 화면 · 일일 배치', [
    { display: 'Alt + ↑ / ↓', label: '블록 시간 ±15분' },
    { display: 'Alt + Shift + ↑ / ↓', label: '블록 길이 ±15분' },
    { display: 'Alt + Backspace', label: '트레이로 되돌리기' },
  ]);

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (!e.altKey) return;
    if (e.key === 'ArrowUp') {
      e.preventDefault();
      if (e.shiftKey) onSetMin(min - SNAP);
      else onMove(-SNAP);
    } else if (e.key === 'ArrowDown') {
      e.preventDefault();
      if (e.shiftKey) onSetMin(min + SNAP);
      else onMove(SNAP);
    } else if (e.key === 'Backspace' || e.key === 'Delete') {
      e.preventDefault();
      onUnplace();
    }
  };

  // 포인터 리사이즈 — 하단 핸들에서 아래로 끌면 길이 증가. px→분은 공용 pxToMin(변환 SSOT).
  const startResize = (e: React.PointerEvent) => {
    e.stopPropagation();
    e.preventDefault();
    const col = (e.currentTarget as HTMLElement).closest('.' + COL_CLASS) as HTMLElement | null;
    const colH = col?.getBoundingClientRect().height ?? 0;
    if (!colH) return;
    const y0 = e.clientY;
    const min0 = min;
    // 값 변화 가드 — pointermove는 60~120 Hz로 오는데 결과는 SNAP(15분) 격자라 대부분 같은 값이다.
    // 가드가 없으면 드래그 내내 매 이벤트가 store 커밋이 되고, persist가 400ms 디바운스라
    // 그 사이 recipe가 무제한 누적된다(드래그 1회에 수백 건 → 리베이스 시 일괄 재생).
    // 이제 커밋은 '실제로 다른 길이가 됐을 때'만 = 드래그 중 격자 칸을 넘은 횟수만큼.
    let lastMin = min0;
    const onMoveP = (ev: PointerEvent) => {
      const nm = Math.max(SNAP, snapMin(min0 + pxToMin(ev.clientY - y0, colH, spanMin)));
      if (nm === lastMin) return;
      lastMin = nm;
      onSetMin(nm);
    };
    /* ⚠⚠ **`pointerup` 만 듣지 않는다(H21 · 2026-07-31 `/감사 근본`).** 포인터 시퀀스가 취소되면
       (이 카드는 실제로 `draggable` 이라 네이티브 드래그가 개시될 수 있고, 터치에선 브라우저가
       스크롤을 인수한다) **`pointerup` 이 오지 않는다.** 그러면 `pointermove` 가 window 에 영구히
       남아, 이후 **마우스를 움직일 때마다** 그 블록 길이가 계속 커밋된다(→ store → flush →
       동기화 트리거). 이펙트가 아니라 이벤트 핸들러라 React 가 걷어가지도 않는다.
       `lostpointercapture` 까지 듣는 이유: 캡처를 뺏기는 경로도 같은 결과를 낸다. */
    const onUp = () => {
      window.removeEventListener('pointermove', onMoveP);
      window.removeEventListener('pointerup', onUp);
      window.removeEventListener('pointercancel', onUp);
      window.removeEventListener('lostpointercapture', onUp);
    };
    window.addEventListener('pointermove', onMoveP);
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onUp);
    window.addEventListener('lostpointercapture', onUp);
  };

  /* 카드는 '누를 수 있는 것'이 아니라 여러 조작(편집·완료·핀·삭제)을 담는 **묶음**이다.
     전엔 role="group"에 aria-pressed(그 role이 갖지 않는 무효 속성)를 달고 tabIndex로 포커스만 받되
     onKeyDown이 Alt 키만 처리해 Enter/Space로는 편집 바를 열 수 없었다(키보드로 유일하게 막힌 경로).
     → 이름 있는 group은 유지하되 무효 상태 속성은 떼고, 편집은 툴바의 **진짜 버튼**(✎)이 맡는다.
     Enter/Space·펼침 상태(aria-expanded/controls)를 네이티브로 얻고, Alt+화살표는 그 버튼에서
     컨테이너로 버블링돼 그대로 동작한다 → 컨테이너 tabIndex(중복 탭 스톱)는 없앴다.
     본문을 button으로 감싸지 않은 건 의도적이다: 본문이 곧 드래그 손잡이라 폼 컨트롤로 바꾸면
     시간박기 드래그가 브라우저별로 흔들린다(핵심 상호작용을 건드리지 않는 쪽을 택함). */
  return (
    /* 위 주석의 계약대로 키보드 대안이 전부 같은 요소 위에 있다 — onKeyDown 의 Alt+↑↓(이동) ·
       Alt+Shift+↑↓(길이, 포인터 리사이즈 핸들의 대안) · Alt+Backspace(트레이 복귀), 그리고
       aria-label 이 그 키들을 스크린리더에 직접 안내한다. onClick 은 툴바 ✎ 버튼과 완전히
       같은 onSelect 를 부르는 마우스 중복 경로다. */
    // eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions
    <div
      className={`${C.card} ${kind === 'task' ? C.cardTask : C.cardStudy} ${done ? 'opacity-[0.42] saturate-[0.6]' : ''} ${compact ? 'py-0.5' : 'py-1.25'} ${selected ? C.cardSel : ''} ${mock ? '[--seg:var(--bad)]' : ''} ${half ? 'left-[var(--evhalf)]' : 'left-1'}`}
      style={{ top: `${top}%`, height: `${height}%`, ...(color ? ({ ['--seg']: color } as React.CSSProperties) : {}) }}
      draggable
      onDragStart={onDragStart}
      onClick={() => onSelect?.()}
      role="group"
      onKeyDown={onKeyDown}
      aria-label={`${title} · ${meta} ${toHM(start)}–${toHM(start + min)}. Alt+화살표로 이동, Alt+Shift+화살표로 길이, Alt+Backspace로 트레이로.`}
      data-tip={`${title}\n${meta} · ${toHM(start)}–${toHM(start + min)}`}
    >
      <div className={C.cardMain}>
        <span className={`${C.cardName} ${done ? 'ds-shed' : ''}`}>
          {pinned && (
            <>
              <Icon name="pin" />{' '}
            </>
          )}
          {title}
        </span>
        {!compact && (
          <span className={C.cardMeta}>
            {meta} · {toHM(start)}–{toHM(start + min)}
          </span>
        )}
      </div>
      {/* stopPropagation 뿐 — 툴바 버튼 클릭이 카드 onClick 으로 새지 않게 막는 마우스 전용
          가드다(키보드 경로엔 영향 없음). */}
      {/* eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */}
      <div className={C.cardTools} onClick={(e) => e.stopPropagation()}>
        {/* 편집 바 여는 진짜 버튼 — 키보드로 카드에 들어오면 첫 탭 스톱이 여기고, Enter/Space가
            네이티브로 동작한다(마우스의 '카드 클릭'과 같은 일). 툴바는 focus-within에서 드러난다. */}
        <button
          type="button"
          className={`${TOOLBASE} ${selected ? 'text-acc!' : 'text-mut!'}`}
          onClick={() => onSelect?.()}
          title="시각·길이 편집"
          aria-label={`${title} 시각·길이 편집`}
          aria-expanded={!!selected}
          aria-controls={selected ? EDIT_BAR_ID : undefined}
        >
          ✎
        </button>
        <button type="button" className={C.tool} onClick={() => onToggle(!done)} title="완료" aria-label="완료 토글">
          {done ? '↺' : '✓'}
        </button>
        {onPin && (
          <button
            type="button"
            className={`${TOOLBASE} ${pinned ? 'text-acc!' : 'text-mut!'}`}
            onClick={onPin}
            title="핀(재초안에서 보존)"
            aria-label="핀 토글"
            aria-pressed={!!pinned}
          >
            <Icon name="pin" />
          </button>
        )}
        <button
          type="button"
          className={C.tool}
          onClick={onUnplace}
          title="트레이로(미지정)"
          aria-label="트레이로 되돌리기"
        >
          <Icon name="arrowUpRight" />
        </button>
        {onDelete && (
          <button type="button" className={C.tool} onClick={onDelete} title="삭제" aria-label="삭제">
            ✕
          </button>
        )}
      </div>
      <span className={C.resizeHandle} onPointerDown={startResize} aria-hidden="true" />
    </div>
  );
}

/* ============================================================
   Schedule — 배치 세그먼트(계획개편 §5-3): [일·주·월] 타임블로킹.
   질문 "오늘/이번 주, 무엇을 언제 할까?"에 한 화면으로 답한다.
   상단 네비(뷰 스위치 일/주/월 + 주 뷰 이동) · 본문:
     · 일 = DayPlanner(트레이 + 하루 타임라인 드래그 시간박기)
     · 주 = 주간 캘린더(WeekCalendar) — 요일 클릭 시 일 뷰로 드릴다운
     · 월 = MonthCalendar(마감 + 그날만의 할 일 칩 · 칸 클릭→일 뷰)
   주간 합계·완료율·마감은 상단 바(usePageChrome)로 끌어올린다. 하단 스트립(예상 완료·마감·.ics)은 공통.
============================================================ */
import { useMemo, useState } from 'react';
import { useApp } from '@/store/useApp';
import { useRuntime } from '@/store/useRuntime';
import { useUI } from '@/store/useUI';
import { useNavigate, useSearchParams } from 'react-router-dom';
import State from '@/components/State';
import { selectFinishGains, useSchedule, useStudyMinByWeekday } from '@/store/selectors';
import { usePageChromeEffect } from '@/store/usePageChrome';
import { exportICS, planSignature } from '@/shell';
import {
  iso,
  parseISO,
  addDays,
  dayDiff,
  weekLabel,
  fmtShort,
  ddayInfo,
  todayISO,
  DOW_MON,
  hNum,
  hLabel,
} from '@/lib/utils';
import { Button } from '@/components/ui';
import { useHeroPointer, useNowMin } from '@/hooks/interactions';
import { useWeekOffset } from '@/hooks/useWeekOffset';
import { computeDay, indexDays, deadlineDdays } from '@/lib/scheduleView';
import { examMarks } from '@/lib/semester';
import { timedTasksForDay } from '@/lib/tasks';
import { WeekCalendar } from './WeekCalendar';
import { DayPlanner } from './DayPlanner';
import { MonthCalendar } from './MonthCalendar';
import { CutCard } from './CutCard';
import { Icon } from '@/components/Icon';

/* ── C-7 이식(Schedule 셸) — Tailwind 클래스 SSOT ───────────────────────────────
   상단 네비(줄바꿈 금지 · 좁으면 서술 텍스트를 sr-only 로 접어 화살표만) · 본문(뷰별 fill) ·
   하단 스트립(예상 완료·마감·.ics). 'ds-seg'/on/spotHost/glow/spotlight/note 는 공용이라 유지.
   내장 크기(text-sm/lg)만 companion line-height 를 흘리므로 정상 흐름엔 leading-text/원본 LH 를
   명시(line-height 트랩). `.dd`(마감 카운트다운)는 <button> 이라 전역 button 이 유틸을 이겨 다른
   값만 `!`. @media(900) 세로 스택은 max-wide: 로 재현. */
const S = {
  wrap: 'flex h-full min-w-0 flex-col',
  nav: 'flex flex-none flex-nowrap items-center gap-2.5 border-b border-line px-5.5 py-3.5',
  wknav: 'flex flex-auto items-center gap-2.5 min-w-0',
  navBtn: 'flex-none whitespace-nowrap',
  wk: 'flex-auto min-w-0 truncate text-center',
  wkLab: 'whitespace-nowrap text-lg leading-text font-extrabold tracking-wk',
