/* ============================================================
   ResumeChip — 다른 기기에서 하던 것으로 이어가는 칩(N-7).

   ⚠ **다른 기기의 커서가 살아 있을 때만 존재한다.** 조건이 안 맞으면 `null` 이라 화면에 자리도
   안 만든다 — 이 앱의 빈 상태 규율(0·평온은 아무것도 안 그린다)과 같은 규칙이고, 실제로도
   대부분의 시간엔 커서가 없다(기기 하나로 쓰거나 6시간이 지났거나).

   ⚠ `components/` 가 아니라 여기 있는 이유는 **레이어 경계**다: 이 칩은 `store` 를 읽는데
   `components → store` 는 금지 방향이라 린트가 error 로 막는다(절대규칙 #2). 폰은 이 파일을
   공유하지 않고 자기 화면 문법으로 따로 그린다(C-6 의 "lib 만 공유" 규율 그대로).
   ⚠ 시각은 마운트 시 한 번만 읽는다 — 렌더 중 `Date.now()` 는 순수성 린트가 막고, 커서의
   6시간 TTL 은 초 단위 정확도가 필요 없다.
============================================================ */
import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useApp } from '@/store/useApp';
import { latestResume, resumeDevice, resumeLabel, resumeIndex, RESUME_ROUTE, type ResumeNav } from '@/lib/resume';
import { Icon } from '@/components/Icon';

const CHIP =
  'inline-flex items-center gap-2 rounded-chip border! border-line-acc-pill! bg-tint-acc-9! px-3! py-1.5! text-sm! leading-auto font-bold! text-ink! hover:bg-tint-acc-14! focus-visible:outline-2 focus-visible:outline-acc focus-visible:-outline-offset-2';

export default function ResumeChip() {
  const state = useApp((s) => s.state);
  const navigate = useNavigate();
  const [now] = useState(() => Date.now());
  const hit = latestResume(state, resumeDevice(), now);
  if (!hit) return null;
  /* 진행 인덱스를 **내비 state 로 실어 보낸다** — 착지 화면이 커서를 스스로 읽으면 레일·⌘K 로
     그냥 연 사람까지 7번째 카드에서 시작한다. 이어하기는 누른 사람의 의도다.
     ⚠ 이 칩이 `(7/12)` 를 약속하는 동안 러너는 언제나 0 에서 열렸다 — 이 기능이 막으려던
     중복 학습을 기능이 보장하던 자리다. */
  const go = (): void => {
    const at = resumeIndex(hit.cur);
    // Q-27 — `screen` 커서는 **자기 경로를 들고 온다**(다른 종류는 kind 가 화면을 정한다).
    const to = hit.cur.route || RESUME_ROUTE[hit.cur.kind];
    navigate(to, at === null ? undefined : { state: { resumeAt: at } satisfies ResumeNav });
  };
  return (
    <button type="button" className={CHIP} onClick={go} title="다른 기기에서 하던 것을 이어서">
      <Icon name="arrowForward" />
      {resumeLabel(hit.cur)}
    </button>
  );
}

/* SetupGuide — 첫 실행 온보딩(콜드 스타트 빈 화면 방지). 3스텝 라이브 체크.
   과목+목표가 갖춰지면 자동으로 숨는다(Today가 setupComplete로 대시보드와 스위칭).

   ⚠ W3(2026-07-31) — 종전엔 **3버튼이 전부 `/items` 로** 갔다(화면은 "3단계"라 말하는데 목적지가
   하나). 그리고 볼트를 **묻지도 않아서**, 노트 604개가 옆에 있는 사용자에게도 빈 앱을 보여줬다.
   지금은 `app/VaultSync` 가 부팅에 채운 `['vault']` 를 읽어 **볼트에 무엇이 있는지 먼저 말하고**,
   각 단계가 서로 다른 목적지(임포트 패널 · 과목 시트 · 뼈대)를 갖는다. */
import { useNavigate } from 'react-router-dom';
import { useQuery, skipToken } from '@tanstack/react-query';
import { useApp } from '@/store/useApp';
import { Button, Pill } from '@/components/ui';
import type { VaultScan } from '@/lib/vault';
import type { AppState } from '@/lib/types';
import { Icon } from '@/components/Icon';

/** 셋업 완료 판정 — 과목 1개 이상 + 목표(일일분/주당시간/챕터) 1개 이상. Today와 공유(단일 원천).
 *
 * ⚠⚠ **이 판정은 "사용자가 정한 것"만 봐야 한다(W1 · 2026-07-31).** 종전엔 `makeItem` 기본값
 * `weeklyHours: 3` 때문에 **과목을 만드는 행위 자체가 목표까지 충족**시켰다 — `+ 첫 과목 추가`
 * 한 번에 3단계 중 2단계가 켜지고 `Today.tsx` 가 스크림을 영구히 걷어, 시각적으로 지배적인
 * primary 버튼이 곧 막다른 길이었다. 고친 자리는 판정식이 아니라 **생성부**(`Items.addItem` 이
 * `weeklyHours: 0` 으로 만든다) — 판정식을 비틀면 "3을 직접 고른 사용자"까지 미완으로 읽는다. */
export function setupComplete(items: AppState['items']): boolean {
  const hasSubjects = items.some((i) => i.name);
  const hasTargets = items.some(
    (i) =>
      i.name &&
      ((i.mode === 'daily' && (i.dailyMin || 0) > 0) ||
        (i.weeklyHours || 0) > 0 ||
        (i.chapters && i.chapters.length > 0)),
  );
  return hasSubjects && hasTargets;
}

export function SetupGuide() {
  const navigate = useNavigate();
  const items = useApp((s) => s.state.items);
  const routine = useApp((s) => s.state.routine);

  const scan = useQuery<VaultScan>({ queryKey: ['vault'], queryFn: skipToken }).data;

  const hasSubjects = items.some((i) => i.name);
  /** U028 — 이름이 붙은 과목만 «만든 것»이다(빈 껍데기로 보내면 2단계가 더 막힌다). */
  const subjects = items.filter((i) => i.name);
  const hasTargets = setupComplete(items);
  const hasRoutine = (routine || []).length > 0;
  // 볼트가 실제로 무엇을 갖고 있나 — 없으면(브라우저·미설정) 이 줄 자체가 안 나온다.
  const vaultSubjects = scan?.subjects.length || 0;
  const vaultNotes = scan?.subjects.reduce((t, s) => t + s.notes, 0) || 0;
  if (hasSubjects && hasTargets) return null; // 셋업 완료 → 숨김(안전망 — Today가 이미 스위칭)

  const steps: { ok: boolean; title: string; desc: string; actions: React.ReactNode }[] = [
    {
      ok: hasSubjects,
      title: '공부할 과목 추가',
      desc: vaultSubjects
        ? '볼트를 통째로 가져오면 과목과 챕터(1·2단계)가 한 번에 채워져요. 직접 입력도 됩니다.'
        : '계획 › 과목에서 직접 입력하거나 “불러오기”로 볼트(전공 폴더)를 통째로 가져오세요.',
      actions: (
        <>
          {/* ⚠ **볼트가 있으면 그쪽이 primary 다**(W1). 종전엔 지배적인 버튼이 `+ 첫 과목 추가`
              였고 임포트는 그 옆 ghost 였다 — 눈에 띄는 쪽이 막다른 길이었다. */}
          <Button sm variant={vaultSubjects ? 'primary' : 'default'} onClick={() => navigate('/items?import=1')}>
            <Icon name="folder" /> 볼트에서 불러오기
          </Button>
          <Button sm variant={vaultSubjects ? 'default' : 'primary'} onClick={() => navigate('/items')}>
            직접 추가
          </Button>
        </>
      ),
    },
    {
      ok: hasTargets,
      title: '주당 목표 시간·챕터 설정',
      desc: '과목마다 주당 몇 시간 공부할지와 챕터(순서)를 정하면 블록이 배분됩니다.',
      /* ⚠ **방금 만든 과목으로 데려간다**(U028 · 2026-08-21 ux 축). 종전엔 조건 없이 `/items`
         (갤러리)라, 1단계에서 과목을 막 만든 사람이 2단계에서 **자기 과목을 목록에서 다시
         찾아야** 했다 — 온보딩은 «막힌 지점으로 데려다준다»가 특히 중요한 자리다(D-4).
         ⚠ 과목이 여럿이면 갤러리가 맞다(어느 것을 고를지는 사람이 정한다). 하나일 때만 좁힌다. */
      actions: (
        <Button
          sm
          variant={hasSubjects ? 'primary' : 'default'}
          onClick={() => navigate(subjects.length === 1 ? `/subject/${subjects[0]!.id}` : '/items')}
        >
          {subjects.length === 1 ? `‘${subjects[0]!.name}’ 설정하기` : '학습 항목에서 설정'}
        </Button>
      ),
    },
    {
      ok: hasRoutine,
      title: '일과·가용 시간 확인',
      desc: '수면·식사·수업을 빼고 남는 빈 시간이 자동으로 공부시간이 됩니다(기본값 제공 — 필요 시 조정).',
      actions: (
        <Button sm onClick={() => navigate('/items?skeleton=1')}>
          가용시간(뼈대) 열기
        </Button>
      ),
    },
  ];
  const done = steps.filter((s) => s.ok).length;

  /* ⚠ 여기만 `ds-well` 에 **테두리를 명시로 되살린다.** 이 패널은 콜드스타트에서 화면을 통째로
     차지하는 단 하나의 표면이라 `--line-setup` 으로 자기 가장자리를 구분하는데, `ds-well` 은
     테두리가 없어 색 지정만 남으면(`border-[color:…]`) 폭이 0이라 **조용히 아무것도 안 그려진다**
     — 정의되지 않은 토큰이 회색으로 렌더되던 H20 과 같은 부류다. */
  return (
    <div className="ds-well w-full max-w-runner-narrow border border-[color:var(--line-setup)]! shadow-[var(--shadow-setup-card)]!">
      <h2>
        시작하기 <span className="ds-tiny text-mut">— 3단계만 채우면 오늘의 블록이 자동으로 잡혀요</span>
      </h2>
      {/* W3 — **볼트에 무엇이 있는지 먼저 말한다.** `scanVaultViaShell()` 은 폴더 선택도 권한도
          없는 한 번의 Rust 호출인데, 그걸 부르는 화면이 연동 탭과 임포트 패널뿐이라 콜드 화면은
          옆에 노트 604개가 있어도 빈 앱처럼 보였다. 지금은 `app/VaultSync` 가 부팅에 채운다. */}
      {vaultSubjects > 0 && !hasSubjects && (
        <div className="ds-well ds-tiny mb-2 flex flex-wrap items-center gap-x-2 gap-y-1">
          <b className="text-txt">
            볼트에 과목 {vaultSubjects}개 · 노트 {vaultNotes}개가 있어요
          </b>
          <span className="text-mut">— 아래 1단계에서 통째로 가져오면 챕터까지 함께 채워집니다.</span>
        </div>
      )}
      <div className="ds-row" style={{ alignItems: 'center', marginBottom: 6 }}>
        <Pill tone={done === 3 ? 'good' : 'warn'}>{done}/3 완료</Pill>
        <span className="h-1.5 min-w-20 flex-1 overflow-hidden rounded-full bg-panel2 shadow-[var(--shadow-inset-line-soft)]">
          <i
            style={{ width: `${Math.round((done / 3) * 100)}%` }}
            className="block h-full rounded-full bg-[image:var(--bg-setup-prog)] transition-[width] duration-draw ease-[var(--ease)]"
          />
        </span>
      </div>
      {steps.map((s, i) => (
        <div key={i} className="flex items-start gap-2.75 border-t border-line-soft px-0.5 py-2.75">
          <span
            className={`mt-px inline-flex size-5.5 flex-none items-center justify-center rounded-full [border-width:var(--setupck-border-w)] [border-style:solid] text-sm leading-text font-extrabold ${s.ok ? 'border-good bg-good text-on-acc' : 'border-line text-mut'}`}
            aria-hidden="true"
          >
            {s.ok ? '✓' : ''}
          </span>
          <div className="min-w-0 flex-1">
            <div className="mb-px text-base14 font-semibold">
              {s.ok ? <s className="text-mut [text-decoration-color:var(--setup-strike)]">{s.title}</s> : s.title}
            </div>
            <div className="ds-tiny text-mut">{s.desc}</div>
            {!s.ok && <div className="mt-2 flex flex-wrap gap-1.75">{s.actions}</div>}
          </div>
        </div>
      ))}
    </div>
  );
}

/* ============================================================
   Today — 탭: 🎯 오늘 학습 (데모 v6 단일 화면 대시보드)
   기본 화면 = TodaySignature(프레임 가득 채우는 4컬럼 대시보드, 무스크롤).
   세부(블록 액션·일일 의식·흐름 가이드)는 "＋"/"지금 시작" → 오버레이 패널로(필요할 때만).
============================================================ */
import { useCallback, useEffect, useRef, useState } from 'react';
import { useKeymapDoc } from '@/hooks/useKeymap';
import { useApp } from '@/store/useApp';
import { useFocusTrap } from '@/hooks/useFocusTrap';
import { toast } from '@/shell';
import { setRitual } from '@/lib/methodology';
import { isDone } from '@/lib/persistence';
import { useSchedule } from '@/store/selectors';
import { dayShape } from '@/lib/insights';
import { useTodayISO } from '@/hooks/useTodayISO';
import type { Ritual } from '@/lib/types';
import { TodaySignature } from './TodaySignature';
import { SetupGuide, setupComplete } from './SetupGuide';
import ReturnSlot from './ReturnSlot';
import { TodayBlocks } from './TodayBlocks';
import { BLOCK_STAGES, PRINCIPLES } from './consts';
import { Icon } from '@/components/Icon';

/** 일일 의식(아침 계획·저녁 셧다운) — 핵심 통계는 TodaySignature가 보여주고, 여기선 의식 체크만. */
function RitualCard() {
  const state = useApp((s) => s.state);
  const mutate = useApp((s) => s.mutate);

  /* ⚠ **훅이어야 한다**(H20). 이 카드는 오버레이라 자기 틱이 없어, 순수 `todayISO(state)` 로 두면
     열어 둔 채 자정을 넘겼을 때 아래 `toggle`·`saveNote` 가 **어제 날짜 키에 쓴다**. 읽기가
     하루 틀리는 것보다 나쁘다 — 사용자는 오늘을 체크했다고 믿는다. */
  const ds2 = useTodayISO(state); // '오늘' 단일 출처(_today 시드 존중 · 자정 자동 롤오버).
  const r: Ritual = state.rituals?.[ds2] || { plan: false, shutdown: false, note: '' };
  // ID-5 오늘의 모양 — 셧다운 순간의 회고 한 줄(완료·요약 있을 때만).
  const shape = dayShape(state, ds2);
  const [note, setNote] = useState(r.note || '');
  const [justSaved, setJustSaved] = useState(false); // blur 저장이 조용해서 반영 여부를 인라인으로 표시.
  // T-10 — 오늘 남은 블록 수. 0이면 물을 것이 없으므로 칸 자체가 존재하지 않는다.
  const res = useSchedule();
  const pending =
    (res.days || []).find((d) => d.ds === ds2)?.items.filter((it) => !isDone(state, ds2, it.sid, it.type)).length ?? 0;
  /* I004 — **계획을 참조하지 않는 한 줄**(2026-08-22 발상 축). 근거는 `RitualSchema.did` 주석. */
  const [did, setDid] = useState(r.did || '');
  const saveDid = () => {
    if (did === (r.did || '')) return;
    mutate((st) => setRitual(st, ds2, 'did', did.trim()));
    toast('오늘 있었던 일 기록됨', 'info');
  };
  const [stopWhy, setStopWhy] = useState(r.stopWhy || '');
  const saveStopWhy = () => {
    if (stopWhy === (r.stopWhy || '')) return;
    mutate((st) => {
      setRitual(st, ds2, 'stopWhy', stopWhy.trim());
      // 이유만 있고 규모가 없으면 나중에 비교가 안 된다 — 분모를 **같은 순간에** 함께 굳힌다.
      setRitual(st, ds2, 'stopPending', pending);
    });
    toast('중단 지점 기록됨', 'info');
  };
  const toggle = (key: 'plan' | 'shutdown', on: boolean) => {
    mutate((st) => setRitual(st, ds2, key, on));
    toast(on ? '기록됨' : '해제됨', 'info');
  };
  // '내일 한 줄'은 blur 시 저장(키 입력마다 mutate 방지).
  const saveNote = () => {
    if (note === (r.note || '')) return;
    mutate((st) => setRitual(st, ds2, 'note', note.trim()));
    setJustSaved(true);
    toast('내일 한 줄 저장됨', 'info');
  };

  return (
    <div className="ds-rule">
      <h2>
        일일 의식 <span className="ds-tiny text-mut">— 아침 계획 → 저녁 셧다운(작은 의식이 일관성을 만든다)</span>
      </h2>
      <div className="flex flex-wrap gap-2.5">
        <label className="flex! min-w-55 flex-1 cursor-pointer items-center gap-1.75 rounded-md border border-line bg-panel2 px-2.75 py-2.25 text-md! hover:border-[color:var(--line-acc-hover)]">
          <input type="checkbox" checked={r.plan} onChange={(e) => toggle('plan', e.target.checked)} />{' '}
          <Icon name="sunrise" /> <b>아침 계획</b>{' '}
          <span className="ds-tiny text-mut">블록 훑고 오늘 가장 중요한 1개 정하기</span>
        </label>
        <label className="flex! min-w-55 flex-1 cursor-pointer items-center gap-1.75 rounded-md border border-line bg-panel2 px-2.75 py-2.25 text-md! hover:border-[color:var(--line-acc-hover)]">
          <input type="checkbox" checked={r.shutdown} onChange={(e) => toggle('shutdown', e.target.checked)} />{' '}
          <Icon name="moon" /> <b>저녁 셧다운</b>{' '}
          <span className="ds-tiny text-mut">완료 체크 · 내일 한 줄 · 끝내기</span>
        </label>
      </div>
      {/* ID-5 오늘의 모양 — 하루 회고 한 줄(완료 세션·요약 있을 때만). 셧다운 전 '오늘이 어땠나'. */}
      {(shape.sessions > 0 || shape.learned) && (
        <div className="ds-foot" style={{ marginTop: 8 }}>
          <Icon name="moon" /> <b>오늘의 모양</b> — {shape.subjects}과목 · {shape.sessions}세션 · {shape.focusMin}분
          집중
          {shape.learned && (
            <>
              {' '}
              · 배운 것: <i className="text-txt">{shape.learned}</i>
            </>
          )}
        </div>
      )}
      {/* ── I004 오늘 있었던 일 ──────────────────────────────────────────────────────
          ⚠⚠ **이 칸은 계획을 안 본다.** 이 카드의 다른 칸은 전부 계획을 기준으로 묻는다
          (체크박스=계획대로 했나 · 아래 `stopWhy`=왜 못 했나 · `note`=내일 뭘 할까). 실측이
          그 전제를 반증했다 — 학습 표가 전부 0행이다. 계획 밖에서 한 것도, 계획을 통째로
          갈아엎은 것도 여기 그대로 적힌다.
          ⚠ **항상 있다**(`pending` 게이트 없음): 다 끝낸 날에도 «무슨 일이 있었나»는 있다. */}
      <div className="ds-fld" style={{ marginTop: 8 }}>
        <label htmlFor="ritual-did">
          오늘 있었던 일 <span className="ds-tiny text-mut">— 계획과 상관없이, 실제로 무슨 일이 있었나</span>
        </label>
        <input
          id="ritual-did"
          type="text"
          value={did}
          onChange={(e) => setDid(e.target.value)}
          onBlur={saveDid}
          onKeyDown={(e) => {
            if (e.key === 'Enter') (e.target as HTMLInputElement).blur();
          }}
          placeholder="예) 계획은 3장이었는데 2장 예제에 막혀서 거기만 팠다"
        />
      </div>
      <div className="ds-fld" style={{ marginTop: 8 }}>
        <label htmlFor="ritual-note">
          내일 한 줄 <span className="ds-tiny text-mut">— 셧다운의 마지막 조각, 내일의 나에게 남기는 메모</span>
          {justSaved && note.trim() === (r.note || '').trim() && (
            <span className="ds-pill ds-good ds-tiny" style={{ marginLeft: 8 }}>
              ✓ 저장됨
            </span>
          )}
        </label>
        <input
          id="ritual-note"
          type="text"
          value={note}
          onChange={(e) => {
            setNote(e.target.value);
            setJustSaved(false);
          }}
          onBlur={saveNote}
          onKeyDown={(e) => {
            if (e.key === 'Enter') (e.target as HTMLInputElement).blur();
          }}
          placeholder="예) 내일은 3장 변위전류부터 — 백지 복습 먼저"
        />
      </div>
      {/* ── T-10 중단 지점 ─────────────────────────────────────────────────────────────
          **남은 블록이 있을 때만** 존재한다. 매일 물으면 그게 새 죄책감 더미가 되고(P-9 가 같은
          함정을 만나 같은 방어를 썼다), 다 끝낸 날엔 물을 것이 없다.
          ⚠ 종전엔 이 사실을 담을 곳이 앱에 **한 군데도 없었다** — 완료를 해제하면 `setDone` 이
          기록을 통째로 지우기 때문이다. 그래서 "왜 매번 이 과목만 밀리나"의 근거가 0이었다.
          ⚠ 강제하지 않는다(필수 아님). 비워 두고 떠나도 잃는 것이 없다 — W8 인라인 메모와 같은
          판단이다: 기록은 이미 남았고 이 칸은 정밀도만 올린다. */}
      {pending > 0 && (
        <div className="ds-fld" style={{ marginTop: 8 }}>
          <label htmlFor="ritual-stop">
            오늘 못 끝낸 {pending}개 — 왜? <span className="ds-tiny text-mut">(선택 · 나중에 패턴이 된다)</span>
          </label>
          <input
            id="ritual-stop"
            type="text"
            value={stopWhy}
            onChange={(e) => setStopWhy(e.target.value)}
            onBlur={saveStopWhy}
            onKeyDown={(e) => {
              if (e.key === 'Enter') (e.target as HTMLInputElement).blur();
            }}
            placeholder="예) 회로 3장이 예상보다 두 배 걸렸다"
          />
        </div>
      )}
    </div>
  );
}

