// 'ds'는 이 파일서 날짜문자열 지역변수라 별칭 회피

const TYPE_LABEL: Record<string, string> = {
  new: '집중 학습',
  rev: '간격 복습',
  blank: '백지 복습',
  anki: 'Anki',
  mock: '모의시험',
};

/**
 * **A-11** — 오늘 계획된 과목들의 실측 배율(가중 평균). 표본이 없으면 `null`.
 *
 * ⚠ 가중치는 **오늘 계획된 분**이다: 3시간짜리 과목의 배율이 30분짜리보다 오늘 판정을 더
 * 좌우해야 한다(단순 평균이면 작은 블록이 하루의 판정을 흔든다).
 * ⚠ 배율을 모르는 과목은 **1**로 센다 — 모르는 것을 다른 값으로 채우면 지어낸 근거가 된다.
 */
function todayEstimateRatio(
  state: AppState,
  enriched: readonly { it: { sid: string; min?: number } }[],
): number | null {
  let w = 0;
  let sum = 0;
  let known = 0;
  for (const e of enriched) {
    const min = e.it.min || 0;
    if (min <= 0) continue;
    const c = subjectCalibration(state, e.it.sid);
    if (c) known += min;
    w += min;
    sum += min * (c?.ratio ?? 1);
  }
  return w > 0 && known > 0 ? sum / w : null;
}

/* ── C-7 이식(today) — Tailwind 클래스 SSOT ────────────────────────────────────────
   시그니처 히어로(과목색 --tint 베이크·포인터 스포트라이트·3D 틸트) + 통합 집중 CTA + now-중심
   발광 흐름 레일 + 하단 스트립. 색·그래디언트·발광·틸트는 tokens.css 에 이름 주고 bg-[var]·
   shadow-[var]·[transform:var] 로 참조(런타임 --tint/--mx/--my/--tiltX·Y 는 히어로 인라인 style 이
   얹는 사용 시점 해석). 상태 의존(노드 study/block/live/sel/done·CTA 변형)은 아래 map/inline 이
   정적 클래스맵으로 조립(동적 문자열 금지 · §15). ⚠ preflight 부재 → 전역 button/h2(unlayered)가
   유틸을 이기므로 다른 값만 `!`(§ global element rules). 내장 크기(text-xs/sm/base/lg)는 companion
   line-height 를 흘리므로 leading 명시(폼컨트롤/그 자손=normal · 일반 흐름=1.6 또는 원본값 · line-height 트랩).
   ds.ringSvg/Track/Arc 는 공용 스켈레톤이라 유지. `TodaySignature.module.css` 삭제. */

/** UX-1 액센트 게이트 — hot 이면 액센트, 아니면 조용한 상태 보고색.
 *  ⚠ 판정을 컴포넌트 **밖**에 두는 건 취향이 아니라 래칫이 실제로 걸린 결과다: 조건을 JSX 안에
 *    흩었더니 이 컴포넌트의 인지복잡도가 77→80 이 되어 `sonarjs/cognitive-complexity` 가 막았다.
 *    이름 붙은 술어로 밖에 내면 복잡도도 내려가고 "왜 이것만 강조인가"도 JSX 밖에서 읽힌다. */
/**
 * **A-13 확정 토글**(W7) — 오늘의 히어로를 못박거나 푼다.
 *
 * ⚠ 컴포넌트로 뺀 이유는 응집이자 래칫이다: 본체가 인지복잡도 상한에 붙어 있어(그 파일의
 * 다른 추출들과 같은 사정) 조건부 JSX 를 더 쌓으면 게이트가 막는다 — *새 분기는 새 이름을
 * 갖는다*는 이 파일의 기존 규율 그대로.
 * ⚠ 해제도 같은 버튼이다(상태를 두 곳에 두지 않는다). `onToggle(null)` 이 해제다.
 */
function FocusLockButton({
  focus,
  locked,
  onToggle,
}: {
  focus: FocusEntry | null;
  locked: boolean;
  onToggle: (key: string | null) => void;
}) {
  if (!focus) return null;
  return (
    <button
      type="button"
      className={S.why}
      aria-pressed={locked}
      onClick={() => onToggle(locked ? null : focusKey(focus))}
      title={locked ? '확정을 풀면 앱이 다시 고릅니다' : '오늘은 이걸로 확정합니다'}
    >
      <Icon name={locked ? 'pin' : 'flag'} /> {locked ? '확정됨' : '이걸로 확정'}
    </button>
  );
}

/* ── N-5 마감 국면의 두 조각 ────────────────────────────────────────────────
   본문에서 떼어 낸 것은 스타일이 아니라 **분기**다 — `TodaySignature` 는 이미 인지복잡도
   래칫(77) 바로 아래에 있어서, 조건부 JSX 를 그 안에 더 쌓으면 게이트가 막는다. 래칫이
   "더 나빠지지 않는다"만 보장한다는 뜻이 정확히 이것이다: 새 분기는 새 이름을 갖는다. */

/** '오늘의 모양'(ID-5) 한 줄 — 닫을 때가 아니거나 잴 것이 없으면 아무것도 안 그린다.
 *  ⚠ `when` 을 **인자로 받아 자기가 판정한다**: 호출부에서 `closing && …` 로 감싸면 그 분기가
 *  본문의 복잡도로 잡히고, 이 파일은 래칫 바로 아래에 있다. 계산도 여기서 해야 안 그릴 때
 *  안 돈다(호출부가 삼항으로 넘기면 그 삼항이 또 한 분기다). */
function ShapeLine({ state, ds, when }: { state: AppState; ds: string; when: boolean }) {
  if (!when) return null;
  const shape = dayShape(state, ds);
  if (shape.sessions === 0 && !shape.learned) return null;
  return (
    <div className={S.yesterday}>
      <Icon name="moon" /> 오늘의 모양 — {shape.subjects}과목 · {shape.sessions}세션 · {shape.focusMin}분
      {shape.learned && (
        <>
          {' '}
          · <b className="font-bold text-[color:var(--yesterday-b)]">{shape.learned}</b>
        </>
      )}
    </div>
  );
}

/** 포모도로 프리셋(25·50분).
 *
 *  ⚠ N-5 — 닫을 때가 되면 **사라진다**. 남은 창이 가장 짧은 블록도 못 담는 시점에 25·50분을
 *  권하는 것은 있지도 않은 시간을 제안하는 것이다. 부수 효과로 버튼 셋이 한 줄에 몰려 글자가
 *  두 줄로 접히던 것도 함께 풀린다 — 실렌더 확인이 그걸 잡았다(§15-4).
 *  ⚠ `hidden` 속성으로는 안 된다: `inline-flex` 유틸이 display 를 세워 이긴다(실측). */
function Presets({ focusMin, onPick, when }: { focusMin: number; onPick: (m: number) => void; when: boolean }) {
  if (!when) return null;
  return (
    <span className={S.presets}>
      {[25, 50]
        .filter((m) => m !== focusMin)
        .map((m) => (
          <button key={m} type="button" className={S.preset} onClick={() => onPick(m)} aria-label={`${m}분 집중 시작`}>
            {m}′
          </button>
        ))}
    </span>
  );
}

/** 하루를 닫는 길 — 의식 카드로 열고 '내일 한 줄'에 커서까지 놓는다(`Today.tsx` 가 그 포커스를 소유). */
function CloseDayCta({
  onOpenMore,
  cap,
  when = true,
}: {
  onOpenMore: (focus?: 'ritual') => void;
  cap: string;
  when?: boolean;
}) {
  if (!when) return null;
  return (
    <button type="button" className={`${S.cta} ${S.ctaGhost}`} onClick={() => onOpenMore('ritual')}>
      <span className={S.ctaGo}>
        <Icon name="moon" /> 하루 닫기
      </span>
      <span className={S.ctaCap}>{cap}</span>
    </button>
  );
}

/** 오늘의 확정 키 — **날짜가 다르면 무효**다(어제 확정이 오늘을 붙들지 않게 · A-13/W7). */
function lockedKeyFor(lock: { ds: string; key: string } | null | undefined, ds: string): string | null {
  return lock && lock.ds === ds ? lock.key : null;
}

/** 프런티어 표시명 — 제목이 없으면 파일명, 그것도 없으면 빈 문자열(그러면 호출부가 안 그린다). */
function frontierLabel(f: { title?: string; basename?: string } | null | undefined): string {
  return f?.title || f?.basename || '';
}

/** Anki due 합 — 캐시가 아예 없으면(`decks` 부재) **null 이지 0 이 아니다**. 0 으로 그리면
 *  "복습할 게 없다"가 되는데 사실은 "모른다"이고, 이 화면은 그 둘을 다르게 말한다. */
function dueOf(live: { decks?: unknown } | null | undefined): number | null {
  return live?.decks ? totalDue(live.decks as Parameters<typeof totalDue>[0]) : null;
}

/** 오늘 남은 가용 구간 — 배치된 날이면 `layoutDay` 의 잔여 `free`(학습 세션·일과 차감 + 당일
 *  오버라이드 캡 반영), 빈 날이면 순수 날짜 창 폴백.
 *  ⚠ N-1(W8) — 빈 날 폴백도 **날짜 창**이다. 요일 창은 일정·과제를 모르므로, 계획이 없는 날에만
 *  창이 과대 표시되던 비대칭이 있었다(같은 하루를 배치 유무로 다르게 말한다). */
function freeIntervalsOf(
  state: AppState,
  ds: string,
  today: Date,
  L: { free: [number, number][] } | null,
): [number, number][] {
  if (L) return L.free;
  return freeWindowsForDay(state, ds, today.getDay()).windows.map((w) => [w.s, w.e] as [number, number]);
}

/** 히어로 문장 — **큰 자리에 무엇을 쓸 것인가**.
 *  ── D-5 히어로의 주어를 행동으로 ──────────────────────────────────────
 *  72px 자리에 **과목명**이 있었다 — 내가 이미 아는 것이다. 정작 무엇을 하는지(챕터·유형)는
 *  18px 였고 "왜 이것인가"는 화면 어디에도 없었다. 큰 자리를 행동에 준다.
 *  ⚠ 챕터가 없는 블록(Anki·모의 등)이면 큰 자리는 **과목명으로 폴백**한다 — 그때는 그것이
 *    유일하게 구체적인 이름이고, 유형은 바로 아래 줄이 말한다.
 *  ⚠ 큰 자리에 챕터가 섰으면 아래 줄은 `과목 · 유형`, 아니면 유형만이다(같은 말을 두 번 하지 않는다).
 *  ⚠ 컴포넌트 밖으로 뺀 이유(2026-08-20): 여섯 값이 전부 `focus`·`allDone`·`todayTotal` 세 입력의
 *    삼항 조합이라, 이 묶음 하나가 컴포넌트 인지복잡도의 상당 부분이었다. **문자열만 낸다** —
 *    JSX 를 자르지 않으므로 렌더 트리가 원리적으로 안 변한다(§15-4). */
function heroCopy(s: { focus: FocusEntry | null; current: unknown; allDone: boolean; todayTotal: number }): {
  kicker: string;
  focusMin: number;
  heroMain: string;
  heroSub: string;
  dispColor: string | undefined;
} {
  const { focus, allDone, todayTotal } = s;
  const focusType = focus ? TYPE_LABEL[focus.it.type] || '학습' : '';
  const chapter = focus?.it.chapters?.length ? focus.it.chapters.join(', ') : '';
  return {
    kicker: todayTotal === 0 ? '오늘 할 일' : allDone ? '오늘 학습' : s.current ? '지금 할 일' : '다음 할 일',
    focusMin: focusMinutes(focus),
    heroMain: allDone ? '완료' : focus ? chapter || focus.it.name : todayTotal === 0 ? '비어 있음' : '—',
    heroSub: focus ? (chapter ? `${focus.it.name} · ${focusType}` : focusType) : '—',
    dispColor: !allDone && focus ? focus.it.color : undefined,
  };
}

/** 포모도로 표시값 — 남은 초·진행%·MM:SS. 세션이 없으면 0/0/`00:00`(값 부재를 0 으로 그리는
 *  것이 여기서는 옳다 — 타이머는 "안 돌고 있음"이 곧 0이다). */
function timerView(
  timer: { endsAt: number; total?: number } | null,
  nowMs: number,
): { timerLeft: number; timerPct: number; timerLabel: string } {
  const timerLeft = timer ? Math.max(0, Math.round((timer.endsAt - nowMs) / 1000)) : 0;
  return {
    timerLeft,
    timerPct: timer && timer.total ? Math.min(100, ((timer.total - timerLeft) / timer.total) * 100) : 0,
    timerLabel: mmss(timerLeft),
  };
}

/** 히어로 부제 — **오늘이 어떤 날인가**로 세 갈래다: 배치 0 / 다 함 / 진행 중.
 *
 *  ⚠ 컴포넌트로 뺀 이유(2026-08-20): 여기가 3중 중첩 삼항이었고 각 가지가 또 자기 분기를 품어,
 *  이 한 블록이 `TodaySignature` 인지복잡도의 큰 몫이었다. **`<div className={S.heroSub}>` 은
 *  호출부에 남겨** 이 컴포넌트가 그 안의 내용만 그대로 낸다 — 래퍼가 하나도 안 늘어난다(§15-4).
 *
 *  ── W19 완료 날은 **단일 포커스**다(2026-07-31) ──────────────────────────
 *  종전엔 클릭 가능한 '다음 걸음'이 최대 11개였고 그중 5개가 **다른 탭으로 흩어졌다**
 *  (프런티어→숙달도 · 복습 위험→리뷰 · 보충→기록 …). 다 한 사람에게 갈 곳 다섯을 늘어놓는 것은
 *  동력이 아니라 목록이다. → **내일 한 줄 + 지금 가장 값나가는 것 하나**. 나머지는 사라진 게
 *  아니라 레일 아래 '오늘 밖' 구역(W18)이 이미 같은 신호를 같은 자리에서 말한다.
 *  ⚠ **momentum 을 셧다운 뒤로 옮기지 않았다** — 셧다운을 안 누르는 사용자에게 영원히 안 보이게
 *  되고, 그건 `dayPhase.ts` 가 경고한 함정을 반대 방향으로 밟는 것이다(자리를 옮기는 게 아니라
 *  **수를 줄이는** 것이 이 안이다). */
const NEXT_TO: Record<string, string> = { review: '/review-run', backlog: '/day', frontier: '/mastery' };

function HeroSubline(p: {
  todayTotal: number;
  hasItems: boolean;
  allDone: boolean;
  tmrNew: { name: string } | undefined;
  nextStep: NextStep | null;
  go: (to: string) => void;
  heroSub: string;
  focus: FocusEntry | null;
  focusReason: string;
  locked: boolean;
  ds: string;
  setFocusLock: (v: { ds: string; key: string } | null) => void;
}): React.JSX.Element {
  if (p.todayTotal === 0)
    return p.hasItems ? (
      // §7: 히어로 중복 CTA(.mChip) 제거 — 안내 텍스트만. '오늘 계획 짜기'는 아래 큰 버튼 단일.
      <span>오늘은 배치된 블록이 없어요</span>
    ) : (
      <>학습 항목을 추가하면 오늘의 흐름이 그려져요.</>
    );
  if (p.allDone)
    return (
      <span className={S.momentum}>
        {p.tmrNew ? (
          <span className={S.chapter}>내일 · {p.tmrNew.name}</span>
        ) : (
          <span>내일 일정은 아직 비어 있어요</span>
        )}
        {p.nextStep && (
          <button
            type="button"
            className={S.mChip}
            onClick={() => p.go(NEXT_TO[p.nextStep!.kind]!)}
            aria-label={p.nextStep.aria}
          >
            {p.nextStep.label}
          </button>
        )}
      </span>
    );
  return (
    <>
      <span className={S.chapter}>{p.heroSub}</span>
      {/* D-5 — "왜 이것인가". 고르는 함수가 이유까지 돌려주므로 화면과 규칙이 갈릴 수 없다. */}
      {p.focusReason && <span className={S.why}>{p.focusReason}</span>}
      {/* A-13 — 확정 토글. ⚠ **앱이 자동으로 잠그지 않는다**: 그러면 또 하나의 알고리즘이 되고,
          이 항목이 고치려는 것은 *알고리즘이 자꾸 말을 바꾸는 것*이다.
          ⚠ 해제는 같은 버튼이다(상태를 두 곳에 두지 않는다). */}
      <FocusLockButton
        focus={p.focus}
        locked={p.locked}
        onToggle={(k) => p.setFocusLock(k ? { ds: p.ds, key: k } : null)}
      />
    </>
  );
}

export function TodaySignature({ onOpenMore }: { onOpenMore: (focus?: 'ritual') => void }) {
  const state = useApp((s) => s.state);
  const ankiLive = useRuntime((s) => s.cache._ankiLive);
  const res = useSchedule();
  const toggleDone = useApp((s) => s.toggleDone);
  const navigate = useNavigate();
  const go = (to: string) => navigate(to, { viewTransition: true });
  const setSchedView = useUI((st) => st.setSchedView);
  // "오늘 계획 짜기" — 목적지를 **결정론적으로** 고정한다. 예전엔 `/plan-host`로만 보내 캘린더의
  // 영속 뷰(schedView·기본 week)에 그대로 떨어졌다 → '오늘'을 요청했는데 주 격자(혹은 지난번 아무 뷰)가
  // 열려 첫 화면이 매번 달랐다(재설계 사상 "0.5초에 요지" 위반).
  // 탭 경계를 넘는 드릴다운 규약(v4)을 그대로 따른다: 날짜는 딥링크(?ds=), **뷰 전환은 보내는 쪽에서 먼저**
  // — 받는 쪽 effect에서 setState로 되받으면 캐스케이드 렌더가 된다(린트가 막는 패턴 · Alloc.onOpenDay와 동형).
  // 일반 진입(나브 '계획'·⌘K·g p)은 여전히 영속 뷰를 존중한다(v4 "기본 착지=캘린더 주 뷰") — 결정론은
  // 의도가 '오늘'로 명시된 이 경로에만 건다.
  const goPlanToday = () => {
    setSchedView('day');
    go(`/schedule?ds=${todayISO(state)}`); // '오늘'은 앱 단일 출처(_today 시드 존중) — new Date() 금지
  };

  // 히어로 포인터 추적 — 스포트라이트(--mx/--my) + 3D 틸트(--tiltX/Y). 정본 훅(interactions) 공유.
  const { ref: heroRef, onMouseMove: onHeroMove, onMouseLeave: onHeroLeave } = useHeroPointer(7);

  // 집중 타이머(포모도로) — 전역 세션(useFocus): 탭 이동·새로고침에도 이어짐. 종료 감지는 FocusChip.
  const timer = useFocus((st) => st.session);
  const startSession = useFocus((st) => st.start);
  const stopSession = useFocus((st) => st.stop);

  // 적응형 틱 — 초 단위 표시는 포모도로(mmss)뿐이므로 세션 중에만 1초, 평시엔 30초(FocusChip과 동일 패턴).
  // 무조건 1초는 방치된 대시보드를 초당 리렌더하는 60배 과잉이었다. 백그라운드 정지·복귀 캐치업은 훅이 소유.
  useAdaptiveTick(timer ? 1000 : 30_000);

  const ds = todayISO(state);
  const today = parseISO(ds);
  // 날짜→Day 인덱스 1회 생성(선형 find 제거) — Schedule과 동일 패턴, O(1) 조회.
  const byDs = indexDays(res);

  const todayDay = byDs[ds];
  const items = todayDay?.items || [];
  const L = items.length ? layoutDay(state, todayDay!) : null;

  const nowDate = new Date();
  const nowMin = nowDate.getHours() * 60 + nowDate.getMinutes();
  const nowMs = nowDate.getTime();
  /* ⚠ '지금 할 일'의 답은 **`selectTodayFocus` 하나**에서 온다(H4 · 2026-07-26 감사).
     D-5 가 "초점은 한 함수가 고른다"로 통일했는데 **호출부 하나가 남아** 절반만 통일됐었다:
     `useFocus.startOnCurrent` 가 `stat`·`today` 를 안 넘겨(기본값 `[]`·`''`) 급함 계산이 죽었고,
     그래서 히어로는 "마감 임박 블록", ⌘K·FocusChip 의 집중 시작은 "가장 큰 블록"을 가리켰다.
     재료 조립을 셀렉터에 두면 **인자 선택권이 호출부에서 사라져** 같은 일이 재발할 수 없다. */
  /* A-13(W7) — **오늘의 확정**. 히어로 입력이 전부 시간 의존이라 하루에 여러 번 바뀌었고,
     그건 *"결정이 끝나 있다"* 는 이 화면의 약속과 정반대다. 판정은 `lib/focusState` 가 하고
     여기는 저장된 키만 넘긴다(날짜가 다르면 무효 — 어제 확정이 오늘을 붙들지 않게). */
  const focusLock = useUI((st) => st.ui.focusLock);
  const setFocusLock = useUI((st) => st.setFocusLock);
  const lockedKey = lockedKeyFor(focusLock, ds);
  const { entries: enriched, current, focus, reason: focusReason, locked } = selectTodayFocus(state, nowMin, lockedKey);
  const todayDone = enriched.filter((e) => e.done).length;
  const todayTotal = items.length;

  const pending = enriched.filter((e) => !e.done);
  const allDone = todayTotal > 0 && pending.length === 0;

  /* ⚠ **히어로의 `다음 ·` 줄이 여기서 사라졌다**(P-6 · 2026-08-01). 히어로의 선택 기준이 시각에서
     급함으로 바뀌었으므로(`focusState.ts`) 히어로 안에서 "다음"을 시각 순으로 말하면 **한 위젯이
     두 개의 다른 정렬을 동시에 주장한다.** 시각 순서는 흐름 레일(`FlowRail`)이 온전히 갖는다 —
     원칙 ③(시그니처는 페이지마다 하나)과 같은 논증이고, 여기선 정렬 축이 그 대상이다. */

  /* E8 — 주(週) 누적 시간 계산이 여기서 사라졌다(스트립의 `이번 주 N h` 와 함께). 그건 오늘의
     판단이 아니라 주의 조망이고, `/schedule` 이 그 질문을 통째로 소유하는 화면이다. 매일 7일을
     순회하던 비용과 `useCountUp` 훅 하나도 같이 없어진다. */

  const due = dueOf(ankiLive);
  const ankiFresh = ankiFreshness(ankiLive, ds); // 이 숫자가 오늘 것인가(캐시라 어제 것일 수 있다)
  const openBl = openBacklog(state).length;
  // 셋업은 됐지만(과목 있음) 오늘 배치가 0인 경우를 콜드스타트와 구분 — 빈 메시지가 이미 설정한 사용자에게
  // 또 "설정하라"고 말하지 않도록. 마감 지남·가용시간 없음 등이면 스케줄로 안내.
  const hasItems = state.items.some((it) => it.name);

  // A1 — 어제 셧다운에서 남긴 '내일 한 줄'을 오늘 아침 다시 보여줌(셧다운→모닝 루프 닫기).
  const prevNote = (state.rituals?.[iso(addDays(today, -1))]?.note || '').trim();
  // ID-4 — On This Day: 달력상 같은 날(−4주·−1년)의 과거 실기록 한 줄(있을 때만·이력 30일+ 게이트).
  const onThis = onThisDay(state, ds)[0];
  // A3 — 오늘 '일과 블록·이미 배치된 학습 뺀' 남은 가용시간(now 이후) — 워터마크를 정보성으로.
  // 배치된 날이면 layoutDay의 잔여 free(학습 세션·일과 차감 + 당일 오버라이드 캡 반영)를 쓰고,
  // 빈 날(L 없음)이면 순수 루틴 창으로 폴백. now 이후로 클램프해 빡빡한 날 과대표시를 막는다.
  const freeLeftMin = freeMinAfter(freeIntervalsOf(state, ds, today, L), nowMin);
  // A2 — 회상 카드(내 과거 요약을 인출 연습으로). 후보 없으면 null.
  const recall = pickRetrieval(state, ds);
  /* ⚠ `recallN`('회상 N개 대기')이 여기 있었다 — **W19 에서 완료 화면의 다음 걸음을 하나로
     좁히며 사라졌다.** 회상 카드 자체는 레일 아래에 그대로 있고, 그 옆의 대기 수는 카드가
     이미 존재한다는 사실을 한 번 더 말할 뿐이었다(한 양 = 한 자리). */
  // 회상 카드가 바뀌면(새 날짜·다른 요약) 정답 공개를 초기화 — 다음 카드가 답이 열린 채 뜨는 인출연습 무력화 방지.
  // effect 대신 렌더 중 조건부 setState(React 권장 · 이 코드베이스의 draftFor 관용과 동일).
  /* 카드 정체성 — **`RetrievalSlot` 의 `key`** 다. 종전엔 이 값으로 부모가 직접 공개 여부를
     되돌렸는데(파생 상태 방어 2종 + 렌더 중 setState), 리마운트가 그걸 구조로 대체했다. */
  const recallKey = recall ? `${ds}|${recall.summary.name || ''}` : '';
  // A4 — 완료 후 다음 동력: 내일 첫 학습 + 복습 위험(개념 간격반복).
  const tmrNew = byDs[iso(addDays(today, 1))]?.items.find((it) => it.type === 'new');
  /* ⚠ 메모된 셀렉터를 쓴다(S6 · 2026-07-31 `/감사 근본`) — `selectRiskSummary` 가 정확히 이 호출을
     위해 존재한다(`store/selectors.ts` 주석: _"사이드바가 유일한 무조건 호출부였다"_ 의 재발).
     이 컴포넌트는 집중 세션 중 `useAdaptiveTick(1000)` 으로 **초당 리렌더**하므로 전수 스캔이
     초당 한 번 돌고 있었다. 캐시 키가 `reviewTouches`·볼트 앵커 버전까지 포함하므로 값도 더 정확하다. */
  const risk = selectRiskSummary(state);
  const riskN = risk.overdue + risk.due;
  // I-8 — 프런티어 다음 추천(지식엔진 frontier). 백엔드 사용 가능 시에만 페치(mastery와 KNOWLEDGE_KEY 캐시 공유,
  // 신규 IO 최소). 후보 없거나 미연결이면 frontier=null → 렌더 안 함.
  const ping = usePing();
  const know = useKnowledge(ping.isSuccess).data;
  const frontier = frontierNext(know);
  const frontierTitle = frontierLabel(frontier);
  // I-10 — 착각 재확인 카드: conf('확신했지만 틀림') 선 과거 오답 1건(날짜 해시로 하루 회전). 후보 없으면 null.
  const confWrong = pickConfidentWrong(state, ds);
  const confWrongN = confWrong ? confidentWrongCount(state, ds) : 0;

  // 마감 임박(스트립) + 가장 가까운 마감(상단 리드아웃). 파생 로직은 lib/scheduleView.deadlineDdays로 위임.
  const ddays = deadlineDdays(res.itemStat, ds);
  const soon = ddays.filter((st) => st.dday <= 14).slice(0, 3); // 14=D-day 임박 임계 · 3=스트립 최대 표시
  const nearestDday = ddays[0]?.dday ?? null;

  // 오늘의 흐름 노드 — 학습(체크 가능)+일과 블록을 시간순 단일 리스트로(무지개 가로 트랙 폐기).
  const tl = L?.tl || [];
  type EnrichedItem = (typeof enriched)[number];
  /* ── E9 "오늘 밖"을 오늘 것처럼 그리지 않는다 + W6 그 판정을 **문장으로** ────────────
     판정은 `lib/dayCapacity` 하나가 소유한다(옮긴 이유·규칙·비대칭은 그 파일 머리주석).
     여기선 블록을 그 함수가 아는 형태로만 바꿔 넘긴다. */
  const cap = dayCapacity(
    enriched.map((e) => ({
      key: 'study|' + completionKey(e.it.sid, e.it.type),
      start: e.start,
      min: e.it.min || 0,
      done: e.done,
      name: e.it.name,
      color: e.it.color,
    })),
    freeLeftMin,
    /* 7-I4 — 오늘 배정된 미완 할 일 중 **소요를 적은 것**을 창에서 먼저 뺀다.
       ⚠⚠ **N-1(W8)이 이 인자의 뜻을 좁혔다**: 이제 시각이 박힌 과제는 `freeWindowsForDay` 가
       구간으로 이미 빼므로(= `L.free` 안에 반영돼 있다) 여기서는 **시각 없는 것만** 넘긴다.
       종전 값(`choreMinForDay`)을 그대로 두면 타임박스한 과제가 두 번 깎인다. */
    untimedChoreMin(state, ds),
    /* A-11(W7) — **실측 배율을 아침 문장에 먹인다.** 배율은 지금까지 과목 상세에만 있었고
       (`/items` → 카드 → 상세 = 3화면·2클릭) 오늘 화면과 연결이 0이었다 — 앱이 "내 추정이 20%
       낙관적이다"를 알면서 아침에 한 번도 말하지 않았다.
       ⚠ **오늘 계획된 과목들의 가중 평균**이다: 오늘 실제로 걸린 것을 말하려면 오늘 하는
         과목의 배율이어야 하고, 전 과목 평균은 안 하는 과목의 오차까지 오늘에 얹는다.
       ⚠ 표본이 얇은 과목은 `subjectCalibration` 이 `null` 을 준다 → 그 과목은 배율 1로 센다
         (모르는 것을 1이 아닌 값으로 채우면 그게 곧 지어낸 근거다). */
    todayEstimateRatio(state, enriched),
  );
  const { beyondKeys } = cap;
  /* 분모는 **오늘 가능한 것**이다(E9). 종전엔 `todayTotal` 이라, 남은 창에 안 들어가는
     블록까지 목표에 넣고 매일 그 목표에 못 미쳤다 — 게이지가 매일 지는 게임을 그린 셈이다.
     ⚠ P-7 이 레일 필터는 없앴지만 이 분모는 **그대로 둔다**: 저건 "안 보여준다"였고 이건
     "오늘 목표가 무엇인가"라, 같은 `beyondKeys` 를 쓰지만 다른 질문이다. */
  const todayPossible = Math.max(todayDone, todayTotal - beyondKeys.size);
  /* E15 — 완료 수가 바뀌면 그 숫자가 스스로 번쩍인다(`commit` 어휘). 마운트엔 안 번쩍인다. */
  const doneRef = useCommitOnChange(todayDone);
  /* ⚠ `pct`(링 호 길이)가 여기 있었다 — P-7 에서 링과 함께 사라졌다. 진행률을 다시 그리고
     싶어지면 먼저 "왜 `DayBar` 로 부족한가"를 적을 것(시그니처는 페이지마다 하나 · 원칙 ③). */

  /* ⚠⚠ **레일에서 '오늘 밖' 블록을 지우던 필터가 P-7 에서 사라졌다(2026-08-01).**
     종전엔 `dayCapacity` 가 접은 블록을 여기서 **조용히 제외**했고, 화면에 남는 흔적은 14px
     한 줄(`fitLine`)뿐이었다 — 무엇이 잘렸는지 보려면 `/schedule` 로 1클릭·2화면이었다.
     그리고 기준이 "시각이 늦은 것"이라 **마감 D-1 과목이 오후 배치면 그게 잘렸다.**
     이제 `DayBar` 가 그 컷을 **창 밖으로 삐져나온 칸**으로 명시적으로 그리므로, 레일에서까지
     지울 이유가 없다(지우면 막대가 가리키는 것을 레일에서 못 찾는다). */
  const flowNodes: FlowNode<EnrichedItem>[] = [
    ...enriched
      .filter((e) => e.start != null)
      .map((e): FlowNode<EnrichedItem> => ({
        key: 'study|' + completionKey(e.it.sid, e.it.type),
        kind: 'study',
        start: e.start as number,
        end: e.end,
        name: e.it.name,
        sub: e.it.chapters?.length ? e.it.chapters.join(', ') : TYPE_LABEL[e.it.type] || '학습',
        color: e.it.color,
        done: e.done,
        e,
      })),
    ...tl
      .filter((t) => t.kind === 'block' && t.start != null)
      .map((t, i): FlowNode<EnrichedItem> => ({
        key: 'block|' + i + '|' + String(t.start),
        kind: 'block',
        start: t.start as number,
        end: (t.end ?? null) as number | null,
        name: t.name || '블록',
        sub: t.btype && t.btype !== t.name ? t.btype : '일과',
        color: t.color,
        done: false,
        e: null,
      })),
  ].sort((a, b) => a.start - b.start);

  // I-4 — 흐름 레일의 선택·키보드(j/k/Enter/s)·DOM refs 는 `FlowRail` 이 소유한다(재설계 · 책임 이전).
  // 여기선 노드가 요구하는 세 동작을 **불투명 콜백**으로만 준다(FlowRail 은 enriched 형태·store 를 모른다).
  const startNodeFocus = (e: EnrichedItem): void => {
    startSession({ ds, sid: e.it.sid, type: e.it.type, name: e.it.name, min: focusMinutes(e), blockMin: e.it.min });
  };
  const prefillNode = (e: EnrichedItem): void => {
    usePrefill.getState().request('sum', e.it.sid, ds);
    toast(`${e.it.name} — 기록 프리필됨`, 'info');
  };

  /* ── N-5 하루의 국면 ────────────────────────────────────────────────
     판정은 순수 함수가 `layoutDay` 산출물에서만 뽑는다(임의 시각 상수 없음 — 근거는
     `lib/dayPhase.ts` 머리주석). 여기서 시각으로 다시 나누기 시작하면 밤샘하는 날에
     화면이 틀린 질문을 크게 던진다. */
  const phase = dayPhase({
    todayTotal,
    pending: pending.length,
    freeLeftMin,
    // 남은 것 중 가장 짧은 블록 — "자리에 들어가는가"의 기준(dayPhase 머리주석).
    shortestPendingMin: pending.reduce((m, e) => Math.min(m, e.it.min || 0), Number.POSITIVE_INFINITY),
    underway: !!current,
  });
  const closing = phase === 'closing';
  /* ── P-15 국면이 서로의 객체를 지운다(2026-08-01) ─────────────────────────────
     종전엔 국면 의존 렌더가 **셋뿐**이었다(`Presets` !closing · `ShapeLine` closing ·
     `CloseDayCta` closing) — 즉 *낮 화면이 기본이고 마감에서 둘이 붙었다 떨어질 뿐*이었고,
     히어로에 동시 존재 가능한 표면이 18~19개였다.

     배분 규칙은 취향이 아니라 **그 표면이 답하는 질문이 이 국면의 질문인가** 하나다:
       · opening("오늘 무엇부터") — 하루를 *여는* 회고(어제 한 줄 · On This Day)가 여기 산다.
         두 번째 블록(`upNext`)과 길이 대안(`Presets`)은 아직 첫 번째도 안 열었으므로 없다.
       · run("지금 이것")         — 실행 도구가 산다. 여는 회고는 실행 중엔 소음이라 빠진다.
       · closing("오늘 어땠나")   — 오늘의 모양·하루 닫기. 오늘 안 할 것(`upNext`)은 없다.

     ⚠ **인출 카드는 어느 국면에서도 안 지운다.** `todaySlots.ts` 가 그 값어치를 명시적으로
     방어해 뒀다(_"슬롯을 없애면 이 앱이 만드는 학습 증거가 함께 준다"_) — 아침에 안 그리면
     그날 우발적 인출 한 장이 통째로 사라지고, 그건 국면 분리가 사려던 것보다 비싸다. */
  /** 하루를 *여는* 회고 — 여는 국면에만. 실행 중·닫는 중엔 같은 문장이 소음이다.
   *  ⚠⚠ **빈 날을 함께 넣는다.** `dayPhase` 는 `todayTotal <= 0` 을 'run' 으로 답하는데
   *  (_"빈 날은 닫을 하루가 없다"_), 그건 *닫기* 관점의 답이지 여는 관점의 답이 아니다 —
   *  배치가 0인 날의 질문은 정확히 "오늘 무엇을 할까"이고 그게 여는 국면의 질문이다.
   *  이 한 줄이 없으면 **아무것도 계획되지 않은 날에 어제 한 줄·회고가 통째로 사라진다**
   *  (실렌더 확인이 잡았다 — `today · onthisday` 스냅샷이 빈 히어로로 떨어졌다).
   *  ⚠ `dayPhase` 자체를 고치지 않는 이유: 'opening' 을 빈 날까지 넓히면 `Presets`·`upNext`
   *  같은 *실행* 분기까지 그 판정을 따라가는데, 빈 날엔 실행할 대상이 애초에 없어 무의미하고
   *  그 함수의 계약(_"빈 날은 닫을 하루가 없다"_)만 흐려진다. 판정은 그대로 두고 **이 화면이
   *  자기 문장에 대해** 범위를 정한다. */
  const showOpeningRecall = phase === 'opening' || todayTotal === 0;

  const { kicker, focusMin, heroMain, heroSub, dispColor } = heroCopy({
    focus,
    current,
    allDone,
    todayTotal,
  });

  /* E8 — 일일 의식 토글이 스트립에서 빠졌다. 같은 토글이 앱 안에 셋이었고(여기 · 온디맨드
     `RitualCard` · `하루 닫기` CTA), 닫는 길은 CTA 가 이미 커서까지 놓아 준다. 상태 읽기도
     그 카드가 소유한다. */

  // 집중 타이머(포모도로) — 남은 초·진행%·MM:SS(1초 틱으로 갱신). 종료 알림·완료 연결은 FocusChip이.
  const { timerPct, timerLabel } = timerView(timer, nowMs);
  // 포모도로 프리셋 — 기본은 블록 파생(focusMinutes), 25/50은 명시 선택.
  const startTimer = (min?: number) => {
    if (!focus) return;
    startSession({
      ds,
      sid: focus.it.sid,
      type: focus.it.type,
      name: focus.it.name,
      min: min ?? focusMinutes(focus),
      blockMin: focus.it.min,
    });
  };
  // 조기중단 confirm — 진행 중 세션이 실수 클릭으로 날아가는 것 방지(휴식은 즉시 중단).
  const stopTimer = async () => {
    if (timer?.kind === 'break') return stopSession();
    if (
      await confirmIrreversible('집중 세션을 중단할까요? 진행 시간은 기록되지 않아요.', {
        title: '집중 중단',
        okLabel: '중단',
      })
    )
      stopSession();
  };

  // 전부 완료 순간 셀레브레이션(한 번만).
  const wasDone = useRef(false);
  const [celebrate, setCelebrate] = useState(false);
  useEffect(() => {
    if (allDone && !wasDone.current) {
      wasDone.current = true;
      setCelebrate(true);
      toast('오늘 블록 완료!', 'info');
      const id = setTimeout(() => setCelebrate(false), 1400);
      return () => clearTimeout(id);
    }
    if (!allDone) wasDone.current = false;
  }, [allDone]);

  /* ⚠⚠ **여기 PL-9 스트릭 마일스톤 축하가 있었다 — 은퇴했다**(I054 · 2026-08-22 발상 축).
     I046 이 통계 탭의 게이미피케이션 셋을 지운 짝이다. 근거는 같다: 그 수의 입력(`completions`)이
     실물에서 **0행**이라 이 축하는 원리적으로 뜬 적이 없고, 뜬다면 그건 «0을 크게 그리는 것»의
     가장 강한 형태다(축하는 조망이 아니다).
     ⚠ 영속 마커 `_lastStreakCele` 도 함께 지웠다 — 축하가 없으면 «마지막으로 축하한 임계»가
     가리킬 것이 없다. 옛 저장본에 남아 있어도 zod 가 모르는 키를 버린다(무마이그레이션). */

  // 진행률·연속·마감 + 주 액션을 상단 바로 끌어올림(데모 v6 헤더).
  /* ── E23 하루 신호 기록 ────────────────────────────────────────────────
     '정적(quiet)의 설계'가 기다린 미지수는 **all-clear 빈도** 하나였다. 그 값은 그날그날의
     상태에서만 알 수 있고 지나가면 재구성이 불가능하다(항목이 지워지거나 마감이 바뀌면 과거가
     소급해 달라진다) → 관측된 시점에 남긴다.
     ⚠ deps 가 다섯 숫자다 — 값이 **바뀔 때만** 쓴다. 매 렌더에 쓰면 관측이 관측 대상보다
       비싸지고, 하루 한 번만 쓰면 "하루가 어떻게 끝났나"를 놓친다(그 둘 사이가 정확한 자리).
     ⚠ Anki 미연결은 `-1` 이다 — 0(없음)과 구분한다. `isQuiet` 이 그 차이를 쓴다. */
  useEffect(() => {
    void recordDaySignal(
      { pending: pending.length, overdue: riskN, backlog: openBl, ankiDue: due ?? -1, dueSoon: soon.length },
      ds,
    );
    void pruneDaySignals(ds);
  }, [pending.length, riskN, openBl, due, soon.length, ds]);

  /* ⚠ 크롬 설정을 **모듈 함수로 뺐다**(W7 · 2026-08-07). A-10·A-13 이 붙으며 이 컴포넌트가
     인지복잡도 래칫(62)을 넘었고, 이 블록은 그 복잡도의 큰 몫이다(중첩 삼항 넷 + 조건부 스프레드).
     응집도 맞다 — "상단 44px 과 리드아웃에 무엇을 세우나" 하나에만 답한다. */
  /* ⚠⚠ **`cap.slackMin` 이 deps 에 없으면 44px 앵커가 시간을 안 본다**(2026-08-20 리뷰 M-2).
     `chromeFor` 의 `primary`(= 이 화면 최상위 앵커)는 **오직 `cap.slackMin` 만** 읽는데, `cap` 은
     `freeMinAfter(freeIntervals, nowMin)` 파생이고 `useAdaptiveTick(30_000)` 이 30초마다 리렌더를
     강제한다. 즉 **여유는 30초마다 줄어드는데 이펙트는 안 돌아**, 상단 바가 나머지 deps 중 하나가
     마지막으로 바뀐 시점(대개 마운트)의 값을 하루 종일 붙들고 있었다. *"다음 행동을 가장 많이
     바꾸는 한 수"* 라는 이 자리의 정의가 시간에 반응하지 않으면 그 값이 없는 것이다.
     ⚠ 참조가 아니라 **스칼라**로 넣는다 — `cap` 은 매 렌더 새 객체라 참조를 넣으면 이펙트가
     30초마다 무조건 돌고, 그건 이 목록이 존재하는 이유를 없앤다.
     ⚠ 이 훅은 계약상 `exhaustive-deps` 를 끈다(`store/usePageChrome` 참조) — 즉 이 손 목록이
     유일한 방어선이다. 여기에 값을 추가할 때는 `chromeFor` 가 **실제로 읽는 것**을 세어라. */
  usePageChromeEffect(
    () => chromeFor({ cap, todayDone, todayTotal, allDone, hasItems, res, nearestDday, goPlanToday, go }),
    [cap.slackMin, todayDone, nearestDday, todayTotal, allDone, hasItems, res.adaptApplied, res.adapt],
  );

  // W20 — 오늘 띄울 인출 카드 **하나**(회전 규칙·근거는 `lib/todaySlots` 머리주석).
  const retrievalSlot = pickRetrievalSlot(!!confWrong, !!recall, parseISO(ds).getDate());

  /* ── W19 빈 날은 **1컬럼**이다(2026-07-31) ─────────────────────────────────────
     빈 날의 우측 컬럼은 링 `0/0` + LIVE 시계 + 종결 캡 + `＋` 로 **내용 0의 골격만** 유지했다.
     그리고 같은 문장이 두 자리(히어로 · 레일 빈 상태)에 **글자까지 같게** 있었고, 같은 핸들러
     `goPlanToday` 가 세 자리에 있었다.
     ⚠⚠ **판정은 `flowNodes.length === 0` 이다 — `todayTotal === 0` 이 아니다.** 후자로 잡으면
     학습 블록이 없을 뿐 **일과 블록이 있는 날**까지 컬럼을 지워, 그 날의 시간표가 통째로
     사라진다(로드맵이 이 안의 미실행 사유로 적어 둔 함정 그대로). */
  const emptyDay = flowNodes.length === 0;

  // W19 — 완료 날의 **다음 걸음 하나**(우선순위·근거는 `lib/todaySlots` 머리주석).
  const nextStep = pickNextStep(riskN, openBl, frontierTitle);
  /* ── A-10(W7) — **적재량이 아니라 오늘 몫** ────────────────────────────────────────
     이 화면은 `freeLeftMin` 을 이미 알면서도 세 신호를 **적재량**으로 말했다(`복습 12개 밀림`).
     그 12는 어떤 행동으로도 오늘 안에 0이 될 수 없어 **마비를 만든다** — 알림(A-1)이 정확히
     같은 이유로 수를 버렸는데 화면만 남아 있었다(두 표면이 같은 사실을 다르게 말한 것).
     ⚠ 판정은 순수 lib 이 한다(`lib/todayShare`) — "12가 3이 된다"는 규칙 자체가 유닛으로
       잠겨야 하고, 화면은 문장을 놓기만 한다. */
  const share = todayShare({
    overdue: riskN,
    backlog: openBl,
    freeLeftMin,
    reviewMin: reviewBlockMin(state.moduleLen || 120),
  });
  const shareText = shareLine(share);

  const toggle = (e: (typeof enriched)[number]) => toggleDone(ds, e.it.sid, e.it.type, e.it.min, !e.done);

  /* ── E8 하단 스트립 = **오늘의 판단**만 ─────────────────────────────────
     각 그룹은 *말할 것이 있을 때만* 존재한다(레일 신호와 같은 규칙 — `selectors.ts` 의 그 계약).
     전부 비면 스트립 줄 자체가 없고 히어로가 그 높이를 먹는다: 정적(quiet)이 문구가 아니라
     **레이아웃으로** 표현된다.
     ⚠ Anki 는 `due > 0` 일 때만 — `due == null`(이 기기에서 연결한 적 없음)까지 그리면 Anki 를
       안 쓰는 날마다 "연결 필요"를 외치게 되고, 그건 N-13 이 금지한 바로 그 형태다. 연결 상태의
       소유자는 연동 탭이다. */
  /* ⚠ **스트립 조립을 함수로 뺐다**(W7 · 2026-08-07). A-10·A-13 이 붙으며 이 컴포넌트의 인지
     복잡도가 래칫(62)을 넘었고, 래칫이 막으려는 것이 정확히 이것이다 — 한 함수가 화면 전체의
     분기를 다 쥐는 것. 뺀 기준은 *응집*이다: 이 덩어리는 "오늘 밖에 무엇이 있나"라는 한 질문에만
     답한다(히어로·타이머·흐름과 상태를 공유하지 않는다).
     ⚠ 컴포넌트가 아니라 **함수**인 것도 의도다 — 렌더 상태가 없고 인자만으로 결정된다. */
  /* I010 — 학사 눈금이 오늘에 닿는다. 창은 **7일**이다: 졸업탭 국면판은 21일을 보지만 그건
     «학기가 어디쯤인가»의 축이고, 여기는 «오늘 무엇이 다른가»라 3주 뒤 정정 마감이 오늘 줄에
     서면 그것은 신호가 아니라 배경이 된다. */
  const marks = upcomingMarks(state, ds, 7);
  const beyondNode = buildBeyondStrip({ soon, marks, due, ankiFresh, openBl, riskN, share, shareText, go });

  return (
    <section className={S.today} aria-label="오늘 대시보드">
      {/* ── 상단 밴드: 포커스 히어로 | 오늘의 블록 ── */}
      <div className={emptyDay ? `${S.top} grid-cols-1!` : S.top}>
        {/* HERO — 거대 과목명 = 행동의 무대. 과목색 오로라 + 통합 집중 시작. */}
        <div
          ref={heroRef}
          onMouseMove={onHeroMove}
          onMouseLeave={onHeroLeave}
          className={S.hero}
          style={dispColor ? ({ '--tint': dispColor } as CSSProperties) : undefined}
        >
          {/* heroDone 오로라 — allDone 이면 --tint 미주입이라 acc 로 폴백. 원본 .heroDone .aura 의
              opacity 0.6(모션 자제 시에만 노출)만 재현. 애니 켜지면 auraBreathe 가 opacity 를 덮는다. */}
          <div className={`${S.aura} ${allDone ? 'opacity-60' : 'opacity-55'}`} aria-hidden="true" />
          <div className={S.spotlight} aria-hidden="true" />
          {timer && <div className={S.heroFill} style={{ width: `${timerPct}%` }} aria-hidden="true" />}
          {/* ⚠ D-5 — 132px '남은 N h' 워터마크가 여기 있었다. `aria-hidden` **장식이 화면 최대
              활자**인 상태였고(SR 에는 애초에 없던 정보다), 그 옆의 72px 은 과목명이었다.
              값은 버리지 않고 상단 리드아웃('남은 가용')으로 내렸다 — 거기선 SR 도 읽는다.
              우상단 시각도 뺐다: 같은 값을 아래 근거 한 줄과 흐름 레일이 이미 말한다. */}
          <div className={S.heroHead}>
            <span className={S.eyebrow}>
              {current && <i className={S.live} />}
              {kicker}
            </span>
          </div>
          {/* P-7 — W6 의 판정 **문장**이 여기 있었다. 같은 판정을 이제 길이로 말한다(`DayBar`).
              문장은 사라진 것이 아니라 막대의 `aria-label` 이 됐다 — 길이로 옮긴 것을 SR 이
              못 읽으면 그건 이전(移轉)이 아니라 손실이다. */}
          <DayBar
            segments={cap.segments}
            scaleMin={cap.scaleMin}
            windowRatio={cap.windowRatio}
            fitLine={cap.fitLine}
            beyondMin={cap.beyondMin}
          />

          <h2 className={S.subj}>{heroMain}</h2>
          <div className={S.heroSub}>
            <HeroSubline
              todayTotal={todayTotal}
              hasItems={hasItems}
              allDone={allDone}
              tmrNew={tmrNew}
              nextStep={nextStep}
              go={go}
              heroSub={heroSub}
              focus={focus}
              focusReason={focusReason}
              locked={locked}
              ds={ds}
              setFocusLock={setFocusLock}
            />
          </div>
          {/* A1 — 어제 남긴 '내일 한 줄'.
              ⚠ P-15 — **하루를 여는 국면에만.** 종전엔 완료 전까지 하루 종일 떠 있었는데, 이건
              *어제의 나에게서 온 메모*라 오늘을 여는 순간에 값이 있고 세 시간 뒤엔 소음이다. */}
          {prevNote && showOpeningRecall && (
            <div className={S.yesterday}>
              <Icon name="moon" /> 어제 남긴 한 줄 —{' '}
              <b className="font-bold text-[color:var(--yesterday-b)]">{prevNote}</b>
            </div>
          )}
          <ShapeLine state={state} ds={ds} when={closing} />
          {/* ID-4 — On This Day 회고: 달력상 같은 날의 과거 실기록 한 줄(회상 카드와 달리 달력 정합).
              ⚠ P-15 — 같은 이유로 여는 국면에만. 이것도 *과거를 여는* 문장이다. */}
          {onThis && showOpeningRecall && (
            <div className={S.yesterday}>
              <Icon name="calendar" /> {onThis.offsetLabel} —{' '}
              {onThis.subject && <b className="font-bold text-[color:var(--yesterday-b)]">{onThis.subject}</b>}{' '}
              {onThis.detail}
            </div>
          )}

          {/* 주 액션 — 집중 타이머(포모도로). 히어로 안에 통합 = 가장 큰 요소가 곧 행동. */}
          <div className={S.actions}>
            {timer ? (
              <button
                type="button"
                className={`${S.cta} ${S.ctaRun}`}
                onClick={() => void stopTimer()}
                aria-label={timer.kind === 'break' ? '휴식 타이머 정지' : '집중 타이머 정지'}
              >
                <span className={S.ctaNum}>{timerLabel}</span>
                <span className={S.ctaCap}>
                  {timer.kind === 'break' ? (
                    <>
                      <Icon name="coffee" /> 휴식 · ■ 정지
                    </>
                  ) : (
                    '■ 정지'
                  )}
                </span>
              </button>
            ) : allDone ? (
              /* N-5 — 다 한 날의 다음 걸음은 '기록 보기'가 아니라 **하루를 닫는 것**이다.
                 종전엔 그 행위가 ＋블록 상세 → 오버레이 → 스크롤 뒤에 있었다. */
              <CloseDayCta onOpenMore={onOpenMore} cap="내일 한 줄 →" />
            ) : focus ? (
              <>
                <button
                  type="button"
                  className={`${S.cta} ${S.ctaFill}`}
                  onClick={() => startTimer()}
                  aria-label="집중 타이머 시작"
                >
                  <span className={S.ctaGo}>
                    <Icon name="play" /> 집중 시작
                  </span>
                  <span className={S.ctaCap}>{focusMin}분</span>
                </button>
                {/* N-5 — 못 한 채로 끝나는 날. 남은 창이 0인데도 화면은 계속 "집중 시작"만
                    크게 띄우며 있지도 않은 시간을 쓰라고 했다. 시작을 **지우지는 않는다**
                    (밤샘은 사용자의 선택이다) — 닫는 길을 옆에 낼 뿐이고, 그래서 채움 버튼은
                    여전히 하나다(D-6 액센트 예산). */}
                {/* ⚠ P-15 — 여는 국면에도 안 그린다. 25·50분은 *기본 길이를 바꾸는* 도구인데,
                    아직 한 번도 안 시작한 시점의 기본은 블록이 정한 길이(`focusMinutes`)가 맞다.
                    고를 것을 먼저 보여 주면 여는 화면의 질문이 "무엇부터"에서 "몇 분"으로 바뀐다. */}
                <Presets focusMin={focusMin} onPick={startTimer} when={phase === 'run'} />
              </>
            ) : hasItems ? (
              // §7: 과목은 있으나 오늘 포커스가 없음 → 오늘 계획을 직접 짜는 단일 목적지(계획 › 캘린더 일 뷰).
              <button type="button" className={`${S.cta} ${S.ctaFill}`} onClick={goPlanToday}>
                <span className={S.ctaGo}>오늘 계획 짜기</span>
                <span className={S.ctaCap}>캘린더 · 오늘 →</span>
              </button>
            ) : (
              <button type="button" className={`${S.cta} ${S.ctaFill}`} onClick={() => go('/items')}>
                <span className={S.ctaGo}>＋ 학습 항목 추가</span>
                <span className={S.ctaCap}>시작하기 →</span>
              </button>
            )}
            {/* N-5 — 닫는 길은 **어느 분기에도** 있다. 처음엔 `focus` 분기 안에 뒀는데, 늦은
                시각엔 화면이 다른 분기를 타서(포커스가 없다) 정작 필요한 순간에 안 보였다 —
                실렌더 확인이 그걸 잡았다(§15-4). 완료 화면은 자기 CTA 가 이미 닫기라 뺀다.
                채움 버튼은 여전히 하나다(D-6): 이건 ghost 다. */}
            <CloseDayCta onOpenMore={onOpenMore} cap="남은 창 없음 →" when={closing && !allDone && !timer} />
            {/* E7 — 히어로 시계를 뗐다. 바로 아래 흐름 헤더가 `● 09:00 LIVE` 로 **같은 문자열**을
                이미 말하고 있었다(한 양이 두 자리). 시각의 소유자는 흐름 헤더 하나다. */}
          </div>
          {/* 빈 날엔 '오늘 밖' 신호가 히어로 아래로 내려온다(W19) — 컬럼을 접으면서 이 신호까지
              사라지면 마감·Anki·보충이 **가장 한가한 날에만 안 보이는** 뒤집힌 상태가 된다. */}
          {emptyDay && beyondNode}
        </div>

        {/* 오늘의 흐름 — now-중심 세로 레일(학습 체크 + 일과, 색 통일). 무지개 트랙 폐기.
            ⚠ 빈 날엔 **그리지 않는다**(W19) — 링 0/0·LIVE·종결 캡·＋ 는 내용 0의 골격이고,
            골격만 남은 컬럼은 "여기 뭔가 있어야 한다"고 말하는 유령이다. */}
        {!emptyDay && (
          <aside className={S.flow}>
            <h2 className={S.flowHead} aria-label={`오늘의 흐름 ${todayDone}/${todayPossible} 완료`}>
              {/* ⚠⚠ **여기 `ProgressRing` 이 있었고 그 한가운데 `3/7` 이 겹쳐 있었다 — P-7 에서
                  **링을** 지웠다(숫자가 아니라).**

                  로드맵은 "링의 중복 숫자"를 지우라고 적었고 처음엔 그렇게 했는데, **실렌더
                  확인**(§15-4)이 그게 틀렸음을 보여 줬다: 숫자 없는 34px 링은 진행 0%인 아침에
                  **빈 원**이라 로딩 스피너처럼 읽혔고, 분모(오늘 몇 칸인가)를 말할 자리가 통째로
                  사라졌다. 로드맵도 그 가능성을 적어 뒀다 — _"링 숫자 제거가 첫 걸음이지만
                  충분하지 않을 수 있다."_

                  같은 원칙(한 양 = 한 부호화 · 시그니처는 페이지마다 하나)을 반대쪽으로 적용한다:
                  **길이 그래픽은 위 `DayBar` 하나**가 갖고, 여기는 세는 것만 남긴다. 34px 도넛은
                  애초에 약한 그래픽이었고(NN/g 가 게이지·도넛을 비권장한 그 형태다) 막대가
                  들어온 이상 둘을 같은 화면에 둘 이유가 없다.
                  ⚠ E15 의 `commit` 번쩍임과 완주 셀레브레이션은 이제 **숫자 자리**에서 난다 —
                    값이 바뀐 그 자리다(`useCommitOnChange` 머리주석의 원래 의도 그대로). */}
              <span
                ref={doneRef}
                className={`${S.ringNum}${celebrate ? ' animate-[commit-cele_var(--dur-cele)_var(--ease)] motion-reduce:animate-none' : ''}`}
                aria-hidden="true"
              >
                {todayDone}
                <small className={S.ringNumSmall}>/{todayPossible}</small>
              </span>
              <span className={S.flowT}>오늘의 흐름</span>
              <span className={S.now}>● {toHM(nowMin)} LIVE</span>
            </h2>
            <div className={S.rail}>
              {flowNodes.length ? (
                <FlowRail
                  nodes={flowNodes}
                  nowMin={nowMin}
                  onToggle={toggle}
                  onFocus={startNodeFocus}
                  onPrefill={prefillNode}
                />
              ) : (
                /* ⚠ 여기 히어로와 **글자까지 같은 문장** + 같은 핸들러(`goPlanToday`)가 또 있었다 —
                 W19 에서 빈 날 컬럼 자체가 사라지며 도달 불가가 됐다. 이 분기는 `flowNodes` 가
                 비었는데 `emptyDay` 가 아닌 경우(있을 수 없다)의 안전망으로만 남긴다. */
                <div className={S.railEmpty}>오늘 그릴 흐름이 없어요.</div>
              )}
            </div>
            {/* ── W20 인출 슬롯은 **하나**다(2026-07-31) ────────────────────────────────
                종전엔 `🧠 회상`과 `⚠ 착각 재확인`이 **같은 `S.recall` 형상**으로 나란히 뜰 수
                있었고(둘은 태그 색만 다르다) 그 위에 `복습 N개 밀림` 칩이 또 있었다 — 최대 3
                입구. 같은 모양이 셋이면 그건 카드가 아니라 목록이다.

                ⚠⚠ **미실행 사유가 이 구현의 제약이다**: 홈의 인출 카드는 "가려던 게 아닌데 하게
                되는" **우발적 인출**이 값어치라, 슬롯을 없애면 이 앱이 만드는 학습 증거가 함께
                준다. 그래서 **없애지 않고 하루 한 장으로 회전**시킨다 — 두 소스 다 이미 날짜
                해시로 후보를 고르므로(`pickRetrieval`·`pickConfidentWrong`) 회전이 그 규칙의
                연장이고, 매일 한 장은 계속 뜬다(우발적 인출의 빈도가 유지된다).
                ⚠ 착각이 있으면 착각이 이긴다 — "확신했는데 틀린 것"은 회상보다 늦게 발견될수록
                비싸다(그쪽만 오답으로 이미 관측된 사실이다). 회상은 그 다음 날 온다. */}
            {/* F5 추출(2026-08-06) — 카드 두 장의 마크업이 여기 70줄로 있었고, 그와 함께
                `recallShown`·`recallKeyShown`·**렌더 중 조건부 setState** 셋이 이 컴포넌트에
                살았다. 셋 중 둘은 오로지 첫째를 리셋하려고 있던 것이라 `key` 리마운트가 통째로
                대체한다(`SummaryEditor` 가 세운 F5 선례와 같은 수법).
                ⚠ `key={recallKey}` 가 그 계약이다 — 빼면 카드가 바뀌어도 정답이 펼쳐진 채 남는다. */}
            <RetrievalSlot
              key={recallKey}
              slot={retrievalSlot}
              recall={recall}
              confWrong={confWrong}
              confWrongN={confWrongN}
              onGo={go}
            />
            {!emptyDay && beyondNode}
            <button type="button" className={S.more} onClick={() => onOpenMore()}>
              ＋ 블록 상세 · 일일 의식 · 흐름 가이드
            </button>
          </aside>
        )}
      </div>
    </section>
  );
}

/** 상단 크롬(44px 앵커 + 리드아웃 + 액션) — 위 컴포넌트에서 뺀 설정부. 근거는 그 호출부 주석. */
function chromeFor(p: {
  cap: ReturnType<typeof dayCapacity>;
  todayDone: number;
  todayTotal: number;
  allDone: boolean;
  hasItems: boolean;
  res: ReturnType<typeof useSchedule>;
  nearestDday: number | null;
  goPlanToday: () => void;
  go: (to: string) => void;
}) {
  /* ⚠ `todayDone`·`nearestDday` 는 **deps 로만** 쓰인다(E7 이 그 둘을 상단에서 뗐다 — 각각
     흐름 헤더의 링과 하단 '마감 임박' 이 소유자다). 인자로 받는 이유는 호출부의 deps 와 이
     함수의 입력이 갈리지 않게 하기 위함이고, 그 사실을 여기 적어 둔다. */
  const { cap, todayTotal, allDone, hasItems, res, goPlanToday, go } = p;
  return {
    /* ⚠⚠ **Q-2 에서 뒤집혔다(2026-08-02).** 종전 주석은 _"이 화면은 렌즈라 44px 앵커를 세우지
         않는다 — 잊은 것이 아니라 없다고 정한 것이다"_ 였는데, 그 판단의 대가가 뒤늦게 드러났다:
         **오늘의 여유는 화면에 문자가 0자였다.** 값은 이미 계산돼 있었지만(`dayCapacity`) 막대의
         `aria-label` 로만 존재해서, 눈으로 읽을 방법이 없었다(P-7 이 길이로 옮기며 생긴 사각).
         `오늘 여유 1.2h` 는 이 화면에서 **다음 행동을 가장 많이 바꾸는 한 수**다 — 그게 곧 44px
         앵커의 정의이므로 여기 선다.
         ⚠ 할 일이 없으면 여전히 `null` 이다(`slackMin === null`) — 말할 것이 없으면 안 그린다. */
    primary:
      cap.slackMin == null
        ? null
        : // ⚠ `value` 는 **문자열**이고 단위는 `unit` 이다 — 이 자리는 한 값이지 조판이 아니라는
          //   것이 `ChromePrimary` 의 명시 계약이다(ReactNode 를 받으면 탭마다 조판이 갈린다).
          {
            label: cap.slackMin >= 0 ? '오늘 여유' : '오늘 초과',
            value: String(hNum(Math.abs(cap.slackMin))),
            unit: 'h',
          },
    /* ── E7 한 양 = 한 자리(2026-07-29) ────────────────────────────────
         평일 낮 이 화면의 상시 숫자 26개 중 다음 행동을 바꾸는 것은 5개인데, **6개 양이
         15자리에서** 렌더되고 있었다. 여기서 뗀 둘은 각각 이미 소유자가 있다:
         · 진행률 → 흐름 헤더의 `ProgressRing`(호(弧) + `3/7`)이 두 표현으로 말한다.
         · 마감   → 하단 스트립 '마감 임박'이 D-day 와 **이름까지** 말한다(같은 `ddays[0]`).
         ⚠ 마감을 상단에서 떼면 급한 D-day 를 보려고 시선이 하단까지 내려간다 — 대신 이 화면은
           무스크롤이라 내려갈 거리가 화면 안이고, 스트립은 E8 에서 *있을 때만* 그린다(0인 날은
           아예 없으므로 마감이 떠 있으면 그 자체가 신호다). */
    readouts: [
      /* ⚠ `연속`(스트릭) 리드아웃이 여기 있었다 — I054 가 지웠다(위 축하 주석이 근거의 SSOT).
         I046 이 통계 탭에서 같은 자리를 「밀린 복습」에 준 것과 짝이다. 여기서는 그 자리를
         **비운다**: 이 화면의 상단은 이미 히어로가 «지금 무엇을»을 44px 로 말하고 있고,
         빈 칸을 급히 채우는 것이 이 저장소가 반복해 온 «표면을 하나 더» 다. */
      /* ⚠ `남은 가용` 리드아웃이 여기 있었다 — **W6 이 흡수했다.** 30px 로 크게 그리면서도
           그 수 혼자서는 "오늘 안에 들어가는가"를 못 말했고(사용자가 남은 계획과 대각선으로
           눈을 이어 뺄셈을 했다), 지금은 히어로 아이브로 아래 한 줄이 두 수를 **판정과 함께**
           말한다. 값은 사라지지 않았고 자리와 문법이 바뀌었다. */
      // PL-5: 적응형 용량이 적용된 날만(최근 이행률 저조 → 오늘 가용 축소) 감축률을 노출 — 비가시 해소.
      ...(res.adaptApplied ? [{ label: '용량', value: `−${Math.round((1 - (res.adapt ?? 1)) * 100)}%` }] : []),
    ],
    action:
      todayTotal === 0
        ? // PL-1: 이미 과목이 있는 사용자(hasItems)에게 "항목 설정"은 모순 — 오늘만 빈 것이므로 스케줄로 안내.
          hasItems
          ? { label: '오늘 계획 짜기 →', onClick: goPlanToday }
          : { label: '학습 항목 설정 →', onClick: () => go('/items') }
        : allDone
          ? { label: '기록 보기', onClick: () => go('/day') }
          : /* ⚠ D-6 — 여기 '지금 시작 →' 네온 버튼이 있었다. 히어로의 '▶ 집중 시작'과 **거의 같은
                 동작**을 하면서 화면 대각선 반대쪽에 앉아, 한 화면에 채움 버튼이 둘이었다.
                 액센트 예산은 채움 1개다 → 오늘 탭에서 상단 액션을 비운다(진행 중 세부 패널은
                 흐름 카드의 '+ 블록 상세…'가 연다). 빈 날·완주 화면의 액션은 히어로에 짝이 없어
                 남긴다 — 중복이 아니라 그 화면의 **유일한** 다음 걸음이다. */
            undefined,
  };
}

/* ============================================================
   interactions.ts — 탭 공유 인터랙션 프리미티브(오늘 탭 "FOCUS"에서 추출).
   세계적 수준의 "살아있는" 감각을 전 탭에 일관 적용하기 위한 단일 원천.
   • useCountUp — 현재 표시값→target 카운트업(reduced-motion이면 즉시).
   • useHeroPointer — 포인터 추적: --mx/--my(스포트라이트) + --tiltX/Y(3D 틸트) CSS 변수 주입.
   짝이 되는 CSS는 styles/ds.css의 .ds-spotHost/.ds-spotlight/.ds-glow.
============================================================ */
import { useEffect, useRef, useState, type MouseEvent as ReactMouseEvent } from 'react';
import { minutesOfDay } from '@/lib/utils';
import { prefersReducedMotion } from '@/lib/motion';
import { onVisible, onHidden } from '@/lib/visibility';
import { useKeymap } from './useKeymap';
import { isTyping } from '@/lib/typing';

/** 현재 표시값→target으로 부드럽게 카운트업/다운(easeOutCubic). reduced-motion·SSR이면 즉시 target.
 *  target 변경 시 0이 아니라 *현재값*에서 트윈 — 데이터 갱신마다 KPI가 0으로 튀는 깜빡임 방지(L-8). */
export function useCountUp(target: number, ms = 750): number {
  const [v, setV] = useState(0);
  const vRef = useRef(0); // 현재 표시값 미러(deps에 넣지 않고 애니메이션 시작점으로 읽기 위함)
  useEffect(() => {
    // ⚠ 판정은 `lib/motion` 하나다(H19) — 여기서 matchMedia 를 직접 부르면 앱 설정('발광 효과
    //    줄이기')을 모르는 사본이 된다. 그 사본들이 설정 라벨을 거짓으로 만들고 있었다.
    const reduce = prefersReducedMotion();
    if (reduce || typeof requestAnimationFrame === 'undefined') {
      vRef.current = target;
      // eslint-disable-next-line react-hooks/set-state-in-effect -- 모션 자제 시 애니메이션 없이 즉시 최종값.
      setV(target);
      return;
    }
    const from = vRef.current; // 이번 트윈의 출발점 = 현재 화면에 보이는 값
    let raf = 0;
    let startedAt = 0;
    const step = (now: number) => {
      if (!startedAt) startedAt = now;
      const t = Math.min(1, (now - startedAt) / ms);
      const val = from + (target - from) * (1 - Math.pow(1 - t, 3));
      vRef.current = val;
      setV(val);
      if (t < 1) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [target, ms]);
  return v;
}

/** 현재 시각을 '자정 이후 분(0~1439)'으로 — 분단위 틱(60s)으로 갱신, 백그라운드 복귀 시 즉시 캐치업.
 *  '지금' 라인·⏱ 지금 행이 로드 시각에 멈추지 않도록(스케줄·일과 공유 · 3중 중복 이펙트 제거). */
export function useNowMin(): number {
  const [nowMin, setNowMin] = useState(() => {
    const d = new Date();
    return minutesOfDay(d);
  });
  useEffect(() => {
    const tick = () => {
      const d = new Date();
      setNowMin(minutesOfDay(d));
    };
    const id = setInterval(tick, 60_000);
    const off = onVisible(tick); // 백그라운드 복귀 시 즉시 캐치업.
    return () => {
      clearInterval(id);
      off();
    };
  }, []);
  return nowMin;
}

/** 주기적으로 **리렌더만** 트리거하는 틱 — 화면의 상대시각(⏱ mm:ss·now 라인)이 로드 시점에
 *  멈추지 않게. period 는 호출부가 상황에 맞게 준다(포모도로 세션 중=1s · 평시=30s). 백그라운드에선
 *  멈추고 복귀 시 즉시 캐치업. 카운터 값은 리렌더 트리거일 뿐이라 읽지도 반환하지도 않는다
 *  (그래서 종전의 `% 86400` 상한도 불필요 — 단조 증가로 충분하다). */
export function useAdaptiveTick(periodMs: number): void {
  const [, setTick] = useState(0);
  useEffect(() => {
    let id: ReturnType<typeof setInterval> | null = null;
    const bump = (): void => setTick((t) => t + 1);
    const start = (): void => {
      if (id == null) id = setInterval(bump, periodMs);
    };
    const stop = (): void => {
      if (id != null) {
        clearInterval(id);
        id = null;
      }
    };
    start();
    const offHide = onHidden(stop);
    const offShow = onVisible(() => {
      bump(); // 복귀 즉시 캐치업
      start();
    });
    return () => {
      stop();
      offHide();
      offShow();
    };
  }, [periodMs]);
}

/** 언마운트 시 미커밋 초안 flush — fn을 이펙트에서 ref에 담아(렌더 중 ref쓰기 금지·React Compiler refs 준수)
 *  언마운트 클린업에서 1회 호출. ArticlePractice·BookShelf의 상이한 두 구현을 한 방식으로 통일(SR-16). */
export function useFlushOnUnmount(fn: () => void): void {
  const ref = useRef(fn);
  useEffect(() => {
    ref.current = fn; // 렌더마다 최신 콜백 동기화(이펙트서 할당)
  });
  useEffect(() => () => ref.current(), []);
}

/** 포커스가 입력 요소(텍스트 편집)에 있으면 전역 단일키 단축키를 무시.
 *  ⚠ 구현은 `lib/typing.ts` 로 내려갔다 — 이 파일과 `useKeymap.ts` 사이의 **순환을 끊기 위해서**다
 *  (m-15 · 근거는 그 파일 머리주석). 여기 재수출은 기존 소비처 보존용이고, 새 코드는 `@/lib/typing`
 *  을 직접 물어라. */
export { isTyping };

/** 주 이동 `,`/`.` — **N-16 이후 `useKeymap` 위에 얹힌 얇은 래퍼**다.
 *  옛 구현은 자기 리스너를 직접 걸었고, 그래서 이 키가 *어느 화면에 사는지* 앱이 몰랐다
 *  (치트시트는 전역이라 적었지만 실제론 2화면뿐 = 12개 탭에서 거짓말). 이제 등록과 설명이
 *  같은 선언에서 나오므로 치트시트가 "지금 이 화면" 섹션에 스스로 뜬다. */
export function useWeekNavKeys(onPrev: () => void, onNext: () => void): void {
  useKeymap(
    '이 화면 · 주 이동',
    [
      { keys: [','], display: ',', label: '이전 주' },
      { keys: ['.'], display: '.', label: '다음 주' },
    ].map((b, i) => ({ ...b, run: i === 0 ? onPrev : onNext })),
  );
}

/** 포인터 추적 — 패널 위 커서 위치를 CSS 변수로(스포트라이트 --mx/--my, 3D 틸트 --tiltX/Y).
    tilt=0이면 틸트 없이 스포트라이트만(큰 보드/편집 패널용). ds.spotHost와 함께 사용. */
export function useHeroPointer<T extends HTMLElement = HTMLDivElement>(tilt = 6) {
  const ref = useRef<T>(null);
  const onMouseMove = (e: ReactMouseEvent<T>) => {
    const el = ref.current;
    if (!el) return;
    const r = el.getBoundingClientRect();
    const px = (e.clientX - r.left) / r.width;
    const py = (e.clientY - r.top) / r.height;
    el.style.setProperty('--mx', `${px * 100}%`);
    el.style.setProperty('--my', `${py * 100}%`);
    if (tilt) {
      el.style.setProperty('--tiltY', `${(px - 0.5) * tilt}deg`);
      el.style.setProperty('--tiltX', `${-(py - 0.5) * tilt}deg`);
    }
  };
  const onMouseLeave = () => {
    const el = ref.current;
    if (!el) return;
    el.style.setProperty('--tiltX', '0deg');
    el.style.setProperty('--tiltY', '0deg');
  };
  return { ref, onMouseMove, onMouseLeave };
}

/* ============================================================
   useFormSubmit — 폼 키 계약의 단일 원천(N-17).

   ## 왜 필요했나

   앱 전체에서 `⌘/Ctrl+Enter` 를 처리하는 곳이 `shell/modal.tsx` **한 곳**뿐이었고, 기록
   카드 셋의 계약이 서로 달랐다: `CbmsCard`·`BacklogCard` 는 맨 Enter 로 제출, **`SummaryCard`
   의 textarea 셋은 아무 키 계약이 없었다.** 즉 이 앱에서 가장 잦은 일일 기록인 3문장 요약만
   유일하게 마우스로 버튼을 눌러야 저장됐다. 편집 취소 `Esc` 는 세 카드 모두 없었다.

   ## 계약 (한 문장씩)

   · `⌘/Ctrl+Enter` — **어디서나** 제출. 한 줄 입력이든 여러 줄이든 같다(외울 것이 하나).
   · 맨 `Enter` — **한 줄 입력에서만** 제출. textarea 에선 줄바꿈이다(당연하지만, 그 당연함이
     계약으로 적혀 있지 않아 카드마다 갈렸다).
   · `Esc` — 취소(넘겼을 때만). ⚠ 취소 **버튼은 남긴다** — Esc 만 두면 발견성 없는 파괴 동작이
     된다(로드맵 N-17 의 명시 제약).

   ## ⚠⚠ IME 조합 중의 Enter 는 제출이 아니다 — 이건 선재 결함이었다

   한글 입력에서 마지막 음절이 **조합 중**일 때 누르는 Enter 는 "조합 확정"이지 "제출"이
   아니다. 그런데 옛 핸들러들(`e.key === 'Enter' && submit()`)은 그 구분이 없어서, 크롬이
   `isComposing: true` 로 함께 보내는 그 keydown 에 **덜 친 내용을 제출**했다. 한국어로만
   쓰는 앱에서 한글 입력 칸 7곳이 전부 이랬다 — 증상이 "가끔 반쯤 친 게 저장됨"이라
   재현 조건을 모르면 사용자 실수로 읽힌다. 계약을 한 곳에 모으니 방어도 한 곳이 된다.

   ## 왜 `field`/`area` 로 안 나눴나

   두 벌을 내놓으면 textarea 에 `field` 를 붙이는 실수가 가능하고, 그 결과는 "요약 칸에서
   줄바꿈이 안 됨"이라는 조용한 오작동이다. 대신 `e.currentTarget` 의 태그를 보고 **런타임에
   판정**한다 — 붙이는 쪽이 틀릴 수 있는 선택지를 없앤다.
============================================================ */
import { useMemo } from 'react';
import type { KeyboardEvent } from 'react';

export interface FormKeyProps {
  onKeyDown: (e: KeyboardEvent<HTMLElement>) => void;
}

export interface FormSubmitOptions {
  /**
   * **Q-20** — 여러 줄 칸에서 맨 Enter 를 "다음 칸"으로 쓸 때의 이동 함수.
   *
   * @returns 실제로 옮겼는가. **`false` 면 Enter 는 줄바꿈 그대로** — 마지막 칸에서 커서가
   *   갈 곳이 없는데 `preventDefault` 를 하면 그 칸에서만 Enter 가 죽는다(조용한 고장).
   */
  advance?: (from: HTMLElement) => boolean;
}

/**
 * 폼 키 계약을 입력 요소에 붙일 props 로 돌려준다 — `<input {...keys} />` · `<textarea {...keys} />`.
 *
 * @param submit 제출. 유효성 검사·토스트는 호출부가 소유한다(여기는 키만 안다).
 * @param cancel 취소(편집 폼). 없으면 Esc 는 아무 일도 안 한다 — 새 항목 폼에서 Esc 가
 *   입력을 날리면 그게 더 놀랍다.
 */
export function useFormSubmit(submit: () => void, cancel?: () => void, opts?: FormSubmitOptions): FormKeyProps {
  const advance = opts?.advance;
  return useMemo(
    () => ({
      onKeyDown: (e: KeyboardEvent<HTMLElement>) => {
        // ⚠ 조합 중 Enter 는 확정이지 제출이 아니다(머리주석). Esc 도 조합 취소가 먼저다.
        if (e.nativeEvent.isComposing) return;
        if (e.key === 'Escape') {
          if (!cancel) return;
          e.preventDefault();
          e.stopPropagation(); // 오버레이 안의 폼이면 Esc 가 오버레이까지 닫는 것을 막는다
          cancel();
          return;
        }
        if (e.key !== 'Enter') return;
        const multiline = (e.currentTarget as HTMLElement).tagName === 'TEXTAREA';
        if (e.altKey || e.shiftKey) return; // Shift+Enter 는 줄바꿈 관용구라 뺏지 않는다
        /* ── Q-20 다음 칸으로 ────────────────────────────────────────────────────────────
           `advance` 를 넘긴 폼에서는 여러 줄 칸의 맨 Enter 가 **다음 칸**이다(⌘Enter 는 여전히
           제출 · ⇧Enter 는 줄바꿈).
           ⚠ 왜 안전한가: 이 옵션은 `rows={2}` 짜리 **"한 문장 그릇"** 에만 붙인다 — 화면이 이미
           크기로 "여기는 한 문장"이라 말하고 있어서, 맨 Enter 의 자연스러운 뜻이 줄바꿈이 아니라
           "다 썼다"다. 긴 글을 받는 textarea 에는 **붙이지 않는다**(그때는 줄바꿈이 맞다).
           ⚠ 옵션으로 둔 이유: 기본값으로 만들면 앱의 모든 textarea 에서 Enter 가 줄바꿈을
           잃는다. 붙이는 쪽이 틀릴 수 있는 선택지를 없앤다는 이 훅의 규율과 어긋나지 않는다 —
           여기서 고르는 것은 *칸의 종류*가 아니라 *폼의 성격*이라 호출부만 알 수 있다. */
        if (multiline && advance && !(e.metaKey || e.ctrlKey)) {
          if (!advance(e.currentTarget as HTMLElement)) return; // 마지막 칸이면 줄바꿈 그대로
          e.preventDefault();
          return;
        }
        if (multiline && !(e.metaKey || e.ctrlKey)) return; // 여러 줄 칸의 맨 Enter = 줄바꿈
        e.preventDefault();
        submit();
      },
    }),
    [submit, cancel, advance],
  );
}

/* ============================================================
   artifacts.ts — parent(pipeline) 아티팩트의 _schemaVersion 소비 (P7 Bet 1 · repo 경계 계약).

   왜: pipeline↔hub 는 별도 git repo 인데 JSON 아티팩트를 주고받으며 공유 스키마가 0이었다 —
   생산자가 필드명 하나 바꾸면 이 앱 탭이 *조용히* 깨졌다. P7 Bet 1 이 부모에 버전드 JSON Schema
   (knowledge/_meta/contract/schemas/*)를 세우고 각 아티팩트에 `_schemaVersion` 을 주입한다. hub 는
   read 시 기대 버전과 대조해 불일치면 콘솔 경고를 낸다(조용한 깨짐 → 시끄러운 경고).

   버전 진화(INV-2): 부모가 파괴적 스키마 변경으로 버전을 올리면 스키마 `_schemaVersion.const` 을
   올린다 → `npm run codegen` 이 아래 EXPECTED_SCHEMA_VERSION 을 재생성한다(손유지 아님). 미스매치
   경고가 "서브모듈/재빌드 동기가 필요하다"를 개발자에게 알린다.
   (SSOT = 부모 JSON Schema. artifacts.gen.ts 가 그로부터 생성 · 여기선 재노출만.)
============================================================ */

// 버전 상수·이름 타입은 부모 스키마에서 생성된다(artifacts.gen). 하위호환 위해 여기서 재노출 —
// 기존 소비처(`from './artifacts'`)를 안 건드린다.
import { ARTIFACT_SCHEMAS, EXPECTED_SCHEMA_VERSION, type ArtifactName } from './artifacts.gen';
export { EXPECTED_SCHEMA_VERSION, type ArtifactName };

/** 아티팩트의 `_schemaVersion` 을 기대치와 대조 — 불일치/부재면 콘솔 경고(비차단 · 소비는 계속). */
export function checkSchemaVersion(name: ArtifactName, data: unknown): void {
  const v = (data as { _schemaVersion?: number } | null | undefined)?._schemaVersion;
  const exp = EXPECTED_SCHEMA_VERSION[name];
  if (v !== exp) {
    console.warn(
      `[artifact:${name}] _schemaVersion ${v ?? '(없음)'} ≠ 기대 ${exp} — parent↔hub 스키마 드리프트. ` +
        `parent 재빌드 또는 hub 서브모듈 동기가 필요할 수 있어요(P7 Bet 1).`,
    );
  }
}

/** ARTIFACT_SCHEMAS 에 스키마가 있는 이름(= 부모 JSON Schema 에서 생성된 것). */
type ParsableName = ArtifactName & keyof typeof ARTIFACT_SCHEMAS;

/* ── 경계 파싱(2026-07-19 플랫폼 감사 ③) ──────────────────────────────────
   `checkSchemaVersion` 은 **버전 숫자 하나**만 봤다. 그런데 이 파일 서두가 적은 실제 실패
   모드는 "생산자가 필드명 하나 바꾸면 탭이 조용히 깨진다" — 그건 버전이 그대로인 채로 일어나므로
   버전 대조로는 절대 안 잡힌다. 정작 필요한 모양 검증은 `artifacts.gen.ts` 가 부모 스키마에서
   이미 생성해뒀는데("소비처 선택 사용") 아무도 선택하지 않아, 소비처는 전부 `as T` 캐스팅이었다.

   설계 계약:
   - **비차단.** 검증 실패해도 원본을 그대로 돌려준다 → 최악의 경우 오늘과 똑같이 동작하고,
     달라지는 건 "조용히 깨진다"가 "시끄럽게 경고하고 깨진다"가 되는 것뿐이다. 탭을 빈 화면으로
     만들지 않는다(persistence.ts:255 가 경계한 '정상 레코드 오폭 삭제'와 같은 이유).
   - **부모 스키마 파생이라 신뢰할 수 있다.** 손유지 AppStateSchema 와 달리 이건 생성물이라
     실데이터와 대조된 적 없는 스키마가 아니다.
   - 스키마가 passthrough 라 미지 필드는 보존된다(생산자가 필드를 *추가*하는 건 깨짐이 아니다).
──────────────────────────────────────────────────────────────────────── */
export function parseArtifact<N extends ParsableName>(name: N, data: unknown): unknown {
  checkSchemaVersion(name, data);
  const r = ARTIFACT_SCHEMAS[name].safeParse(data);
  if (r.success) return r.data;
  // 상위 5개만 — 필드 하나가 어긋나면 하위 이슈가 수십 개 딸려 나와 콘솔이 쓸려나간다.
  const issues = r.error.issues
    .slice(0, 5)
    .map((i) => `  · ${i.path.join('.') || '(루트)'}: ${i.message}`)
    .join('\n');
  const more = r.error.issues.length > 5 ? `\n  … 외 ${r.error.issues.length - 5}건` : '';
  console.warn(
    `[artifact:${name}] 모양이 계약과 다릅니다 — parent(pipeline)가 필드를 바꿨을 수 있어요.\n${issues}${more}\n` +
      `원본을 그대로 사용합니다(비차단). 계약 정본 = parent 의 knowledge/_meta/contract/schemas/.`,
  );
  return data;
}

/* ============================================================
   cloud/schema.ts — **신뢰 경계의 계약**(C-2 · P0-3).

   ## 이 파일이 다른 경계와 정반대인 이유

   이 저장소에는 이미 경계 파싱 관용구가 있다 — `artifacts.ts:49` 의 **비차단 경고**:
   모양이 어긋나도 경고만 남기고 **원본을 그대로 돌려준다**. 산출물은 *우리가 만든* 파일이고
   거부하면 화면이 비므로, 거기선 그게 옳다(파싱은 **드리프트 탐지**가 목적이다).

   **여기서 그 패턴을 복제하면 안 된다.** `OutboxBatch` 는 네트워크를 건너오는 페이로드이고,
   클라우드는 **정의상 신뢰할 수 없는 입력을 받는다**(설계서 §6 P0-3). 거부가 부작용이 아니라
   **목적 그 자체**다. 그래서 여기는 `.strict()` + 차단이다.

   > 설계서 §6 이 지목한 현실: `AppStateSchema` 는 런타임에서 **한 번도 실행되지 않고**
   > (`schema.ts:116-117` 이 스스로 그렇게 적어 뒀다), 실제 방어는 손코딩 `validShape()`
   > **5줄**(`persistence.ts:193`)이며 배열 내부는 완전 무검증이다. 로컬에선 "내 파일만 연다"라
   > 수용 가능했지만 클라우드에선 아니다.

   ## 왜 명세에서 **파생**하는가

   테이블 목록·열 개수를 손으로 다시 적으면 이 저장소가 이미 두 번 물린 divergence 를 세 번째로
   사는 것이다(`rows.ts` ↔ `rows.rs` 쌍둥이). `OUTBOX_TABLES` 하나에서 파생시키면 테이블이
   늘어도 스키마가 **자동으로 따라온다**.

   ## 막는 것 (전부 조용히 파손되는 부류다)

   · `tbl` 이 자유 문자열 → 서버가 SQL 테이블명에 그대로 쓰면 **인젝션**이다.
   · `data` 길이 불일치 → **열이 밀린 채 upsert** 된다. 타입이 맞으면 SQL 은 성공하고,
     증상은 "왜 이 값이 저기 있지"로 한참 뒤에 나타난다.
   · `NaN`/`Infinity` 타임스탬프 → 워터마크 비교를 오염시켜 동기화가 멈추거나 폭주한다.
   · fence 계약 위반 → 클라이언트가 `since`~`upto` 밖의 행을 보내면 워터마크 전진이 거짓이 된다.
============================================================ */
import * as z from 'zod/mini';
import { MAX_BATCH_ITEMS, OUTBOX_TABLES, type OutboxBatch } from './contract';

/** 테이블 이름 → 명세. 길이 검사가 이걸 참조한다. */
const SPEC = new Map(OUTBOX_TABLES.map((t) => [t.name, t]));

const TABLE_NAMES = OUTBOX_TABLES.map((t) => t.name) as [string, ...string[]];

/** 동기화 대상 테이블 이름만 허용한다 — 서버가 이 값을 테이블명으로 쓰기 때문이다. */
export const TableNameSchema = z.enum(TABLE_NAMES);

/** 스탬프 상한 — 서기 2100(epoch ms). 실제 스탬프는 이보다 한참 아래이고, 이 위는 전부
 *  손상·악의다. 상한이 없으면 `1e18` 같은 거대 유한값이 통과해(`.int()` 는 유한하기만 하면 OK),
 *  `merge.ts` 의 `seedStamp` 래칫이 발급기를 그 값으로 끌어올려 `nextStamp` 이 **영원히 `_last+1`**
 *  만 내게 된다(벽시계 복귀 불가 · H5). 스키마 머리주석의 "타임스탬프 오염 차단"을 완성한다. */
const MAX_STAMP = 4102444800000;

/** epoch ms. `z.int()` 가 `NaN`·`Infinity`·소수를, `lte` 가 거대 미래값을 함께 걸러낸다.
 *  ⚠ mini 에서는 제약이 **메서드가 아니라 체크 함수**다(`.nonnegative()` → `z.nonnegative()`) —
 *  의미는 같고 붙이는 방식만 다르다(H28). */
const Stamp = z.int().check(z.nonnegative(), z.lte(MAX_STAMP));

export const OutboxRowSchema = z
  .strictObject({
    tbl: TableNameSchema,
    key: z.array(z.string()),
    /* 열 값은 텍스트·정수가 섞이고(`records.ord` 는 INTEGER) *어느 열이 어느 타입인가*는
       스키마가 아니라 **길이와 위치**가 계약이다(아래에서 길이를 검사한다).
       ⚠⚠ 그래도 `unknown` 이면 안 된다(2026-08-20 리뷰 m-10) — 서버가 이 값을 **그대로 D1 `.bind()` 에 넘긴다**
       (`server/src/index.ts` 의 push 핸들러). D1 은 `null|number|string|boolean|ArrayBuffer`
       만 받으므로 객체·배열이 섞이면 `bind()` 가 던지고, 그 오류는 `SCHEMA_SKEW` 정규식에도
       한도 정규식에도 안 걸려 **500** 으로 나간다. 클라이언트는 5xx 를 재시도 대상으로 읽으니
       백오프 5회 → `failed` → 워터마크 미전진 → **다음 동기화마다 같은 배치로 같은 500** 이다.
       신뢰 경계에서 원시값만 받으면 그 루프가 400(=`PermanentPushError`)으로 바뀌고 원인에
       이름이 붙는다. 우리 쪽 생산자(`db/rows.ts` 의 행 표현)는 전부 `string | number` 다. */
    data: z.array(z.union([z.string(), z.number(), z.boolean(), z.null()])),
    updatedAt: Stamp,
  })
  .check((ctx) => {
    /* ⚠ `superRefine` 은 mini 에 없다(H28) — `check` 가 같은 자리다. 다만 시그니처가 다르다:
       값은 `ctx.value` 로 오고, 이슈는 `ctx.addIssue(...)` 가 아니라 `ctx.issues.push(...)` 다
       (`input` 을 함께 실어야 한다 — classic 이 자동으로 채워 주던 필드). */
    const r = ctx.value;
    const spec = SPEC.get(r.tbl);
    if (!spec) return; // enum 이 이미 걸렀다(방어적)
    if (r.key.length !== spec.keyLen) {
      ctx.issues.push({
        code: 'custom',
        path: ['key'],
        message: `${r.tbl}: 기본키 ${spec.keyLen}개여야 하는데 ${r.key.length}개`,
        input: ctx.value,
      });
    }
    const dataLen = spec.cols.length - spec.keyLen;
    if (r.data.length !== dataLen) {
      ctx.issues.push({
        code: 'custom',
        path: ['data'],
        message: `${r.tbl}: 데이터 열 ${dataLen}개여야 하는데 ${r.data.length}개`,
        input: ctx.value,
      });
    }
  });

export const OutboxTombSchema = z
  .strictObject({
    tbl: TableNameSchema,
    k1: z.string(),
    /** 단일키 테이블은 빈 문자열(db.rs v3 규약). */
    k2: z.string(),
    deletedAt: Stamp,
  })
  .check((ctx) => {
    const t = ctx.value;
    const spec = SPEC.get(t.tbl);
    if (spec && spec.keyLen === 1 && t.k2 !== '') {
      ctx.issues.push({
        code: 'custom',
        path: ['k2'],
        message: `${t.tbl}: 단일키 테이블인데 k2 가 비어 있지 않다`,
        input: ctx.value,
      });
    }
  });

export const OutboxBatchSchema = z
  .strictObject({
    since: Stamp,
    upto: Stamp,
    rows: z.array(OutboxRowSchema),
    tombstones: z.array(OutboxTombSchema),
  })
  .check((ctx) => {
    const b = ctx.value;
    if (b.upto < b.since) {
      ctx.issues.push({
        code: 'custom',
        path: ['upto'],
        message: `upto(${b.upto}) 가 since(${b.since}) 보다 작다`,
        input: ctx.value,
      });
    }
    /* ⚠⚠ **건수 상한은 여기 없다 — `parseOutboxBatch`(송신 전용)가 소유한다.**

       종전엔 이 스키마가 `total > MAX_BATCH_ITEMS` 를 거부했고, `parseInboundBatch` 가 같은
       스키마를 **수신에도** 썼다. 그런데 서버는 상한을 **정당하게** 넘길 수 있다: 같은 스탬프
       그룹은 쪼개면 유실이 나므로 `pull.ts` 의 `fetchGroup` 이 통째로 주고, `capBatch` 의
       `taken > 0` 가드가 첫 그룹을 상한 초과해도 담는다(그 신호 `oversized` 를 pull 라우트가
       읽지 않는다). 즉 **서버가 계약대로 보낸 것을 클라이언트가 거부**하는 구조였다.

       그때의 귀결이 최악이다 — `pullChanges` 가 던지고 `isPermanent` 는 거짓이라 `run.ts` 가
       `failed` 로 접는데, 그러면 `commitPullMark` 에 도달하지 못해 **`since` 가 영원히 그
       자리**다. 다음 트리거마다 같은 배치를 받아 같은 자리에서 죽고 자가복구 경로가 없다.

       도달 조건은 가설이 아니다: `migrations/006_backfill_stamps.sql` 이 7개 테이블의 레거시
       행 전량을 `updated_at = 1` **상수**로 올린다(시계를 안 쓰는 것은 옳은 결정이다). 그래서
       레거시 행 전체가 **단일 스탬프 그룹**이고, 그 합이 상한을 넘는 기기에서 두 번째 기기의
       첫 전량 pull 이 영구 실패한다.

       이건 push 축이 `chunkBatch`(H2)로 이미 고친 결함의 수신 방향 판박이다 — **상한은 보내는
       쪽 계약**이지 받는 쪽 계약이 아니다. fence·열 개수·k2 규약·스탬프 상한은 한 글자도
       느슨해지지 않는다(관용은 *건수*에만 있고 *내용*엔 없다). */
    /* fence 계약 — 모든 항목이 (since, upto] 안에 있어야 한다. 밖의 행이 섞이면 워터마크를
       upto 로 전진시키는 순간 그 행이 "보냈다"고 잘못 기록되거나, 반대로 영영 안 올라간다. */
    for (const [i, r] of b.rows.entries()) {
      if (r.updatedAt <= b.since || r.updatedAt > b.upto) {
        ctx.issues.push({
          code: 'custom',
          path: ['rows', i],
          message: `updatedAt ${r.updatedAt} 이 (${b.since}, ${b.upto}] 밖이다`,
          input: ctx.value,
        });
      }
    }
    for (const [i, t] of b.tombstones.entries()) {
      if (t.deletedAt <= b.since || t.deletedAt > b.upto) {
        ctx.issues.push({
          code: 'custom',
          path: ['tombstones', i],
          message: `deletedAt ${t.deletedAt} 이 (${b.since}, ${b.upto}] 밖이다`,
          input: ctx.value,
        });
      }
    }
  });

export type ParsedOutboxBatch = z.infer<typeof OutboxBatchSchema>;

/**
 * 신뢰할 수 없는 입력을 배치로 파싱한다. **실패는 거부다** — 원본을 돌려주지 않는다.
 *
 * 서버가 요청 본문에 쓰고, 클라이언트도 보내기 직전 자기 페이로드에 쓴다. 후자가 이상해
 * 보이지만 값이 크다: **깨진 배치를 만드는 버그를 유선에 나가기 전에** 잡고, 서버와
 * 클라이언트가 **같은 계약**을 본다는 것을 테스트가 보장하게 된다.
 */
/* ============================================================
   ⚠⚠ **수신은 관용, 송신은 엄격**(H16 · 2026-07-30 `/감사 근본`).

   위 `OutboxBatchSchema` 는 `z.enum(TABLE_NAMES)` + `.strict()` 다. 그건 **서버가 받는 쪽**에선
   옳다(신뢰 경계 · 서버가 `tbl` 을 테이블명으로 쓴다). 그런데 클라이언트의 **pull** 도 같은
   스키마를 쓰고 있었고, 거기서는 정반대 결과를 낸다:

     다음 릴리스에서 `TABLES` 에 테이블이 하나 늘면 → 서버 pull 응답에 그 `tbl` 이 섞인다 →
     **아직 업데이트 안 한 데스크톱**이 배치를 통째로 throw → `pullMark` 가 전진하지 않는다 →
     **그 기기의 수신이 영구 정지**한다(표시는 `failed` 토스트 한 줄).

   버전 스큐는 우연이 아니라 **구조적**이다: 데스크톱 업데이터는 사용자 승인을 기다리고 폰 SW 는
   `autoUpdate` 다. 즉 두 기기가 서로 다른 스키마를 아는 창이 정상적으로 존재한다.

   지금은 무증상이고 **다음 스키마 추가가 방아쇠**다 — 그래서 지금 10줄이 나중에 "구버전 기기가
   조용히 죽는" 사고보다 싸다.

   ## 관용의 범위를 좁게 못박는다

   · 모르는 `tbl` 행/툼스톤은 **버린다**(경고와 함께). 우리가 모르는 테이블에 병합할 방법이 없다.
   · ⚠⚠ **열 개수가 다른 행도 버린다**(D002 · 2026-08-21). 종전엔 이 축이 빠져 있어서, 아는
     테이블의 열 구성이 바뀌면(009 가 실제로 그랬다) 관용 필터를 통과한 뒤 길이 검사에서
     **배치 전량이 거부**돼 같은 영구 정지가 났다. 관용을 «한 축만» 덮은 것이 결함이었다.
   · `upto` 는 **그대로 전진시킨다** — 버린 것은 "우리가 쓸 수 없는 것"이고, 다시 받아도 또 버린다.
     전진시키지 않으면 그 구간을 영원히 되묻는다(H2/2026-07-24 가 고친 정체와 같은 형태).
   · 그 외 검사는 **한 글자도 느슨해지지 않는다**: 살아남은 항목에 원래의 엄격 스키마를 그대로
     적용한다(스탬프 상한·열 개수·k2 규약·fence). 관용은 *경계*에만 있고 *내용*엔 없다.
   · ⚠ **배치 건수 상한은 애초에 이 스키마에 없다**(`parseOutboxBatch` 가 송신 전용으로 소유).
     종전 이 줄은 상한을 관용 예외 목록에 넣지 않아 "엄격하게 지킨다"고 말했는데, 그것이 바로
     pull 을 영구 정지시키던 원인이었다 — 근거는 `OutboxBatchSchema` 안의 ⚠⚠ 블록.
   ============================================================ */
export function parseInboundBatch(
  input: unknown,
): { ok: true; batch: OutboxBatch; dropped: number } | { ok: false; error: string } {
  const env = z
    .object({
      since: Stamp,
      upto: Stamp,
      rows: z._default(z.array(z.unknown()), []),
      tombstones: z._default(z.array(z.unknown()), []),
    })
    /* ⚠ `.strict()` 를 쓰지 않는다 — 서버가 배치 객체에 **새 필드**를 더해도(진단용 메타 등)
       구버전 클라이언트가 죽지 않아야 한다. 모르는 필드는 여기서 조용히 사라진다. */
    .safeParse(input);
  if (!env.success) return { ok: false, error: `서버 응답 봉투가 계약과 다릅니다 — ${issueLine(env.error)}` };

  /* ⚠⚠ **열 개수 축도 관용의 대상이다**(D002 · 2026-08-21 데이터 축).

     종전 필터는 `tbl` 만 봤다. 그래서 «아는 테이블인데 열 구성이 다른» 행은 필터를 통과한 뒤
     아래 엄격 스키마의 길이 검사에 걸려 **배치 전체가 거부**됐다 — 즉 `known` 이 막으려던
     바로 그 결말(수신 영구 정지)이 다른 축으로 그대로 났다.

     가설이 아니다. 009 가 `summaries` 를 `['sid','ord','value']` → `['sid','id','ord','value']`
     로 바꿨고, 그 마이그레이션이 지시하는 배포 순서는 «D1 먼저, 앱 나중»이다. 그 창에서
     구버전 데스크톱이 pull 하면 정확히 이 경로를 탄다. 스키마 추가만이 아니라 **기존 표의
     열 변경**도 같은 창을 연다 — 그리고 후자가 실제로 한 번 지나갔다.

     관용의 범위는 종전과 같다: 버리고 · `upto` 는 전진시키고 · 살아남은 것에는 한 글자도
     느슨하지 않은 검사를 적용한다. */
  const knownRow = (v: unknown): boolean => {
    const r = v as { tbl?: unknown; key?: unknown; data?: unknown } | null;
    const spec = typeof r?.tbl === 'string' ? SPEC.get(r.tbl) : undefined;
    if (!spec) return false;
    if (!Array.isArray(r?.key) || r.key.length !== spec.keyLen) return false;
    return Array.isArray(r?.data) && r.data.length === spec.cols.length - spec.keyLen;
  };
  /* 툼스톤은 열 구성이 `(tbl,k1,k2,deletedAt)` 로 고정이라 표의 열이 바뀌어도 형태가 안 변한다
     — 그래서 여기서는 `tbl` 만 본다(k2 규약은 아래 엄격 스키마가 그대로 지킨다). */
  const knownTomb = (v: unknown): boolean => {
    const t = (v as { tbl?: unknown } | null)?.tbl;
    return typeof t === 'string' && SPEC.has(t);
  };
  const rows = env.data.rows.filter(knownRow);
  const tombstones = env.data.tombstones.filter(knownTomb);
  const dropped = env.data.rows.length - rows.length + (env.data.tombstones.length - tombstones.length);

  // 살아남은 것에는 **원래의 엄격 스키마**를 그대로 적용한다.
  const strict = OutboxBatchSchema.safeParse({ since: env.data.since, upto: env.data.upto, rows, tombstones });
  if (!strict.success) return { ok: false, error: `서버 응답이 계약과 다릅니다 — ${issueLine(strict.error)}` };
  return { ok: true, batch: strict.data as OutboxBatch, dropped };
}

/** zod 이슈를 한 줄로 — 상위 5개만(전량은 로그가 페이로드만큼 커진다). */
function issueLine(e: z.core.$ZodError): string {
  return e.issues
    .slice(0, 5)
    .map((i) => `${i.path.join('.') || '(루트)'}: ${i.message}`)
    .join(' · ');
}

export function parseOutboxBatch(input: unknown): { ok: true; batch: OutboxBatch } | { ok: false; error: string } {
  const r = OutboxBatchSchema.safeParse(input);
  // 상위 5개만 — 전량을 늘어놓으면 로그가 페이로드만큼 커진다(`artifacts.ts:52` 와 같은 판단).
  if (!r.success) return { ok: false, error: issueLine(r.error) };
  /* ⚠ 건수 상한은 **여기**에만 있다(송신 전용). 근거는 `OutboxBatchSchema` 안의 ⚠⚠ 블록 —
     수신에서 거부하면 그 기기의 pull 이 영구 정지한다. 넘는 배치는 서버 CPU 한도에서 어차피
     죽는데 거기서 죽으면 원인이 "타임아웃"으로 보이므로, 보내기 전에 이름 붙여 거부한다. */
  const total = r.data.rows.length + r.data.tombstones.length;
  if (total > MAX_BATCH_ITEMS) return { ok: false, error: `배치가 상한을 넘었다: ${total} > ${MAX_BATCH_ITEMS}` };
  return { ok: true, batch: r.data as OutboxBatch };
}

/* ============================================================
   dayPlans.ts — 일일 배치 오버라이드(계획개편 §4·§6)의 순수 CRUD·선택자.
   자동엔진(schedule)은 제안자, dayPlans[ds]가 그날 배치의 진리(mode:'manual'). 첫 편집 시
   자동초안을 스냅샷해 승격(§6-3 자동초안을 잃지 않게) → 그 위에서 시간박기/추가/핀/삭제.
   applyDayPlans(scheduler)가 manual인 날 day.items를 이 블록으로 치환하고, layoutDay가 start를 존중.
   변형 헬퍼는 스토어 mutate 안에서 호출(→ persist), 컴포넌트는 blocksForDay 등 선택자로 파생만 읽는다.
============================================================ */
import { completionKey } from './domainKeys';
import { rid, clamp, reviewBlockMin } from './utils';
import type { AppState, DayPlan, PlacedBlock, ScheduleResult } from './types';

/** 시간박기 스냅 격자(분) — 드래그·리사이즈·시각 입력 공통. */
export const SNAP = 15;
/** 15분 격자로 스냅. */
export function snap(min: number): number {
  return Math.round(min / SNAP) * SNAP;
}

/** 드롭 충돌 해소(§6-2 "겹치면 밀거나 거부") — 요청 시각에서 occupied 구간과 겹치면 그 구간 끝으로 밀고,
 *  그래도 dayMax를 넘겨 못 들어가면 null(거부). occupied=[start,end][](고정 일과·타임박스 카드, 드래그 대상 제외).
 *  순수 함수라 단위 테스트 가능 — 컴포넌트는 occupied를 빚어 넘기고 결과 시각으로 placeBlock/placeTask. */
export function resolveSlot(
  occupied: [number, number][],
  requested: number,
  dur: number,
  dayMax = 1440,
): number | null {
  let s = clamp(snap(requested), 0, Math.max(0, dayMax - dur));
  const sorted = [...occupied].filter(([a, b]) => b > a).sort((a, b) => a[0] - b[0]);
  let moved = true;
  let guard = 0;
  while (moved && guard++ < 500) {
    moved = false;
    for (const [os, oe] of sorted) {
      if (s < oe && s + dur > os) {
        // 겹침 → 그 구간 끝으로 밀기
        s = snap(oe);
        moved = true;
      }
    }
  }
  return s + dur <= dayMax ? s : null; // 끝까지 밀어도 안 들어가면 거부
}

/* ── 자동초안 스냅샷 ──────────────────────────────────────────────────────
   그날 자동 산출(res.days[ds].items)을 PlacedBlock[]로 굳힌다. start 미부여(미지정=트레이) —
   승격 직후엔 layoutDay가 auto-pack하므로 화면 무변, 사용자가 시간박기하면 그 블록만 고정된다.
   id는 (ds·sid·type·i) 결정론 — blocksForDay 프리뷰(미승격)와 승격 후 id가 일치해 드래그 연속성 보존. */
export function snapshotAutoDraft(res: ScheduleResult, ds: string): PlacedBlock[] {
  const day = (res.days || []).find((d) => d.ds === ds);
  if (!day) return [];
  return day.items.map((it, i) => ({
    id: `${ds}:${it.sid}:${it.type}:${i}`,
    type: it.type,
    sid: it.sid,
    name: it.name,
    /* ⚠ **색을 굳히지 않는다(H13 · 2026-07-31 `/감사 근본`).** 이 스냅샷은 승격되면 그대로
       저장되므로, 여기 hex 를 실으면 절대규칙 #3("색 = 파생물 · 저장값 아님")이 승격된 블록에
       대해 거짓이 된다 — 노브 교체가 그 블록에 영원히 도달하지 않는다. 렌더는 `sid` 로 다시
       뽑는다(`lib/utils.blockColor`). 필드는 타입에 남지만 **여기서 채우지 않는다**. */
    min: it.min,
    chapters: it.chapters ? it.chapters.slice() : undefined,
  }));
}

/* ── 선택자(순수 파생 · 읽기 전용) ────────────────────────────────────── */

/** 그날이 수동(사용자 소유)인가. */
export function isManual(state: AppState, ds: string): boolean {
  return state.dayPlans?.[ds]?.mode === 'manual';
}
/** 그날 편집 대상 블록 — 수동이면 저장된 블록, 아니면 자동초안 스냅샷(읽기 프리뷰). */
export function blocksForDay(state: AppState, res: ScheduleResult, ds: string): PlacedBlock[] {
  const dp = state.dayPlans?.[ds];
  return dp && dp.mode === 'manual' ? dp.blocks : snapshotAutoDraft(res, ds);
}
/** 미지정(트레이) 블록 — 시각 없음. 드래그로 시각 부여 대상. */
export function untimedBlocks(blocks: PlacedBlock[]): PlacedBlock[] {
  return blocks.filter((b) => b.start == null);
}
/** 타임박스된 블록 — 시각 있음. 캘린더에 카드로 렌더(시각순). */
export function timedBlocks(blocks: PlacedBlock[]): PlacedBlock[] {
  return blocks.filter((b) => b.start != null).sort((a, b) => a.start! - b.start!);
}

/* ── 변형(스토어 mutate 안에서 호출 · 이후 persist) ───────────────────── */

/** 수동 승격(§6-3) — 첫 편집 시 자동초안 스냅샷으로 dayPlans[ds] 생성. 이미 수동이면 그대로 반환.
 *  res는 스냅샷 원본(호출부가 현재 useSchedule 결과 주입). 승격 자체는 화면을 바꾸지 않는다. */
export function ensureManual(state: AppState, res: ScheduleResult, ds: string): DayPlan {
  const plans = (state.dayPlans = state.dayPlans || {});
  let dp = plans[ds];
  if (!dp || dp.mode !== 'manual') {
    dp = plans[ds] = { mode: 'manual', blocks: snapshotAutoDraft(res, ds) };
    // 승격 시점에 sid|type 완료가 있으면 그 블록의 done을 시딩(승격 직후 체크가 풀려 보이지 않게).
    // 승격 시엔 sid|type당 블록이 1개(자동 스냅샷)라 매핑이 모호하지 않다.
    const day = state.completions?.[ds];
    if (day) for (const b of dp.blocks) if (day[b.sid + '|' + b.type]?.done) b.done = true;
  }
  return dp;
}

/** sid|type 집계 완료(completions) 재계산 — 그날 같은 sid|type 블록들의 done을 OR/합으로 미러링.
 *  하류(스케줄러 복습씨앗·통계·.ics)는 이 집계만 읽으므로 블록별 done을 두고도 무변경으로 굴러간다. */
function syncBlockCompletion(state: AppState, ds: string, sid: string, type: string, todayIso: string): void {
  const dp = state.dayPlans?.[ds];
  if (!dp || dp.mode !== 'manual') return;
  const done = dp.blocks.filter((b) => b.sid === sid && b.type === type && b.done);
  const comps = (state.completions = state.completions || {});
  const day = (comps[ds] = comps[ds] || {});
  const key = completionKey(sid, type);
  if (done.length) {
    const min = done.reduce((t, b) => t + b.min, 0);
    day[key] = { done: true, min: Math.round(min), doneDs: todayIso };
  } else {
    delete day[key];
    if (!Object.keys(day).length) delete comps[ds];
  }
}

/** 블록별 완료 토글(수동 날) — 그 블록의 done을 세팅하고 sid|type 집계를 재계산.
 *  같은 과목·유형 여러 블록을 독립으로 체크할 수 있다(병합 제거의 짝 · §6-3 충돌 해소). */
export function setBlockDone(state: AppState, ds: string, id: string, on: boolean, todayIso: string): void {
  const dp = state.dayPlans?.[ds];
  if (!dp || dp.mode !== 'manual') return;
  const b = findBlock(dp, id);
  if (!b) return;
  if (on) b.done = true;
  else delete b.done;
  syncBlockCompletion(state, ds, b.sid, b.type, todayIso);
}

function findBlock(dp: DayPlan, id: string): PlacedBlock | undefined {
  return dp.blocks.find((b) => b.id === id);
}

/** 시간박기 — 블록에 start 부여(스냅 15분, 0..1440 클램프). 필요 시 수동 승격. */
export function placeBlock(state: AppState, res: ScheduleResult, ds: string, id: string, start: number): void {
  const dp = ensureManual(state, res, ds);
  const b = findBlock(dp, id);
  if (b) b.start = clamp(snap(start), 0, 1440 - SNAP);
}
/** 미지정 복귀 — start 제거(캘린더→트레이). */
export function unplaceBlock(state: AppState, res: ScheduleResult, ds: string, id: string): void {
  const dp = ensureManual(state, res, ds);
  const b = findBlock(dp, id);
  if (b) delete b.start;
}
/** 길이 변경(분, 15 스냅, 최소 15). */
export function resizeBlock(state: AppState, res: ScheduleResult, ds: string, id: string, min: number): void {
  const dp = ensureManual(state, res, ds);
  const b = findBlock(dp, id);
  if (b) b.min = Math.max(SNAP, snap(min));
}
/** 핀 토글(§6-2) — 핀 블록은 '다시 자동으로' 재초안에서 보존 대상 플래그. */
export function togglePin(state: AppState, res: ScheduleResult, ds: string, id: string): void {
  const dp = ensureManual(state, res, ds);
  const b = findBlock(dp, id);
  if (b) b.pinned = !b.pinned;
}
/** 블록 추가(공부/복습/Anki/백지/모의) — id 자동 부여. 필요 시 수동 승격. */
export function addBlock(
  state: AppState,
  res: ScheduleResult,
  ds: string,
  block: Omit<PlacedBlock, 'id'>,
): PlacedBlock {
  const dp = ensureManual(state, res, ds);
  const b: PlacedBlock = { ...block, id: rid() };
  dp.blocks.push(b);
  return b;
}

/** 공부 블록 추가하되 같은 sid|type 블록이 이미 있으면 min·챕터 병합(§6-3 완료 충돌 방지 —
 *  완료 키가 sid|type이라 같은 날 2블록이면 한 체크가 둘 다 토글되는 충돌이 난다). 반환=대상 블록. */
export function addOrMergeBlock(
  state: AppState,
  res: ScheduleResult,
  ds: string,
  block: Omit<PlacedBlock, 'id'>,
): { block: PlacedBlock; merged: boolean } {
  const dp = ensureManual(state, res, ds);
  const ex = dp.blocks.find((b) => b.sid === block.sid && b.type === block.type);
  if (ex) {
    ex.min += block.min;
    if (block.chapters) {
      ex.chapters = ex.chapters || [];
      for (const c of block.chapters) if (!ex.chapters.includes(c)) ex.chapters.push(c);
    }
    return { block: ex, merged: true };
  }
  return { block: addBlock(state, res, ds, block), merged: false };
}
/** 블록 삭제 — 수동인 날만. */
export function removeBlock(state: AppState, ds: string, id: string): void {
  const dp = state.dayPlans?.[ds];
  if (dp && dp.mode === 'manual') dp.blocks = dp.blocks.filter((b) => b.id !== id);
}
/** 다시 자동으로(§6-2) — dayPlans[ds] 제거해 자동 산출로 되돌린다. 핀 있으면 핀 블록만 남기고 재초안.
 *  (자유 할 일 tasks는 사용자 소유라 리셋 대상 아님 — 별도 리스트.) */
export function resetDay(state: AppState, ds: string): void {
  const plans = state.dayPlans;
  if (!plans || !plans[ds]) return;
  const pinned = plans[ds]!.blocks.filter((b) => b.pinned);
  if (pinned.length) plans[ds] = { mode: 'manual', blocks: pinned };
  else delete plans[ds];
}

/* ── 고아 sid 청소(과목 삭제 경로) ────────────────────────────────────────
   과목을 지워도 dayPlans[ds].blocks[].sid는 승격된 모든 날에 그대로 남는다(참조 무결성 없는 구조).
   그 잔재는 blocksForDay를 타고 배치·캘린더에 '연결된 과목이 없는 유령 블록'으로 뜨고,
   applyDayPlans가 그걸 day.items로 되돌려 used·주별시간·통계까지 오염시킨다.
   weekAlloc의 removeSidFromAlloc와 대칭 — 삭제 경로에서 둘을 함께 부른다. */

/** 한 과목의 블록을 전 dayPlans에서 제거하고 그 sid의 completions 고아 키까지 정리 — 과목 삭제 경로 전용.
 *
 *  **빈 날은 키째 삭제(auto 복귀).** 이 청소로 블록이 하나도 안 남은 날에 `{mode:'manual',blocks:[]}`를
 *  남기면 applyDayPlans가 그날 `d.items=[]`·`d.used=0`으로 치환해 **자동 스케줄이 죽는다**
 *  — "manual 날이 없으면 자동 산출 100% 불변"(결정로그 §계획개편)의 정반대. weekAlloc이 빈 주 객체를
 *  키째 지우는 것(removeSidFromAlloc)과 같은 판단이다. 단 **원래부터 비어 있던 날은 손대지 않는다**:
 *  그건 사용자가 손수 비운 '쉬는 날' 의사표시라 이 과목 삭제와 무관하다(실제로 지운 날만 정리).
 *
 *  **completions는 전 날짜에서 그 sid의 키를 지운다.** setBlockDone→syncBlockCompletion이 블록 done을
 *  `completions[ds]['sid|type']`로 미러링하므로, 블록만 지우면 그 집계 키가 고아로 남아
 *  완료 분(adherenceFactor·통계·연속일수)을 계속 부풀린다. 과목이 사라진 이상 그 sid의 완료는 manual/auto
 *  어느 날에서도 의미가 없으므로 날짜 전체를 훑어 지우고, 빈 날 객체는 syncBlockCompletion과 같은 규칙으로
 *  키째 정리한다. 남는 다른 sid의 집계는 sid|type로 분리돼 있어 재계산이 필요 없다.
 *
 *  @returns 정리한 개수(지운 블록 수 + 지운 완료 키 수). state 변형. */
/* ⚠ 두 저장소를 **따로** 훑는다(2026-08-20 리뷰 M-14 원장 축소). 수동 배치와 완료 기록은
   서로를 모르고 각자 다른 모양으로 그 과목을 담는다 — 한 함수에 뭉치면 중첩 루프 넷이 된다. */

/** 수동 배치에서 그 과목 블록을 뺀다. 빈 manual 날은 **키째** 지운다 — 빈 manual 은 자동
 *  스케줄이 죽은 상태라 그대로 두면 그날이 통째로 사라진다(`isWeekManaged` 와 같은 함정). */
function purgeFromPlans(state: AppState, sid: string): number {
  const plans = state.dayPlans;
  if (!plans) return 0;
  let n = 0;
  for (const ds in plans) {
    const dp = plans[ds];
    if (!dp || dp.mode !== 'manual' || !dp.blocks.length) continue;
    const before = dp.blocks.length;
    dp.blocks = dp.blocks.filter((b) => b.sid !== sid);
    const removed = before - dp.blocks.length;
    if (!removed) continue;
    n += removed;
    if (!dp.blocks.length) delete plans[ds];
  }
  return n;
}

/** 완료 기록에서 그 과목의 키(`sid|type`)를 뺀다. 빈 날은 키째 정리한다. */
function purgeFromCompletions(state: AppState, sid: string): number {
  const comps = state.completions;
  if (!comps) return 0;
  let n = 0;
  const prefix = completionKey(sid, '');
  for (const ds in comps) {
    const day = comps[ds];
    if (!day) continue;
    for (const key in day)
      if (key.startsWith(prefix)) {
        delete day[key];
        n++;
      }
    if (!Object.keys(day).length) delete comps[ds];
  }
  return n;
}

export function removeSidFromDayPlans(state: AppState, sid: string): number {
  return purgeFromPlans(state, sid) + purgeFromCompletions(state, sid);
}

/** 블록 유형별 기본 길이(분) — 모듈 길이에서 파생. '+ 블록 추가'가 쓰는 프리셋.
 *  왜 lib인가: 이건 화면 장식이 아니라 도메인 규칙(복습=모듈의 1/4, 백지=2/5 …)이라
 *  블록 CRUD 옆이 제자리다. 예전엔 DayPlanner 컴포넌트 본문에 인라인이라 테스트도 재사용도 불가했다. */
export function blockMinPresets(moduleLen: number): Record<string, number> {
  const ML = moduleLen || 120;
  return {
    new: ML,
    rev: reviewBlockMin(ML),
    anki: 20,
    blank: Math.max(30, Math.round(ML * 0.4)),
    mock: ML,
  };
}

/* ============================================================
   db/browserDb.ts — 폰용 SQLite 백엔드(C-6a). 워커의 메인 스레드 쪽 절반.

   ## 이 파일이 존재하는 이유 — 두 번째 구현을 만들지 않기 위해

   `cloud/outbox.ts` · `merge.ts` · `run.ts` · `client.ts` 는 전부 **SQL 문자열**을
   `selectDb`/`execDb` 로 흘려보낸다. 폰을 붙이는 방법은 둘이었다:

   | 방법 | 대가 |
   | --- | --- |
   | 동기화 층을 인터페이스로 추상화 → IndexedDB 로 재구현 | LWW 비교·툼스톤 순서·fence 의미론을 **두 번째로** 손코딩 |
   | **`Db` 인터페이스에 브라우저 구현을 하나 더 끼운다** | wasm 의존 + OPFS 가용성 |

   후자를 골랐다. 이 저장소는 쌍둥이 구현으로 **두 번** 물렸고(`rows.ts`↔`rows.rs`,
   경계 파서 2종), 둘 다 "각 구현은 자기 테스트를 통과하는데 둘이 갈라져 있었다"는 형태였다.
   여기서 갈리면 그 결과는 **동기화 유실**이라 대가가 훨씬 크다. 이 방식이면 검증된 SQL 이
   폰에서 **문자 그대로** 돈다 — `roundtrip` 과 `restoreDrill` 이 검사하는 그 경로다.

   ⚠ **`sqlite.ts` 의 `Db` 인터페이스와 모양이 같아야 한다**(`execute`/`select`). 그게 이
   교체가 성립하는 유일한 근거다.
============================================================ */
import type { DbRequest, DbResponse } from './sqlite.worker';

interface Db {
  execute(query: string, values?: unknown[]): Promise<unknown>;
  select<T>(query: string, values?: unknown[]): Promise<T>;
  /** 여러 문장을 한 왕복으로(H-1). 워커에선 트랜잭션으로 감싸 **원자적**이다. */
  batch(stmts: { sql: string; args: unknown[] }[]): Promise<void>;
}

/** OPFS 를 못 잡아 인메모리로 내려갔는가. 화면이 이 사실을 말해야 한다(워커 머리주석). */
let _durable = false;
export function isDurable(): boolean {
  return _durable;
}

let _seq = 0;
const _waiting = new Map<number, { resolve: (r: DbResponse) => void; reject: (e: Error) => void }>();

/** 한 왕복의 응답 시간 상한(H5). 워커가 open 성공 뒤 죽으면 이후 요청은 응답도 `onerror`(1회성)도
 *  못 받아 **영원히 대기**한다(폰 무음 정지). wasm SQLite 연산은 밀리초대라 넉넉히 잡아도 안전. */
const CALL_TIMEOUT_MS = 30_000;

/* ⚠ `Omit<DbRequest,'id'>` 는 여기서 틀린다 — 유니온에 그냥 걸면 **공통 속성만 남아**
   `sql`·`bind` 가 사라진다. 조건부 타입으로 감싸야 각 갈래에 개별 적용된다(분배 법칙). */
type WithoutId<T> = T extends unknown ? Omit<T, 'id'> : never;

/* ============================================================
   워커 수명 — **죽었으면 확실히 죽인다**(H13 · 2026-07-30 `/감사 근본`)

   종전엔 이 파일에 `terminate()` 가 **한 번도 없었다**(전 저장소 0건). 결과가 둘이다:

   ① **좀비가 OPFS 락을 쥔다.** 워커가 멎어도(무한 루프·wasm 트랩) 컨텍스트는 살아 있어
      `FileSystemSyncAccessHandle` 을 놓지 않는다. 그 상태로 새 워커를 세우면 SAH 풀을 못 잡아
      **조용히 `:memory:` 로 내려앉는다** — 앱은 정상으로 보이고 저장만 사라진다.
      `terminate()` 는 컨텍스트를 파괴해 그 핸들을 브라우저가 회수하게 하는 유일한 수단이다.
   ② **모든 연산이 30초씩 매달린다.** 타임아웃은 *그 한 호출*만 거절했고 `_handle` 은 멀쩡한
      채였다 → 다음 호출이 같은 죽은 워커에 또 붙어 또 30초를 기다린다. `onerror` 는 핸들을
      무효화하지만 그건 **로드 실패에만** 오고, 열린 뒤 멎는 경우는 그 이벤트가 아예 안 온다.

   그래서 죽이는 자리를 하나로 모은다. 타임아웃은 "느린 연산"이 아니라 **죽음의 증거**로 다룬다 —
   wasm SQLite 연산은 밀리초대라 30초는 정상 범위가 아니고, 오판해도 대가는 워커 재기동뿐이다
   (같은 DB 를 다시 연다). 반대로 안 죽이면 대가가 무음 `:memory:` 다 — 비대칭이 명확하다. */
let _worker: Worker | null = null;

function killWorker(reason: string): void {
  const w = _worker;
  _worker = null;
  _handle = null;
  _durable = false; // 새 워커가 OPFS 를 다시 잡기 전까지 "내구성 있다"고 말하면 안 된다
  for (const [, p] of _waiting) p.reject(new Error(reason));
  _waiting.clear();
  /* ⚠ 마지막에 죽인다 — 먼저 죽이면 대기자들이 이유 없이 매달린 채 남는다. */
  w?.terminate();
}

function call(worker: Worker, req: WithoutId<DbRequest>): Promise<DbResponse> {
  const id = ++_seq;
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      /* ⚠ 이 호출만 거절하지 않는다(H13) — 응답이 없다는 것은 워커가 멎었다는 뜻이고, 그대로
         두면 이후 모든 연산이 30초씩 매달리며 좀비가 OPFS 락을 계속 쥔다. */
      if (_waiting.has(id)) killWorker('SQLite 워커 응답 시간 초과 — 워커를 재기동합니다.');
      else reject(new Error('SQLite 워커 응답 시간 초과 — 워커가 죽었을 수 있습니다.'));
    }, CALL_TIMEOUT_MS);
    _waiting.set(id, {
      resolve: (r) => {
        clearTimeout(timer);
        resolve(r);
      },
      reject: (e) => {
        clearTimeout(timer);
        reject(e);
      },
    });
    worker.postMessage({ ...req, id } as DbRequest);
  });
}

let _handle: Promise<Db> | null = null;

/**
 * 폰용 SQLite 핸들(지연 로드·1회). 실패하면 **null** — 호출부는 `getDb()` 계약대로
 * "DB 미가용"으로 다룬다(`selectDb` 가 null 을 "모름"으로 취급하는 그 규약).
 */
export async function getBrowserDb(): Promise<Db | null> {
  _handle ??= (async (): Promise<Db> => {
    /* ⚠ 새 워커를 세우기 전에 **직전 것을 반드시 죽인다**(H13). `_handle` 만 null 로 두면
       옛 워커가 살아남아 OPFS 핸들을 쥔 채 새 워커와 경합한다 — 그 결과가 무음 `:memory:` 다. */
    if (_worker) killWorker('SQLite 워커를 재기동합니다.');
    const worker = new Worker(new URL('./sqlite.worker.ts', import.meta.url), { type: 'module' });
    _worker = worker;
    worker.onmessage = (ev: MessageEvent<DbResponse>): void => {
      const w = _waiting.get(ev.data.id);
      if (!w) return;
      _waiting.delete(ev.data.id);
      if (ev.data.ok) w.resolve(ev.data);
      else w.reject(new Error(ev.data.error));
    };
    /* 워커가 통째로 죽으면(스크립트 로드 실패·wasm 미지원) 대기 중인 약속이 **영원히 안
       풀린다** — 그러면 부팅이 멈춘 채 화면이 아무 말도 안 한다. 전부 깨워서 실패시킨다.
       ⚠ `_handle` 도 무효화한다(H5) — 안 하면 다음 `getBrowserDb()` 가 **죽은 워커를 쥔 핸들**을
       그대로 돌려줘 이후 모든 요청이 타임아웃까지 매달린다. null 로 두면 다음 호출이 새 워커를
       세운다(`getBrowserDb` 의 `_handle ??=`). */
    worker.onerror = (): void => killWorker('SQLite 워커가 죽었습니다.');

    const opened = await call(worker, { kind: 'open' });
    if (!opened.ok || opened.kind !== 'open') {
      // 못 열었으면 이 워커는 쓸모가 없다 — 남겨 두면 그대로 좀비다.
      killWorker('SQLite 를 열지 못했습니다.');
      throw new Error('SQLite 를 열지 못했습니다.');
    }
    _durable = opened.durable;

    return {
      async execute(query: string, values: unknown[] = []): Promise<unknown> {
        await call(worker, { kind: 'exec', sql: query, bind: values });
        return undefined;
      },
      async select<T>(query: string, values: unknown[] = []): Promise<T> {
        const r = await call(worker, { kind: 'select', sql: query, bind: values });
        if (!r.ok || r.kind !== 'select') throw new Error('select 응답이 계약과 다릅니다.');
        return r.rows as T;
      },
      async batch(stmts: { sql: string; args: unknown[] }[]): Promise<void> {
        // 워커 프로토콜은 `bind` 를 쓴다(`Db` 계약은 `args`) — 경계에서 맞춘다.
        await call(worker, { kind: 'batch', stmts: stmts.map((s) => ({ sql: s.sql, bind: s.args })) });
      },
    };
  })();

  try {
    return await _handle;
  } catch (e) {
    // `sqlite.ts` 와 같은 규약: 조용히 삼키지 않고, 한 번 실패가 영구 불능이 되지 않게 한다.
    console.error('[db] 폰 SQLite 초기화 실패 — 로컬 캐시 없이 돕니다.', e);
    /* ⚠ `_handle = null` 만으로는 부족하다(H13) — 실패한 워커가 살아남아 OPFS 핸들을 쥔다.
       `open` 이 **거절**로 끝나는 경로는 위 `if (!opened.ok)` 를 지나지 않으므로 여기가
       그 갈래의 유일한 정리 지점이다. */
    killWorker('폰 SQLite 초기화 실패');
    return null;
  }
}

/* ============================================================
   db/docs.ts — **AppState 에 속하지 않는 사용자 저작물**의 저장소(4단계-J).

   대상: 내 요약·독후감(`lh:reads`) · 진로 메모(`atlas.notes`) · 즐겨찾기(`atlas.stars`).
   2단계가 "사용자 저작물이라 정본과 같은 곳에 있는 게 맞다"고 적고 4단계로 미뤄 둔 항목이고,
   **5단계가 그 빚을 청구한다** — 모바일 뷰는 폰이 PC 의 SQLite 를 직접 읽는 모델이라
   localStorage 에 남은 저작물은 폰에서 **원리적으로 안 보인다**.

   ## ⚠ 동기 시그니처를 지켜야 한다 — 이게 이 파일의 설계 제약 전부다

   `loadReads()` 는 **동기**이고 팔레트·Reads 탭이 **렌더 경로에서** 부른다. SQLite 는 비동기라
   정면 충돌한다. 2단계-A 가 `AppState` 에서 같은 충돌을 만났을 때 고른 답을 그대로 쓴다:
   **부팅에 한 번 읽어 메모리에 올리고, 이후 읽기는 메모리에서 동기로 준다**(`preloadedState`
   와 같은 관용구). 쓰기만 비동기로 흘려보낸다.

   게이트 컴포넌트(로딩 플래그) 방식을 쓰지 않는 이유도 2단계-A 와 같다 — "하이드레이션 전에
   쓰기가 일어나면 기본값이 실데이터를 덮는" 새 실패 모드를 만들고, 그건 0단계-E 에서 이미 한 번
   물린 부류다(*낡은 메모리가 복원본을 덮는다*).

   ## 브라우저에선 그대로 localStorage 다

   `npm run dev` 와 트랙 A 는 Chromium 이라 SQLite 가 없다. `docGet`/`docSet` 이 그 분기를
   흡수하므로 **소비처(`reads.ts`·`sidecars.ts`)는 어디에 저장되는지 모른다.**
============================================================ */
import { storage } from '../kv';
import { isTauri } from '../isTauri'; // ⚠ 부팅 경로 — 초소형 모듈에서(H7 · `lib/isTauri.ts` 머리주석)
import { execDb, isSqlitePrimary, selectDb } from './sqlite';
import { runExclusive } from './write';
import { nextStamp } from './stamp';
import { pushUndo, type PreImageRow } from './undoStack'; // H3 — 저작물 쓰기도 ⌘Z 스택에 든다
import { markDbFallback, setSaveFallback } from './fallback'; // C2 — 저작물 쓰기 실패의 표면화

/* ── ⚠⚠ **세입자가 0이다**(P10 W4 · 2026-08-07) ────────────────────────────────
   이 표에는 다섯이 있었다: `lh:reads`(내 요약·독후감) · `atlas.notes`·`atlas.stars`(진로 지도
   메모·관심) · `artifact:reads`·`artifact:markets`(PC→폰 산출물 미러). **다섯 다 그 화면이
   `survey/` 필러로 가면서 사라졌다.**

   왜 배관은 남기나: `docs` 는 P10 이 만든 발판이 아니라 **앱 인프라**다(SQLite 표 · 클라우드
   `DOCS_SPEC.sync` · 아웃박스 · ⌘Z 프리이미지 · pull 뒤 `reloadDocs`). 세입자가 없다고 그것을
   걷으면 스키마 마이그레이션 + 서버 계약 + 왕복 테스트가 한 벌 더 필요한데, 그건 W4 의 범위
   (화면·아티팩트·Rust)가 아니고 되돌리기도 비싸다. 그래서 **빈 채로 두되 빈 것을 명시**한다.
   존치 근거·재검토일은 `docs/유예_원장.md` — 다음 저작물 키가 생기면 여기 한 줄이면 된다.

   ⚠ 빈 배열의 대가: `DocKey` 가 `never` 라 `docGet`/`docSet` 은 **전량 localStorage 로 흐른다**.
   즉 지금 이 파일은 *동작상* 얇은 KV 래퍼이고, SQLite 경로는 세입자가 돌아오는 순간 다시 산다.
   그 사실을 숨기지 않는 것이 요점이다(조용히 죽은 배관이 이 저장소가 반복해 만든 형태다).

   ✅ **세입자가 돌아왔다 — `ics:feed`**(N-7 · W8 · 2026-08-07). 위 문단이 예약한 "한 줄"이 이것이고,
   이 표가 왜 앱 인프라인지를 그 항목이 실증한다: 살아 있는 캘린더 구독은 **서버가 읽을 수 있는
   곳**에 계획을 놓아야 하는데, `docs` 는 이미 D1 까지 동기화되는 유일한 자유 KV 다
   (`cloud/contract.DOCS_SPEC`). 새 테이블·새 마이그레이션·새 인증 경로가 **전부 0**이고,
   Worker 는 이 한 행을 읽는 **공개 GET 하나**만 는다. 값의 형태는 `lib/icsFeed.ts` 가 소유한다. */
export const DOC_KEYS = ['ics:feed'] as const;
export type DocKey = (typeof DOC_KEYS)[number];

const isDocKey = (k: string): k is DocKey => (DOC_KEYS as readonly string[]).includes(k);

/** 부팅에 채우는 메모리 사본. `null` = 아직 안 읽음(브라우저이거나 초기화 전). */
let _cache: Map<string, string> | null = null;

/* ⚠ `updated_at` 을 **반드시 함께 쓴다**(5단계-D 결함 정정).
   `INSERT OR REPLACE` 는 행을 지우고 다시 넣으므로, 이 열을 빼면 매 저장마다
   `DEFAULT 0` 으로 되돌아간다. `db.rs` v3 이 **0 = "아주 오래된 것 = 상대가 이긴다"** 로
   규정했으니, 그대로 두면 LWW 병합에서 **PC 가 쓴 저작물이 폰 사본에게 항상 진다.**
   내 요약·독후감·진로 메모는 정본이 따로 없는 사용자 저작물이라 유실이 곧 소실이다.

   ⚠ 남은 갭 — `docs` 는 `rows.ts` 의 `TABLES` 에 없어 `diffRows` 가 손대지 않는다.
   즉 **툼스톤이 없다**(키를 지워도 삭제 사실이 안 남는다). 저작물 삭제는 드물고 지금은
   병합 엔진 자체가 없어 실害가 없지만, 5-F 전에 `TableSpec` 편입 또는 전용 동기화 경로를
   명시해야 한다. 이 파일이 `AppState` 매퍼와 분리된 이유는 `db.rs:76-78` 참조. */
const DOC_UPSERT = 'INSERT OR REPLACE INTO docs (key, value, updated_at) VALUES (?1, ?2, ?3)';

/** 부팅 시 1회 — DB 의 저작물을 메모리로 끌어올린다. 실패는 조용히 넘긴다(호출부가 localStorage 로 폴백).
 *
 *  ⚠ 조건이 **`isTauri()` 가 아니라 `isSqlitePrimary()`** 다(C-6 이 만든 구분 · CLAUDE.md 가
 *  경고한 그 부류). 폰은 Tauri 가 아닌데 SQLite 가 정본이라, `isTauri()` 로 막으면 동기화로
 *  내려온 `docs` 행을 **읽지도 쓰지도 못한다** — 읽기는 빈 화면이 되고 쓰기는 폰 localStorage 로
 *  새어 아웃박스에 안 걸린다(= 영원히 동기화되지 않는 편집). C-6 이 `AppState` 경로에서만
 *  이 조건을 바꾸고 `docs` 를 놓쳤다. */
export async function initDocs(): Promise<void> {
  if (!isSqlitePrimary()) return;
  const rows = await selectDb<{ key: string; value: string }>('SELECT key, value FROM docs');
  if (!rows) return; // DB 미가용 — _cache 를 null 로 두어 localStorage 경로가 살아 있게 한다
  const map = new Map(rows.map((r) => [r.key, r.value]));

  /* 1회 이관 — 빈 docs 를 "새 사용자"가 아니라 "아직 안 옮겨졌다"로 읽는다.
     `initAppStore` 가 `AppState` 에 대해 하는 것과 같은 판단이고, 안 하면 셸로 넘어온 사용자의
     **요약·독후감이 조용히 사라진 것처럼 보인다**(localStorage 엔 그대로 있는데 화면이 빈다).
     ⚠ 여기만은 **셸 전용**이다 — 폰의 빈 docs 는 "아직 클라우드에서 안 받았다"이지 이관 대상이
     아니고, 폰 오리진의 localStorage 에 뭔가 있다면 그건 **남의 데이터**다
     (`initPhoneStore` 가 `AppState` 에 대해 같은 이유로 이관을 안 하는 것과 짝). */
  if (map.size === 0 && isTauri()) {
    for (const k of DOC_KEYS) {
      const v = storage.getItem(k);
      if (v != null) {
        map.set(k, v);
        void execDb(DOC_UPSERT, [k, v, nextStamp()]);
      }
    }
  }
  _cache = map;
  /* ③ — 미지 키를 **지우지 않고 보고**한다(D005). 실 DB 에 51KB 가 도달 불가인 채 있었고,
     그 사실을 아는 코드가 어디에도 없었다. 판정은 화면(설정 › 진단)이 `unknownDocKeys()` 로
     한다 — 여기서 하는 일은 개발자 채널에 한 줄 남기는 것까지다(D006 의 교훈: 개발자 채널
     **만** 있으면 그건 아무도 모르는 것과 같다. 그래서 화면 쪽 짝을 함께 뒀다). */
  const 미지 = unknownDocKeys();
  if (미지.length) {
    console.warn(
      `[docs] 알려지지 않은 키 ${미지.length}개(${미지.reduce((a, b) => a + b.bytes, 0)}B) — 설정 › 진단에서 확인하세요.`,
      미지.map((d) => d.key),
    );
  }
}

/**
 * 병합으로 `docs` 행이 바뀐 뒤 메모리 사본을 다시 읽는다(H1).
 *
 * ⚠ `_cache` 는 **부팅에만** 채워진다(`initDocs`). pull 이 받아온 독후감·진로 메모·미러
 * 산출물을 SQLite `docs` 에 병합해도 이 사본은 낡은 채라, 폰 `ReadsView`(`readMirrored`→`docGet`)가
 * 받아온 것을 **다음 앱 재시작까지 못 본다** — C-6 의 "폰에서 읽을거리를 읽는다"를 직접 깎는다.
 * `applyPull` 이 `docs` 행을 병합했으면 이 함수로 사본을 되맞춘다. `initDocs` 와 달리 1회 이관
 * 분기는 없다(이관은 부팅의 관심사이고, 여기는 "받아온 것 반영"만 한다).
 */
export async function reloadDocs(): Promise<void> {
  if (!isSqlitePrimary()) return;
  const rows = await selectDb<{ key: string; value: string }>('SELECT key, value FROM docs');
  if (!rows) return; // DB 미가용 — 기존 사본 유지(빈 사본으로 덮어 화면을 비우지 않는다)
  _cache = new Map(rows.map((r) => [r.key, r.value]));
}

/* ============================================================
   ⚠⚠ **표는 비어 있지 않았다**(D005 · 2026-08-21 데이터 축).

   위 문단은 *"빈 채로 두되 빈 것을 명시한다"* 고 적었는데, 실 DB 를 읽으니 **3행 51,793 B**
   가 있었다: `lh:reads`(103 B · 사용자 저작물) · `artifact:reads`(40,834 B) ·
   `artifact:markets`(10,856 B). 셋 다 P10 W4 에서 화면이 `survey/` 로 가며 은퇴한 세입자다.

   그 셋의 상태가 **도달 불가**였다:
   · 읽을 수 없다 — `DOC_KEYS` 밖이라 `isDocKey` 가 false → `docGet` 이 localStorage 로 흐른다.
   · 지울 수 없다 — 전 저장소에 `DELETE FROM docs` 가 0건이었고, `docs` 는 `rows.ts` 의
     `TABLES` 밖이라 `diffRows` 가 DELETE 도 툼스톤도 만들지 못한다.
   · 그런데 나른다 — `OUTBOX_TABLES` 에 `DOCS_SPEC` 으로 들어 있어 이미 D1 에 밀렸고, pull 이
     폰 OPFS 로 같은 51KB 를 내린다. 매 부팅에 `initDocs` 가 메모리로도 올린다.

   ## 순서가 처방의 일부다

   ① **회수 먼저**(`exportAllDocs` → 백업 페이로드). ②를 먼저 하면 `lh:reads` — 사용자가 쓴
      글 — 이 회수 불가 상태로 사라진다. ② 삭제 경로(`docDelete`)는 **툼스톤을 먼저** 낸다
      (`contract.ts` 가 *"docs 에 삭제를 추가하는 커밋은 툼스톤을 같이 넣어야 한다"* 를 이미
      규칙으로 못박아 뒀다 — 안 그러면 다른 기기에서 지운 것이 되살아난다). ③ `initDocs` 는
      미지 키를 **지우지 않고 보고**한다(설정 › 진단).
   ⚠ 앱이 스스로 지우지 않는 것이 의도다. 판정 근거가 «`DOC_KEYS` 에 없다» 뿐인데, 그 목록은
     세입자가 오갈 때마다 바뀐다 — 자동 삭제를 달면 다음 리팩터가 사용자 저작물을 지운다.
============================================================ */

/** 백업 페이로드의 `docs` 필드명. `_local`·`_obs` 와 같은 **추가 키** 관용구. */
export const DOCS_FIELD = '_docs';

/** 백업용 — `docs` 표 **전량**(미지 키 포함). 회수 경로가 이 함수 하나다. */
export async function exportAllDocs(): Promise<Record<string, string>> {
  if (!isSqlitePrimary()) return {};
  const rows = await selectDb<{ key: string; value: string }>('SELECT key, value FROM docs');
  return Object.fromEntries((rows ?? []).map((r) => [r.key, r.value]));
}

/**
 * 가져오기 — `_docs` 블롭에서 **아는 키만** 되살린다. 복원한 키 수를 돌려준다.
 *
 * ⚠ 미지 키를 되쓰지 않는 것이 의도다. 파일에 담는 이유는 **회수**(사람이 읽을 수 있게)이고,
 * 표에 되돌려 놓으면 도달 불가 행을 그대로 재생산한다 — 그게 D005 가 고치는 상태다.
 */
export async function importDocs(v: unknown): Promise<number> {
  if (!v || typeof v !== 'object' || Array.isArray(v)) return 0;
  let n = 0;
  for (const [k, val] of Object.entries(v as Record<string, unknown>)) {
    if (!isDocKey(k) || typeof val !== 'string') continue;
    docSet(k, val);
    n += 1;
  }
  return n;
}

/** `DOC_KEYS` 밖에서 표에 남아 있는 키들(진단 표시용 · 지우지 않는다). */
export function unknownDocKeys(): { key: string; bytes: number }[] {
  if (!_cache) return [];
  return [..._cache.entries()]
    .filter(([k]) => !isDocKey(k))
    .map(([key, value]) => ({ key, bytes: new TextEncoder().encode(value).length }));
}

/**
 * 저작물 삭제 — **툼스톤을 먼저** 낸다.
 *
 * ⚠ 순서가 계약이다. `docs` 는 `TABLES` 밖이라 `diffRows` 가 삭제 사실을 만들어 주지 못하므로,
 * 여기서 안 내면 다른 기기의 pull 이 그 행을 다시 내려보내 **지운 것이 되살아난다**(G2 금지).
 * 툼스톤 쓰기가 실패하면 **행을 지우지 않는다** — 되살아나는 것보다 안 지워지는 편이 낫다.
 */
export async function docDelete(key: string): Promise<boolean> {
  if (!isSqlitePrimary()) {
    storage.removeItem(key);
    return true;
  }
  return runExclusive(async () => {
    const at = nextStamp();
    /* `DOCS_SPEC` 의 키는 (key) 하나 — `k2` 는 v3 규약대로 빈 문자열이다. */
    const marked = await execDb(
      `INSERT OR REPLACE INTO tombstones (tbl, k1, k2, deleted_at) VALUES ('docs', ?1, '', ?2)`,
      [key, at],
    );
    if (!marked) return false;
    const gone = await execDb('DELETE FROM docs WHERE key = ?', [key]);
    if (gone) _cache?.delete(key);
    return gone;
  });
}

/** 저작물 읽기(**동기**) — 셸이면 메모리, 아니면 localStorage. */
export function docGet(key: string): string | null {
  if (_cache && isDocKey(key)) return _cache.get(key) ?? null;
  return storage.getItem(key);
}

/**
 * 저작물 쓰기 — 셸이면 메모리 즉시 + DB 비동기, 아니면 localStorage(동기).
 * 반환은 **동기 성공 여부**다: 셸에선 메모리 반영이 곧 화면 반영이라 항상 true 이고,
 * 브라우저에선 쿼터 초과가 여기서 드러난다(호출부가 그걸로 안내한다).
 *
 * ## ⚠⚠ `undo` — 전역 ⌘Z 캡처(H3 · 2026-08-01 `/감사 근본` · 사용자 승인)
 *
 * 이 경로는 `writeRows` 가 아니라 별도 `runExclusive(execDb)` 라 **pre-image 가 안 잡혔다.**
 * 결과는 침묵이 아니라 **거짓말**이었다: 독후감을 쓰고 ⌘Z 를 누르면 되돌아가는 것은 *10분 전
 * 챕터 편집*인데 토스트는 "직전 편집을 되돌렸어요"라고 말했다. 사용자는 방금 한 일이 취소된 줄
 * 알고, 실제로는 아무 관련 없는 옛 편집이 사라진다.
 *
 * 기계는 이미 준비돼 있었다 — `docs` 는 `cloud/contract.OUTBOX_TABLES` 에 `DOCS_SPEC` 으로 들어
 * 있고 `merge.applyPull` 이 `docs` 행을 쓰면 `reloadDocs()` 로 사본까지 되맞춘다. **빠진 것은
 * 캡처 하나뿐**이었다.
 *
 * ⚠ **기본값이 `write.ts`(기본 캡처)와 반대인 것이 의도다.** 거기선 `runWrite` 에 닿는 경로가
 * 사용자 flush 하나뿐이라 기본 참이 안전하다. 여기 호출부는 다섯인데 **사용자 편집은 하나**다
 * (`reads.saveReads`) — 나머지 넷은 IDB 복구·`_local` 가져오기·산출물 미러링, 전부 *내 편집이
 * 아니다*. 기본을 참으로 두면 새 호출부가 깜빡하는 순간 기계가 낸 쓰기가 ⌘Z 를 오염시키고,
 * 그게 정확히 이 항목이 고치는 형태다. 틀렸을 때의 결말이 **"되돌릴 수 없다" < "엉뚱한 것을
 * 되돌린다"** 이므로 안전한 쪽으로 기본을 잡는다.
 */
export function docSet(key: string, value: string, opts?: { undo?: boolean }): boolean {
  if (_cache && isDocKey(key)) {
    const prev = _cache.get(key);
    /* ⚠ 무변경 쓰기는 안 쌓는다 — `rows.ts:222` 가 AppState 쪽에서 지키는 규율과 같다. 쌓으면
       ⌘Z 한 번이 "아무 일도 안 일어남"이 되고, 그건 사용자에게 고장으로 보인다
       (`undoStack.pushUndo` 머리주석). */
    const capture: PreImageRow[] =
      opts?.undo && prev !== value
        ? // DOCS_SPEC.cols = ['key','value'] · keyLen 1 → vals 는 키 포함 전량(`undo.ts` 가 slice 한다).
          [{ table: 'docs', key: [key], vals: prev === undefined ? null : [key, prev] }]
        : [];
    _cache.set(key, value);
    /* ⚠ DB 쓰기 실패를 삼키지 않는다 — 정본을 쥔 층의 침묵이 2단계-E 에서 원인 추적을 막았다.
       사용자 토스트까지 띄우진 않는다: 메모리엔 있어 화면은 정상이고, 다음 저장이 다시 시도한다.
       ⚠ **`runExclusive` 체인에 얹는다**(M1 · 2026-07-24). 종전엔 생 `execDb` 라 `whenSettled()`
       (창 닫기 가드)가 이 쓰기를 **안 기다렸다** — 요약·독후감을 입력한 직후 앱을 닫으면 IPC/워커
       왕복이 절단될 수 있었고, docs 는 정본이 따로 없어 유실이 곧 소실이다. 체인에 얹으면 AppState
       flush 와 같은 배리어를 공유해 닫기 가드가 함께 기다린다(스탬프는 실행 시점에 발급해 쓰기
       순서와 일치). 로컬 쓰기라 §5-2 "로컬만 기다린다"를 어기지 않는다(원격 push 는 이 체인 밖). */
    let stamp = 0;
    void runExclusive(() => {
      stamp = nextStamp();
      return execDb(DOC_UPSERT, [key, value, stamp]);
    }).then((ok) => {
      if (!ok) {
        console.error('[docs] 저장 실패:', key);
        /* ⚠⚠ **여기가 침묵이었다(C2 · 2026-07-31 `/감사 근본`).** 위 주석이 든 근거
           _"메모리엔 있어 화면은 정상이고, **다음 저장이 다시 시도한다**"_ 는 *다음 저장이 있을
           때만* 참이다. 그런데 이 파일이 스스로 적듯(`:51`) docs 는 정본이 따로 없는 사용자
           저작물이고, **독후감을 다 쓰고 앱을 닫는 것이 정상 사용**이다 — 그 경우 마지막 편집은
           메모리에만 있다가 사라지고 앱은 한마디도 안 한다.

           `AppState` 는 같은 사건을 3중으로 덮는다(임시 사본 → 마커 → 지속 배너). docs 에는
           그중 아무것도 없었다. 새 표면을 만들지 않고 **그 셋을 그대로 재사용**한다:
           ① 임시 사본 — 브라우저 경로와 **같은 키**라 회수 경로가 이미 아는 자리다
           ② 마커 — 다음 부팅에 배너 ②("임시 저장본이 있어요" + 내려받기)가 뜬다
           ③ 지속 배너 — 지금 화면에 "내보내기로 백업하세요"가 선다(내보내기는 `_reads`·`_local`
              로 docs 내용을 담으므로 그 CTA 가 실제로 이 저작물을 구한다)
           ⚠ 실패해도 던지지 않는다 — 저장 실패를 알리다 또 실패하면 그게 최악이다. */
        try {
          storage.setItem(key, value);
        } catch {
          /* 임시 사본조차 못 남기면 남은 것은 배너뿐이다(아래 두 줄은 계속 돈다). */
        }
        markDbFallback();
        setSaveFallback(true);
        return;
      }
      /* ⚠ **쓰기가 끝난 뒤 메모리 사본을 다시 못박는다(H1 · 2026-07-24 감사).** 병합이 `runExclusive`
         체인에서 도는 중 이 `docSet` 이 겹치면, 병합의 `reloadDocs()` 가 (이 쓰기 W1 반영 전) DB 를
         읽어 `_cache` 를 통째 재할당하면서 방금 친 값을 떨어뜨린다 — `docs` 는 `pending` rebase 가 없어
         재시작 전까지 화면에서 사라졌다. 이 쓰기는 항상 `reloadDocs` 뒤(같은 체인 순서)에 완결되므로,
         완결 시 값을 되박으면 클로버가 복원된다. DB·서버는 이미 이 값이라 되박음이 정본과 어긋나지 않는다. */
      if (_cache && isDocKey(key)) _cache.set(key, value);
      /* ⚠ **성공한 뒤에만 쌓는다** — `write.ts:260` 과 같은 규율이다. 쓰기가 실패했으면 DB 는
         pre-image 그대로이거나 부분 적용이라 "직전"이 무엇인지 모르고, 그 상태를 되돌릴 수
         있다고 말하는 것이 침묵보다 나쁘다(위 실패 분기는 임시 사본·배너로 이미 응답한다).
         ⚠ 스탬프는 **실행 시점의 그것**이어야 한다 — `undo.ts` 의 툼스톤 가드가 "이 쓰기 뒤에
         생긴 삭제"를 이 값으로 가려낸다. 그래서 `nextStamp()` 를 위 클로저 안으로 옮겼다. */
      if (capture.length) pushUndo(capture, stamp);
    });
    return true;
  }
  try {
    storage.setItem(key, value);
    return true;
  } catch {
    return false; // 저장공간 가득 — 호출부가 안내
  }
}

/** 테스트 전용 — 메모리 사본을 비워 브라우저 경로로 되돌린다. */
export function _resetDocs(): void {
  _cache = null;
}

/* ============================================================
   db/sqlite.ts — 행 표현 ↔ SQLite 의 **얇은** IO(플랫폼 개편 2단계-B).

   불변식 I2: Tauri 로 나가는 호출은 `lib/` 가 소유한다. `@tauri-apps/plugin-sql` 은 자체 invoke 를
   쓰지만 **이 파일 안에서만** import 되므로 경계는 유지된다(features/ 는 이 표면만 본다).

   의도적으로 로직이 없다 — 변환은 전부 `db/rows.ts`(순수, Tauri 없이 테스트됨)에 있고
   여기는 SQL 문장만 있다. 저장소 교체의 위험은 SQL 문법이 아니라 매퍼의 필드 누락이라,
   테스트 가능한 쪽에 로직을 몰아둔 것이다.

   ⚠ 스키마(DDL)는 여기 없다 — `src-tauri/src/db.rs` 가 단일 원천이다. 프런트가 DDL 을 들고
   있으면 배포본마다 스키마가 갈릴 수 있다.
============================================================ */
/* ⚠ `isTauri` 는 **초소형 모듈**에서 가져온다(H7) — 여기서 `../tauri` 를 정적으로 물면 그
   503줄(백엔드 커맨드 전량 + zod)이 **두 엔트리의 초기 청크**에 들어간다. 폰은 그 표면을
   한 번도 안 부른다. `dbUrl()` 은 아래 Tauri 분기 안에서 동적으로 가져온다. */
import { isTauri } from '../isTauri';
import {
  coalesceStmts,
  diffRowsDetailed,
  TABLES,
  toTableData,
  type DbRows,
  type RemovedRow,
  type TableSpec,
  type TouchedRow,
} from './rows';
import type { PreImageRow } from './undoStack';

/** `writeRows` 의 결과 — 성공 여부 + **이번에 실제로 손댄 행**(되읽기 대조의 대상). */
export interface WriteResult {
  ok: boolean;
  touched: TouchedRow[];
  /** 이 쓰기가 **지운** 행들 — 되읽기 대조에서 *없어야 하는* 쪽(H6). `touched` 는 upsert 만 담는다. */
  removed: RemovedRow[];
  /** 손대기 **직전** 그 행들의 모습(전역 ⌘Z). 기준선이 없던 쓰기면 빈 배열(`rows.ts` 참조). */
  preImages: PreImageRow[];
  /** 이 쓰기가 발급한 **최대 스탬프**(동기화 행이 없었으면 0). 되돌리기의 툼스톤 기준선이 된다. */
  stamp: number;
}
import { chunkedStamp } from './stamp';

/** flush 한 번이 만드는 스탬프 그룹의 상한. `MAX_BATCH_ITEMS`(500) 아래로 여유를 둔다 —
 *  이유는 아래 `writeRows` 주석(C2). `boot.ts` 의 이관 청크와 같은 값. */
const WRITE_STAMP_CHUNK = 400;

/** plugin-sql 의 Database 인스턴스(타입만 최소로 — 전체 타입을 끌어오면 브라우저 번들에 샌다). */
interface Db {
  execute(query: string, values?: unknown[]): Promise<unknown>;
  select<T>(query: string, values?: unknown[]): Promise<T>;
  /** 여러 문장을 한 왕복으로(H-1). **폰(워커)만 구현**한다 — plugin-sql 은 배치 API 가 없어
   *  `undefined` 이고, `batchDb`/`writeRows` 가 순차 `execute` 로 폴백한다. 그쪽은 IPC 라
   *  왕복이 싸고, 무엇보다 sqlx 풀에서 트랜잭션(`BEGIN`)이 잠금으로 죽어 배치 이득이 작다. */
  batch?(stmts: { sql: string; args: unknown[] }[]): Promise<void>;
}

/* ⚠ 연결 문자열 상수는 **여기 없다**(SD-6). 폴더가 하네스 override 로 갈릴 수 있게 되면서,
   프런트가 값을 따로 들면 백엔드가 마이그레이션한 DB 와 다른 파일을 열 수 있다 —
   스키마 없는 빈 DB 가 열리고 앱은 "데이터가 없다"고 조용히 말한다. `lib/tauri.dbUrl()` 이
   Rust(`paths::db_url`)에게 묻는다. */

let _db: Promise<Db> | null = null;

/* ── 폰 백엔드(C-6a) ─────────────────────────────────────────────

   ⚠ **기본은 꺼져 있고, 폰 진입점만 켠다.** 브라우저에서 무조건 SQLite 를 열면
   `npm run dev` 와 **트랙 A 시각 베이스라인**이 통째로 저장 백엔드를 갈아탄다 — 그 둘은
   localStorage 경로를 쓰도록 **의도적으로 남겨 둔 것**이고(`db/boot.ts` 가 계약으로 명시),
   여기서 조용히 뒤집으면 시각 검증망과 개발 경로가 함께 죽는다.

   그래서 스위치를 둔다: `phone.tsx` 만 `enableBrowserDb()` 를 부른다. 켜지 않으면
   `getDb()` 의 거동은 C-6 이전과 **한 글자도 다르지 않다**. */
let _browserDbEnabled = false;

/** 폰 진입점 전용 — 이 실행 경로에서 브라우저 SQLite 를 쓰겠다고 선언한다. */
export function enableBrowserDb(): void {
  _browserDbEnabled = true;
}

/**
 * 이 실행 경로에서 **SQLite 가 정본인가**(= 셸이거나 폰이다).
 *
 * ⚠ `isTauri()` 를 저장 경로의 조건으로 쓰던 자리를 이걸로 바꿔야 한다. 그 둘은 C-6 전까지
 * 같은 뜻이었지만 이제 아니다 — 폰은 Tauri 가 아닌데 SQLite 가 정본이다. 조건을 안 바꾸면
 * 폰의 편집이 localStorage 로 가고, **아웃박스는 SQLite 만 훑으므로 그 편집은 영원히
 * 동기화되지 않는다**(= 조용한 유실. C-1·§12-1 이 두 번 물린 실패 모드와 같은 형태).
 *
 * 동기 함수인 것이 의도다 — 호출부(`useApp` 의 `flush`)가 동기 경로다.
 */
export function isSqlitePrimary(): boolean {
  return isTauri() || _browserDbEnabled;
}

/* ── 가용성(C1 · 2026-07-26 감사) ────────────────────────────────

   ⚠ **`isSqlitePrimary()` 는 "가용성"이 아니다.** 그 둘을 한 술어가 겸직하던 것이 이 파일
   `getDb()` 의 catch 가 정확히 진단해 놓고도(아래 주석) 사용자 절반을 열어 둔 원인이다:
   연결이 실패하면 `getDb()` 는 null 을 주는데, 정본 쓰기 경로(`db/write.ts`)는 그 null 을
   **"브라우저라 SQL 을 안 쓴다"(정상)** 와 구분하지 못해 `skipped` 로 보고했고, 호출부
   (`useApp.flush`)는 그걸 성공으로 읽고 **localStorage 폴백도 타지 않은 채** 반환했다.
   결과: 그 세션의 편집이 메모리에만 살고, 재시작하면 낡은 localStorage 로 떠서
   사용자에겐 "저장한 게 사라졌다"가 된다.

   그래서 술어를 가른다 — **실행 경로**(`isSqlitePrimary`, 여기)와 **저장이 실제로 됐는가**
   (`db/write.ts` 의 `ParityReport.unavailable` → `useApp` → `db/fallback.ts` 의 신호).

   ⚠ 사용자에게 말하는 판단을 **연결 성공 여부**로 두지 않은 이유는 `db/fallback.ts` 머리주석이
   소유한다(트랙 A 가 그 차이를 즉시 드러냈다). 이 파일은 "열렸나"만 알고, "무엇을 잃었나"는
   쓰기 경로가 안다. */

/** DB 핸들(지연 로드·1회). 셸이면 plugin-sql, 폰이면 wasm, 그 외 브라우저는 null. */
export async function getDb(): Promise<Db | null> {
  if (!isTauri()) {
    if (!_browserDbEnabled) return null;
    const { getBrowserDb } = await import('./browserDb');
    return getBrowserDb(); // 자체 catch 로 null 을 준다(로그는 그쪽이 남긴다)
  }
  // ⚠ `dbUrl()` 도 여기서 동적으로 — 셸 분기 안이라 폰·브라우저는 이 청크를 아예 안 받는다(H7).
  _db ??= Promise.all([import('@tauri-apps/plugin-sql'), import('../tauri').then((m) => m.dbUrl())])
    .then(([m, url]) => m.default.load(url) as Promise<Db>)
    .then(async (db) => {
      /* WAL 로 올린다 — 기본 롤백 저널에선 **읽는 중엔 쓸 수 없어** `database is locked` 가 난다.
         plugin-sql 은 sqlx 커넥션 **풀**이라 읽기와 쓰기가 서로 다른 커넥션에서 겹치는 게 정상
         동작이고, 실제로 "닫기 직전에 상태를 읽으면 그 다음 쓰기가 통째로 실패"하는 형태로
         드러났다(트랙 B 에서 잡음). WAL 은 DB 파일에 영속되는 설정이라 한 번만 걸면 된다. */
      try {
        await db.execute('PRAGMA journal_mode=WAL');
      } catch (e) {
        console.error('[db] WAL 전환 실패 — 동시 읽기/쓰기에서 잠금 오류가 날 수 있습니다.', e);
      }
      return db;
    });
  try {
    return await _db;
  } catch (e) {
    // ⚠ 조용히 삼키지 않는다 — 정본이 SQLite 인데 연결 실패가 무음이면 앱은 "저장되는 것처럼"
    //   보이면서 아무것도 안 쓴다(2단계-E 에서 실제로 이 침묵 때문에 원인을 못 찾았다).
    //   ⚠ 로그는 **개발자 절반**만 닫는다. 사용자 절반은 쓰기 경로가 닫는다(C1) —
    //   `db/write.ts` 가 `unavailable` 로 보고하고, `useApp` 이 폴백 저장 + 지속 배너로 잇는다.
    console.error('[db] SQLite 연결 실패 — 저장이 되지 않습니다.', e);
    _db = null; // 다음 호출에서 재시도 — 한 번 실패가 영구 불능이 되지 않게
    return null;
  }
}

/* ── 범용 1문장 실행/조회(4단계-J) ────────────────────────────────
   `docs` 테이블(AppState 밖 사용자 저작물)이 쓰는 얇은 통로다. 아래 `readRows`/`writeRows` 는
   `AppState` 전용 매퍼와 짝이라 재사용할 수 없어서, **SQL 만 아는 층**의 규약(이 파일은 로직을
   두지 않는다)을 지킨 채 두 함수를 더 둔다. */

/** 1문장 실행. 성공 여부만 돌려주고 **실패를 삼키지 않는다**(로그를 남긴다). */
export async function execDb(query: string, values: unknown[] = []): Promise<boolean> {
  const db = await getDb();
  if (!db) return false;
  try {
    await db.execute(query, values);
    return true;
  } catch (e) {
    console.error('[db] execute 실패:', query, e);
    return false;
  }
}

/**
 * 여러 문장을 **한 배치**로 실행한다(H-1). 폰(워커)이면 한 왕복 + 트랜잭션(원자적),
 * 셸이면 순차 `execute` 폴백(plugin-sql 은 배치 API 가 없다). 성공 여부만 돌려주고 삼키지 않는다.
 *
 * ⚠ 폴백은 **비원자적**이다(중간에 죽으면 부분 적용) — 데스크톱은 이미 diff 쓰기가 그
 * 성질을 전제로 안전하고(`writeRows` 주석: "남는 건 여분의 옛 행이지 사라진 행이 아니다"),
 * 병합(`applyPull`)은 실패를 **던져** 워터마크 전진을 막는다(다음 pull 이 재개).
 */
export async function batchDb(stmts: { sql: string; args: unknown[] }[]): Promise<boolean> {
  if (!stmts.length) return true;
  const db = await getDb();
  if (!db) return false;
  /* ⚠ **접고 나서 보낸다**(H26). 셸은 문장마다 IPC 왕복이라 전량 쓰기 경로에서 수천 번이 됐다 —
     같은 SQL 의 연속 INSERT 를 다중 VALUES 한 문장으로 접으면 왕복이 두 자릿수로 떨어진다.
     의미는 동일하고 오히려 원자적이다(근거는 `rows.ts` 의 `coalesceStmts` 머리주석).
     폰(워커)도 접힌 편이 싸다 — 파싱·바인딩 횟수가 그만큼 준다. */
  const folded = coalesceStmts(stmts);
  try {
    if (db.batch) await db.batch(folded);
    else for (const s of folded) await db.execute(s.sql, s.args);
    return true;
  } catch (e) {
    console.error('[db] batch 실패:', e);
    return false;
  }
}

/** 1문장 조회. DB 미가용·실패는 **null**(빈 배열과 구분해야 한다 — 전자는 "모름", 후자는 "없음"). */
export async function selectDb<T>(query: string, values: unknown[] = []): Promise<T[] | null> {
  const db = await getDb();
  if (!db) return null;
  try {
    return await db.select<T[]>(query, values);
  } catch (e) {
    console.error('[db] select 실패:', query, e);
    return null;
  }
}

/** SQLite 가 이 실행 경로에서 쓸 수 있는가(브라우저면 false). */
export async function isDbAvailable(): Promise<boolean> {
  return (await getDb()) !== null;
}

type Row = Record<string, string | number>;
const str = (v: string | number | undefined): string => (v == null ? '' : String(v));

/**
 * **방금 쓴 행만** 되읽는다 — 되읽기 대조의 행축 판(`write.ts` 참조).
 *
 * 왜: 종전 대조는 매번 8테이블을 **전량** 읽었고(2년 근사 상태에서 IPC 946KB + JS 9ms) 그래서
 * 20회에 1회만 돌렸다. 즉 **19회는 무검증**이었다. 이 층의 목적은 "SQL 층의 타입 강제변환·
 * NULL 처리 탐지"인데 그건 **행의 성질**이라, 손댄 행만 보면 비용이 O(변경행)으로 떨어지면서
 * 오히려 **매 flush 검증**이 된다 — 더 싸고 탐지력은 오른다.
 *
 * ⚠ 복합키(keyLen=2) 테이블은 **첫 키만 `IN`** 으로 좁히고 정확한 조합은 호출부가 거른다.
 * 행 값 튜플(`WHERE (a,b) IN (VALUES …)`)은 SQLite 가 지원하지만 plugin-sql → sqlx 경로에서
 * 바인딩 거동을 이 저장소가 검증한 적이 없다 — 정본 저장 경로에서 미검증 SQL 문법에 기대지
 * 않는다. 첫 키로 좁히면 과다 인출이 생기지만 그 상한은 "이번에 손댄 서로 다른 첫 키 수"다.
 * ⚠ 반환은 `키 → 데이터 열 배열`(`spec.cols` 순서, `updated_at` 제외)이다. 없는 키는 없는
 * 채로 둔다 — 호출부가 "썼는데 안 읽힌다"를 불일치로 판정할 수 있어야 한다.
 */
export async function readTouched(
  touched: readonly { table: string; key: unknown[] }[],
): Promise<Map<string, unknown[]> | null> {
  const db = await getDb();
  if (!db || !touched.length) return db ? new Map() : null;
  const bySpec = new Map<TableSpec, { table: string; key: unknown[] }[]>();
  for (const t of touched) {
    const spec = TABLES.find((x) => x.name === t.table);
    if (!spec) continue;
    const list = bySpec.get(spec);
    if (list) list.push(t);
    else bySpec.set(spec, [t]);
  }
  const out = new Map<string, unknown[]>();
  await Promise.all(
    [...bySpec.entries()].map(async ([spec, list]) => {
      const firsts = [...new Set(list.map((t) => String(t.key[0])))];
      const rows = await db.select<Row[]>(
        `SELECT ${spec.cols.join(',')} FROM ${spec.name} WHERE ${spec.cols[0]} IN (${firsts.map(() => '?').join(',')})`,
        firsts,
      );
      for (const r of rows) {
        const vals = spec.cols.map((c) => r[c as keyof Row]);
        out.set(touchedKey(spec.name, vals.slice(0, spec.keyLen)), vals);
      }
    }),
  );
  return out;
}

/** 접촉 행 식별자 — 테이블 + 기본키. 구분자는 값에 안 나오는 NUL 이다(`join('')` 충돌 방지). */
export function touchedKey(table: string, key: unknown[]): string {
  return [table, ...key.map((k) => String(k))].join('\u0000');
}

/** 전체 상태를 읽어 행 표현으로. 빈 DB 면 null(= 아직 이관 전). */
export async function readRows(): Promise<DbRows | null> {
  const db = await getDb();
  if (!db) return null;

  const [meta, settings, runtime, completions, dsMap, records, summaries, weekAlloc] = await Promise.all([
    db.select<Row[]>('SELECT key, value FROM meta'),
    db.select<Row[]>('SELECT key, value FROM settings'),
    db.select<Row[]>('SELECT key, value FROM runtime_cache'),
    db.select<Row[]>('SELECT ds, k, value FROM completions'),
    db.select<Row[]>('SELECT slice, ds, value FROM ds_map'),
    db.select<Row[]>('SELECT slice, id, ord, value FROM records ORDER BY slice, ord'),
    // ⚠ `id` 가 키의 절반이다(C-3 · v9). 정렬은 여전히 `ord` — 표시 순서는 데이터 열이다.
    db.select<Row[]>('SELECT sid, id, ord, value FROM summaries ORDER BY sid, ord'),
    db.select<Row[]>('SELECT wk, sid, value FROM week_alloc'),
  ]);

  // settings 가 통째로 비었으면 "한 번도 안 썼다" — 기본값으로 부팅하지 말고 호출부가 판단하게.
  if (!settings.length && !meta.length) return null;

  const rows: DbRows = {
    present: JSON.parse(str(meta.find((m) => m.key === 'present')?.value) || '[]'),
    settings: settings.map((r) => ({ key: str(r.key), json: str(r.value) })),
    runtime: runtime.map((r) => ({ key: str(r.key), json: str(r.value) })),
    completions: completions.map((r) => ({ ds: str(r.ds), k: str(r.k), json: str(r.value) })),
    dsMaps: { dayOverrides: [], dayPlans: [], rituals: [], resume: [] },
    arrays: {
      cbms: [],
      backlog: [],
      blankResults: [],
      retentionLog: [],
      events: [],
      tasks: [],
      questions: [],
      jolAsks: [],
      retrievals: [],
    },
    summaries: summaries.map((r) => ({ sid: str(r.sid), id: str(r.id), ord: Number(r.ord), json: str(r.value) })),
    weekAlloc: weekAlloc.map((r) => ({ wk: str(r.wk), sid: str(r.sid), json: str(r.value) })),
  };
  for (const r of dsMap) {
    const bucket = rows.dsMaps[str(r.slice) as keyof DbRows['dsMaps']];
    if (bucket) bucket.push({ ds: str(r.ds), json: str(r.value) });
  }
  for (const r of records) {
    const bucket = rows.arrays[str(r.slice) as keyof DbRows['arrays']];
    if (bucket) bucket.push({ id: str(r.id), ord: Number(r.ord), json: str(r.value) });
  }
  return rows;
}

/**
 * DB 에 이미 존재하는 **가장 큰 동기화 타임스탬프**(부팅 시 `seedStamp` 의 씨앗).
 * 없거나 DB 미가용이면 0.
 *
 * ⚠ 툼스톤의 `deleted_at` 도 함께 본다 — 삭제도 같은 발급기를 쓰므로 여기서 빼면 재시작
 * 직후에 **이미 쓴 값을 다시 발급**할 수 있다(단조성이 끊긴다).
 */
export async function readMaxStamp(): Promise<number> {
  const rows = await selectDb<{ m: number | null }>(
    `SELECT MAX(m) AS m FROM (
        SELECT MAX(updated_at) AS m FROM settings
        UNION ALL SELECT MAX(updated_at) FROM completions
        UNION ALL SELECT MAX(updated_at) FROM ds_map
        UNION ALL SELECT MAX(updated_at) FROM records
        UNION ALL SELECT MAX(updated_at) FROM summaries
        UNION ALL SELECT MAX(updated_at) FROM week_alloc
        UNION ALL SELECT MAX(updated_at) FROM docs
        UNION ALL SELECT MAX(deleted_at) FROM tombstones
     )`,
  );
  return Number(rows?.[0]?.m ?? 0) || 0;
}

/** 마지막으로 DB 에 반영된 행 표현 — 증분 diff 의 기준. 읽기/쓰기 성공 때마다 갱신된다. */
let _last: DbRows | null = null;
/** `_last` 의 테이블 표현 캐시(m-5) — 지연 생성하고 쓰기 성공 시 다음 회차 것으로 교체한다. */
let _lastTables: Record<string, Map<string, unknown[]>> | null = null;

/** 부팅 읽기가 끝난 뒤 기준선을 세운다(그래야 첫 쓰기가 전량 쓰기가 되지 않는다). */
export function setDiffBaseline(rows: DbRows | null): void {
  _last = rows;
  _lastTables = null; // 다음 diff 가 지연 생성한다(m-5).
}

/**
 * 상태를 DB 에 반영한다 — **변경된 행만** upsert 하고 사라진 행만 삭제한다.
 *
 * ⚠ 트랜잭션을 쓰지 않는 것이 의도다. `tauri-plugin-sql` 은 sqlx **커넥션 풀**이라 별도
 * `execute` 로 부른 `BEGIN` 은 다른 커넥션의 쓰기를 막아 `database is locked` 로 죽는다(실측).
 * 대신 diff 방식이 트랜잭션 없이도 안전하다 — DELETE-후-INSERT 와 달리 **DB 가 비는 순간이
 * 없고**, 중간에 죽어도 남는 건 "여분의 옛 행"이지 "사라진 행"이 아니다(다음 쓰기가 정리한다).
 */
export async function writeRows(rows: DbRows, stamp?: number | (() => number)): Promise<WriteResult> {
  const db = await getDb();
  if (!db) return { ok: false, touched: [], removed: [], preImages: [], stamp: 0 };
  // 기준선이 없으면(첫 쓰기·이관 직후) DB 를 한 번 읽어 세운다 — 없다고 전량 삭제하면
  // 위에 적은 안전 속성이 그대로 깨진다.
  if (!_last) _last = await readRows();
  /* ⚠ `diffRows` 의 기본값(`Date.now()`)에 맡기지 않는다 — 시계가 뒤로 점프하면 그 뒤 편집이
     워터마크에 영영 안 걸린다(`stamp.ts` 머리주석). 발급을 한 지점으로 모으는 게 그 방어다.

     ⚠⚠ 기본을 `nextStamp()`(단일 스탬프)에서 **`chunkedStamp(400)`** 로 바꾼다(C2 · 2026-07-24).
     `chunkedStamp` 는 첫 400건까지 **같은 스탬프**를 내므로 일반 flush(≤400 변경 행)는 종전과
     한 글자도 다르지 않다(한 flush = 한 스탬프 그룹). 그런데 `loadState`(가져오기·복구·되돌리기
     — `shell/actions.ts` 4곳)는 상태를 **통째로** 써서 sync 행이 500 을 넘을 수 있고, 그러면 단일
     스탬프 그룹이 `capBatch` 가 못 쪼개는 `oversized` 가 되어 스키마 상한에 걸려 **아웃박스가
     영구 차단**된다(그 사용자의 이후 모든 편집이 조용히 동기화 안 됨). 최초 이관(`boot.ts`)만
     `chunkedStamp` 로 막고 런타임 import 경로는 안 막던 비대칭이 결함이었다. 여기서 기본을 청크로
     바꾸면 **어느 호출자든** 단일 그룹이 상한을 못 넘어 그 차단이 원천 봉쇄된다(호출자 무관 방어). */
  /* ⚠ `diffRowsDetailed` 로 문장과 **접촉 행**을 한 순회에서 함께 받는다 — 되읽기 대조(`write.ts`)가
     "방금 쓴 행"만 확인할 수 있게. 두 번 순회해 따로 만들면 언젠가 한쪽만 고쳐져 **검증이 엉뚱한
     행을 본다**(그때 증상은 "대조는 통과하는데 저장이 틀렸다"다). */
  /* ⚠ 발급을 한 겹 감싸 **이번 쓰기가 쓴 최대 스탬프**를 안다(전역 ⌘Z). 되돌리기는 그 값으로
     "이 쓰기 뒤에 생긴 툼스톤"을 가려낸다 — 없으면 다른 기기가 지운 행을 조용히 되살린다.
     `currentStamp()` 로 대신 읽지 않는 이유: 그건 *전역* 최대라 이 쓰기가 안 쓴 값(병합 씨앗
     등)까지 포함하고, 그러면 가려내기가 실제보다 관대해진다(= 가드가 헐거워진다). */
  const issuer = stamp ?? chunkedStamp(WRITE_STAMP_CHUNK);
  const provider = typeof issuer === 'function' ? issuer : (): number => issuer;
  let maxStamp = 0;
  const issue = (): number => {
    const v = provider();
    if (v > maxStamp) maxStamp = v;
    return v;
  };
  /* ⚠ 기준선의 테이블 표현을 재사용한다(m-5) — `_lastTables` 가 없으면 여기서 한 번 만든다.
     `_last === null`(기준선 없음 = 전량 쓰기)이면 `null` 을 명시로 넘겨야 한다: `undefined` 는
     "안 넘겼다"는 뜻이라 `diffRowsDetailed` 가 자기 경로로 되돌아간다. */
  _lastTables ??= _last ? toTableData(_last) : null;
  const { stmts, touched, removed, preImages, nextTables } = diffRowsDetailed(_last, rows, issue, _lastTables);
  try {
    /* 한 배치로(H-1). 폰은 한 왕복 + 트랜잭션이라 매 flush(400ms)의 N 왕복이 1 로 접힌다.
       셸은 순차 `execute` 폴백 — 트랜잭션 없이도 diff 방식이 안전하다(머리주석). */
    const folded = coalesceStmts(stmts); // H26 — 왕복 수를 문장 수에서 줄인다(rows.ts 머리주석)
    if (db.batch) await db.batch(folded);
    else for (const s of folded) await db.execute(s.sql, s.args);
    _last = rows;
    _lastTables = nextTables; // 방금 만든 표현을 다음 회차 기준선으로 그대로 넘긴다(m-5)
    return { ok: true, touched, removed, preImages, stamp: maxStamp };
  } catch (e) {
    console.error('[db] 쓰기 실패', e);
    _last = null; // 부분 적용됐을 수 있다 — 다음 쓰기가 DB 를 다시 읽어 기준선을 세우게 한다
    _lastTables = null;
    /* ⚠ 실패한 쓰기의 pre-image 는 **주지 않는다.** 부분 적용됐을 수 있어 "직전"이 무엇인지
       모르는 상태이고, 그걸 스택에 얹으면 되돌리기가 실제로 없던 상태를 만들어 낸다. */
    return { ok: false, touched: [], removed: [], preImages: [], stamp: 0 };
  }
}

/* ============================================================
   durability.ts — 저장소 내구성(0단계-E ①②).
   문제: 앱이 `navigator.storage`를 한 번도 호출하지 않아 오리진 저장소가 **best-effort 등급**에
   머문다 — 브라우저가 디스크 압박 시 localStorage/IDB를 **예고 없이 축출**할 수 있고, 그러면
   앱 데이터(study_planner_v3)와 IDB 미러가 *동시에* 사라진다(미러가 같은 오리진에 있으므로
   복구층이 함께 증발 — idb.ts의 위협모델이 못 막는 유일한 경로).
   해결: ① 부팅 시 persist() 승격 요청 ② estimate()로 쿼터 80% 사전 경고.
   순수 IO만 — 토스트/문구는 호출부(app/StorageGuard)가 소유한다.
============================================================ */

/** 쿼터 경고 임계 — 이 비율을 넘으면 부팅 시 1회 안내. */
export const QUOTA_WARN_RATIO = 0.8;

export interface DurabilityReport {
  /** true=영속 승격됨 · false=best-effort(축출 가능) · null=API 미지원(판단 불가). */
  persisted: boolean | null;
  usage: number | null;
  quota: number | null;
  /** usage/quota. quota가 0이거나 미지원이면 null. */
  ratio: number | null;
}

const UNKNOWN: DurabilityReport = { persisted: null, usage: null, quota: null, ratio: null };

/** StorageManager 접근 — 미지원(구 브라우저·jsdom·비보안 컨텍스트)이면 null. */
function manager(): StorageManager | null {
  if (typeof navigator === 'undefined') return null;
  const sm = (navigator as Navigator).storage;
  return sm && typeof sm === 'object' ? sm : null;
}

/** 저장소를 영속 등급으로 승격 요청.
    이미 영속이면 재요청하지 않는다(persist()는 멱등하지만 일부 브라우저에서 권한 UI를 유발). */
async function requestPersist(sm: StorageManager): Promise<boolean | null> {
  try {
    if (typeof sm.persisted === 'function' && (await sm.persisted())) return true;
    if (typeof sm.persist !== 'function') return null;
    return await sm.persist();
  } catch {
    return null; // 권한 거부·비보안 컨텍스트 — 판단 불가로 처리(앱은 정상 동작)
  }
}

/** 사용량/쿼터 추정. 미지원이거나 실패면 전부 null. */
async function readEstimate(sm: StorageManager): Promise<Pick<DurabilityReport, 'usage' | 'quota' | 'ratio'>> {
  if (typeof sm.estimate !== 'function') return { usage: null, quota: null, ratio: null };
  try {
    const { usage, quota } = await sm.estimate();
    const u = typeof usage === 'number' ? usage : null;
    const q = typeof quota === 'number' ? quota : null;
    // quota 0 나눗셈 방지 — 0이면 비율이 무의미(Infinity/NaN)하므로 판단 불가로 둔다.
    return { usage: u, quota: q, ratio: u != null && q != null && q > 0 ? u / q : null };
  } catch {
    return { usage: null, quota: null, ratio: null };
  }
}

/** 부팅 1회 호출 — 영속 승격 + 쿼터 추정을 한 번에. 어떤 경로로도 throw하지 않는다. */
export async function ensureDurableStorage(): Promise<DurabilityReport> {
  const sm = manager();
  if (!sm) return UNKNOWN;
  // 병렬 — estimate는 persist 결과와 무관하고, 부팅 경로라 왕복 하나라도 아낀다.
  const [persisted, est] = await Promise.all([requestPersist(sm), readEstimate(sm)]);
  return { persisted, ...est };
}

/** 쿼터 임계 초과 여부(경고 게이트). ratio를 모르면 경고하지 않는다(오탐 금지). */
export function isQuotaTight(r: DurabilityReport): boolean {
  return r.ratio != null && r.ratio >= QUOTA_WARN_RATIO;
}

/** 바이트 → 사람이 읽는 크기(경고 문구용). */
export function fmtBytes(n: number): string {
  if (!isFinite(n) || n < 0) return '—';
  const units = ['B', 'KB', 'MB', 'GB'];
  let v = n;
  let i = 0;
  while (v >= 1024 && i < units.length - 1) {
    v /= 1024;
    i++;
  }
  return `${v < 10 && i > 0 ? v.toFixed(1) : Math.round(v)}${units[i]}`;
}

/* ============================================================
   ics.ts — 캘린더(.ics) 빌드 + 계획 서명(프레임워크 무관). 레거시 scheduler.js의 ICS 경로 이식.
   planSignature: 계획 입력의 가벼운 지문 → .ics 신선도 판정(F-10). 내보낼 때의 서명과 현재가 다르면
   스케줄 탭이 "재내보내기 필요"를 띄운다.
============================================================ */
import { schedule, layoutDay } from './scheduler';
import { iso, parseISO, hLabel, rid, pad2, minutesOfDay } from './utils';
import type { AppState } from './types';

function icsEsc(s: unknown): string {
  return (s ?? '').toString().replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\n/g, '\\n');
}
/** 로컬 시각 → YYYYMMDDTHHMMSS(플로팅 로컬타임). */
function icsDt(ds: string, min: number): string {
  const d = parseISO(ds);
  // 자정 종료(min>=1440)는 iCalendar에서 불법인 24:00:00 → 다음날 00:00:00으로 정규화.
  // (늦은 모듈이 22:00–24:00처럼 wake1=1440까지 차면 DTEND가 T240000이 돼 엄격한 캘린더가 거부했다.)
  if (min >= 1440) {
    d.setDate(d.getDate() + Math.floor(min / 1440));
    min %= 1440;
  }
  const h = Math.floor(min / 60);
  const m = min % 60;
  return `${d.getFullYear()}${pad2(d.getMonth() + 1)}${pad2(d.getDate())}T${pad2(h)}${pad2(m)}00`;
}

/* ⚠ 여기 이모지를 되살리지 말 것 — 이 문자열은 **캘린더 앱이 그리는 이벤트 제목**이라 아이콘
   컴포넌트가 닿지 않는다(계획 §3-2 ②: 문자열 자리는 교체가 아니라 제거가 답이다). 유형 구분은
   단어가 이미 하고 있었고, 이모지는 캘린더마다 다르게(또는 두부로) 렌더됐다. */
const LABEL: Record<string, string> = {
  new: '학습',
  rev: '복습',
  blank: '백지복습',
  mock: '모의시험',
  anki: 'Anki',
};

/** 현재 계획을 VCALENDAR 문자열로(학습 세션만 이벤트화). */
export function buildICS(state: AppState): string {
  const r = schedule(state);
  const now = new Date();
  const stamp = icsDt(iso(now), minutesOfDay(now));
  const lines: string[] = [
    'BEGIN:VCALENDAR',
    'VERSION:2.0',
    'PRODID:-//러닝허브//KR',
    'CALSCALE:GREGORIAN',
    'METHOD:PUBLISH',
  ];
  (r.days || []).forEach((day) => {
    if (!day.items.length) return;
    const L = layoutDay(state, day);
    L.tl
      .filter((x) => x.kind === 'study' && x.start != null)
      .forEach((x, i) => {
        const label = LABEL[x.type || 'anki'] || 'Anki';
        const ch = x.chapters && x.chapters.length ? ' — ' + x.chapters.join(', ') : '';
        lines.push(
          'BEGIN:VEVENT',
          `UID:${day.ds}-${x.sid}-${x.type}-${i}-${rid()}@studyplanner`,
          `DTSTAMP:${stamp}`,
          `DTSTART:${icsDt(day.ds, x.start as number)}`,
          `DTEND:${icsDt(day.ds, x.end as number)}`,
          `SUMMARY:${icsEsc(label + ' ' + x.name)}`,
          `DESCRIPTION:${icsEsc(x.name + ch + ' (' + hLabel((x.end as number) - x.start) + ')')}`,
          'END:VEVENT',
        );
      });
  });
  lines.push('END:VCALENDAR');
  return lines.join('\r\n');
}

/** 계획에 영향을 주는 입력의 가벼운 지문 — .ics 신선도 판정용. */
export function planSignature(state: AppState): string {
  try {
    const it = (state.items || []).map((s) => [
      s.id,
      s.name,
      s.mode,
      s.weeklyHours,
      s.dailyMin,
      s.deadline,
      (s.chapters || []).map((c) => [c.name, c.hours, !!c.done]),
    ]);
    const rt = (state.routine || []).map((b) => [b.name, b.type, b.start, b.end, (b.days || []).join('')]);
    return JSON.stringify([
      it,
      rt,
      state.dayOverrides || {},
      state.moduleLen,
      state.reviewRatio,
      state.peakStart,
      state.peakEnd,
      state.blankReviewWeekly,
      state.mockEveryWeeks,
      state.reviewViaAnki,
      state.adaptiveCapacity,
      state.startDate,
    ]);
  } catch {
    return '';
  }
}

/* ============================================================
   idb.ts — IndexedDB write-through 미러(레거시 state.js의 IDB 경로 이식).
   localStorage가 동기 1차 저장, IDB엔 같은 스냅샷을 비동기 미러 →
   '사이트 데이터 삭제'로 localStorage가 전소해도 IDB로 복구 가능.
   indexedDB 미지원(노드/테스트)에선 전부 no-op라 동기 경로 불변.
============================================================ */
const IDB_NAME = 'learning_hub';
const IDB_STORE = 'kv';
const IDB_VER = 1;
let _conn: Promise<IDBDatabase> | null = null;

function open(): Promise<IDBDatabase> {
  if (typeof indexedDB === 'undefined') return Promise.reject(new Error('no-idb'));
  if (_conn) return _conn;
  _conn = new Promise<IDBDatabase>((res, rej) => {
    const r = indexedDB.open(IDB_NAME, IDB_VER);
    r.onupgradeneeded = () => {
      const db = r.result;
      if (!db.objectStoreNames.contains(IDB_STORE)) db.createObjectStore(IDB_STORE);
    };
    r.onsuccess = () => res(r.result);
    r.onerror = () => {
      _conn = null;
      rej(r.error);
    };
  });
  return _conn;
}

/** persist마다 호출 — 실패해도 앱 영향 0(비차단). key로 앱상태('state')·UI설정('ui')을 분리 미러. */
export function idbMirror(json: string, key: string = 'state'): void {
  if (typeof indexedDB === 'undefined') return;
  open()
    .then((db) => {
      try {
        db.transaction(IDB_STORE, 'readwrite').objectStore(IDB_STORE).put(json, key);
      } catch {
        _conn = null;
      }
    })
    .catch(() => {});
}

/* ── 세대 백업(감사 #21) — fallback 부팅 직후 '마지막 미러'를 별도 키로 보존.
   미러('state')는 단일 키 덮어쓰기라, defaults로 부팅한 탭의 첫 flush가 마지막 백업을
   영구 파괴했다(복구 창=12초 토스트뿐). 부팅 복구 안내(BootRecovery)가 미러를 읽은 즉시
   여기로 넘겨 2세대(직전·그 전)로 보존 → 토스트를 놓쳐도 설정/⌘K '복구'가 살릴 수 있다. */
export const IDB_BACKUP_KEY = 'state_backup';
export const IDB_BACKUP2_KEY = 'state_backup2';
export async function idbPreserveBackup(json: string): Promise<void> {
  const prev = await idbGet<string>(IDB_BACKUP_KEY);
  if (prev != null && prev !== json) await idbPut(IDB_BACKUP2_KEY, prev); // 기존 백업은 한 세대 밀어 보존
  await idbPut(IDB_BACKUP_KEY, json);
}

/** 최신 미러 1건(JSON 문자열|null). key 기본 'state'(앱상태). */
export function idbLoad(key: string = 'state'): Promise<string | null> {
  return open().then(
    (db) =>
      new Promise<string | null>((res, rej) => {
        const g = db.transaction(IDB_STORE, 'readonly').objectStore(IDB_STORE).get(key);
        g.onsuccess = () => res((g.result as string) || null);
        g.onerror = () => rej(g.error);
      }),
  );
}

/* ── 임의 값 저장(구조화 복제) — FileSystemDirectoryHandle 같은 non-JSON 값을 영속.
   JSON 미러(idbMirror)와 같은 'kv' 스토어를 키로 구분해 공유한다. 미지원(노드/테스트)에선
   put/del은 no-op, get은 null — 실패해도 앱 영향 0(비차단). */
export function idbPut(key: string, value: unknown): Promise<void> {
  if (typeof indexedDB === 'undefined') return Promise.resolve();
  return open()
    .then(
      (db) =>
        new Promise<void>((res) => {
          try {
            const tx = db.transaction(IDB_STORE, 'readwrite');
            tx.objectStore(IDB_STORE).put(value, key);
            tx.oncomplete = () => res();
            tx.onerror = () => res();
          } catch {
            _conn = null;
            res();
          }
        }),
    )
    .catch(() => {});
}
export function idbGet<T = unknown>(key: string): Promise<T | null> {
  if (typeof indexedDB === 'undefined') return Promise.resolve(null);
  return open()
    .then(
      (db) =>
        new Promise<T | null>((res) => {
          try {
            const g = db.transaction(IDB_STORE, 'readonly').objectStore(IDB_STORE).get(key);
            g.onsuccess = () => res((g.result as T) ?? null);
            g.onerror = () => res(null);
          } catch {
            res(null);
          }
        }),
    )
    .catch(() => null);
}
export function idbDel(key: string): Promise<void> {
  if (typeof indexedDB === 'undefined') return Promise.resolve();
  return open()
    .then(
      (db) =>
        new Promise<void>((res) => {
          try {
            const tx = db.transaction(IDB_STORE, 'readwrite');
            tx.objectStore(IDB_STORE).delete(key);
            tx.oncomplete = () => res();
            tx.onerror = () => res();
          } catch {
            _conn = null;
            res();
          }
        }),
    )
    .catch(() => {});
}

/* ============================================================
   methodology.ts — 학습방법론 데이터 레이어. 레거시 js/data-methodology.js 이식.
   3문장 요약·CBMS 오답·보충 백로그·백지 결과·주간 리뷰·Anki 카드·유지율·아카이빙.
   레거시는 전역 state 변형 + persist()/toast()/download를 섞었다 → 여기선
   *순수*하게: reads는 state를 받아 값 반환, 뮤테이터는 받은 state를 변형(Immer draft
   또는 평범한 객체 모두 동작). persist/다운로드/토스트는 store·features가 조립한다.
============================================================ */
import { keySid } from './domainKeys';
import { addDays, iso, mondayOf, parseISO, rid, todayISO } from './utils';
import { SCHEMA_VERSION, isDone } from './persistence';
import type { AppState, Backlog, BlankResult, CbmsCode, Ritual, ScheduleResult, Summary } from './types';

/* ── 인출 증거·추세 파생(통계 리드아웃·인출카드 공용 · 중복 제거 SSOT) ── */

export interface RecallEvidence {
  blankPlan: number; // 계획된 백지복습 수
  blankDone: number; // 완료된 백지복습 수
  mockDone: number; // 완료된 모의 수
  blankRate: number; // 백지복습 완료율(%)
  recallActs: number; // 능동 인출 활동 총수 = 요약 + 백지완료 + 모의완료
}

/** 능동 인출 증거 — 요약·백지·모의 완료를 집계(북극성 출력 지표). Stats 리드아웃·인출카드가 공유. */
export function recallEvidence(state: AppState, r: ScheduleResult): RecallEvidence {
  let blankPlan = 0;
  let blankDone = 0;
  let mockDone = 0;
  (r.days || []).forEach((d) =>
    d.items.forEach((it) => {
      if (it.type === 'blank') {
        blankPlan++;
        if (isDone(state, d.ds, it.sid, it.type)) blankDone++;
      }
      if (it.type === 'mock' && isDone(state, d.ds, it.sid, it.type)) mockDone++;
    }),
  );
  const blankRate = blankPlan ? Math.round((blankDone / blankPlan) * 100) : 0;
  const recallActs = summaryCount(state) + blankDone + mockDone;
  return { blankPlan, blankDone, mockDone, blankRate, recallActs };
}

export interface TrendGlyph {
  delta: number; // lastW - thisW (양수 = 감소 = 개선)
  icon: string; // '▼ 감소' | '▲ 증가' | '＝ 유지'
  good: boolean; // 개선 방향(감소) 또는 둘 다 0
}

/** CBMS 오답 주간 추세를 아이콘/판정으로 — 인출카드·리드아웃의 중복 파생을 하나로. */
export function cbmsTrendGlyph(tr: { thisW: number; lastW: number }): TrendGlyph {
  const delta = tr.lastW - tr.thisW;
  const bothZero = tr.lastW === 0 && tr.thisW === 0;
  const good = delta > 0 || bothZero;
  const icon = bothZero ? '＝ 유지' : delta > 0 ? '▼ 감소' : delta < 0 ? '▲ 증가' : '＝ 유지';
  return { delta, icon, good };
}

/* ── 3문장 요약(3절) ── */
export function summariesFor(state: AppState, ds: string): Summary[] {
  // 순수 읽기 — 예전엔 `state.summaries = state.summaries || {}`로 지연초기화하며 state를 제자리 변형했다.
  // 이 함수는 렌더(동결 state)에서 불려 immer autoFreeze를 못 켜게 한 SD-5 주범 → 변형 없이 읽기만 한다.
  return (state.summaries && state.summaries[ds]) || [];
}
export function addSummary(
  state: AppState,
  ds: string,
  sid: string,
  name: string,
  s1: string,
  s2: string,
  s3: string,
): void {
  state.summaries = state.summaries || {};
  const arr = (state.summaries[ds] = state.summaries[ds] || []);
  arr.push({ id: rid(), sid: sid || '', name: name || '', s1: s1 || '', s2: s2 || '', s3: s3 || '', at: Date.now() });
}
/** 요약 인라인 편집 — 세 문장·과목만 갈아끼운다(id·작성시각 보존). 오타 수정을 위해 삭제-재작성이 필요 없게. */
export function editSummary(
  state: AppState,
  ds: string,
  id: string,
  patch: { sid?: string; name?: string; s1?: string; s2?: string; s3?: string },
): void {
  const arr = state.summaries && state.summaries[ds];
  const rec = arr && arr.find((x) => x.id === id);
  if (!rec) return;
  if (patch.sid !== undefined) rec.sid = patch.sid;
  if (patch.name !== undefined) rec.name = patch.name;
  if (patch.s1 !== undefined) rec.s1 = patch.s1;
  if (patch.s2 !== undefined) rec.s2 = patch.s2;
  if (patch.s3 !== undefined) rec.s3 = patch.s3;
}
export function delSummary(state: AppState, ds: string, id: string): void {
  const arr = state.summaries && state.summaries[ds];
  if (!arr) return;
  state.summaries[ds] = arr.filter((x) => x.id !== id);
  if (!state.summaries[ds].length) delete state.summaries[ds];
}
export function summaryCount(state: AppState): number {
  let n = 0;
  const m = state.summaries || {};
  for (const ds in m) n += m[ds]!.length;
  return n;
}

/* ── CBMS 오답 분류(6·12절) — code ∈ C/B/M/S/T ── */
export const CBMS_INFO: Record<CbmsCode, { label: string; tip: string; color: string }> = {
  // 색은 의미론 토큰으로 — 예전엔 다크 전용 생 hex라 흰 패널 위에서 1.58~2.42:1로 읽히지 않았다
  // (칩이 코드 구분의 유일한 시각 단서인데). 토큰은 테마별로 갈리므로 두 테마 모두 통과한다.
  C: { label: '개념', tip: '교재 해당 단원 다시 정독(2절 ①로 복귀)', color: 'var(--bad)' },
  B: { label: '경계', tip: '그 문제 유형의 체크리스트 만들기', color: 'var(--warn)' },
  M: { label: '수학', tip: '도출 단계 백지 연습(손으로 끝까지)', color: 'var(--info)' },
  S: { label: '실수', tip: '검산 습관 + 단위 체크 자동화', color: 'var(--ok)' },
  T: { label: '시간', tip: '자주 막히는 계산 손에 익히기 + 시간 분배 훈련', color: 'var(--violet)' },
};
/** CBMS 코드 순서·집합의 단일 원천(SSOT) — CBMS_INFO에서 파생. Stats·Review·Journal이 각자
   `['C','B','M','S','T']`/`Object.keys(CBMS_INFO)`를 재선언하던 드리프트 위험을 봉쇄. */
export const CBMS_CODES = Object.keys(CBMS_INFO) as CbmsCode[];

/* ── P-3 복습 사다리를 **앞당기는** 유형(2026-08-01) ──────────────────────────
   여기까지 CBMS 코드는 **아무것도 안 바꿨다**: 5분류 + 코드별 처방까지 갖춰 놓고
   `grep cbms lib/scheduler/ lib/spacedReview.ts` 가 **0건**이었다. 즉 사용자가 매번 고르던
   5지선다가 화면 문구 말고는 어디에도 안 닿았다 — 방향 §1-b 의 세 번째 규율("넣었을 때 무엇이
   즉시 달라지는가")이 **이미 만들어 둔 슬롯에서** 위반되고 있던 자리다.

   가르는 축은 **지식 결손인가**다:
   · `C`(개념)·`B`(경계)·`M`(수학) — 몰라서 틀렸다. 다시 만나는 시점을 앞당길 근거가 된다.
   · `S`(실수)·`T`(시간)          — **알지만** 틀렸다. 부주의 오류는 개념 결손을 뜻하지 않으며
     피로·촉박에서 급증한다(IRIS/Vanderbilt · 확인 2026-08-01). 이걸 개념 오답과 같은 사다리에
     태우면 검산 한 번 놓친 챕터가 정말 모르는 챕터와 같은 급함을 갖는다 — 그게 **오탐**이다.

   ⚠ 임의 계수가 안 생긴다: *얼마나* 앞당길지는 여전히 `REVIEW_OFFSETS` 자신에서 나오고
     (`spacedReview.FAIL_DUE_DAYS`), 여기서 정하는 것은 *앞당길 것인가* 뿐이다.
   ⚠ **자동 분류는 하지 않는다** — `insights.ts` 가 _"LLM 자동 CBMS 분류가 조용한 오분류로
     드롭됐다"_ 고 못박았다. 이 표는 **사람이 고른 코드**의 뜻을 적을 뿐이다. */
export const CBMS_ADVANCES_REVIEW: ReadonlySet<CbmsCode> = new Set<CbmsCode>(['C', 'B', 'M']);

/** 코드별 카운트에서 최다 코드 + 전체합 — 임계 없는 argmax(문턱이 있는 dominantCbms와 별개).
   Stats(sort)·Review(reduce)가 각자 인라인하던 두 관용구를 하나로. 오답 0이면 null. */
export function cbmsTop(counts: Record<CbmsCode, number>): { code: CbmsCode; n: number; total: number } | null {
  let total = 0;
  let top: CbmsCode = CBMS_CODES[0]!;
  for (const c of CBMS_CODES) {
    const n = counts[c] || 0;
    total += n;
    if (n > (counts[top] || 0)) top = c;
  }
  return total ? { code: top, n: counts[top] || 0, total } : null;
}
/** conf: '찍어서 맞음/확신 없었음' 플래그(6절·E5).
 *  @returns 만들어진 기록의 id — 커밋 **뒤에** 메모만 덧붙이는 호출부(P-2 러너 인라인)가 쓴다.
 *    ⚠ 반환값을 안 쓰는 호출부가 대부분이다(그래서 추가여도 안전하다). */
export function addCbms(
  state: AppState,
  ds: string,
  sid: string,
  name: string,
  chapter: string,
  code: CbmsCode,
  note: string,
  conf?: boolean,
): string {
  state.cbms = state.cbms || [];
  const id = rid();
  state.cbms.push({
    id,
    ds: ds || todayISO(state), // '오늘' 단일 출처(_today 시드 존중) — 벽시계 직접 참조 금지
    sid: sid || '',
    name: name || '',
    chapter: chapter || '',
    code: code || 'C',
    note: note || '',
    conf: !!conf,
    at: Date.now(),
  });
  return id;
}
/** CBMS 오답 인라인 편집 — 챕터·유형·메모·확신플래그를 갈아끼운다(id·날짜·작성시각 보존). */
export function editCbms(
  state: AppState,
  id: string,
  patch: { chapter?: string; code?: CbmsCode; note?: string; conf?: boolean },
): void {
  const rec = (state.cbms || []).find((x) => x.id === id);
  if (!rec) return;
  if (patch.chapter !== undefined) rec.chapter = patch.chapter;
  if (patch.code !== undefined) rec.code = patch.code;
  if (patch.note !== undefined) rec.note = patch.note;
  if (patch.conf !== undefined) rec.conf = patch.conf;
}
export function delCbms(state: AppState, id: string): void {
  state.cbms = (state.cbms || []).filter((x) => x.id !== id);
}
/** [fromDs,toDs] 구간(포함) 코드별 카운트. 인자 없으면 전체. */
export function cbmsCounts(state: AppState, fromDs?: string, toDs?: string): Record<CbmsCode, number> {
  const out: Record<CbmsCode, number> = { C: 0, B: 0, M: 0, S: 0, T: 0 };
  (state.cbms || []).forEach((e) => {
    if (fromDs && e.ds < fromDs) return;
    if (toDs && e.ds > toDs) return;
    if (out[e.code] != null) out[e.code]++;
  });
  return out;
}
export function cbmsBetween(state: AppState, fromDs?: string, toDs?: string) {
  return (state.cbms || []).filter((e) => (!fromDs || e.ds >= fromDs) && (!toDs || e.ds <= toDs));
}
/** 과신 오답률(E5) — [fromDs,toDs] 구간에서 conf('찍어서 맞음/확신 없었음') 플래그 비율.
   지식엔진 캘리브레이션 산출물과 달리 앱 상태(cbms[].conf)만으로 실시간. 오답 없으면 null. */
export function confRate(
  state: AppState,
  fromDs?: string,
  toDs?: string,
): { conf: number; total: number; rate: number } | null {
  const rows = cbmsBetween(state, fromDs, toDs);
  if (!rows.length) return null;
  const conf = rows.filter((e) => e.conf).length;
  return { conf, total: rows.length, rate: Math.round((conf / rows.length) * 100) };
}
/* ⚠ **삭제 되돌리기 복원 3종(`restoreSummary`·`restoreCbms`·`restoreBacklog`)이 사라졌다**
   (근본① · 2026-08-01). 그것들은 `useRecordEditor` 가 6.5초 토스트 창 안에서 부르던 역연산이고,
   전역 ⌘Z 가 **행 단위 pre-image** 로 같은 일을 테이블 무관하게 한다(`lib/db/undoStack`).
   되살릴 이유가 생긴다면 그건 "역연산이 필요하다"가 아니라 "⌘Z 가 그 슬라이스를 못 덮는다"는
   뜻이므로, 먼저 그쪽을 보라 — 사본을 두 벌 두는 것이 이 저장소가 반복해 물린 형태다. */

/* ── 백지 복습 결과(9절·E4) — 통과/막힘 실측. 하루·과목당 1개(중복 갱신).
   막힘+메모는 CBMS(C 개념)로 자동 연결(직전이 이미 막힘이면 중복 생성 금지). ── */
export function setBlankResult(
  state: AppState,
  ds: string,
  sid: string,
  name: string,
  passed: boolean,
  note: string,
  chapter: string,
): void {
  state.blankResults = state.blankResults || [];
  const prior = blankResultFor(state, ds, sid);
  state.blankResults = state.blankResults.filter((x) => !(x.ds === ds && x.sid === (sid || '')));
  state.blankResults.push({
    id: rid(),
    ds: ds || todayISO(state), // '오늘' 단일 출처(_today 시드 존중) — 벽시계 직접 참조 금지
    sid: sid || '',
    name: name || '',
    passed: !!passed,
    note: note || '',
    /* ⚠ 챕터를 **기록에도 남긴다**(근본이관 ① · 2026-08-01). 종전엔 이 인자를 받아 놓고
       아래 `addCbms` 로 흘려보내기만 했다 — 즉 "어느 챕터에서 막혔나"는 CBMS 항목에만 남고
       `blankResults` 자신은 과목 단위로만 알았다. 그래서 통과율은 과목 단위로만 낼 수 있었고,
       되먹임 루프(②)가 필요로 하는 **챕터당 증거**가 원리적으로 안 모였다.
       빈 문자열은 안 담는다 — `undefined` 와 `''` 가 같은 뜻이면 소비처마다 둘 다 검사해야 한다. */
    ...(chapter ? { chapter } : {}),
  });
  if (!passed && (note || chapter) && !(prior && !prior.passed))
    addCbms(state, ds, sid, name, chapter || '', 'C', '[백지복습 막힘] ' + (note || ''), false);
}
export function blankResultFor(state: AppState, ds: string, sid: string): BlankResult | null {
  return (state.blankResults || []).find((x) => x.ds === ds && x.sid === (sid || '')) || null;
}
export function clearBlankResult(state: AppState, ds: string, sid: string): void {
  state.blankResults = (state.blankResults || []).filter((x) => !(x.ds === ds && x.sid === (sid || '')));
}
/** [fromDs,toDs] 백지 통과율. 기록 없으면 null('미측정'을 '근사'와 구분). */
export function blankPassRate(
  state: AppState,
  fromDs?: string,
  toDs?: string,
): { total: number; passed: number } | null {
  const rs = (state.blankResults || []).filter((x) => (!fromDs || x.ds >= fromDs) && (!toDs || x.ds <= toDs));
  if (!rs.length) return null;
  return { total: rs.length, passed: rs.filter((x) => x.passed).length };
}

/* ── '보충 필요' 백로그(5절) ──
   ⚠ **id 를 돌려준다**(E2) — 캡처가 곧 커밋이 되면서 "방금 담은 그것"만 되돌릴 수 있어야 했다.
   목록 끝을 지우는 식으로 되돌리면 그 사이에 다른 쓰기가 끼었을 때 엉뚱한 항목이 사라진다. */
export function addBacklog(
  state: AppState,
  sid: string,
  name: string,
  topic: string,
  note: string,
  /* I042 — 캡처가 만든 것은 **판정 전**이다(`false`). 손으로 만든 보충은 이미 판정된 것이라
     기본이 `true` 다 — 그 구분이 이 인자의 전부다. */
  triaged = true,
): string {
  state.backlog = state.backlog || [];
  const id = rid();
  state.backlog.push({
    id,
    ds: todayISO(state), // '오늘' 단일 출처(_today 시드 존중) — 벽시계 직접 참조 금지
    sid: sid || '',
    name: name || '',
    topic: topic || '',
    note: note || '',
    done: false,
    doneDs: '',
    at: Date.now(),
    triaged,
  });
  return id;
}
/** 보충 백로그 한 건 제거(되돌리기 전용) — 없으면 무동작. */
export function removeBacklog(state: AppState, id: string): void {
  state.backlog = (state.backlog || []).filter((x) => x.id !== id);
}
/** 보충 백로그 인라인 편집 — 주제·메모를 갈아끼운다(id·날짜·완료상태 보존). */
export function editBacklog(state: AppState, id: string, patch: { topic?: string; note?: string }): void {
  const rec = (state.backlog || []).find((x) => x.id === id);
  if (!rec) return;
  if (patch.topic !== undefined) rec.topic = patch.topic;
  if (patch.note !== undefined) rec.note = patch.note;
}
export function toggleBacklog(state: AppState, id: string): void {
  const b = (state.backlog || []).find((x) => x.id === id);
  if (!b) return;
  b.done = !b.done;
  b.doneDs = b.done ? todayISO(state) : ''; // '오늘' 단일 출처(_today 시드 존중) — 벽시계 직접 참조 금지
}
export function delBacklog(state: AppState, id: string): void {
  state.backlog = (state.backlog || []).filter((x) => x.id !== id);
}
/* ⚠ 입력을 `Pick<AppState,'backlog'>` 로 좁혔다(H17) — 이 함수가 읽는 것이 그 한 슬라이스뿐이고,
   타입이 그 사실을 말하면 호출부가 **전체 상태를 구독하지 않고** 그 조각만 구독할 수 있다.
   전체 상태를 요구하면 셀렉터가 루트를 물게 되고, 그게 무관 쓰기마다 리렌더를 만든다. */
export function openBacklog(state: Pick<AppState, 'backlog'>, todayDs?: string): Backlog[] {
  /* I042 — 미룬 것은 그 날짜까지 목록에서 빠진다. `todayDs` 를 안 주면 종전 그대로다
     (호출부가 스무 곳이라, 날짜를 모르는 자리에서 스누즈를 무시하는 편이 안전하다 —
     그 자리들이 세는 것은 «열린 것의 총량»이지 «오늘 볼 것»이 아니다). */
  const open = (state.backlog || []).filter((b) => !b.done);
  return todayDs ? open.filter((b) => !b.snoozeUntil || b.snoozeUntil <= todayDs) : open;
}

/* ── I042 캡처 트리아지 ───────────────────────────────────────────────────────────────
   ⚠ **별도 목록을 만들지 않는다.** 미분류는 `triaged:false` 인 열린 보충이고, 그래서 판정을
   건너뛰어도 그 항목은 여전히 백로그에 있다 — 트리아지가 **새 백로그가 되지 않는 유일한 방법**
   이다(밖의 표본이 경고한 그 대가). 근거 전문은 `schema.ts` 의 `BacklogSchema` 주석. */

/** 아직 판정 안 된 캡처(오늘 기준). 옛 항목(`triaged` 없음)은 판정된 것으로 읽는다. */
export function untriagedBacklog(state: Pick<AppState, 'backlog'>, todayDs?: string): Backlog[] {
  return openBacklog(state, todayDs).filter((b) => b.triaged === false);
}

/** 판정 완료로 표시(과목을 함께 줄 수 있다 — 「지금 배정」). */
export function triageBacklog(st: AppState, id: string, sid = '', name = ''): void {
  const b = (st.backlog || []).find((x) => x.id === id);
  if (!b) return;
  b.triaged = true;
  if (sid) {
    b.sid = sid;
    b.name = name;
  }
}

/** N일 뒤로 미룬다. **판정도 함께 끝난 것으로 본다** — 「나중에 본다」가 곧 판정이다.
 *  ⚠ 안 그러면 그 항목이 돌아올 때마다 다시 미분류라, 미루기가 판정 노동을 영구히 되살린다. */
export function snoozeBacklog(st: AppState, id: string, untilDs: string): void {
  const b = (st.backlog || []).find((x) => x.id === id);
  if (!b) return;
  b.snoozeUntil = untilDs;
  b.triaged = true;
}
export function backlogClosedBetween(state: AppState, fromDs?: string, toDs?: string): number {
  return (state.backlog || []).filter(
    (b) => b.done && b.doneDs && (!fromDs || b.doneDs >= fromDs) && (!toDs || b.doneDs <= toDs),
  ).length;
}

/* ── 주간 리뷰(10절) — 키: 그 주 월요일 ISO ── */
export function setWeeklyCheck(state: AppState, wk: string, k: string, on: boolean): void {
  state.weekly = state.weekly || {};
  const w = (state.weekly[wk] = state.weekly[wk] || { checks: {}, note: '' });
  w.checks = w.checks || {};
  w.checks[k] = !!on;
}
export function setWeeklyNote(state: AppState, wk: string, note: string): void {
  state.weekly = state.weekly || {};
  const w = (state.weekly[wk] = state.weekly[wk] || { checks: {}, note: '' });
  w.note = note || '';
}

/* ── 일일 의식(아침 계획·저녁 셧다운) ── */
// ⚠ `val` 에 `number` 가 붙은 것은 T-10 `stopPending`(그날 남아 있던 블록 수) 때문이다 —
//   종전엔 의식이 boolean 셋 + 문자열 하나뿐이라 시그니처가 그 둘만 알았다.
export function setRitual(state: AppState, ds: string, key: keyof Ritual, val: boolean | string | number): void {
  state.rituals = state.rituals || {};
  const r: Ritual = state.rituals[ds] || { plan: false, shutdown: false, note: '' };
  (r as Record<string, boolean | string | number>)[key] = val;
  state.rituals[ds] = r;
}

/* ── Anki 카드 초안(7절) — 요약·반복 오답을 Anki import용 TSV(.txt) 라인으로. ── */
function _cf(s: unknown): string {
  return (s ?? '').toString().replace(/\t/g, ' ').replace(/\r?\n/g, '<br>');
}
export function buildAnkiCards(state: AppState, fromDs?: string, toDs?: string): string[] {
  const lines: string[] = [];
  const sm = state.summaries || {};
  Object.keys(sm)
    .sort()
    .forEach((ds) => {
      if (fromDs && ds < fromDs) return;
      if (toDs && ds > toDs) return;
      (sm[ds] || []).forEach((x) => {
        const front = _cf((x.name ? '[' + x.name + '] ' : '') + (x.s1 || '핵심 현상·문제는?'));
        const back = _cf(['How(도구): ' + (x.s2 || ''), 'Result(결과·의미): ' + (x.s3 || '')].join('\n'));
        const tag = '요약' + (x.name ? '::' + x.name.replace(/\s+/g, '_') : '');
        lines.push([front, back, tag].join('\t'));
      });
    });
  (state.cbms || []).forEach((e) => {
    if (fromDs && e.ds < fromDs) return;
    if (toDs && e.ds > toDs) return;
    const inf = CBMS_INFO[e.code] || { label: '', tip: '' };
    const front = _cf((e.name ? '[' + e.name + '] ' : '') + (e.chapter || '') + ' — 어디서 왜 막혔나?');
    const back = _cf((e.note || '(메모 없음)') + '\n처방(' + e.code + ' ' + inf.label + '): ' + inf.tip);
    lines.push([front, back, '오답::' + e.code].join('\t'));
  });
  return lines;
}

/** 3문장 요약을 날짜·과목별 마크다운 한 장으로(볼트 '연결'용). */
export function buildSummaryNotes(state: AppState, fromDs?: string, toDs?: string): string {
  const sm = state.summaries || {};
  const dss = Object.keys(sm)
    .sort()
    .filter((ds) => (!fromDs || ds >= fromDs) && (!toDs || ds <= toDs) && (sm[ds] || []).length);
  if (!dss.length) return '';
  const md = [
    '# 러닝허브 요약 노트',
    '',
    `> 생성 ${todayISO(state)} · ${dss.length}일치 3문장 요약 · #러닝허브/요약`,
    '',
  ];
  dss.forEach((ds) => {
    md.push('## ' + ds, '');
    (sm[ds] || []).forEach((x) => {
      md.push('### ' + ((x.name ? x.name + ' — ' : '') + (x.s1 || '(핵심 현상·문제)')));
      if (x.s2) md.push('- **도구·어떻게**: ' + x.s2);
      if (x.s3) md.push('- **결과·의미**: ' + x.s3);
      md.push('');
    });
  });
  return md.join('\n');
}

/* ── 데이터 규모/아카이빙 ── */
export function dataSizeKB(state: AppState): number {
  try {
    return Math.round(JSON.stringify(state).length / 1024);
  } catch {
    return 0;
  }
}
/** 기록 수 범주별 분해(완료·요약·오답·백로그·백지) — recordCount의 중간값을 버리지 않고 반환.
   Settings가 "무엇이 저장을 지배하나"를 진단(막연한 총합 → 구성비). */
export function recordBreakdown(state: AppState): {
  done: number;
  summaries: number;
  cbms: number;
  backlog: number;
  blank: number;
} {
  let done = 0;
  const c = state.completions || {};
  for (const k in c) done += Object.keys(c[k]!).length;
  let summaries = 0;
  const s = state.summaries || {};
  for (const k in s) summaries += s[k]!.length;
  return {
    done,
    summaries,
    cbms: (state.cbms || []).length,
    backlog: (state.backlog || []).length,
    blank: (state.blankResults || []).length,
  };
}
export function recordCount(state: AppState): number {
  const b = recordBreakdown(state);
  return b.done + b.summaries + b.cbms + b.backlog + b.blank;
}
/* ============================================================
   아카이브 대상 — **한 곳에 선언한다**(D008 · 2026-08-21 데이터 축).

   ## 무엇이 틀렸었나

   `archivableCount` 와 `archiveOldData` 는 같은 목록을 **각자 손으로** 들고 있었고, 그 목록은
   다섯 슬라이스에서 멈춰 있었다. 그 뒤로 `ARRAY_SLICES` 가 아홉까지 자랐지만 아무도 여기를
   갱신하지 않았다 — 즉 **아홉이 어느 보존 규율에도 없었다**: `events`·`tasks`·`questions`·
   `jolAsks`·`retrievals`·`dayPlans`·`dayOverrides`·`rituals`·`weekAlloc`.

   그중 `retrievals` 가 특히 나빴다: 복습 카드를 펼칠 때마다 1행이고 `records`(sync 대상)로
   가므로 **모든 행이 아웃박스 → D1 → 폰**까지 간다. 상한·프루닝·아카이브가 전부 0이었다
   (하루 50카드면 연 18,250행 ≈ 2MB 가 로컬·D1·폰 각각).

   부수 효과도 있었다: 설정 화면이 `dataSizeKB`(전량)와 `archivableCount`(다섯)를 나란히
   그리므로, 아홉이 자란 만큼 두 수가 벌어지고 «정리»를 눌러도 그만큼은 안 준다.

   ## 처방이 목록 추가가 아닌 이유

   손으로 적은 목록은 표류한다 — 이 저장소의 규율인데 문서에만 적용돼 있었다(오버레이 §1-A).
   그래서 ① 선언을 **하나**로 만들어 두 함수가 같이 돌게 하고 ② `test/methodology.test.ts` 가
   `ARRAY_SLICES`·`DS_MAP_SLICES` 와 대조해 **새 슬라이스가 규율 밖에 있으면 실패**시킨다.
   면제도 목록이 아니라 **사유가 붙은 표**다(사유 없는 면제는 방치의 다른 이름이다).

   ⚠ `records` 슬라이스는 `TABLES` 안이라 나중에 걷어도 툼스톤이 정상 전파된다 — 그게 이
   항목이 Critical 이 아닌 이유이자, 여기서 지워도 안전한 이유다(도달 불가가 되는 `docs` 와
   결정적으로 다르다).
============================================================ */

/** 배열 슬라이스 한 종의 아카이브 규칙 — 「그 행의 날짜는 무엇인가」 하나만 정한다. */
interface ArraySpec {
  slice: ArchivableArraySlice;
  /** cutoff 와 비교할 날짜. `undefined` 면 **절대 아카이브하지 않는다**(인박스·미완료). */
  dsOf: (row: never) => string | undefined;
}

/** 아카이브가 다루는 배열 슬라이스. ⚠ 여기 없는 `ARRAY_SLICES` 항목은 `면제` 표에 사유가 있어야 한다. */
export type ArchivableArraySlice =
  'cbms' | 'backlog' | 'blankResults' | 'events' | 'tasks' | 'questions' | 'jolAsks' | 'retrievals';

const 날짜 = (r: { ds?: string }): string | undefined => r.ds;
/** 완료된 것만 — 미완료는 아무리 오래돼도 «아직 할 일» 이다(backlog·tasks 공통 규칙). */
const 완료날짜 = (r: { done?: boolean; doneDs?: string; ds?: string }): string | undefined =>
  r.done ? (r.doneDs ?? r.ds) : undefined;

export const ARCHIVE_ARRAY_SPECS: readonly ArraySpec[] = [
  { slice: 'cbms', dsOf: 날짜 },
  { slice: 'backlog', dsOf: 완료날짜 },
  { slice: 'blankResults', dsOf: 날짜 },
  /* 지난 일정은 기록이다 — `ds` 가 필수인 슬라이스라 인박스 개념이 없다. */
  { slice: 'events', dsOf: 날짜 },
  /* ⚠ 할 일은 **완료된 것만**. `ds` 가 없는 행은 «언젠가»(인박스)라 날짜로 재면 안 되고,
     미완료를 걷으면 사용자가 잃는 것이 기록이 아니라 **아직 안 한 일**이다. */
  { slice: 'tasks', dsOf: 완료날짜 },
  { slice: 'questions', dsOf: 날짜 },
  { slice: 'jolAsks', dsOf: 날짜 },
  /* A-2 인출 지연 원장 — 이 항목이 D008 의 본체다(무제한 append + 동기화 대상이었다). */
  { slice: 'retrievals', dsOf: 날짜 },
];

/** 아카이브 밖인 슬라이스와 **그 사유**. 사유 없는 면제는 방치다 — 테스트가 이 표를 대조한다. */
export const ARCHIVE_EXEMPT: Record<string, string> = {
  retentionLog: '주별 스냅샷 — 추세 그 자체가 값이라 걷으면 재는 대상이 사라진다',
  weekly: '과목별 주간 설정 — 기록이 아니라 설정',
  weekAlloc: '주간 배분 — 스케줄러 **입력**이다(걷으면 과거 주 재계산이 달라진다)',
  /* I053 — 전공 밖 레인. `weekAlloc` 과 **같은 형상**(주 키 → 7요일 벡터)이지만 면제 사유는
     다르다: 저건 스케줄러 입력이라 못 걷고, 이건 걷어도 배치가 안 바뀌는 대신 **주당 최대
     7숫자**라 자라는 속도가 무시할 만하다. 그리고 전부 0이 되면 `setOutsideCell` 이 키 자체를
     지운다(빈 주가 안 쌓인다). ⚠ 그 삭제가 사라지면 이 사유도 함께 무효다. */
  outsideAlloc: '전공 밖 시간 — 주당 최대 7숫자이고 전부 0이면 키가 삭제된다(자라지 않는다)',
  rituals: '하루 의식 — 날짜 키지만 한 줄짜리 설정성 기록이고 `completions` 와 함께 읽힌다',
  dayPlans: '그날의 계획 배치 — 날짜 키지만 `completions` 의 짝이라 함께 걷어야 뜻이 유지된다',
  dayOverrides: '동상 — `dayPlans` 와 한 쌍',
  resume: '기기별 1행(이어하기 커서) — 자라지 않는다',
};

/** cutoff 이전인가. `undefined` 는 언제나 거짓(= 아카이브 대상 아님). */
const 이전 = (ds: string | undefined, cutoff: string): boolean => !!ds && ds < cutoff;

const cutoffOf = (state: AppState, monthsKeep: number): string =>
  iso(addDays(parseISO(todayISO(state)), -Math.round(monthsKeep * 30)));

/** 아카이브 가능량(mutation 없는 사전 카운트) — `archiveOldData` 와 **같은 선언**에서 돈다.
   블라인드 위험버튼(정리)을 "6개월 이전 N건 보관 가능"으로 승격(N=0이면 정리할 것 없음). */
export function archivableCount(state: AppState, monthsKeep = 6): number {
  const cutoff = cutoffOf(state, monthsKeep);
  let n = 0;
  const c = state.completions || {};
  for (const ds in c) if (ds < cutoff) n += Object.keys(c[ds]!).length;
  const sm = state.summaries || {};
  for (const ds in sm) if (ds < cutoff) n += sm[ds]!.length;
  for (const spec of ARCHIVE_ARRAY_SPECS) {
    const rows = (state[spec.slice] ?? []) as never[];
    n += rows.filter((r) => 이전(spec.dsOf(r), cutoff)).length;
  }
  return n;
}
export interface ArchiveResult {
  archive: {
    schemaVersion: number;
    archivedAt: string;
    cutoff: string;
    completions: AppState['completions'];
    summaries: AppState['summaries'];
  } & { [K in ArchivableArraySlice]: NonNullable<AppState[K]> };
  count: number;
}
/**
 * cutoff(기본 6개월) 이전 기록을 archive로 분리하고 state에서 비운다(다운로드는 호출부).
 *
 * `cutoffOverride` 는 **같은 경계를 두 번 계산하지 않기 위한** 인자다(H2 · 2026-07-30).
 *
 * `shell/actions.ts` 의 `archiveOld` 는 이제 ① 사본에서 보관 payload 를 만들고 ② 저장이
 * **성공한 뒤에** 실제 상태를 비운다(H19 와 같은 규율 — 복구 경로가 복구 대상을 파괴하면 안 된다).
 * 그 둘 사이에는 사용자가 저장 대화를 붙들고 있는 **임의의 시간**이 있고, 그동안 자정을 넘기면
 * 두 번째 호출의 cutoff 가 하루 밀려 **보관한 것과 지운 것이 어긋난다**(archive 엔 없는 날이
 * 지워지거나 그 반대). 첫 호출이 정한 경계를 그대로 물려줘 그 창을 없앤다.
 */
export function archiveOldData(state: AppState, monthsKeep = 6, cutoffOverride?: string): ArchiveResult {
  // '오늘' 단일 출처(_today 시드 존중). 넘겨받았으면 그 값이 진리다(위 주석).
  const cutoff = cutoffOverride ?? cutoffOf(state, monthsKeep);
  const arch = {
    schemaVersion: SCHEMA_VERSION,
    archivedAt: new Date().toISOString(),
    cutoff,
    completions: {},
    summaries: {},
  } as ArchiveResult['archive'];
  for (const spec of ARCHIVE_ARRAY_SPECS) (arch[spec.slice] as unknown[]) = [];
  let n = 0;
  const c = state.completions || {};
  Object.keys(c).forEach((ds) => {
    if (ds < cutoff) {
      arch.completions[ds] = c[ds]!;
      delete c[ds];
      n += Object.keys(arch.completions[ds]!).length;
    }
  });
  const sm = state.summaries || {};
  Object.keys(sm).forEach((ds) => {
    if (ds < cutoff) {
      arch.summaries[ds] = sm[ds]!;
      delete sm[ds];
      n += arch.summaries[ds]!.length;
    }
  });
  for (const spec of ARCHIVE_ARRAY_SPECS) {
    const rows = (state[spec.slice] ?? []) as never[];
    const old = rows.filter((r) => 이전(spec.dsOf(r), cutoff));
    (arch[spec.slice] as unknown[]) = old;
    (state as Record<string, unknown>)[spec.slice] = rows.filter((r) => !이전(spec.dsOf(r), cutoff));
    n += old.length;
  }
  return { archive: arch, count: n };
}

/* ── 유지율(retention) 추세(E6·F-05) — AnkiConnect due를 주별 스냅샷 ── */
interface DeckLike {
  new?: number;
  learn?: number;
  review?: number;
  total?: number;
}
export function recordRetentionSnapshot(state: AppState, decks: DeckLike[]): void {
  if (!Array.isArray(decks)) return;
  const due = decks.reduce((t, d) => t + +(d.new || 0) + +(d.learn || 0) + +(d.review || 0), 0);
  const cards = decks.reduce((t, d) => t + +(d.total || 0), 0);
  const wk = iso(mondayOf(parseISO(todayISO(state)))); // 그 주 월요일 — '오늘' 단일 출처(_today 시드 존중)
  /* ⚠⚠ **값이 안 바뀌었으면 아무것도 안 한다(H17 · 2026-07-31 `/감사 근본`).**

     `at` 이 매 호출마다 새 ISO 시각이라 `due`·`cards` 가 **완전히 같아도 행이 실제로 변했다.**
     `retentionLog` 는 `records` 테이블이고 `sync: true` 라, 통합 탭의 자동 새로고침(5분)이
     `applyLive` → 여기 → `syncedSliceChanged` → `syncSoon()` 로 이어져 **5분마다 Workers 요청
     한 쌍 + D1 행 쓰기 1건**을 냈다(하루 288회). W24 가 은퇴시킨 5분 폴링이 다른 문으로
     돌아온 셈이다 — 그리고 `syncController` 는 바로 그 예산을 명시 제약으로 든다.

     `artifactMirror.ts:99`(_"무변경 — 스탬프를 찍지 않는다"_)가 이미 쓰는 관용구다.
     ⚠ `at` 은 **비교에서 뺀다** — 그게 항상 달라지는 축이라 넣으면 가드가 정의상 무력해진다. */
  const prev = (state.retentionLog || []).find((x) => x.wk === wk);
  if (prev && prev.due === due && prev.cards === cards) return;
  state.retentionLog = (state.retentionLog || []).filter((x) => x.wk !== wk);
  state.retentionLog.push({ wk, at: new Date().toISOString(), due, cards });
  state.retentionLog.sort((a, b) => (a.wk < b.wk ? -1 : a.wk > b.wk ? 1 : 0));
  if (state.retentionLog.length > 26) state.retentionLog = state.retentionLog.slice(-26);
}
export function retentionTrend(state: AppState) {
  const pts = (state.retentionLog || []).slice();
  if (!pts.length) return { points: [], latest: null, prev: null, delta: 0, has: false };
  const latest = pts[pts.length - 1]!;
  const prev = pts.length > 1 ? pts[pts.length - 2] : null;
  return { points: pts, latest, prev, delta: prev ? prev.due - latest.due : 0, has: true };
}

/** 유지율 넛지(F-05 능동화) — due가 지난주보다 늘고 절대량도 유의미하면 경고 문구, 아니면 null.
 *  임계(20장)는 '하루면 지울 수 있는 양'은 조용히 넘어가려는 보수적 기준. */
export function retentionNudge(state: AppState): string | null {
  const t = retentionTrend(state);
  if (!t.has || !t.prev || !t.latest) return null;
  const delta = t.latest.due - t.prev.due;
  if (delta <= 0 || t.latest.due < 20) return null;
  return `복습이 밀리는 중 — Anki 대기 ${t.latest.due}장(지난주보다 +${delta}). 오늘 Anki 블록을 먼저 처리해 보세요.`;
}

/* ── 활동 피드(기록 탭) — 최근 N일의 학습 발자취를 시간역순 단일 리스트로 ── */
export interface ActivityEntry {
  ds: string;
  kind: 'done' | 'summary' | 'cbms' | 'backlog' | 'blank';
  label: string;
  detail: string;
}
/** 완료·요약·오답·보충회수·백지결과를 [fromDs, toDs] 구간에서 모아 날짜 내림차순으로. */
export function activityFeed(state: AppState, fromDs: string, toDs: string, cap = 60): ActivityEntry[] {
  const inRange = (ds?: string) => !!ds && ds >= fromDs && ds <= toDs;
  const nameOf = (sid: string) => (state.items || []).find((it) => it.id === sid)?.name || '';
  const out: ActivityEntry[] = [];
  const c = state.completions || {};
  for (const ds in c) {
    if (!inRange(ds)) continue;
    for (const key in c[ds]) {
      const e = c[ds]![key]!;
      if (!e || e.done !== true) continue;
      const sid = keySid(key);
      out.push({ ds, kind: 'done', label: '블록 완료', detail: nameOf(sid || '') || key });
    }
  }
  for (const ds in state.summaries || {}) {
    if (!inRange(ds)) continue;
    (state.summaries![ds] || []).forEach((x) =>
      out.push({ ds, kind: 'summary', label: '3문장 요약', detail: (x.name ? x.name + ' — ' : '') + (x.s1 || '') }),
    );
  }
  (state.cbms || []).forEach((e) => {
    if (!inRange(e.ds)) return;
    out.push({
      ds: e.ds,
      kind: 'cbms',
      label: `오답(${e.code})`,
      detail: (e.name ? e.name + ' — ' : '') + (e.chapter || e.note || ''),
    });
  });
  (state.backlog || []).forEach((b) => {
    if (!b.done || !inRange(b.doneDs)) return;
    out.push({ ds: b.doneDs, kind: 'backlog', label: '보충 완료', detail: (b.name ? b.name + ' — ' : '') + b.topic });
  });
  (state.blankResults || []).forEach((x) => {
    if (!inRange(x.ds)) return;
    out.push({ ds: x.ds, kind: 'blank', label: x.passed ? '백지 복습 통과' : '백지 복습 막힘', detail: x.name || '' });
  });
  return out.sort((a, b) => (a.ds < b.ds ? 1 : a.ds > b.ds ? -1 : 0)).slice(0, cap);
}

/** 인출 증거(14절) — CBMS 주간 추세. */
export function cbmsTrend(state: AppState): { thisW: number; lastW: number } {
  const mon = mondayOf(parseISO(todayISO(state))); // 앱의 '오늘' 단일 출처(_today 시드 존중)

  const thisW = cbmsBetween(state, iso(mon), iso(addDays(mon, 6))).length;
  const lastMon = addDays(mon, -7);
  const lastW = cbmsBetween(state, iso(lastMon), iso(addDays(lastMon, 6))).length;
  return { thisW, lastW };
}

/** 과신(conf) 오답률 주별 시계열(I-5) — 최근 weeks주(오래된→최신). confRate는 단일 구간 스냅샷,
   이건 주 단위로 쪼갠 스파크라인용 시리즈. 표본게이트: 그 주 오답 0이면 rate=null(0%로 오도 금지).
   cbmsTrend와 같은 mondayOf(_today) 정렬. */
export function confTrend(
  state: AppState,
  weeks = 6,
): { weekMon: string; conf: number; total: number; rate: number | null }[] {
  const mon0 = mondayOf(parseISO(todayISO(state)));
  const out: { weekMon: string; conf: number; total: number; rate: number | null }[] = [];
  for (let i = weeks - 1; i >= 0; i--) {
    const mon = addDays(mon0, -7 * i);
    const rows = cbmsBetween(state, iso(mon), iso(addDays(mon, 6)));
    const total = rows.length;
    const conf = rows.filter((e) => e.conf).length;
    out.push({ weekMon: iso(mon), conf, total, rate: total ? Math.round((conf / total) * 100) : null });
  }
  return out;
}

/* ============================================================
   persistence.ts — 기본값·검증·migrate·부팅/영속·내보내기·완료추적.
   레거시 js/state.js 이식. **데이터 100% 호환**이 절대 제약:
   - KEY('study_planner_v3')·SCHEMA_VERSION(3)·필드/스키마 불변.
