/* ── defaults-동형(무활동) 판정(감사 재검증 ⑩#1·#2) ──
   fallback 부팅한 탭의 첫 flush가 IDB 미러를 defaults로 덮으면 그 미러는 '유효한 JSON'이라
   parse 검사를 통과한다 — 복구·백업 링이 실데이터 대신 defaults를 잡는 원인. 사용자 활동
   흔적이 전혀 없는 상태를 판정해 (a) restoreFromIDB가 세대 백업을 우선하고 (b) 백업 링에
   defaults를 밀어넣지 않게 한다. routine/설정 커스터마이즈만 있고 활동 0인 상태도 pristine으로
   보는 보수적 판정(활동 데이터 보존이 우선). */
const ACTIVITY_KEYS = [
  'completions',
  'dayOverrides',
  'items',
  'summaries',
  'cbms',
  'backlog',
  'blankResults',
  'retentionLog',
  'weekly',
  'rituals',
  'reviewTouches',
  'dayPlans', // 일일 배치 오버라이드(§4-1) — 사용자 소유 활동
  'tasks', // 자유 할 일(§4-4) — 사용자 소유 활동
  'events', // 일정(Wave 5) — 사용자 소유 활동
  'weekAlloc', // 주간 배분(§12-3) — 사용자 소유 활동
] as const;
export function isPristineState(s: AppState): boolean {
  const src = s as unknown as Record<string, unknown>;
  return ACTIVITY_KEYS.every((k) => {
    const v = src[k];
    if (v == null) return true;
    if (Array.isArray(v)) return v.length === 0;
    if (typeof v === 'object') return Object.keys(v).length === 0;
    return false;
  });
}

/** 최소 구조 검증 — 엉뚱한 JSON을 그대로 덮어써 앱이 깨지는 것 방지. */
export function validShape(s: unknown): boolean {
  if (!s || typeof s !== 'object') return false;
  const o = s as Record<string, unknown>;
  const deg = o.degree as { semesters?: unknown } | undefined;
  return (
    Array.isArray(o.items) &&
    Array.isArray(o.routine) &&
    !!deg &&
    Array.isArray(deg.semesters) &&
    typeof o.startDate === 'string'
  );
}

/* ── `migrate` 의 표 (2026-08-20 리뷰 M-14 원장 축소) ──────────────────────────
   ⚠ **동작은 한 글자도 안 바뀐다.** 종전엔 같은 모양의 `if` 가 열아홉 줄 늘어서 있었고 그게
   `migrate` 인지복잡도의 대부분이었다 — 어려운 분기가 아니라 **많은 분기**였다. 표로 옮기면
   "새 필드가 생기면 여기 한 줄"이라는 규칙이 코드 모양으로 드러나고, 분기 수는 셋이 된다.
   ⚠ `migrate` 자체는 여전히 **회귀로 동결**이다(byte-exact) — 그래서 표의 키 순서도 옛 코드
   순서 그대로 뒀다(순서 의존은 없지만, 대조를 사람이 눈으로 할 수 있어야 한다). */

/** `null`/`undefined` 면 기본값에서 채우는 키. */
const FILL_FROM_DEFAULTS = [
  'dayOverrides',
  'blankReviewWeekly',
  'mockEveryWeeks',
  'adaptiveCapacity',
  'peakStart',
  'peakEnd',
  'reviewViaAnki',
  'graphPriority',
] as const;
/** 객체가 아니면 `{}` 로 세우는 키(값의 내용은 안 본다 — 그건 `sanitizeImported` 몫). */
const ENSURE_OBJECT = ['completions', 'summaries', 'weekly', 'rituals'] as const;
/** 배열이 아니면 `[]` 로 세우는 키. */
const ENSURE_ARRAY = ['cbms', 'backlog', 'blankResults', 'retentionLog'] as const;

function fillDefaults(s: Record<string, unknown>, d: AppState): void {
  const dd = d as unknown as Record<string, unknown>;
  // 테마는 **정규화**라 표와 다르다: 폐기된 값(세피아 등)도 다크로 되돌린다.
  if (s.theme !== 'light' && s.theme !== 'dark') s.theme = d.theme;
  for (const k of FILL_FROM_DEFAULTS) if (s[k] == null) s[k] = dd[k];
  for (const k of ENSURE_OBJECT) if (s[k] == null || typeof s[k] !== 'object') s[k] = {};
  for (const k of ENSURE_ARRAY) if (!Array.isArray(s[k])) s[k] = [];
}

/** 졸업 계획 백필 — '손대지 않은 기본값'(과목 0 + 요건 3값 모두 0 = 옛 defaults)일 때만 1회.
 *  과목을 하나라도 편성했거나 요건을 설정한 사용자는 절대 건드리지 않는다(빈 상태 존중).
 *  ⚠ m-14 이후 `d.degree` 는 **요건 임계 + 빈 학기**다(옛 성적표 시드가 아니다). */
function backfillDegree(s: Record<string, unknown>, d: AppState): void {
  const dg = s.degree as
    | { reqMajorReq?: number; reqMajorSel?: number; reqLiberal?: number; semesters?: { courses?: unknown[] }[] }
    | undefined;
  if (!dg) return;
  const hasCourses =
    Array.isArray(dg.semesters) && dg.semesters.some((se) => Array.isArray(se.courses) && se.courses.length > 0);
  const untouchedReqs = !dg.reqMajorReq && !dg.reqMajorSel && !dg.reqLiberal;
  if (!hasCourses && untouchedReqs) s.degree = d.degree;
}

/** 불러온 데이터에 새 필드 채우기(구버전 호환). 무효 입력은 null. 동작은 레거시와 동일. */
export function migrate(input: unknown): AppState | null {
  if (!input || typeof input !== 'object') return null;
  if (!validShape(input)) return null;
  const s = input as Record<string, unknown>;
  const d = defaults();
  s.schemaVersion = SCHEMA_VERSION;
  fillDefaults(s, d);
  backfillDegree(s, d);
  /* _today·_nowHm 은 테스트 시드 — 평소 데이터엔 없어야 한다(가져온 파일에 묻어오면 제거).
     ⚠ `_nowHm`(T-8)도 같은 규약이다. 빠뜨리면 시드가 실데이터에 눌러앉아 모든 완료 시각이
     고정값으로 기록된다 — 그러면 T-8 이 쌓으려는 표본이 통째로 거짓이 된다. */
  if (s._today != null) delete s._today;
  if (s._nowHm != null) delete s._nowHm;
  /* '공부' 블록 개념 폐지: 잔존 공부 블록 제거(그 시간은 자동으로 빈 시간=공부 가능). */
  if (Array.isArray(s.routine)) s.routine = (s.routine as RoutineBlock[]).filter((b) => b && b.type !== '공부');
  return s as unknown as AppState;
}

/** 가져오기(신뢰 불가 파일) 전용 방어선 — migrate가 구조를 갖춘 뒤, 다운스트림 feature를 깨뜨릴 수 있는
    *크래시 유발 필드*만 레코드 단위로 검증해 제거한다. migrate는 회귀로 동결(byte-exact)이고 boot(로컬 데이터)는
    신뢰하므로, 이 함수는 오직 importJSON 경로에서만 호출한다.
    ⚠ 전체 zod 스키마 필터를 쓰지 않는 이유: schema.ts의 element 스키마는 '타입 출처'로만 유지돼 실제 영속
    데이터와 정밀히 대조된 적이 없다(schema.ts:114 주석) — 필터로 쓰면 정상 레코드를 오폭 삭제할 위험이 있다.
    그래서 실제로 소비처를 깨는 필드(cbms.code 열거·completions.min 수치·dayOverrides 타입)만 좁게 검사한다. */
/* ── `sanitizeImported` 의 필드별 방어선 (2026-08-20 리뷰 M-14 원장 축소) ────────────
   ⚠ **동작은 안 바뀐다.** 종전엔 일곱 축(cbms·completions·events·tasks·items·routine·dayOverrides)이
   한 함수 안에 순서대로 있었고, 각각이 다시 조건 서넛을 품어 인지복잡도의 전부를 만들었다.
   축끼리는 서로를 모른다 — 각자 *한 슬라이스가 어떻게 소비처를 깨뜨리는가* 만 안다.
   ⚠ 처방이 축마다 다르다는 것이 이 절의 요점이다: **레코드째 거를지, 필드만 뗄지**가 다르고
   그 근거가 각 함수 주석에 있다. 한 함수에 뭉쳐 있으면 그 차이가 안 보인다. */

/** cbms — 코드 열거 이탈은 롤업 집계를 깬다.
 *  ⚠⚠ **열거를 손으로 다시 적지 않는다 — 정본은 `schema.ts` 의 `CbmsCodeSchema` 다.**
 *  종전엔 여기 생 리터럴 `['C','B','M','S','T']` 가 있었고, 그건 그 열거의 **네 번째 사본**
 *  이었다(스키마 · `CBMS_INFO` · `CBMS_CODES` · 여기). 그리고 `methodology.ts` 의 `CBMS_CODES`
 *  주석은 바로 그 드리프트를 *"봉쇄했다"* 고 선언하고 있었다 — 사실이 아니었다.
 *  이 자리가 특히 나쁜 이유: 여기는 **가져오기(백업 복원) 경로의 필터**다. 여섯 번째 코드가
 *  생기면 `CBMS_INFO` 는 `Record<CbmsCode,…>` 라 TS 가 키 추가를 강제하지만 이 `Set` 은
 *  아무 신호도 안 내고, 그 코드가 붙은 오답 레코드가 **복원에서 통째로 삭제된다.**
 *  (`uiState.ts` 의 `AccentSchema.options` 가 같은 관용구 — 순환 없음: persistence → schema.) */
function sanitizeCbms(s: Record<string, unknown>): void {
  if (!Array.isArray(s.cbms)) return;
  const codes = new Set<string>(CbmsCodeSchema.options);
  s.cbms = (s.cbms as Record<string, unknown>[]).filter(
    (c) => !!c && typeof c === 'object' && codes.has(c.code as string),
  );
}

/** completions: sid → ds → {done, min}. `min` 은 학습분 합산의 입력 — 비수치면 NaN 전파. */
function sanitizeCompletions(s: Record<string, unknown>): void {
  if (!s.completions || typeof s.completions !== 'object') return;
  for (const days of Object.values(s.completions as Record<string, Record<string, unknown>>)) {
    if (!days || typeof days !== 'object') continue;
    for (const [ds, e] of Object.entries(days)) {
      const ent = e as { min?: unknown } | null;
      if (!ent || typeof ent !== 'object' || typeof ent.min !== 'number' || !Number.isFinite(ent.min)) delete days[ds];
    }
  }
}

/** events(Wave 5): 일정은 **스케줄 입력**(가용시간 차감)이라 비수치 start/min 이 NaN 구간을 만들어
 *  그날 studyMin 전체를 오염시킨다. ds(문자열)·start/min(유한수)만 통과시킨다. */
function sanitizeEvents(s: Record<string, unknown>): void {
  if (!Array.isArray(s.events)) return;
  s.events = (s.events as Record<string, unknown>[]).filter(
    (e) =>
      !!e &&
      typeof e === 'object' &&
      typeof e.ds === 'string' &&
      Number.isFinite(e.start as number) &&
      Number.isFinite(e.min as number),
  );
}

/** tasks(§4-4): events 와 같은 위험인데 방어가 빠져 있었다(2026-07-19 감사 ⑤ — ACTIVITY_KEYS·
 *  TaskSchema 에는 들어갔는데 여기만 누락). start/min 이 문자열이면 캘린더 배치 산술이 NaN 이 된다.
 *  ⚠ events 와 달리 **레코드를 지우지 않는다** — start/min 이 옵셔널이라 그 필드만 떼면 할 일이
 *  '미지정 트레이 항목'으로 살아남는다. 사용자 저작물이라 최소 파괴가 옳다(events 는 시각이 필수라
 *  시각 없는 일정이 성립하지 않아 레코드째 걸렀다). */
function sanitizeTasks(s: Record<string, unknown>): void {
  if (!Array.isArray(s.tasks)) return;
  s.tasks = (s.tasks as unknown[]).filter((t) => !!t && typeof t === 'object');
  for (const t of s.tasks as Record<string, unknown>[]) {
    if (t.start !== undefined && !Number.isFinite(t.start as number)) delete t.start;
    if (t.min !== undefined && !Number.isFinite(t.min as number)) delete t.min;
  }
}

/** items·routine — 둘 다 **부팅·스케줄 경로에서 throw** 하는 부류다(렌더 밖이라 폴백도 못 잡는다).
 *  items: 비객체 원소는 `refineItemColors` 에서 throw 해 앱을 영구 백지로 만든다.
 *  routine: `days` 가 배열이 아니면 `blocksForWeekday` 의 `.includes` 에서, `start/end` 가
 *  문자열이 아니면 `toMin` 의 `.split` 에서 TypeError → `schedule()` 전체가 throw 하고
 *  스케줄을 읽는 모든 탭이 폴백으로 떨어진다. */
function sanitizeSchedInputs(s: Record<string, unknown>): void {
  if (Array.isArray(s.items)) s.items = (s.items as unknown[]).filter((it) => !!it && typeof it === 'object');
  if (Array.isArray(s.routine))
    s.routine = (s.routine as Record<string, unknown>[]).filter(
      (b) =>
        !!b &&
        typeof b === 'object' &&
        Array.isArray(b.days) &&
        typeof b.start === 'string' &&
        typeof b.end === 'string',
    );
}

/** dayOverrides: ds → 분(number) | 프리셋(string). 그 외 타입은 가용시간 계산을 깬다. */
function sanitizeOverrides(s: Record<string, unknown>): void {
  if (!s.dayOverrides || typeof s.dayOverrides !== 'object') return;
  const ov = s.dayOverrides as Record<string, unknown>;
  for (const [ds, v] of Object.entries(ov)) if (typeof v !== 'number' && typeof v !== 'string') delete ov[ds];
}

export function sanitizeImported(state: AppState): AppState {
  const s = state as unknown as Record<string, unknown>;
  sanitizeCbms(s);
  sanitizeCompletions(s);
  sanitizeEvents(s);
  sanitizeTasks(s);
  sanitizeSchedInputs(s);
  sanitizeOverrides(s);
  return state;
}

/** 내보내기 스냅샷 — 런타임 스캔 캐시 제외(파일 백업은 가볍게·깨끗하게). */
export function exportSnapshot(state: AppState): Partial<AppState> {
  const src = state as Record<string, unknown>;
  const out: Record<string, unknown> = {};
  for (const k in src) if (!(RUNTIME_CACHE_KEYS as readonly string[]).includes(k)) out[k] = src[k];
  return out as Partial<AppState>;
}

export function serialize(state: AppState): string {
  // 로컬 저장: 순수 휘발 캐시(EPHEMERAL_ONLY_KEYS)만 떼고 나머지는 유지.
  // _ankiLive·_knowState·_icsExport는 reload 후 오늘 탭·캘린더 배지가 읽으므로 로컬엔 남긴다(즉시 부팅).
  // 파일 내보내기(exportSnapshot)는 별도로 모든 런타임 캐시를 제외(이식성).
  const src = state as Record<string, unknown>;
  const out: Record<string, unknown> = {};
  for (const k in src) if (!EPHEMERAL_ONLY_KEYS.includes(k)) out[k] = src[k];
  return JSON.stringify(out);
}

/* 부팅이 기본값으로 떨어진 사유 마커 — 'missing'(저장본 없음: 첫 방문 또는 localStorage 전소),
   'corrupt'(저장본은 있는데 못 살림). App 마운트 후 복구 안내(BootRecovery)가 1회 소비한다.
   정상 부팅·의도적 초기화(초기화는 유효한 기본값을 즉시 persist → 다음 부팅 정상)에선 null. */
export type BootFallback = 'missing' | 'corrupt';
let _bootFallback: BootFallback | null = null;
/** 마커를 읽고 즉시 지운다(1회 소비) — StrictMode 이중 이펙트에도 안내가 한 번만 뜨게. */
export function consumeBootFallback(): BootFallback | null {
  const v = _bootFallback;
  _bootFallback = null;
  return v;
}

/** 직렬화 문자열을 파싱→마이그레이션. 손상/형식불일치면 null(throw 안 함).
   `migrate(JSON.parse(raw))`+try/catch 관용구가 boot·undoLast·restoreFromIDB·BootRecovery에
   복제돼 있던 것을 단일 가드로 수렴 — migrate SSOT를 소유한 이 모듈이 파싱 가드도 소유. */
export function parseState(raw: string): AppState | null {
  try {
    return migrate(JSON.parse(raw));
  } catch {
    return null;
  }
}

/* 부팅 — 저장된 상태를 살리되, 손상/형식불일치면 *원본 raw를 CORRUPT_KEY에 보존*한 뒤
   기본값으로 시작(첫 persist가 복구가능한 원본을 덮어 영구손실하는 것 방지 · P1-7). */
export function boot(storage: KV): AppState {
  _bootFallback = null;
  let raw: string | null = null;
  try {
    raw = storage.getItem(KEY);
  } catch {
    /* ignore */
  }
  const s: AppState | null = raw == null ? null : parseState(raw);
  if (!s && raw) {
    // 원본은 있는데 못 살림 = 손상/형식불일치
    try {
      if (storage.getItem(CORRUPT_KEY) == null) storage.setItem(CORRUPT_KEY, raw);
    } catch {
      /* ignore */
    }
  }
  if (!s) _bootFallback = raw == null ? 'missing' : 'corrupt';
  return s || defaults();
}

/** localStorage(동기 1차 저장)에 KEY를 기록하고 직렬화 문자열을 반환(호출부가 IDB 미러에 전달). */
export function persist(storage: KV, state: AppState): string {
  const json = serialize(state);
  storage.setItem(KEY, json);
  return json;
}

/* ── 실행 추적: 그 날 그 과목의 학습/복습/Anki를 '완료'로 기록 ── */
export function compMap(state: AppState, ds: string): Record<string, CompletionEntry> {
  state.completions = state.completions || {};
  return (state.completions[ds] = state.completions[ds] || {});
}
export function isDone(state: AppState, ds: string, sid: string, type: SessionType): boolean {
  const m = state.completions && state.completions[ds];
  const e = m && m[sid + '|' + type];
  return !!(e && e.done);
}
/** 완료 토글(스토어 액션이 호출 후 persist). on=false면 기록 제거. */
/** 회고가 읽어야 하는 '집중한 분'(G-1) — **실측이 있으면 실측, 없으면 계획**.
 *
 *  왜 함수인가: `min` 을 그대로 읽던 곳이 넷(`records.bestFocusMin`·`seasonPace`·
 *  `insights.dayShape`·`scheduler.adherenceFactor`)이었고, 그중 하나는 그 값으로 **미래 계획
 *  용량을 깎는다**. 폴백 규칙을 네 곳에 복제하면 언젠가 한 곳만 남아 "회고는 실측인데 계획은
 *  체크박스"가 된다 — 그 어긋남은 화면 어디에도 안 보인다. 규칙은 여기 한 줄이다. */
export function completionMin(e: { min?: number; actualMin?: number } | undefined): number {
  if (!e) return 0;
  return typeof e.actualMin === 'number' && e.actualMin > 0 ? e.actualMin : +(e.min || 0);
}

/**
 * **Q-1 진도 커밋** — 챕터의 `done` 을 이름으로 확정한다.
 *
 * ## 왜 이 함수가 없었나 (그리고 그게 왜 문제였나)
 * `setDone`(블록 완료)은 `completions[ds]["sid|type"]` 만 쓰고 **챕터를 안 건드린다** — 아래
 * 그 함수의 코드가 스스로 자인한다. 그런데 스케줄러의 계획은 **전적으로 `c.done`** 에서 나온다
 * (`engine.ts` 의 `!c.done && !c.deferred` 필터). 즉 **계획의 유일한 진짜 입력이, 앱에서 가장
 * 비싼 편집이었다**: 씨앗이 51챕터를 넣은 뒤 30번째 챕터를 체크하려면 챕터 표까지 가서
 * `<details>` 를 펼치고(기본 접힘) Tab 약 150회를 눌러야 했다. 발산 7각도 중 셋이 독립적으로
 * 이 지점에 도착했다.
 *
 * ## ⚠ 이름으로 찾는다 — 그게 블록이 가진 전부다
 * `ScheduleItem.chapters` 는 **이름 배열**이다(id 가 아니다). 엔진이 `advance()` 에서 챕터
 * *이름*을 담기 때문이고, 그 계약을 여기서 바꾸면 블록·복습·볼트 앵커가 전부 따라 움직인다.
 * 그래서 이 함수만 이름으로 찾는다. 동명 챕터가 있으면 **첫 번째**가 이긴다 — 표시상 구분이
 * 안 되는 두 행 중 하나를 고르는 것은 어차피 임의이고, 사용자는 챕터 표에서 고칠 수 있다.
 * ⚠ `doneDs` 를 함께 쓴다 — 복습 사다리가 계획일이 아니라 이 날을 앵커한다(②#23).
 */
export function setChapterDone(state: AppState, sid: string, chapterName: string, on: boolean, ds: string): void {
  const it = (state.items || []).find((x) => x.id === sid);
  const ch = (it?.chapters || []).find((c) => c.name === chapterName);
  if (!ch) return;
  ch.done = on;
  if (on) ch.doneDs = ds;
  else delete ch.doneDs;
}

export function setDone(
  state: AppState,
  ds: string,
  sid: string,
  type: SessionType,
  plannedMin: number,
  on: boolean,
  actualMin?: number,
): void {
  const m = compMap(state, ds);
  const k = sid + '|' + type;
  // doneDs = 실제 완료일(②#23 · todayISO는 _today 시드 존중) — 복습 사다리가 계획일이 아니라
  // 이 날을 앵커한다(늦게 완료해도 복습이 앞당겨진 채 고정되지 않게 · 망각곡선 정합).
  if (on)
    m[k] = {
      done: true,
      min: Math.round(plannedMin),
      doneDs: todayISO(state),
      // T-8 시각 원장 — **완료를 누른 하루 중 시각**. 지금은 어느 화면도 안 그린다(로드맵 T-8 의
      // 가장 싼 검증이 "한 필드만 추가하고 2주 방치"다). 이 한 줄이 없어서 T-5·T-8·T-10 이 전부
      // "표본 대기"로 멈춰 있었다 — 관측을 기다리면서 관측 장치를 안 달고 있었다.
      doneAt: nowHm(state),
      // 실측은 **있을 때만** 싣는다 — 0/undefined 를 넣으면 "쟀는데 0분"과 "안 쟀다"가 섞인다.
      ...(actualMin && actualMin > 0 ? { actualMin: Math.round(actualMin) } : {}),
    };
  else delete m[k];
  if (!Object.keys(m).length) delete state.completions[ds];
}
/** ReviewRun 챕터 인출 기록 — 위험모델(spacedReview)의 lastDs를 계획 밖 복습에서도 갱신(감사 #22).
 *  완료(completions)는 `sid|type` 키라 챕터 무구분 — 밀린 챕터를 복습해도 '망각곡선 리셋'이
 *  모델에 반영되지 않던 루프를 챕터 단위 터치 로그로 닫는다. 최신 ds만 유지(단조 증가).
 *
 *  ⚠ **E1(2026-07-29) 이전까지 이 함수의 쓰기 호출부는 `app/FocusChip.tsx` 하나였다.** 그 경로는
 *  조건이 셋이다(집중 세션 완주 + 토스트 수명 안에 '블록 완료로 표시' 클릭 + `chapter` 존재).
 *  그래서 러너에서 챕터를 아무리 인출해도 앵커가 안 생겼고, `reviewQueue.ts` 의 `MAINTENANCE_CAP`
 *  주석이 유지 큐의 존립 근거로 든 _"볼 때마다 진짜 앵커가 하나씩 생겨 큐가 스스로 수렴한다"_ 가
 *  **작동한 적이 없다**(끝낸 챕터는 앵커가 없어 영구히 `due`). 러너가 이제 직접 부른다. */
export function touchReview(state: AppState, sid: string, chapter: string, ds: string): void {
  const m = (state.reviewTouches = state.reviewTouches || {});
  const k = sid + '|' + chapter;
  const cur = m[k];
  if (!cur || ds > cur) m[k] = ds;
}
/** 터치 로그 조회(되돌리기용 이전 값 확보) — 없으면 undefined. */
export function reviewTouchOf(state: AppState, sid: string, chapter: string): string | undefined {
  return (state.reviewTouches || {})[sid + '|' + chapter];
}
/** 되돌리기 전용 — 터치를 **이전 값으로 되돌린다**(원래 없었으면 지운다).
 *
 *  `touchReview` 는 단조 증가라 되감기가 원리적으로 불가능하다. 러너의 `U`(되돌리기)는 세션
 *  상태를 전량 스냅샷으로 되돌리는데, 앵커만 앞으로 간 채 남으면 **화면은 물렸다고 하고 모델은
 *  인출했다고 하는** 상태가 된다 — 그리고 그 어긋남은 조용하다(D-3 이 되돌리기를 키보드 계약의
 *  짝으로 둔 이유가 정확히 "키가 빨라지면 오타도 빨라진다"였다). */
export function restoreReviewTouch(state: AppState, sid: string, chapter: string, prev: string | undefined): void {
  const m = (state.reviewTouches = state.reviewTouches || {});
  const k = sid + '|' + chapter;
  if (prev === undefined) delete m[k];
  else m[k] = prev;
}

/** 총 완료 학습시간(시간). */
export function totalDoneHours(state: AppState): number {
  let mins = 0;
  const c = state.completions || {};
  for (const ds in c) {
    const m = c[ds]!;
    for (const k in m) mins += +m[k]!.min || 0;
  }
  return mins / 60;
}
/* ⚠⚠ **`studyStreak`(연속 학습일)이 여기 있었다 — 소비처 둘이 함께 은퇴했다**(I046 통계 탭 ·
   I054 오늘 탭 · 2026-08-22 발상 축). 근거: 그 수의 입력(`completions`)이 실물에서 **0행**이라
   화면에서 항상 0이었고, 0을 크게 그리는 것은 조망이 아니다. 스트릭 자체가 나쁘다는 판정이
   아니라 **이 앱에서 그 수가 관측된 적이 없다**는 판정이다 — 입력 파이프(묶음 A)가 채워지면
   다시 열 수 있고, 그때는 `git show <이 커밋의 부모>:web/src/lib/persistence.ts`. */

/* ============================================================
   scheduleView.ts — Schedule 탭의 하루치 뷰모델(순수). 컴포넌트에서 분리해 단위테스트 가능.
   scheduler(엔진 결과 ScheduleResult)와 layoutDay(시각배치)를 받아 카드/개요 공용 DayData로 빚는다.
============================================================ */
import { parseCompletionKey } from './domainKeys';
import { dayStudyMin, layoutDay } from './scheduler';
import { isDone } from './persistence';
import { iso, addDays, dayDiff } from './utils';
import type { AppState, ItemStat, ScheduleItem, ScheduleResult, SessionType } from './types';

export interface DeadlineDday {
  name: string;
  color?: string;
  deadline: string;
  dday: number;
}
/** 마감 있고 미완료인 과목의 D-day 목록(가까운 순 정렬) — Today·Schedule·폰·`/alloc` 공유 SSOT.
 *  dday<0(마감 지남)·finished(다 끝낸 과목)는 제외해 두 탭이 항상 같은 '가장 가까운 마감'을 본다
 *  (N-9의 두 탭 복붙 파생을 하나로 수렴 → 규칙 변경 시 재드리프트 예방).
 *
 *  ⚠⚠ **기준은 `nextExam`(다가오는 시험)이지 `deadline`(마지막 시험)이 아니다**(H-2 · 2026-08-06
 *  감사). 종전엔 이 함수가 `deadline` 을 읽어서, 중간고사가 사흘 뒤인데 화면 전체가 기말까지의
 *  D-60 을 그렸다 — 그리고 이 함수가 SSOT 라 **다섯 화면이 한꺼번에** 그 값을 그렸다.
 *  근거 문장은 `semester.ts` 의 `nextExamOf` 가 소유한다. */
export function deadlineDdays(itemStat: ItemStat[] | undefined, todayIso: string): DeadlineDday[] {
  return (itemStat || [])
    .filter((st) => st.nextExam && !st.finished)
    .map((st) => ({
      name: st.name,
      color: st.color,
      deadline: st.nextExam as string,
      dday: dayDiff(todayIso, st.nextExam as string),
    }))
    .filter((st) => st.dday >= 0)
    .sort((a, b) => a.dday - b.dday);
}

/** 통계 '과목별 진행'에서 그 과목이 **지금 손봐야 할 것인가**(UX-2 · 0=평온 · 클수록 급함).
 *  등급은 그 화면이 이미 배지로 말하는 것과 **같은 술어**를 쓴다(배지는 '시간부족'인데 순서는
 *  무관하면 두 신호가 서로를 부정한다):
 *   3 마감초과(late>0) · 2 시간부족(마감 있는데 계획 안에 못 끝냄) · 1 마감 임박(D-7 이내) · 0 그 외.
 *  ⚠ '반복'(daily) 과목은 마감 개념이 없어 항상 0 이다 — 급하지 않은 게 아니라 이 축이 없다. */
export function subjectUrgency(st: ItemStat, todayIso: string): number {
  if (st.daily || !st.deadline) return 0;
  if ((st.late || 0) > 0) return 3;
  if (!st.finished) return 2;
  // ⚠ '임박'은 **다가오는** 시험 기준이다(H-2) — 마지막 시험으로 재면 중간고사 주간이 평온으로 나온다.
  const d = st.nextExam ? dayDiff(todayIso, st.nextExam) : -1;
  return d >= 0 && d <= 7 ? 1 : 0;
}

/** 통계 과목 목록의 **표시 순서**(UX-2). 위험군만 위로 올리는 *안정* 정렬.
 *
 *  왜 안정이어야 하는가: 이 목록은 매번 같은 자리에서 같은 과목을 찾는 화면이다. 급한 것만
 *  위로 올리고 **나머지 상대 순서는 그대로 두어야** 위치 기억이 살아남는다(전체 재정렬은 목록을
 *  매일 새 목록으로 만든다). `Array.prototype.sort` 는 명세상 안정이라 등급만 비교하면 된다.
 *
 *  ⚠ 표시용이다 — 데이터·색·마크업은 손대지 않는다. 정렬 토글 UI 도 붙이지 않는다(과설계).
 */
export function sortSubjectsByUrgency(itemStat: ItemStat[], todayIso: string): ItemStat[] {
  return [...itemStat].sort((a, b) => subjectUrgency(b, todayIso) - subjectUrgency(a, todayIso));
}

/* ── 타임라인 표시 범위 ───────────────────────────────────────────────────
   "일정이 있는 구간 ±여유"로 하루를 좁히는 계산 — 주간 캘린더(spanOf)와 일 편집기(인라인 lo/hi)에
   같은 알고리즘이 두 벌 있었다(스냅 60 vs 30, 폴백만 다름). number[] → {lo,hi} 순수함수인데 뷰
   안에 있어 테스트가 못 닿았다 → 여기로 이주하고 차이는 옵션으로 흡수한다. */
export interface TimeSpanOpts {
  /** 정시/반시 스냅 단위(분). 주간=60, 일 편집기=30. */
  snap?: number;
  /** 앞뒤 여유(분) — 첫/끝 일정이 화면 가장자리에 붙지 않게. */
  pad?: number;
  /** 최소 표시 폭(분) — 일정 하나뿐인 날 타임라인이 납작해지지 않게. */
  minSpan?: number;
  /** 일정이 하나도 없을 때의 창(분). 기본 08:00–(08:00+minSpan). */
  fallback?: { lo: number; hi: number };
  /** 하한/상한 클램프(분) — 일 편집기는 깨어있는 창(wake0~wake1)으로 조인다. 기본 0/1440. */
  min?: number;
  max?: number;
}

/** 일정 시각 목록(분)에서 표시 범위 [lo, hi]를 계산한다. mins가 비면 fallback 창.
 *  ±pad → snap 격자로 확장 → [min,max] 클램프 → minSpan 이중 클램프(hi 먼저, 그래도 좁으면 lo) 순.
 *  마지막 방어: 클램프 창 자체가 minSpan보다 좁아 hi<=lo가 되면 fallback으로 되돌린다. */
export function timeSpan(mins: number[], opts: TimeSpanOpts = {}): { lo: number; hi: number } {
  const snap = opts.snap ?? 60;
  const pad = opts.pad ?? 60;
  const minSpan = opts.minSpan ?? 9 * 60;
  const min = opts.min ?? 0;
  const max = opts.max ?? 1440;
  const fb = opts.fallback ?? { lo: 8 * 60, hi: 8 * 60 + minSpan };

  let lo: number;
  let hi: number;
  if (mins.length) {
    lo = Math.floor((Math.min(...mins) - pad) / snap) * snap;
    hi = Math.ceil((Math.max(...mins) + pad) / snap) * snap;
  } else {
    lo = fb.lo;
    hi = fb.hi;
  }
  lo = Math.max(min, lo);
  hi = Math.min(max, hi);
  if (hi - lo < minSpan) hi = Math.min(max, lo + minSpan);
  if (hi - lo < minSpan) lo = Math.max(min, hi - minSpan);
  if (hi <= lo) return { lo: fb.lo, hi: Math.min(1440, fb.hi) };
  return { lo, hi };
}

export type Row =
  | { kind: 'now'; start: number }
  | { kind: 'free'; start: number; end: number }
  | { kind: 'block'; start: number; end: number; name: string; btype: string; color?: string }
  | { kind: 'study'; start: number | null; end: number | null; it: ScheduleItem; plannedMin: number };

export interface DayData {
  date: Date;
  ds: string;
  wd: number;
  isToday: boolean;
  studyMin: number;
  used: number;
  ratio: number;
  over: boolean;
  doneMinTot: number;
  planMin: number;
  freeMin: number;
  defMin: number;
  ovVal: number | string;
  rows: Row[];
  counts: { studies: number; revs: number; ankis: number; blanks: number; mocks: number };
}

/** 세션 타입 → 표시 메타(태그 클래스·짧은 라벨) — Schedule 목록·주간 캘린더 공유 정본. */
export const SESSION_TYPE_META: Record<SessionType, { cls: string; label: string }> = {
  new: { cls: 'new', label: '학습' },
  rev: { cls: 'rev', label: '복습' },
  blank: { cls: 'blank', label: '백지' },
  mock: { cls: 'mock', label: '모의' },
  anki: { cls: 'anki', label: 'Anki' },
};

export type DayIndex = Record<string, ScheduleResult['days'][number]>;
/** ds→Day 인덱스를 한 번만 만든다. computeDay가 7회 호출되며 매번 전체를 재구축하던 것을 호출부로 끌어올려
 *  렌더당 O(7·horizon)→O(horizon)로 줄인다(horizon은 마감 우선 최대 ~180일). */
export function indexDays(res: ScheduleResult): DayIndex {
  const byDs: DayIndex = {};
  (res.days || []).forEach((d) => (byDs[d.ds] = d));
  return byDs;
}

/** 하루치 계산(머리글/막대/타임라인 행/꼬리) — 카드뷰·개요뷰 공용. byDs는 indexDays로 1회 생성해 주입. */
export function computeDay(
  state: AppState,
  byDs: DayIndex,
  capWd: number[],
  nowMin: number,
  todayIso: string,
  curMon: Date,
  k: number,
): DayData {
  const date = addDays(curMon, k);
  const ds2 = iso(date);
  const wd = date.getDay();
  const isToday = ds2 === todayIso;
  const defMin = capWd[wd] ?? 0;
  const studyMin = dayStudyMin(state, ds2, wd, capWd);
  const ovRaw = state.dayOverrides && state.dayOverrides[ds2] != null ? state.dayOverrides[ds2] : '';
  const planDay = byDs[ds2];
  const items = planDay ? planDay.items : [];
  const L = layoutDay(state, { ds: ds2, date, wd, studyMin, used: planDay?.used || 0, modLeft: 0, revLeft: 0, items });
  const used = planDay ? Math.round(planDay.used) : 0;
  const over = used > studyMin + 1;
  const ratio = studyMin ? Math.min(100, Math.round((used / studyMin) * 100)) : 0;

  const plannedByKey: Record<string, number> = {};
  items.forEach((it) => {
    const key = it.sid + '|' + it.type;
    plannedByKey[key] = (plannedByKey[key] || 0) + it.min;
  });
  const planMin = items.reduce((t, it) => t + it.min, 0);
  let doneMinTot = 0;
  Object.keys(plannedByKey).forEach((key) => {
    const { sid, type } = parseCompletionKey(key);
    if (isDone(state, ds2, sid!, type as SessionType)) doneMinTot += plannedByKey[key]!;
  });

  // 일과 블록 + 학습 세션 + 빈 시간(+오늘이면 현재시각)을 시각순으로.
  const rows: Row[] = [];
  L.tl.forEach((x) => {
    if (x.kind === 'block')
      rows.push({
        kind: 'block',
        start: x.start,
        end: x.end,
        name: x.name || '',
        btype: x.btype || '',
        color: x.color,
      });
    else
      rows.push({
        kind: 'study',
        start: x.start,
        end: x.end,
        it: {
          type: x.type as SessionType,
          sid: x.sid as string,
          name: x.name || '',
          color: x.color,
          min: x.min || 0,
          chapters: x.chapters,
        },
        plannedMin: plannedByKey[(x.sid as string) + '|' + x.type] || x.min || 0,
      });
  });
  L.free.forEach(([s, e]) => rows.push({ kind: 'free', start: s, end: e }));
  if (isToday) rows.push({ kind: 'now', start: nowMin });
  rows.sort((a, b) => (a.start ?? 0) - (b.start ?? 0));

  // 시각 못 잡은 항목(여유 없음) 보강 — 미배치.
  const shown = new Set(L.tl.filter((x) => x.kind === 'study').map((x) => x.sid + '|' + x.type));
  items.forEach((it) => {
    if (!shown.has(it.sid + '|' + it.type))
      rows.push({
        kind: 'study',
        start: null,
        end: null,
        it,
        plannedMin: plannedByKey[it.sid + '|' + it.type] || it.min,
      });
  });

  const counts = {
    studies: items.filter((it) => it.type === 'new').length,
    revs: items.filter((it) => it.type === 'rev').length,
    ankis: items.filter((it) => it.type === 'anki').length,
    blanks: items.filter((it) => it.type === 'blank').length,
    mocks: items.filter((it) => it.type === 'mock').length,
  };

  return {
    date,
    ds: ds2,
    wd,
    isToday,
    studyMin,
    used,
    ratio,
    over,
    doneMinTot,
    planMin,
    freeMin: L.freeMin,
    defMin,
    ovVal: ovRaw,
    rows,
    counts,
  };
}

/* ── 캘린더 겹침 배치(lane packing) ───────────────────────────────────────
   시간이 겹치는 일정을 나란한 세로 레인으로 나눠 서로 가리지 않게 한다(TickTick·Google 캘린더 규약).
   순수 함수라 캘린더 뷰(주/일)가 공유하고 테스트로 잠근다 — 픽셀·DOM 무관.

   규칙: ① 시작 시각 오름차순(같으면 긴 일정 먼저 — 큰 덩어리가 왼쪽) ② 시간이 이어지는 동안 한 '클러스터'
   ③ 클러스터 안에서 비어 있는 가장 왼쪽 레인에 배정 ④ 폭은 그 **클러스터의 레인 수**로 나눈다.
   폭을 전역 최대 레인 수로 나누지 않는 게 핵심 — 하루 중 한 번 3중 겹침이 났다고 나머지가 다 1/3로
   쪼그라들면 안 된다. */
export interface LaneItem<T> {
  item: T;
  start: number;
  end: number;
}
export interface PlacedItem<T> extends LaneItem<T> {
  /** 0부터. 이 일정이 앉은 레인. */
  lane: number;
  /** 이 일정이 속한 클러스터의 총 레인 수(=폭 분모). */
  lanes: number;
}

export function packLanes<T>(items: LaneItem<T>[]): PlacedItem<T>[] {
  const sorted = items
    .filter((e) => e.end > e.start)
    .slice()
    .sort((a, b) => a.start - b.start || b.end - b.start - (a.end - a.start));
  const out: PlacedItem<T>[] = [];
  let cluster: PlacedItem<T>[] = [];
  let clusterEnd = -Infinity;

  const flush = () => {
    if (!cluster.length) return;
    const lanes = Math.max(...cluster.map((p) => p.lane)) + 1;
    for (const p of cluster) p.lanes = lanes;
    out.push(...cluster);
    cluster = [];
    clusterEnd = -Infinity;
  };

  for (const e of sorted) {
    if (e.start >= clusterEnd) flush(); // 앞 클러스터와 안 겹침 → 끊는다
    // 이 클러스터에서 비어 있는(=끝난) 가장 왼쪽 레인
    const laneEnds: number[] = [];
    for (const p of cluster) laneEnds[p.lane] = Math.max(laneEnds[p.lane] ?? -Infinity, p.end);
    let lane = 0;
    while (lane < laneEnds.length && (laneEnds[lane] ?? -Infinity) > e.start) lane++;
    cluster.push({ ...e, lane, lanes: 1 });
    clusterEnd = Math.max(clusterEnd, e.end);
  }
  flush();
  return out;
}

/* ============================================================
   semester.ts — **T-1 학기 계약**의 읽기 SSOT (순수 · React 무관)

   왜 이 파일이 생겼나 (2026-08-02 · 발산 5회차 T-1):
   블라인드 7각도가 **세 곳에서 만났고** 그중 하나가 _"여정의 입구와 출구가 통째로 비어 있다 —
   **'학기'가 데이터에 없다**"_ 였다. 근거는 셋이 독립적으로 왔다:
     · 각도 7 — 학습 여정 28단계 중 앱이 덮는 것은 **3단계**이고 셋 다 학기 *중반*이다.
     · 각도 3 — 시그니처 7종이 **전부 지금 상태**를 그린다(시간축이 수개월인 것 0).
     · 메인 직독 — `Semester` 에 **날짜가 없고**, `Course`(학점·성적)와 `Item`(챕터·마감)이
       **서로를 전혀 참조하지 않는다.** 같은 과목이 6화면에 흩어진 근본 원인이 이것이다.

   이 파일이 지키는 규율 셋:
   1. **읽기는 여기 하나로 모은다.** `item.exams` 와 옛 `item.deadline`/`deadlineThru` 를 **둘 다
      직접 읽는 코드를 만들지 말 것** — 두 원천을 각자 해석하면 화면마다 갈린다. `examsOf()` 가
      옛 필드를 시험 1개로 승격시켜 돌려주므로 호출부는 `exams` 만 아는 세계에 산다.
   2. **동작 보존이 계약이다.** 시험이 0~1개면 `examScopes()` 의 결과가 옛 `deadlineThru` 계산과
      **한 글자도 다르지 않다**(`scheduler.test.ts` 가 이걸 잠근다). 새 동작은 시험이 2개일 때만.
   3. **여기서 파생하고 저장하지 않는다.** 국면(학기중/방학/개강 전)·주차는 전부 날짜에서 계산한다 —
      저장하면 자정을 넘길 때마다 낡는다(과목 색이 저장값이 아닌 것과 같은 논증).
============================================================ */
import type { AcademicMark, AppState, Chapter, Course, Exam, Item, Semester } from './types';
import { dayDiff, todayISO } from './utils';

/** 시험 최대 개수(v1). ⚠ **이 상수를 올리는 것이 금도금 미끄럼틀의 첫 걸음이다** — `schema.ts` 의
 *  `ExamSchema` 머리주석이 무엇을 안 만들기로 했는지 적어 뒀다. 올리려면 근거를 들고 그 주석부터. */
export const MAX_EXAMS = 2;

/** 시험 종류의 표시 이름. 자유입력을 만들지 않는 이유도 같다(유형이 늘면 가중치가 따라온다). */
export const EXAM_LABEL: Record<Exam['kind'], string> = { mid: '중간', final: '기말' };

/**
 * 과목의 시험들을 **날짜순**으로 돌려준다 — 이 앱에서 시험을 읽는 **유일한 입구**.
 *
 * 옛 저장(`deadline`/`deadlineThru`)은 여기서 **시험 1개로 승격**된다. 그래서 `exams` 를 한 번도
 * 안 쓴 사용자에게도 아래 모든 계산이 종전과 동일하게 성립한다(무마이그레이션).
 * ⚠ 승격된 시험의 `kind` 는 `'final'` 이다 — 옛 모델의 마감은 "이 과목의 끝"을 뜻했으므로.
 *
 * ⚠⚠ **소양 과목(P10 D6)은 언제나 빈 배열이다.** 저장값은 **지우지 않는다** — 구분을 되돌리면
 * 넣어 뒀던 시험이 그대로 살아난다. 여기서 거르는 이유는 대안이 둘 다 나쁘기 때문이다:
 *   ① 전환할 때 `exams` 를 지우면 → 셀렉트 한 번이 사용자가 타이핑한 날짜를 **말없이 파괴**한다.
 *   ② 그냥 두면 → 화면엔 없는 시험이 **엔진에는 보인다**(`engine.ts` 가 `examScopes` 로 마감을
 *      압박한다). 이 저장소가 반복해 물린 *"화면과 정본이 갈린다"* 가 정확히 그 형태다.
 * 입구가 하나라서 이 판정을 **한 곳**에 둘 수 있다 — 이 파일 규율 1의 값이 여기서 회수된다.
 */
export function examsOf(item: Pick<Item, 'kind' | 'exams' | 'deadline' | 'deadlineThru'>): Exam[] {
  if (isSoftSubject(item)) return [];
  const list = item.exams?.length
    ? item.exams
    : item.deadline
      ? [{ id: `${item.deadline}-legacy`, kind: 'final' as const, date: item.deadline, thru: item.deadlineThru }]
      : [];
  return [...list].sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0)).slice(0, MAX_EXAMS);
}

/** 과목이 시험을 하나라도 갖고 있나(= 마감 모델이 켜져 있나). */
export function hasExams(item: Pick<Item, 'kind' | 'exams' | 'deadline' | 'deadlineThru'>): boolean {
  return examsOf(item).length > 0;
}

/**
 * 그 날짜에 있는 시험들(없으면 빈 배열). **달력·주 그리드의 마감 표식은 이걸 써야 한다.**
 *
 * ⚠⚠ 종전엔 세 곳이 `it.deadline === ds` 로 **원시 필드**를 직접 읽었다(H-1 · 2026-08-06 감사).
 * 그런데 시험을 편집하면 `SubjectDefinition` 이 `delete it.deadline` 을 한다 — 즉 **시험을 넣는
 * 순간 월 캘린더·주 그리드에서 그 과목 마감이 조용히 사라졌다.** 새 모델을 켠 것이 옛 표시를
 * 끄는 형태이고, 어디에도 오류가 안 난다. `examsOf` 가 *유일한 입구*라고 적혀 있었는데 이 셋이
 * 그 밖에 있었다 — 입구를 선언만 하면 새 소비처가 옆문으로 들어온다.
 * 그리고 시험이 둘이면 **표식도 둘**이어야 한다(옛 필드는 애초에 한 날짜만 표현할 수 있었다).
 */
function examsOn(item: Pick<Item, 'kind' | 'exams' | 'deadline' | 'deadlineThru'>, ds: string): Exam[] {
  return examsOf(item).filter((e) => e.date === ds);
}

/** 그 날짜에 시험이 있는 **이름 있는 과목**들을 시험 하나당 한 줄로 편다. 위 주석이 근거를 갖는다. */
export function examMarks(items: readonly Item[], ds: string): { id: string; name: string; exam: Exam }[] {
  return items.flatMap((it) => (it.name ? examsOn(it, ds).map((exam) => ({ id: it.id, name: it.name, exam })) : []));
}

/**
 * **다가오는** 시험(오늘 이후 중 가장 가까운 것). 없으면 null.
 *
 * ⚠ 화면의 D-day 는 **마지막 시험이 아니라 이것**을 써야 한다 — 중간고사가 코앞인데 기말까지의
 * D-60 을 보여주면 그 숫자는 거짓말이다. 옛 모델은 마감이 하나뿐이라 이 구분이 존재할 수 없었고,
 * 그래서 모든 화면이 자동으로 "마지막 마감"을 그렸다.
 */
export function nextExamOf(item: Pick<Item, 'kind' | 'exams' | 'deadline' | 'deadlineThru'>, ds: string): Exam | null {
  return examsOf(item).find((e) => e.date >= ds) || null;
}

/** 시험 하나가 덮는 챕터 구간. `fromIdx`..`thruIdx` 는 **원본 `chapters` 배열의 인덱스**(포함). */
export interface ExamScope {
  exam: Exam;
  fromIdx: number;
  thruIdx: number;
}

/**
 * 시험들을 챕터 배열 위의 **연속 구간**으로 편다.
 *
 * 규칙 — 시험 i 의 범위는 `직전 시험의 thru 다음`부터 `자기 thru`까지다. `thru` 가 없거나 그 id 를
 * 못 찾으면 **끝까지**로 폴백한다(옛 id 하나 때문에 마감 판정이 통째로 멈추는 것보다, 종전 동작으로
 * 되돌아가는 편이 안전하다 — `engine.ts` 가 P-10 에서 내린 것과 같은 판단).
 *
 * ⚠ **시험이 0~1개면 결과가 옛 계산과 동일하다**: 구간 하나가 `0..scopeEnd` 이고 `scopeEnd` 는
 * `deadlineThru` 를 찾은 인덱스(못 찾으면 마지막)다.
 * ⚠ 날짜순으로 정렬돼 있는데 `thru` 가 역행하면(중간고사 범위가 기말보다 뒤) 구간이 비므로
 * `fromIdx > thruIdx` 가 될 수 있다 — 호출부는 **빈 구간을 정상 값으로** 다뤄야 한다.
 */
export function examScopes(item: Pick<Item, 'kind' | 'exams' | 'deadline' | 'deadlineThru' | 'chapters'>): ExamScope[] {
  const all: Chapter[] = item.chapters || [];
  const exams = examsOf(item);
  const out: ExamScope[] = [];
  let cursor = 0;
  exams.forEach((exam, i) => {
    const found = exam.thru ? all.findIndex((c) => c.id === exam.thru) : -1;
    const isLast = i === exams.length - 1;
    // 마지막 시험은 `thru` 가 없으면 끝까지 덮는다. 중간 시험이 `thru` 없이 오면 범위를 알 수 없어
    // 역시 끝까지로 두는데, 그러면 뒤 시험이 빈 구간이 된다 — 화면이 그 상태를 경고로 말한다.
    const thruIdx = found >= 0 ? found : isLast || !exam.thru ? all.length - 1 : all.length - 1;
    out.push({ exam, fromIdx: cursor, thruIdx });
    cursor = Math.max(cursor, thruIdx + 1);
  });
  return out;
}

/** 챕터 인덱스 → 그 챕터를 덮는 시험 구간의 순번(없으면 -1 = 어느 시험 범위에도 안 든다). */
export function scopeIndexFor(scopes: ExamScope[], chapterIdx: number): number {
  return scopes.findIndex((s) => chapterIdx >= s.fromIdx && chapterIdx <= s.thruIdx);
}

/* ── 학기 국면 ──────────────────────────────────────────────────────────── */

/** 국면. `pre` = 개강 전(방학이지만 다음 학기가 정해져 있다) · `in` = 학기 중 · `off` = 아무 학기도
 *  아니다(다음 학기 미정). ⚠ **`off` 와 `pre` 를 합치지 말 것** — 처방이 정반대다(T-4). */
export type SemesterPhaseKind = 'in' | 'pre' | 'off';

export interface SemesterPhase {
  kind: SemesterPhaseKind;
  /** 현재(또는 다가오는) 학기. `off` 면 null. */
  semester: Semester | null;
  /** `in` 이면 학기 시작 후 경과일(0-based), 아니면 null. */
  dayIndex: number | null;
  /** `in` 이면 1-based 주차, 아니면 null — T-17 주차 싱크의 입력. */
  week: number | null;
  /** `pre` 면 개강까지 남은 일수(D-n), 아니면 null. */
  daysToStart: number | null;
  /** `in` 이면 종강까지 남은 일수, 아니면 null. */
  daysToEnd: number | null;
}

/** 날짜가 든 학기만 — 날짜 없는 학기는 국면 판정에 참여할 수 없다(그게 T-1 이전의 상태였다). */
function datedSemesters(state: Pick<AppState, 'degree'>): Semester[] {
  const list = state.degree?.semesters || [];
  return list
    .filter((s): s is Semester & { startDs: string } => !!s.startDs)
    .sort((a, b) => (a.startDs! < b.startDs! ? -1 : 1));
}

/**
 * 지금이 학기 중인가 · 방학인가 · 개강까지 며칠인가.
 *
 * ⚠ 이 값을 **저장하지 않는다** — 자정 하나로 낡는다. 그래서 `ds` 를 인자로 받고(테스트가 자정을
 * 넘길 수 있어야 한다) 기본값만 `todayISO(state)` 로 둔다(`_today` 시드 존중).
 */
export function semesterPhase(state: Pick<AppState, 'degree' | '_today'>, ds = todayISO(state)): SemesterPhase {
  const dated = datedSemesters(state);
  const none: SemesterPhase = {
    kind: 'off',
    semester: null,
    dayIndex: null,
    week: null,
    daysToStart: null,
    daysToEnd: null,
  };
  if (!dated.length) return none;

  const current = dated.find((s) => s.startDs! <= ds && (!s.endDs || ds <= s.endDs));
  if (current) {
    const dayIndex = dayDiff(current.startDs!, ds);
    return {
      kind: 'in',
      semester: current,
      dayIndex,
      week: Math.floor(dayIndex / 7) + 1,
      daysToStart: null,
      daysToEnd: current.endDs ? dayDiff(ds, current.endDs) : null,
    };
  }
  const upcoming = dated.find((s) => s.startDs! > ds);
  if (upcoming) {
    return { ...none, kind: 'pre', semester: upcoming, daysToStart: dayDiff(ds, upcoming.startDs!) };
  }
  return none;
}

/** 학기 중이면 그 학기, 개강 전이면 다가오는 학기. 국면이 필요 없을 때 쓰는 얇은 래퍼. */
export function activeSemester(state: Pick<AppState, 'degree' | '_today'>, ds?: string): Semester | null {
  return semesterPhase(state, ds).semester;
}

/* ── Subject 일반화 · 학기 세계 안인가 밖인가 (P10 D6) ─────────────────────── */

/**
 * 이 과목이 **학기 회계 밖**인가(언어 등 소양 과목).
 *
 * 이 파일이 이 판정의 집인 이유: 소양 과목이란 정확히 _"위의 학기 계약이 적용되지 않는 과목"_ 이다 —
 * 시험(중간·기말)도 학점도 교수 주차도 없다. 학기 계약을 읽는 자리와 그 계약의 **경계**를 읽는
 * 자리가 갈리면, 화면마다 "이 과목은 예외인가"를 각자 판단하게 된다.
 *
 * ⚠ **`item.kind === 'soft'` 를 화면에서 직접 쓰지 말 것.** 저장 기본값이 `undefined`(= 전공)라
 * 직접 비교는 옳게 쓰기 쉬운 반면 **부정형**(`!== 'soft'`, `=== 'major'`)에서 갈린다.
 * ⚠ 소양 과목도 **학습은 똑같이 한다** — 챕터·복습 주기·주간 배분·숙달도는 전부 그대로다(D6).
 * 이 함수가 가르는 것은 오직 **학기 회계**(시험 칸 · 주차 싱크 · `Course` 연결)다.
 */
export function isSoftSubject(item: Pick<Item, 'kind'>): boolean {
  return item.kind === 'soft';
}

/** 학기 과목(`Course`)에 이어 붙일 수 있는 과목들 — 소양은 후보가 아니다(학점으로 안 센다). */
export function linkableItems(items: readonly Item[]): Item[] {
  return items.filter((i) => !isSoftSubject(i));
}

/* ── 두 우주 잇기 (Course ↔ Item) ───────────────────────────────────────── */

/** 실행 쪽 과목(`Item.id`) → 회계 쪽 과목(`Course`) + 그 학기. 링크가 없으면 null.
 *  ⚠ 순회로 답하는 이유는 `Course.itemId` 단방향이 정본이기 때문(`schema.ts` 참조). */
export function courseOfItem(
  state: Pick<AppState, 'degree'>,
  itemId: string,
): { course: Course; semester: Semester } | null {
  for (const semester of state.degree?.semesters || []) {
    const course = (semester.courses || []).find((c) => c.itemId === itemId);
    if (course) return { course, semester };
  }
  return null;
}

/** 회계 쪽 과목 → 실행 쪽 과목. 링크가 없거나 대상 `Item` 이 지워졌으면 null. */
export function itemOfCourse(state: Pick<AppState, 'items'>, course: Pick<Course, 'itemId'>): Item | null {
  if (!course.itemId) return null;
  return (state.items || []).find((i) => i.id === course.itemId) || null;
}

/** 이 학기에 **실행 짝이 없는** 과목들 — 과목 홈(T-24)·개강 리허설(T-15)이 "이어 붙일 것"으로 쓴다. */
export function unlinkedCourses(state: Pick<AppState, 'items'>, semester: Semester): Course[] {
  const ids = new Set((state.items || []).map((i) => i.id));
  return (semester.courses || []).filter((c) => !c.itemId || !ids.has(c.itemId));
}

/** 학기에 속한 실행 과목들(링크가 있는 것만) — 결산·목표가 "이 학기의 수"를 셀 때 쓰는 렌즈. */
export function itemsOfSemester(state: Pick<AppState, 'items'>, semester: Semester): Item[] {
  return (semester.courses || []).map((c) => itemOfCourse(state, c)).filter((i): i is Item => !!i);
}

/* ── N-19 학사일정 눈금 ────────────────────────────────────────────────────
   ⚠ 읽기가 여기 있는 이유는 이 파일 규율 1 과 같다: 눈금은 **학기의 속성**이고, 학기를 읽는
   입구가 둘이 되면 "이번 학기 정정 마감"이 화면마다 달라진다. 종류·라벨은 `lib/syllabus`. */

/** 그 학기의 눈금 — **날짜순**. 없으면 빈 배열. */
export function marksOf(semester: Semester | null): AcademicMark[] {
  if (!semester?.marks?.length) return [];
  return [...semester.marks].sort((a, b) => (a.ds < b.ds ? -1 : a.ds > b.ds ? 1 : 0));
}

/** 눈금 하나 + 남은 일수(D-day). 지난 것은 음수 — **거르지 않는다**(거르는 것은 화면의 판단). */
export interface MarkDue {
  mark: AcademicMark;
  /** `ds` 기준 남은 일수. 0 = 오늘. */
  daysLeft: number;
}

/**
 * **지금 국면의 학기**에서 오늘 이후 `within` 일 안에 있는 눈금들 — 가까운 순.
 *
 * ⚠ 지난 눈금은 안 준다. 정정·철회는 **지나면 되돌릴 수 없어** 지난 것을 계속 띄우면 그건
 * 정보가 아니라 자책이고(T-4 가 국면 처방에서 세운 규율), 휴강·보강은 지나면 그냥 과거다.
 */
export function upcomingMarks(state: Pick<AppState, 'degree' | '_today'>, ds: string, within = 21): MarkDue[] {
  const sem = activeSemester(state, ds);
  return marksOf(sem)
    .map((mark) => ({ mark, daysLeft: dayDiff(ds, mark.ds) }))
    .filter((m) => m.daysLeft >= 0 && m.daysLeft <= within)
    .sort((a, b) => a.daysLeft - b.daysLeft);
}

/** 그 **날짜**에 있는 눈금들 — 달력이 하루 칸에 표식을 놓을 때 쓴다(시험 표식 `examMarks` 와 같은 형태). */
export function marksOn(state: Pick<AppState, 'degree' | '_today'>, ds: string): AcademicMark[] {
  return (state.degree?.semesters || []).flatMap((s) => (s.marks || []).filter((m) => m.ds === ds));
}

/* ============================================================
   vault.ts — 옵시디언 볼트 현황(File System Access API) — 서버/외부 데이터.
   정본 _meta/cache/_index.json(검사.sh --index 산출)을 우선 소비하고, 없으면 .md 직접 스캔.
   순수 계산 + FS 읽기만(앱 상태에 복제 X). TanStack Query가 스캔 결과를 캐시(설계도 §1-B).
============================================================ */
import { SKIP, rid } from './utils';
import { dirEntries, pickDirectory, queryPermission, requestPermission } from './fsAccess';
import { vaultScan } from './tauri';
import { parseArtifact } from './artifacts';
import type { Chapter } from './types';

export interface VaultChapter {
  name: string;
  notes: number;
  verified: number;
  exported: number;
  legacy: number;
  wip: number;
  /** 이 챕터 노트들의 `reviewed:` 중 **가장 최근**(없으면 ''). 볼트가 아는 유일한 망각 시계다(W2). */
  reviewedRecent: string;
  /** `anki_state === 'stale'` 인 노트 수 — 노트는 고쳤는데 카드가 안 따라온 것. */
  ankiStale: number;
  /** 이 챕터에서 `prereq_in`(이걸 알면 몇 개가 풀리나) 최댓값. */
  prereqIn: number;
}
export interface VaultSubject extends VaultChapter {
  chapters: VaultChapter[];
}
export interface VaultScan {
  at: string;
  src: string;
  subjects: VaultSubject[];
  /** I006 — 원본 노트(파일 이름 포함). 집계는 «몇 개»를, 이것은 «어느 파일»을 답한다.
   *  ⚠ 옵셔널이다 — 브라우저 폴백 경로(FSA)는 아직 안 싣는다(셸이 배포 진입점이다). */
  notes?: IndexNote[];
}

/** 정본 인덱스(_meta/cache/_index.json) 로드 — 없으면 null(호출부가 파일스캔 폴백). */
export async function loadVaultIndex(
  handle: FileSystemDirectoryHandle,
): Promise<{ notes?: unknown[]; anki?: unknown[] } | null> {
  try {
    const meta = await handle.getDirectoryHandle('_meta');
    const aud = await meta.getDirectoryHandle('cache'); // P7 Phase 3: 감사→cache(파생)
    const fh = await aud.getFileHandle('_index.json');
    const idx = JSON.parse(await (await fh.getFile()).text());
    parseArtifact('index', idx); // parent↔hub 버전 + 모양 드리프트 경고(비차단)
    return idx;
  } catch {
    return null;
  }
}

/* ⚠⚠ **경계에서 필드를 버리지 말 것(W2 · 2026-07-31).** 종전엔 17키 중 5키만 뽑았고, 증발하는
   것 중에 **`reviewed`(468건에 날짜가 있다)** 와 **`anki_state`** 가 있었다 — 앱은 "복습 0/0"이라
   말하면서 그 답을 아는 파일을 매번 읽고 있었다. 인덱스 스키마(`artifacts.gen.ts` `indexArtifactSchema`)
   는 이 필드를 **이미 전부** 알고 있었으므로, 여기 좁은 인터페이스가 유일한 병목이었다.
   ⚠ 필드를 늘려도 **집계는 여전히 이 파일 하나**가 소유한다(Rust 는 레코드까지만 · 3단계-B 규율). */
export interface IndexNote {
  kind?: string;
  subject?: string;
  folder?: string;
  /** I006 — 노트 파일 이름. 경계에서 **버리던 필드**였고, 그래서 앱은 노트가 있다는 것을 알면서
   *  그것을 열 수 없었다(`src-tauri/src/vault.rs` 의 `Note.file` 주석이 근거의 SSOT). */
  file?: string | null;
  status?: string;
  anki_exported?: boolean;
  /** 검증 통과일(파이프라인). ⚠ **인출일이 아니다** — 위험을 올리는 방향으로만 쓴다(vaultAnchors). */
  reviewed?: string | null;
  /** 'ok' | 'none' | 'stale' — 노트↔카드 동기 상태. */
  anki_state?: string | null;
  /** 이 노트를 선행으로 삼는 노트 수(링크 인입). */
  prereq_in?: number;
  tier_hint?: string | null;
  role?: string | null;
  type?: string | null;
  flags?: unknown[];
}

/** _index.json.notes → 과목→챕터 집계. status=null=구버전(verified와 구분 · A-2). */
export function subjectsFromIndex(idx: { notes?: IndexNote[] }): VaultSubject[] {
  const bySubj: Record<string, VaultSubject & { _ch: Record<string, VaultChapter> }> = {};
  const zero = { notes: 0, verified: 0, exported: 0, legacy: 0, wip: 0, reviewedRecent: '', ankiStale: 0, prereqIn: 0 };
  for (const n of idx.notes || []) {
    if (n.kind === '실전문제') continue; // 실전문제는 검증%·노트수 분모에서 제외(대시보드 isProb와 정합)
    const sj = n.subject || '?';
    const parts = (n.folder || sj).split('/');
    const ch = parts.length > 1 ? parts.slice(1).join('/') : '(과목 루트)';
    const S = bySubj[sj] || (bySubj[sj] = { name: sj, _ch: {}, ...zero, chapters: [] });
    const C = S._ch[ch] || (S._ch[ch] = { name: ch, ...zero });
    // `reviewed` 는 **최댓값**(가장 최근) — 챕터 안에서 한 노트라도 최근에 검증됐으면 그게 앵커다.
    const rv = n.reviewed || '';
    if (rv > C.reviewedRecent) C.reviewedRecent = rv;
    if (rv > S.reviewedRecent) S.reviewedRecent = rv;
    if (n.anki_state === 'stale') {
      C.ankiStale++;
      S.ankiStale++;
    }
    const pin = +(n.prereq_in || 0);
    if (pin > C.prereqIn) C.prereqIn = pin;
    if (pin > S.prereqIn) S.prereqIn = pin;
    const st = n.status || '';
    const ver = st === 'verified';
    const leg = !st;
    const wip = !!st && !ver; // raw/drafted(파이프라인 진행중)
    const exp = !!n.anki_exported;
    C.notes++;
    S.notes++;
    if (ver) {
      C.verified++;
      S.verified++;
    }
    if (exp) {
      C.exported++;
      S.exported++;
    }
    if (leg) {
      C.legacy++;
      S.legacy++;
    }
    if (wip) {
      C.wip++;
      S.wip++;
    }
  }
  return Object.values(bySubj).map((s) => {
    const chapters = Object.values(s._ch);
    const { _ch, ...rest } = s;
    void _ch;
    return { ...rest, chapters };
  });
}

/** 프론트매터를 찾기 위해 읽는 선두 길이(**바이트** — `Blob.slice` 는 바이트 단위다).
 *  ⚠ `src-tauri/src/vault.rs` 의 `FM_HEAD_BYTES` 와 **같은 값·같은 단위**여야 한다. 종전에 저쪽이
 *  `chars().take(1600)`(문자)였고 주석은 "동형"이라 적어, 한글 노트에서 최대 3배를 읽었다. */
const FM_HEAD_BYTES = 1600;

async function readFM(fh: FileSystemFileHandle): Promise<Record<string, string>> {
  try {
    const f = await fh.getFile();
    const t = (await f.slice(0, FM_HEAD_BYTES).text()) as string;
    // `\s*\n`이 아니라 `[ \t]*\r?\n` — `\s`가 개행을 포함해 `\s*\n`과 뒤따르는 lazy `[\s\S]*?`가
    // 같은 문자를 두고 겹치면서 백트래킹이 초선형이 된다(sonarjs/super-linear-regex).
    // 문자 클래스를 겹치지 않게 가르면 모호성이 사라지고, 덤으로 CRLF 볼트도 인식한다.
    const m = t.match(/^---[ \t]*\r?\n([\s\S]*?)\r?\n---/);
    if (!m) return {};
    const o: Record<string, string> = {};
    m[1]!.split('\n').forEach((l) => {
      const i = l.indexOf(':');
      if (i > 0) o[l.slice(0, i).trim()] = l.slice(i + 1).trim();
    });
    return o;
  } catch {
    return {};
  }
}

/** 순회에서 통째로 건너뛸 폴더인가 — `_`/`.` 접두(파생·시스템)와 SKIP 목록.
    ⚠ **모든 깊이에서** 적용해야 한다. 실제 볼트에 `기초 수학/미적분/.trash`·`.../_리포트` 처럼
    깊은 곳에도 있어서, 최상위에서만 거르면 휴지통 노트가 집계에 섞인다. */
function skipDir(name: string): boolean {
  return name.startsWith('_') || name.startsWith('.') || SKIP.has(name);
}
/** 집계에서 뺄 노트 파일인가(파일명 기준). 정본 인덱스는 파이프라인이 생성 시점에 걸러 주므로
    이 필터는 **폴백 경로가 인덱스의 분모를 흉내내는** 장치다.
    ⚠ 흉내에는 원리적 한계가 있다 — 인덱스는 `kind`(개념노트·집합체·실전문제)로 분류하는데
    폴백엔 그 정보가 없어 파일명으로만 유추한다. 실측(실제 볼트): 이 차이로 남는 오차는
    **노트 1개**(`기초 수학/🏠 수학노트 홈.md` — 이름에 MOC 가 없지만 파이프라인은 제외).
    깊이 결함을 고치기 전엔 오차가 **239개**였으니, 남은 1개는 감수한다. */
function skipNote(fn: string): boolean {
  return !fn.endsWith('.md') || fn.includes('MOC') || fn.includes('실전문제');
}

/** 볼트 트리를 **임의 깊이**로 순회해 정본 인덱스와 같은 모양의 노트 레코드를 만든다.
 *
 *  ⚠ **깊이 2단 고정이 실제로 46%를 버리고 있었다.** 예전 구현은 `과목/챕터/` 안에서 파일만
 *  집계하고 디렉터리는 조용히 `continue` 했다 — 실측(2026-07-19, 실제 볼트): 전체 519개 중
 *  폴백이 보는 건 280개, **239개(46%)가 누락**. `기초 수학/미적분/01 극한과 연속/*.md` 처럼
 *  3단 구조가 실재하는데, 사용자에겐 "노트 수가 좀 적네"로만 보여 진단이 불가능했다.
 *
 *  인덱스 경로(`subjectsFromIndex`)는 `folder` 문자열을 쪼개 임의 깊이를 이미 지원했다 —
 *  즉 두 경로가 **서로 다른 볼트 구조를 지원**하고 있었고 그게 문서화된 적도 없었다.
 *  이제 폴백도 같은 레코드를 만들어 **같은 집계 함수**에 넣는다(분기 자체를 없앤다). */
async function notesFromFiles(handle: FileSystemDirectoryHandle): Promise<IndexNote[]> {
  const out: IndexNote[] = [];
  const walk = async (dir: FileSystemDirectoryHandle, subject: string, folder: string): Promise<void> => {
    for await (const [name, h] of dirEntries(dir)) {
      if (h.kind === 'directory') {
        if (skipDir(name)) continue;
        await walk(h as FileSystemDirectoryHandle, subject, `${folder}/${name}`);
      } else if (h.kind === 'file' && !skipNote(name)) {
        const fm = await readFM(h as FileSystemFileHandle);
        out.push({
          subject,
          folder,
          status: fm.status,
          // ⚠ 값은 boolean 이 아니라 **날짜 문자열**이다(실측: `anki_exported: 2026-07-11`).
          //    존재 자체가 "내보냄"이므로 truthy 판정이 맞다 — boolean 으로 파싱하려 들면 안 된다.
          anki_exported: !!fm.anki_exported,
          // W2 — 폴백도 같은 레코드를 만든다(인덱스 경로와 모양이 갈리면 같은 볼트에서 숫자가 갈린다).
          // ⚠ `anki_state`·`prereq_in` 은 프론트매터에 없다(파이프라인 파생) — 폴백에선 원리적으로 모른다.
          reviewed: fm.reviewed || '',
        });
      }
    }
  };
  for await (const [name, h] of dirEntries(handle)) {
    if (h.kind !== 'directory' || skipDir(name)) continue;
    await walk(h as FileSystemDirectoryHandle, name, name);
  }
  return out;
}

/** 폴백: 정본 인덱스가 없을 때 .md 직접 스캔(구버전 status 없음도 집계).
    집계는 **인덱스 경로와 같은 함수**를 쓴다 — 예전엔 별도 구현이라 깊이·verified 판정이
    서로 달랐다(같은 볼트에서 숫자가 갈렸다). */
export async function scanVaultFromFiles(handle: FileSystemDirectoryHandle): Promise<VaultSubject[]> {
  return subjectsFromIndex({ notes: await notesFromFiles(handle) });
}

/** 폴더 선택 → 스캔(정본 인덱스 우선·.md 폴백). 사용자가 취소하면 null.
 *  handle도 함께 반환 — Anki 패널이 같은 볼트 폴더를 재선택 없이 재사용(레거시 vaultHandle 공유). */
export async function pickAndScanVault(
  existing?: FileSystemDirectoryHandle,
): Promise<{ scan: VaultScan; handle: FileSystemDirectoryHandle } | null> {
  let handle = existing;
  if (!handle) {
    const picked = await pickDirectory(); // 미지원이면 FsUnsupportedError, 취소면 null
    if (!picked) return null;
    handle = picked;
  }
  const idx = await loadVaultIndex(handle);
  let subjects: VaultSubject[];
  let src: string;
  if (idx && Array.isArray(idx.notes)) {
    subjects = subjectsFromIndex(idx as { notes: IndexNote[] });
    src = '정본 _index.json';
  } else {
    subjects = await scanVaultFromFiles(handle);
    src = '파일 스캔(.md)';
  }
  return { scan: { at: new Date().toLocaleString('ko'), src, subjects }, handle };
}

/** 셸(Tauri)에서 볼트를 읽는다 — **폴더 선택도 권한도 없다.**
 *  `workspace.rs` 가 이미 워크스페이스를 알고 볼트는 `<workspace>/knowledge` 라, 사용자에게
 *  폴더를 물을 이유가 자체가 없다. 브라우저에선 null → 호출부가 기존 FSA 경로로 간다.
 *
 *  ⚠ Rust 는 **노트 레코드까지만** 만든다. 집계는 여기 `subjectsFromIndex` 하나가 소유한다 —
 *  3단계-B 에서 집계가 두 벌이라 같은 볼트에서 숫자가 갈리던 결함을 고쳤으니, 언어를 바꿔
 *  세 번째 구현을 만들지 않는다. */
/** 볼트 스캔 실패의 **쿼리 캐시 자리**(U006). `null` = 지금 문제 없음. */
export const VAULT_ERROR_KEY = ['vaultError'] as const;

/**
 * 이 실패가 **"아직 설정 안 됨"** 인가(= 실패가 아니다).
 *
 * ⚠ `vault.rs` 의 `vault_scan` 은 폴더 미설정도 `Err("볼트 폴더를 찾지 못했습니다…")` 로 답한다.
 * 그 갈래를 에러 배너로 올리면 **워크스페이스를 아직 안 정한 신규 사용자에게 장애를 보고**하게
 * 되고, 그건 `classifyArtifact` 가 SSOT 로 잠근 오분류(미생성을 장애로) 그 자체다. 문자열
 * 계약인 것이 마음에 안 들지만 `isNotYetError` 가 이미 같은 형태를 쓴다 — 두 벌로 갈리지
 * 않게 판정을 여기 하나에 둔다.
 */
export function isVaultUnset(e: unknown): boolean {
  return (e instanceof Error ? e.message : String(e ?? '')).includes('볼트 폴더를 찾지 못했');
}

export async function scanVaultViaShell(): Promise<VaultScan | null> {
  const res = await vaultScan();
  if (!res) return null;
  return {
    at: new Date().toLocaleString('ko'),
    src: res.src,
    subjects: subjectsFromIndex({ notes: res.notes as IndexNote[] }),
    /* I006 — **원본 노트도 함께 싣는다**(2026-08-22). 집계(`subjects`)는 «몇 개인가»를 답하고
       원본은 «어느 파일인가»를 답한다 — 노트를 열려면 후자가 필요한데, 종전엔 이 경계에서
       버려졌다. 별도 질의 키를 파지 않는 이유: 두 값의 신선도가 갈리면 «집계는 새 것인데
       파일 목록은 옛 것» 이 되고 그때 여는 것은 없는 파일이다. */
    notes: res.notes as IndexNote[],
  };
}

/* ── 저장된 핸들 재사용(FS 권한) — IDB에 영속한 폴더 핸들로 재선택 없이 재연결.
   권한은 재시작 뒤 'prompt'로 돌아갈 수 있어(브라우저 정책), 조회→요청 2단계로 다룬다. */
/** 저장된 핸들의 읽기 권한 상태 — 'granted'면 제스처 없이 스캔 가능. */
export async function queryVaultPermission(handle: FileSystemDirectoryHandle): Promise<PermissionState> {
  return queryPermission(handle, 'read');
}
/** 저장된 핸들에 읽기 권한 요청(사용자 제스처 안에서 호출). */
export async function requestVaultPermission(handle: FileSystemDirectoryHandle): Promise<PermissionState> {
  return requestPermission(handle, 'read');
}

/** 노트 수 → 예상시간(h). */
export function estH(notes: number): number {
  return Math.max(1, Math.round(notes * 0.5));
}

/** 볼트 챕터 → 학습 항목 챕터(예상시간 추정). */
export function chaptersFromVault(chs: VaultChapter[]): Chapter[] {
  return chs.map((c) => ({ id: rid(), name: c.name, hours: estH(c.notes), done: false }));
}

/* ── I006 **챕터 → 노트 파일 해석**(2026-08-22 발상 축) ─────────────────────────────────

   앱은 «이 챕터를 공부하라»고 말할 수 있지만 그 일을 **시작시킬 수는 없었다** — 노트를 여는
   경로가 0이었다. 그 첫 조각이 이 함수다: 블록이 가리키는 챕터가 **어느 파일 하나**인가.

   ⚠⚠ **유일해야 연다.** 여럿이면 `null` 이다 — 어느 것을 여는지 사용자가 모르는 채로 파일이
   열리면, 그건 «대상을 연다»가 아니라 «아무거나 연다»다. 그 회차의 최싼검증이 정확히
   *"유일 노트 파일로 해석되는 비율"* 인 것도 그래서다(<60%면 매칭이 먼저다).
   ⚠ 매칭은 **폴더 경로의 마지막 조각**으로 한다 — `subjectsFromIndex` 가 챕터 이름을 만드는
   방식(`folder.split('/').slice(1)`)과 **같은 규칙**이어야 한다. 갈리면 화면이 아는 챕터와
   여기서 찾는 챕터가 다른 것이 되고, 그건 조용하다. */

/** 그 과목·챕터의 노트가 **정확히 하나**면 볼트 상대경로, 아니면 `null`. */
export function noteRelFor(notes: readonly IndexNote[], subject: string, chapter: string): string | null {
  const hits = notes.filter((n) => {
    if (!n.file || (n.subject || '') !== subject) return false;
    const parts = (n.folder || n.subject || '').split('/');
    const ch = parts.length > 1 ? parts.slice(1).join('/') : '(과목 루트)';
    return ch === chapter;
  });
  const only = hits.length === 1 ? hits[0] : undefined;
  return only?.file ? `${only.folder || only.subject || ''}/${only.file}` : null;
}

/* ============================================================
   weekAlloc.ts — 주간 배분(재개편 v2 §12) 순수 CRUD.
   모델: weekAlloc[weekMon][sid] = number[7](분, index=wd 0=일..6=토). '이번 주 어느 과목을 어느 요일에 얼마씩'.
   dayPlans 패턴을 주(週) 층으로 일반화 — 무배분 주는 자동(불변), 첫 편집 시 자동 파생 스냅샷을 managed로 승격.
   스케줄러 입력은 아니고(스케줄러는 state.weekAlloc를 직접 읽음 · §12-4), 여긴 보드/스토어가 쓰는 편집 헬퍼.
   ⚠ state 변형 함수(ensure/set/copy/reset)는 store.mutate(immer draft) 안에서만 호출한다.
============================================================ */
import { keySid } from './domainKeys';
import { addDays, dayDiff, iso, mondayOf, parseISO } from './utils';
import { completionMin } from './persistence';
import type { AppState, Item, ScheduleResult } from './types';

/** 7요일 0벡터(분) — index=wd(0=일..6=토). */
export function zeroVec(): number[] {
  return [0, 0, 0, 0, 0, 0, 0];
}

/** 방치 배지(ID-7) 임계 — 이 일수 이상 손 안 댄 과목에 '방치' 신호. */
export const NEGLECT_DAYS = 7;

/** 과목별 '마지막 완료(손 댄) 날 → 오늘로부터 경과일'(ID-7). 완료(done) 세션만 — 계획만 있고
 *  안 한 건 '손 댐'이 아니다. 예산 상태(배분량 vs 예산)와 **직교한 최근성** 신호라, 배분 보드에서
 *  "이번 주 배분했지만 며칠째 실제로는 안 함"이라는 계획↔실행 괴리를 드러낸다. 완료 이력 없는
 *  과목은 키 없음(신규 과목을 '방치'로 몰아세우지 않는다 — 기준 날짜가 없다). */
export function neglectDaysBySid(state: AppState, todayIso: string): Record<string, number> {
  const comp = state.completions || {};
  const lastDs: Record<string, string> = {};
  for (const ds of Object.keys(comp)) {
    if (ds > todayIso) continue; // 미래 완료 무시
    for (const k of Object.keys(comp[ds] || {})) {
      if (!comp[ds]![k]?.done) continue;
      const sid = keySid(k);
      if (!sid) continue;
      if (!lastDs[sid] || ds > lastDs[sid]!) lastDs[sid] = ds;
    }
  }
  const out: Record<string, number> = {};
  for (const sid of Object.keys(lastDs)) out[sid] = dayDiff(lastDs[sid]!, todayIso);
  return out;
}

/** 그 날짜(또는 주 아무 날)가 속한 주의 월요일(ISO) = weekAlloc 키. */
export function weekMonOf(ds: string): string {
  return iso(mondayOf(parseISO(ds)));
}

/** 스케줄 산출에서 그 주의 new 블록 분을 (sid → 7요일[분])으로 집계 = 자동 분배 스냅샷.
 *  managed 승격 전 보드가 보여줄 시작점이자, ensureWeekAlloc가 심는 값. */
export function deriveAutoAlloc(res: ScheduleResult, wk: string): Record<string, number[]> {
  const out: Record<string, number[]> = {};
  for (const d of res.days) {
    if (weekMonOf(d.ds) !== wk) continue;
    for (const it of d.items) {
      if (it.type !== 'new') continue;
      const vec = (out[it.sid] ||= zeroVec());
      vec[d.wd] = (vec[d.wd] || 0) + it.min;
    }
  }
  return out;
}

/** 그 주가 managed(사용자 배분 확정)인가 — **배분 계약의 단일 술어**.
 *  ⚠ `weekAlloc[wk] = {}`(과목 키가 하나도 없는 빈 주 객체)는 **managed가 아니다**.
 *  왜: 빈 객체도 truthy라 예전 `!!state.weekAlloc?.[wk]`는 스케줄러(§12-4 managed 분기)에서
 *  "전 과목 0분 배분"으로 해석돼 그 주 new 블록이 통째로 사라졌다(무음 전멸 — 배지는 '내 배분',
 *  토스트는 '복사했어요'로 성공 신호만 떴다). 스케줄러·보드·시트가 **이 함수 하나로** 같은 판정을 쓴다.
 *  단, 과목 키가 있고 값이 전부 0인 주(사용자가 의도적으로 비운 '쉬는 주')는 managed로 존중한다 —
 *  키 유무가 '사용자가 이 주를 손댔다'의 신호이고, 합 0을 auto로 되돌리면 의도를 뒤집는다. */
export function isWeekManaged(state: AppState, wk: string): boolean {
  const map = state.weekAlloc?.[wk];
  return !!map && Object.keys(map).length > 0;
}

/** 그 주 표시용 배분(읽기 전용) — managed면 명시값, 아니면 자동 파생 스냅샷.
 *  판정은 isWeekManaged 하나로 — 빈 주 객체를 '명시값'으로 보면 보드는 텅 비고 엔진은 auto로 도는 괴리가 난다. */
export function allocView(state: AppState, res: ScheduleResult, wk: string): Record<string, number[]> {
  const map = state.weekAlloc?.[wk];
  return isWeekManaged(state, wk) ? map! : deriveAutoAlloc(res, wk);
}

/** managed 승격 — 없으면(또는 빈 주 객체면) 자동 파생을 스냅샷해 weekAlloc[wk]에 심고 반환(dayPlans ensureManual 동형). state 변형. */
export function ensureWeekAlloc(state: AppState, res: ScheduleResult, wk: string): Record<string, number[]> {
  state.weekAlloc = state.weekAlloc || {};
  if (!isWeekManaged(state, wk)) state.weekAlloc[wk] = deriveAutoAlloc(res, wk);
  return state.weekAlloc[wk]!;
}

/** 셀 배분 설정(분) — 승격 후 (sid,wd) 칸을 mins로(음수는 0). state 변형. */
export function setAllocCell(
  state: AppState,
  res: ScheduleResult,
  wk: string,
  sid: string,
  wd: number,
  mins: number,
): void {
  if (wd < 0 || wd > 6) return;
  const map = ensureWeekAlloc(state, res, wk);
  const vec = (map[sid] ||= zeroVec());
  vec[wd] = Math.max(0, Math.round(mins));
}

/* ── I053 「전공 밖」 레인 — **승격 없이 쓰는 칸**(2026-08-22 발상 축) ─────────────────────
   이 셋이 위 `setAllocCell` 과 대칭인데 **`ensureWeekAlloc` 을 안 지난다**. 그것이 요점이다:
   전공 밖 시간을 `weekAlloc` 의 합성 sid 로 두면 칸 하나를 채우는 순간 그 주가 managed 로
   승격돼 배치 전체가 자동에서 수동으로 바뀐다(2026-08-22 착수 전 확인). 저장 자리와 그 근거는
   `schema.ts` 의 `outsideAlloc` 절.
   ⚠ **스케줄러는 이 값을 안 읽는다.** 하는 일은 배분판의 **분모를 정직하게** 만드는 것뿐이고,
     그게 부모 규약의 «교양축과 계약 0»을 지키면서 이 축을 말하는 유일한 형태다. */

/** 그 주의 전공 밖 분(7요일). 없으면 0벡터 — **사본을 준다**(호출부의 제자리 변형 차단). */
export function outsideVec(state: Pick<AppState, 'outsideAlloc'>, wk: string): number[] {
  const v = state.outsideAlloc?.[wk];
  return v && v.length === 7 ? v.slice(0, 7) : zeroVec();
}

/** 전공 밖 칸 설정(분). `weekAlloc` 을 건드리지 않는다(위 ⚠). state 변형. */
export function setOutsideCell(state: AppState, wk: string, wd: number, mins: number): void {
  if (wd < 0 || wd > 6) return;
  state.outsideAlloc = state.outsideAlloc || {};
  const vec = (state.outsideAlloc[wk] ||= zeroVec());
  vec[wd] = Math.max(0, Math.round(mins));
  /* ⚠ 전부 0이면 **키를 지운다** — 안 지우면 «손댔다»의 흔적이 영원히 남아 백업·동기화가
     빈 주를 계속 나른다(`copyPrevWeekAlloc` 이 빈 managed 주를 안 만드는 것과 같은 규율). */
  if (vec.every((m) => !m)) delete state.outsideAlloc[wk];
}

/** 이전 주 배분(명시 or 자동)을 이 주로 스냅샷 복사 — per-week지만 되풀이 편의(§12-2). state 변형.
 *  @returns 복사한 과목 수(0 = **아무것도 쓰지 않음**). 호출부는 0이면 실패 신호를 줘야 한다.
 *  왜 no-op 경로가 필요한가: 계획 **첫 주**에서 누르면 이전 주는 지평 밖이라 allocView가 `{}`를 준다.
 *  예전엔 그 `{}`를 그대로 써서 그 주를 '빈 managed'로 만들었고 → 스케줄러가 전 과목 0분으로 돌아
 *  그 주 new 블록이 조용히 사라졌다. 복사할 게 없으면 **기존 상태를 손대지 않는다**. */
export function copyPrevWeekAlloc(state: AppState, res: ScheduleResult, wk: string): number {
  const prev = iso(addDays(parseISO(wk), -7)); // wk=월요일 → -7일 = 지난 주 월요일
  const src = allocView(state, res, prev);
  const copy: Record<string, number[]> = {};
  for (const sid in src) copy[sid] = (src[sid] || zeroVec()).slice(0, 7);
  const n = Object.keys(copy).length;
  if (n === 0) return 0; // 소스가 비었다 → 쓰지 않는다(빈 managed 주 생성 금지).
  state.weekAlloc = state.weekAlloc || {};
  state.weekAlloc[wk] = copy;
  return n;
}

/** 두 배분 스냅샷 사이에서 **값이 실제로 달라진 칸**의 키(`${sid}:${wd}`)를 행·요일 순서로.
 *  보드 툴바 액션('지난 주 복사'·'자동으로')의 결과를 그 칸들만 훑어 보여주는 데 쓴다(UX-A4).
 *  ⚠ `sids` 는 **보이는 과목**만 넘긴다 — 삭제된 과목의 고아 배분이 바뀌어도 가리킬 칸이 화면에
 *    없다(colSumMin 의 validSids 방어선과 같은 이유).
 *  왜 액션별 반환 확장이 아니라 전후 비교인가: 두 액션이 같은 답을 필요로 하는데 lib 쪽 반환을
 *  액션마다 넓히면 그만큼 계약이 갈린다. 비교는 순수하고, 한 함수가 두 경로를 덮는다. */
export function changedAllocCells(
  before: Record<string, number[]>,
  after: Record<string, number[]>,
  sids: readonly string[],
): string[] {
  const keys: string[] = [];
  for (const sid of sids) {
    const b = before[sid] || zeroVec();
    const a = after[sid] || zeroVec();
    for (let wd = 0; wd < 7; wd++) if ((b[wd] || 0) !== (a[wd] || 0)) keys.push(`${sid}:${wd}`);
  }
  return keys;
}

/** 그 주를 자동으로 되돌리기 — weekAlloc[wk] 삭제(auto 복귀). state 변형. */
export function resetWeekAlloc(state: AppState, wk: string): void {
  if (state.weekAlloc) delete state.weekAlloc[wk];
}

/** 과목 행 합(분) — 그 과목 주간 배분 총합. */
export function rowSumMin(vec: number[] | undefined): number {
  return (vec || []).reduce((t, m) => t + (m || 0), 0);
}

/** 요일 열 합(분) — 그 wd의 전 과목 배분 합.
 *  validSids를 주면 **그 집합에 있는 sid만** 센다 — 삭제된 과목의 고아 배분이 열 합·초과 경고를
 *  부풀리는 것을 호출부에서 방어할 수 있게(옵셔널이라 기존 호출부는 무변경). 정상 경로의 청소는
 *  pruneAlloc/removeSidFromAlloc가 담당하고, 이건 이미 오염된 저장본에 대한 표시 단계 방어선이다. */
export function colSumMin(map: Record<string, number[]>, wd: number, validSids?: ReadonlySet<string>): number {
  let t = 0;
  for (const sid in map) {
    if (validSids && !validSids.has(sid)) continue;
    t += map[sid]?.[wd] || 0;
  }
  return t;
}

/* ── 고아 배분 청소 ──────────────────────────────────────────────────────
   과목을 지워도 weekAlloc[wk][sid]는 전 주에 남는다(참조 무결성 없는 맵). 그 잔재는
   colSumMin(열 합)·가용 초과 경고를 부풀려 "보이는 행 합 1h인데 푸터는 4h" 같은 유령을 만든다.
   삭제 경로에서 removeSidFromAlloc를, 부팅/복구 같은 일괄 지점에선 pruneAlloc를 부른다. */

/** 한 과목의 배분을 전 주에서 제거 — 과목 삭제 경로 전용. 빈 주 객체는 키째 지운다(auto 복귀).
 *  @returns 실제로 지운 (주, 과목) 쌍 수. state 변형. */
export function removeSidFromAlloc(state: AppState, sid: string): number {
  const all = state.weekAlloc;
  if (!all) return 0;
  let n = 0;
  for (const wk in all) {
    const map = all[wk];
    if (!map || !(sid in map)) continue;
    delete map[sid];
    n++;
    if (Object.keys(map).length === 0) delete all[wk]; // 빈 주는 managed가 아니다 → 키 자체를 정리.
  }
  return n;
}

/** 유효 sid 집합에 없는 모든 배분을 제거(일괄 청소·복구용). @returns 지운 (주, 과목) 쌍 수. state 변형. */
export function pruneAlloc(state: AppState, validSids: Iterable<string>): number {
  const keep = validSids instanceof Set ? (validSids as Set<string>) : new Set(validSids);
  const all = state.weekAlloc;
  if (!all) return 0;
  let n = 0;
  for (const wk in all) {
    const map = all[wk];
    if (!map) continue;
    for (const sid in map) {
      if (keep.has(sid)) continue;
      delete map[sid];
      n++;
    }
    if (Object.keys(map).length === 0) delete all[wk];
  }
  return n;
}

/* ── 배분 대상 과목·집계 단일화 ───────────────────────────────────────────
   `it.name && it.mode !== 'daily'` 파생이 Alloc·AllocBoard 3곳에 복붙돼 있었고, 리드아웃의
   분자(배분 합)와 분모(예산 합)가 각자 필터를 굴려 집합이 어긋날 수 있었다(주당 0h 과목이
   분자엔 들어가고 분모엔 안 들어가 "4.0 / 2.0h · 200%"). 술어와 집계를 여기 한 곳에 둔다. */

/** 배분 보드에 행으로 서는 과목(=주간 과목). daily(Anki)와 이름 없는 자리표시자는 제외. */
export function weeklyItems(state: AppState): Item[] {
  return (state.items || []).filter((it) => it.name && it.mode !== 'daily');
}

/** 배분해도 엔진이 **새 학습(new) 블록을 만들지 않는** 과목인가 — 주당 목표시간이 0/미입력.
 *  scheduler의 weeklyRaw 필터(`mode!=='daily' && weeklyHours>0`)와 같은 판정이다. 보드는 이걸로
 *  "배분해도 안 굴러가요" 배지를 띄우고, 아래 집계들은 이 과목을 분자·분모 **양쪽에서 함께** 뺀다. */
export function isUnschedulable(it: Item): boolean {
  return it.mode !== 'daily' && +(it.weeklyHours || 0) <= 0;
}

/** 이번 주 예산 합(분) = 스케줄 가능한 주간 과목들의 weeklyHours 합. 리드아웃 분모. */
export function weekBudgetMin(state: AppState): number {
  return weeklyItems(state).reduce(
    (t, it) => (isUnschedulable(it) ? t : t + Math.round((it.weeklyHours || 0) * 60)),
    0,
  );
}

/**
 * 이번 주 **필요 시간**(분) = 매일 과목(dailyMin×7) + 주간 과목(weeklyHours). "가용시간이 이걸
 * 담을 수 있나"를 묻는 쪽의 분자다(H11 · 2026-07-26 감사).
 *
 * ⚠ `weekBudgetMin` 과 **다른 질문이고, 그래서 값이 다르다.** 저기는 *배분 보드가 나눠 담을 수
 * 있는 양*(매일 과목은 엔진이 따로 굴리므로 제외)이고, 여기는 *일주일에 실제로 필요한 총량*이다.
 * 감사가 잡은 결함은 값이 다른 것 자체가 아니라 **두 값이 각각 두 곳에 인라인으로 복제**돼
 * 있었다는 점이다(`AvailRail`·`Items` 가 각자 계산 → 한 화면에서 15.0h 와 18.5h 가 동시에 뜬다).
 * 정의를 하나로 모으고, 이름으로 무엇을 묻는지 구분한다.
 */
export function weekRequiredMin(state: AppState): number {
  return (state.items || []).reduce((t, it) => {
    if (!it.name) return t;
    return t + (it.mode === 'daily' ? (it.dailyMin || 0) * 7 : Math.round((it.weeklyHours || 0) * 60));
  }, 0);
}

/** 그 주 배분 합(분) — 분모(weekBudgetMin)와 **같은 과목 집합**을 순회한다(비율 오염 방지). 리드아웃 분자. */
export function weekAllocTotalMin(state: AppState, res: ScheduleResult, wk: string): number {
  const map = allocView(state, res, wk);
  return weeklyItems(state).reduce((t, it) => (isUnschedulable(it) ? t : t + rowSumMin(map[it.id])), 0);
}

/**
 * 그 주에 **실제로 해낸 새 학습 분**(월~일 7일 합).
 *
 * 왜 필요한가: 배분 보드는 "이번 주 얼마를 배분했나"만 말하고 "지난주엔 그 배분이 얼마나
 * 지켜졌나"를 말하지 않았다 — **다음 주 숫자를 정하는 바로 그 자리에서 유일하게 없는 근거**다.
 *
 * ⚠ **`new` 타입만 센다.** 배분(`weekAlloc`)이 구동하는 것은 새 학습 블록이고, `completions` 는
 * 복습·백지·Anki·모의까지 전 타입의 합이다. 좁히지 않으면 "배분 10h / 실제 14h" 같은 **비교
 * 불가능한 대조**가 나오고, 그건 근거가 아니라 소음이다(이 항목이 Later 로 내려갔던 사유가
 * 정확히 그 의미 어긋남이었다 — 좁힌 첫 조각만 취한다).
 * ⚠ 분은 `completionMin` 이 소유한다(실측 있으면 실측, 없으면 계획 · G-1). 폴백 규칙을 여기서
 * 다시 쓰면 회고가 두 가지 답을 갖게 된다.
 */
export function weekDoneNewMin(state: AppState, wk: string): number {
  let total = 0;
  for (let i = 0; i < 7; i++) {
    const day = state.completions?.[iso(addDays(parseISO(wk), i))];
    if (!day) continue;
    for (const [key, entry] of Object.entries(day)) {
      if (!key.endsWith('|new')) continue;
      if (entry?.done) total += completionMin(entry);
    }
  }
  return total;
}

/* ── E-4 레버의 SSOT (Q-19 · 2026-08-02) ──────────────────────────────────────
   `Review.tsx` 의 `useWeeklyAllot` 이 반올림까지 포함한 이 계산을 갖고 있었는데, 그건 React 훅
   이라 **화면 안에서만** 부를 수 있었다. ⌘K 가 같은 동사를 갖게 되면서(팔레트는 훅이 아니다)
   같은 식이 두 벌 될 참이었고, 그 파일 자신이 이미 그 위험을 적어 뒀다(_"CoachCard·WorkbenchCard가
   바이트 동일 복붙하던 것 … 반올림 로직 드리프트=실버그 위험"_). 그래서 **식을 여기로 내린다** —
   훅은 이 함수를 부르는 껍데기가 되고, 팔레트도 같은 것을 부른다.

   ⚠ 반올림이 계산의 일부다: `weeklyHours` 는 0.5 단위로 편집되는데 부동소수 누적이 `2.9999…`
   를 만들면 화면에 그대로 샌다. `Number.EPSILON` 보정 후 소수 1자리 — **옮기면서 바꾸지 않았다.**
   ⚠ 하한이 0 인 것도 계약이다. 0 은 "안 함"이 아니라 **이번 주 스케줄 제외**라는 뜻이고
   (`isUnschedulable` 이 그렇게 읽는다), 음수는 그 어휘에 없다. */
export function bumpWeeklyHours(cur: number | undefined, delta: number): number {
  return Math.max(0, Math.round((+(cur || 0) + delta + Number.EPSILON) * 10) / 10);
}

/* ⚠⚠ **레버의 진짜 SSOT 는 산술이 아니라 이 recipe 다**(2026-08-20 리뷰 M-9).

   위 함수를 내리고도 *"과목을 찾아서 그 필드에 쓴다"* 는 부분이 **세 층에 그대로 남아** 있었다
   (`features/review/Review.tsx` 의 훅 · `shell/actions.ts` 의 팔레트 동사 · `app/CommandPalette.tsx`
   의 계획 명령). 셋 다 `mutate(st => { const t = st.items.find(x => x.id === id); … })` 로 문자
   그대로 같았고, 그래서 이 파일과 `Review.tsx` 가 각각 *"팔레트도 같은 것을 부른다"* ·
   *"E-4 레버 SSOT"* 라 적은 문장이 둘 다 사실이 아니었다.

   그리고 네 번째 변종이 이미 계약을 어기고 있었다 — `planVerbs` 의 "이번 주 쉼"이 `setWeekly(0)`
   으로 `bumpWeeklyHours` 를 통째로 건너뛰어, 위 ⚠ 의 *"하한이 0 인 것도 계약이다"* 가 한
   호출부에서만 강제됐다. `{ set }` 가지를 여기 두면 그 어휘가 한 곳으로 돌아온다.

   ⚠ `mode === 'daily'` 가드도 여기가 자리다 — 세 호출부 중 그걸 가진 것은 훅 하나뿐이었다
   (`leverFor`). 레버가 없는 과목에 레버를 거는 것은 어느 입구에서든 틀렸다.

   ⚠ 이 저장소의 관용구를 따른다: 순수 recipe 를 `mutate(s => …)` 안에서 부른다
   (`addBacklog`·`setWeeklyCheck` 와 같은 형태). 스토어를 모르므로 전량 유닛 테스트가 붙는다. */
export function applyWeeklyHours(s: AppState, sid: string, op: { delta: number } | { set: number }): number | null {
  const it = (s.items || []).find((x) => x.id === sid);
  if (!it || it.mode === 'daily') return null;
  it.weeklyHours = 'set' in op ? Math.max(0, op.set) : bumpWeeklyHours(it.weeklyHours, op.delta);
  return it.weeklyHours;
}

/* ============================================================
   phone/Connect.tsx — 폰을 클라우드에 붙이는 화면(C-6).

