 */
export function backupAt(): { at: number | null } | null {
  try {
    if (storage.getItem(BACKUP_KEY) == null) return null;
    const raw = storage.getItem(BACKUP_AT_KEY);
    const n = raw == null ? NaN : Number(raw);
    return { at: Number.isFinite(n) ? n : null };
  } catch {
    return null;
  }
}
