export async function importVaultSubject(s: VaultSubject, ledger: Ledger | undefined, tail: string): Promise<void> {
  const items = st().state.items;
  if (items.some((x) => x.name === s.name)) {
    toast('이미 추가된 항목입니다.', 'warn');
    return;
  }
  const chapters = chaptersFromVault(s.chapters);
  const id = rid();
  st().mutate((state) => {
    state.items.push(makeItem({ id, source: '볼트', name: s.name, chapters }));
  });
  toast(`"${s.name}" 추가됨 — 챕터 ${chapters.length}개. ${tail}`, 'ok');
  /* W4 — 임포트는 모든 챕터를 `done:false` 로 만들어 **가짜 백로그**를 세운다. 원장은 같은
     챕터에 대해 `carded` 를 이미 아는데, 자동으로 찍으면 안 익힌 챕터가 조용히 유지 큐로
     내려간다 → **한 번 묻고 사람이 판단한다**(근거는 `lib/ledgerSeed.ts` 머리주석). */
  const carded = cardedChapters(ledger, s.name, chapters);
  if (!carded.length) return;
  /* Q-13 ②단 — 원장이 밖에 그대로 있으니 언제든 다시 맞출 수 있다(재구성 가능). */
  const ok = await confirmLossy(cardedPrompt(s.name, carded.length, chapters.length), {
    title: '원장과 맞출까요?',
    okLabel: `${carded.length}개 끝낸 것으로 표시`,
    cancelLabel: '그대로 두기',
  });
  if (!ok) return;
  let marked = 0;
  st().mutate((state) => {
    const it = state.items.find((x) => x.id === id);
    if (it) marked = applyCardedDone(it.chapters || [], carded);
  });
  toast(`챕터 ${marked}개를 끝낸 것으로 표시했어요 — 유지 복습 큐로 넘어갑니다.`, 'ok');
}

/* ============================================================
   shell/modal.tsx — confirm 모달(레거시 ui-kit.js의 confirmModal 대체).
   명령형 Promise API(confirm) — 호출부가 await. 표시는 <ModalHost/>(앱 루트 1개).
   CSS는 .modal-ov/.modal/.modal-*(전역) 재사용. Esc=취소, Enter=확인.

   ⚠⚠ **`prompt` 는 은퇴했다(W8 · 2026-07-31).** 전 앱 유일한 호출부가 백지 복습의 '막힘 메모'
   였는데, 취소하면 **"막혔다"는 사실 자체가 기록되지 않았다** — 모달 하나가 데이터를 먹는
   형태였다. 지금은 사실을 먼저 커밋하고 메모는 그 행 아래 인라인 한 줄로 받는다
   (`features/today/TodayBlocks.tsx`). 함께 사라진 것: prompt 경로·`PromptOpts`·모달 안의
   textarea 와 그 Ctrl/⌘+Enter 분기.
   ⚠ **되살리지 말 것** — "값을 받는 모달"이 필요하다고 느껴지면 그건 대개 *커밋을 값 입력에
   묶고 있다*는 신호다. 커밋을 먼저 하고 값은 나중에 받는 형태가 이 앱의 규약이다. */
import { useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { create } from 'zustand';
import { useFocusTrap } from '@/hooks/useFocusTrap';
import { useScrollLock } from '@/hooks/useScrollLock';

export interface ConfirmOpts {
  title?: string;
  okLabel?: string;
  cancelLabel?: string;
  danger?: boolean;
}
interface ModalReq {
  id: number;
  message: string;
  title?: string;
  okLabel?: string;
  cancelLabel?: string;
  danger?: boolean;
  resolve: (v: boolean) => void;
}
interface ModalStore {
  current: ModalReq | null;
  open: (req: ModalReq) => void;
  close: () => void;
}
let _id = 0;
const useModalStore = create<ModalStore>((set) => ({
  current: null,
  open: (req) => set({ current: req }),
  close: () => set({ current: null }),
}));

/** 확인창이 떠 있는가 — 구독 없이(전역 keydown 게이트 전용 · `shell/keyGate`). */
export function isModalOpen(): boolean {
  return useModalStore.getState().current !== null;
}

/** 확인 모달 → Promise<boolean>. */
export function confirm(message: string, opts: ConfirmOpts = {}): Promise<boolean> {
  return new Promise((resolve) => {
    useModalStore.getState().open({
      id: ++_id,
      message,
      title: opts.title,
      okLabel: opts.okLabel,
      cancelLabel: opts.cancelLabel,
      danger: opts.danger,
      resolve,
    });
  });
}

export function ModalHost() {
  const current = useModalStore((s) => s.current);
  const close = useModalStore((s) => s.close);
  const okRef = useRef<HTMLButtonElement>(null);
  const dialogRef = useRef<HTMLDivElement>(null);
  const initialRef = useRef<HTMLElement | null>(null);

  const titleId = current ? `modal-t-${current.id}` : undefined;
  const bodyId = current ? `modal-b-${current.id}` : undefined;

  /* 포커스 관리는 이제 공유 훅이 소유한다 — 여기 손코딩돼 있던 것을 useFocusTrap 이 그대로
     추출해 갔는데(주석이 그렇게 적혀 있다) 정작 원본은 남아, 검증된 패턴의 **복제 두 벌**이
     ShortcutsHelp·DetailDrawer 와 갈라진 채 유지되고 있었다.
     ⚠ `active` 를 `!!current` 로 주는 것이 안전한 이유: finish()가 resolve 직후 close()로
     current 를 반드시 null 로 만들어, 연속된 모달 사이에 false 를 한 번 거친다(그래야 새
     모달에서 초기 포커스가 다시 잡힌다). */
  useEffect(() => {
    initialRef.current = okRef.current;
  }, [current]);
  useFocusTrap(!!current, dialogRef, initialRef);
  useScrollLock(!!current);

  if (!current) return null;

  const finish = (v: boolean) => {
    current.resolve(v);
    close();
  };

  // Tab 순환은 useFocusTrap(document 리스너)이 맡는다 — 여기는 확정/취소 키만.
  const onKey = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape') {
      e.preventDefault();
      finish(false);
    } else if (e.key === 'Enter') {
      e.preventDefault();
      finish(true);
    }
  };

  // body로 포털 — 앱 트리 안에 두면 조상이 만든 스태킹 컨텍스트에 갇혀 z-index가 무의미해진다.
  // DetailDrawer(시트)는 body 직속 포털이라, 확인창이 트리 안에 있으면 z-index를 아무리 올려도
  // 시트가 위를 덮었다(시트에서 '과목 삭제' → 확인창이 뒤에 떠 클릭이 안 되던 결함).
  return createPortal(
    /* 오버레이 mousedown-닫기 = 마우스 편의이고, 결과는 취소 버튼과 동일하다. 키보드 경로는
       위 onKey(ESC 취소 · Enter 확인) · trapTab(포커스 순환) ·
       열기 전 포커스 복원 · 취소/확인 진짜 버튼이 전부 갖고 있다. */
    // eslint-disable-next-line jsx-a11y/no-static-element-interactions
    <div className="modal-ov in" onMouseDown={(e) => e.target === e.currentTarget && finish(false)} onKeyDown={onKey}>
      <div
        ref={dialogRef}
        className="modal"
        role="dialog"
        aria-modal="true"
        aria-labelledby={current.title ? titleId : undefined}
        aria-describedby={bodyId}
      >
        {current.title && (
          <div id={titleId} className="modal-t">
            {current.title}
          </div>
        )}
        <div id={bodyId} className="modal-b">
          {current.message}
        </div>
        <div className="modal-a">
          <button type="button" className="ghost modal-cancel" onClick={() => finish(false)}>
            {current.cancelLabel || '취소'}
          </button>
          <button
            ref={okRef}
            type="button"
            className={`primary modal-ok${current.danger ? ' modal-danger' : ''}`}
            onClick={() => finish(true)}
          >
            {current.okLabel || '확인'}
          </button>
        </div>
      </div>
    </div>,
    document.body,
  );
}

/* ============================================================
   shell/palette.ts — ⌘K 명령 팔레트 항목(레거시 paletteCommands 이식 + 고도화).
   탭 이동(React Router) + 핵심 데이터/내보내기/백업 액션. tab 항목은 CommandPalette가 navigate,
   act는 run() 호출. 최근 실행한 명령(recent.ts)을 위로 끌어올려 재실행이 빠르다.
============================================================ */
import { orderedTabs, tabByKey } from './tabs';
import { NAV_SHORTCUTS } from './shortcuts';
import { recentIds } from './recent';
import * as A from './actions';
import { useFocus } from '@/store/useFocus';
import { usePrefill } from '@/store/prefill';
import { useOverlay } from '@/store/useOverlay';
import { MOD_LABEL } from '@/lib/platform';
import { MINI_PATH, enterMini } from '@/lib/miniMode';

// C-5: 탭 → g-시퀀스 매핑(치트시트가 이미 정의). 팔레트 hint에 노출해 사용 중 키보드 내비를 학습시킨다.
const SEQ_BY_TAB = new Map(NAV_SHORTCUTS.map((s) => [s.tab, s.seq]));

export type PaletteCommand =
  | { id: string; kind: 'tab'; key: string; label: string; hint: string }
  /** act — run() 실행 후 to가 있으면 해당 탭으로 이동(팔레트가 navigate).
   *  ⚠ `run` 이 **선택**인 것은 P3 의 산물이다: 탭이 아닌 **화면**(`/items?view=structure`)으로
   *  가는 항목은 부수효과가 없고 이동이 전부다. 빈 `() => {}` 를 놓는 것보다 타입이 사실이다. */
  /** ⚠ `enter` 는 **실패할 수 있는 진입**이다(N-20 · W3). `run`+`to` 조합은 부수효과가 성공했든
   *  말든 이동하는데, 창 모드 전환처럼 *실패하면 이동하면 안 되는* 동작이 있다 — 작아지지
   *  않았는데 알약 화면만 뜨면 나갈 문이 화면에서 사라진다(`lib/miniMode` 가 H9 에서 세운 규율).
   *  성공하면 갈 경로를, 실패하면 `null` 을 준다. 팔레트는 `null` 이면 **아무 데도 안 간다**. */
  | {
      id: string;
      kind: 'act';
      label: string;
      hint: string;
      run?: () => void;
      to?: string;
      enter?: () => Promise<string | null>;
    };

function baseCommands(): PaletteCommand[] {
  const tabs: PaletteCommand[] = orderedTabs().map((t) => {
    const seq = SEQ_BY_TAB.get(t.key);
    /* Q-22 — 은퇴한 탭은 **`to` 로 간다**(`key` 가 경로가 아니다). 종전엔 은퇴하면 `TABS` 에서
       통째로 빼서 ⌘K 에서도 사라졌고, 그 구멍을 `act:graph` 한 줄로 손으로 메우고 있었다. */
    if (t.role === 'view') {
      /* ⚠ 힌트는 **사용자의 언어**여야 한다(U012 · 2026-08-21 ux 축). 종전 `은퇴` 는 이 저장소의
         내부 어휘(`role:'view'`(옛 `retired`))를 그대로 노출한 것이라, 사용자에게는 *"이건 이제 없다"* 로
         읽혔다 — 실제로는 살아 있는 화면이고 ⌘K 가 그 유일한 문인데도. 힌트가 말해야 하는 것은
         상태가 아니라 **어디에 있는가**다(호스트 탭 이름). */
      const 호스트 = tabByKey(t.to?.replace(/^\//, '').split('?')[0] ?? '')?.label;
      return {
        id: 'tab:' + t.key,
        kind: 'act',
        label: '이동 · ' + t.label,
        hint: 호스트 ? `${호스트} 안` : '화면',
        to: t.to,
      };
    }
    return {
      id: 'tab:' + t.key,
      kind: 'tab',
      key: t.key,
      label: '이동 · ' + t.label,
      hint: seq ? 'G ' + seq.toUpperCase() : '탭',
